-- ============================================================================
-- 图书馆样书 seed:The Wonderful Wizard of Oz (wizard-of-oz)
-- 生成自 scripts/library/books/wizard-of-oz.json —— node scripts/library/build-seed.mjs wizard-of-oz
-- ⚠️ 内容(英文改写 + 中文)须先过审(Aaron/网页版 Claude)再落库(content-review-gate + D9)。
-- 幂等:upsert 书 + 删该书旧句重灌。BEGIN/COMMIT + 前后计数。
-- 章号真实(D12);共 24 章 / 2083 句。
-- ============================================================================

BEGIN;

-- 0) 章标题列(方案 A:jsonb,幂等加列)。[{idx,title_en,title_zh}]
ALTER TABLE public.library_books
  ADD COLUMN IF NOT EXISTS chapters jsonb NOT NULL DEFAULT '[]'::jsonb;

SELECT 'before' AS phase,
       (SELECT count(*) FROM public.library_books WHERE book_key = 'wizard-of-oz') AS book_exists,
       (SELECT count(*) FROM public.library_sentences s
          JOIN public.library_books b ON b.id = s.book_id
         WHERE b.book_key = 'wizard-of-oz') AS sentence_rows;

-- 1) 书目(upsert)
INSERT INTO public.library_books
  (book_key, title, zh_title, author, age_band, age_range, cover,
   intro_en, intro_zh, sentence_count, copyright_note, chapters, is_published)
VALUES
  ('wizard-of-oz', 'The Wonderful Wizard of Oz', '绿野仙踪', 'L. Frank Baum',
   '儿童', '8-12岁', '{"c1":"#10b981","c2":"#065f46"}'::jsonb,
   'Swept far from her Kansas home by a cyclone, a young girl named Dorothy lands in the magical Land of Oz. To find her way back, she follows a road of yellow brick toward the Emerald City, making three unlikely friends along the way — a Scarecrow who wants a brain, a Tin Woodman who longs for a heart, and a Lion in search of courage.', '一场龙卷风把堪萨斯的小女孩多萝西卷到了神奇的奥兹国。为了回家,她沿着黄砖路走向翡翠城,一路上结识了三位奇特的朋友——想要脑子的稻草人、渴望一颗心的铁皮人,以及寻找勇气的狮子。', 2083, 'Public domain (first published 1900). Source: Project Gutenberg eBook #55. 公有领域(1900 年首版);正文取自 Project Gutenberg #55,面向学习者的分句/翻译加工。',
   '[{"idx":1,"title_en":"The Cyclone","title_zh":"龙卷风"},{"idx":2,"title_en":"The Council with the Munchkins","title_zh":"与芒奇金人的商议"},{"idx":3,"title_en":"How Dorothy Saved the Scarecrow","title_zh":"多萝西如何拯救稻草人"},{"idx":4,"title_en":"The Road Through the Forest","title_zh":"穿过森林的路"},{"idx":5,"title_en":"The Rescue of the Tin Woodman","title_zh":"营救铁皮人"},{"idx":6,"title_en":"The Cowardly Lion","title_zh":"胆小的狮子"},{"idx":7,"title_en":"The Journey to the Great Oz","title_zh":"前往奥兹大王之旅"},{"idx":8,"title_en":"The Deadly Poppy Field","title_zh":"致命罂粟花田"},{"idx":9,"title_en":"The Queen of the Field Mice","title_zh":"田鼠女王"},{"idx":10,"title_en":"The Guardian of the Gate","title_zh":"城门守卫"},{"idx":11,"title_en":"The Wonderful City of Oz","title_zh":"奇妙的翡翠城"},{"idx":12,"title_en":"The Search for the Wicked Witch","title_zh":"寻找坏女巫"},{"idx":13,"title_en":"The Rescue","title_zh":"营救"},{"idx":14,"title_en":"The Winged Monkeys","title_zh":"飞猴"},{"idx":15,"title_en":"The Discovery of Oz, the Terrible","title_zh":"发现可怕的奥兹大王"},{"idx":16,"title_en":"The Magic Art of the Great Humbug","title_zh":"伟大骗子的魔法"},{"idx":17,"title_en":"How the Balloon Was Launched","title_zh":"气球升空"},{"idx":18,"title_en":"Away to the South","title_zh":"南行"},{"idx":19,"title_en":"Attacked by the Fighting Trees","title_zh":"战树的袭击"},{"idx":20,"title_en":"The Dainty China Country","title_zh":"娇小的瓷器国"},{"idx":21,"title_en":"The Lion Becomes the King of Beasts","title_zh":"狮子成为百兽之王"},{"idx":22,"title_en":"The Country of the Quadlings","title_zh":"奎德林人之国"},{"idx":23,"title_en":"Glinda The Good Witch Grants Dorothy’s Wish","title_zh":"好女巫格林达实现了多萝西的愿望"},{"idx":24,"title_en":"Home Again","title_zh":"重返家园"}]'::jsonb, false)
ON CONFLICT (book_key) DO UPDATE SET
  title          = EXCLUDED.title,
  zh_title       = EXCLUDED.zh_title,
  author         = EXCLUDED.author,
  age_band       = EXCLUDED.age_band,
  age_range      = EXCLUDED.age_range,
  cover          = EXCLUDED.cover,
  intro_en       = EXCLUDED.intro_en,
  intro_zh       = EXCLUDED.intro_zh,
  sentence_count = EXCLUDED.sentence_count,
  copyright_note = EXCLUDED.copyright_note,
  chapters       = EXCLUDED.chapters;
  -- 注:不覆盖 is_published —— 审后手动置 true,重灌 seed 不会把它打回 false。

-- 2) 句子(删旧重灌,幂等)。audio_url 留 NULL:默认前端实时合成,预生成脚本审后另回填。
DELETE FROM public.library_sentences
 WHERE book_id = (SELECT id FROM public.library_books WHERE book_key = 'wizard-of-oz');

INSERT INTO public.library_sentences (book_id, chapter_idx, para_idx, seq, text_en, text_cn)
SELECT b.id, v.chapter_idx, v.para_idx, v.seq, v.text_en, v.text_cn
FROM public.library_books b
CROSS JOIN (VALUES
    (1, 1, 1, 'Dorothy lived in the midst of the great Kansas prairies, with Uncle Henry, who was a farmer, and Aunt Em, who was the farmer’s wife.', '多萝西和亨利叔叔、艾姆婶婶住在一起。亨利叔叔是农民，艾姆婶婶是农民的妻子。他们住在大大的堪萨斯草原中间。'),
    (1, 1, 2, 'Their house was small, for the lumber to build it had to be carried by wagon many miles.', '他们的房子很小，因为盖房子的木头要用马车运很远的路。'),
    (1, 1, 3, 'There were four walls, a floor and a roof, which made one room; and this room contained a rusty looking cookstove, a cupboard for the dishes, a table, three or four chairs, and the beds.', '房子有四面墙、一个地板和一个屋顶，只有一个房间。这个房间里有一个旧旧的炉子、一个放碗碟的柜子、一张桌子、三四把椅子和几张床。'),
    (1, 1, 4, 'Uncle Henry and Aunt Em had a big bed in one corner, and Dorothy a little bed in another corner.', '亨利叔叔和艾姆婶婶有一个大床在屋子的一角，多萝西有一个小床在另一个角。'),
    (1, 1, 5, 'There was no garret at all, and no cellar—except a small hole dug in the ground, called a cyclone cellar, where the family could go in case one of those great whirlwinds arose, mighty enough to crush any building in its path.', '家里没有阁楼，也没有地窖。只有一个小小的洞，挖在地上，大家叫它‘龙卷风地窖’。要是来了大大的龙卷风，能把房子都刮倒，他们就躲到里面去。'),
    (1, 1, 6, 'It was reached by a trap door in the middle of the floor, from which a ladder led down into the small, dark hole.', '从地板中间的一个暗门进去，有一架梯子通到那个又小又黑的洞里。'),
    (1, 2, 7, 'When Dorothy stood in the doorway and looked around, she could see nothing but the great gray prairie on every side.', '当多萝西站在门边向四周看时，她只能看到一片大大的灰色草原，什么都没有。'),
    (1, 2, 8, 'Not a tree nor a house broke the broad sweep of flat country that reached to the edge of the sky in all directions.', '没有一棵树，也没有一座房子，只有平坦的土地一直延伸到天边。'),
    (1, 2, 9, 'The sun had baked the plowed land into a gray mass, with little cracks running through it.', '太阳把耕过的地晒得硬邦邦的，变成一片灰蒙蒙的，上面还有一些小裂缝。'),
    (1, 2, 10, 'Even the grass was not green, for the sun had burned the tops of the long blades until they were the same gray color to be seen everywhere.', '连草都不是绿色的，太阳把长长的草尖都晒黄了，到处都是一样的灰色。'),
    (1, 2, 11, 'Once the house had been painted, but the sun blistered the paint and the rains washed it away, and now the house was as dull and gray as everything else.', '房子以前漆过油漆，但是太阳把油漆晒得起了泡，雨水又把油漆冲掉了。现在房子也变得和周围的一切一样，又暗又灰。'),
    (1, 3, 12, 'When Aunt Em came there to live she was a young, pretty wife.', '艾姆婶婶刚来这里住的时候，她是一个年轻又漂亮的妻子。'),
    (1, 3, 13, 'The sun and wind had changed her, too.', '太阳和风也改变了她。'),
    (1, 3, 14, 'They had taken the sparkle from her eyes and left them a sober gray; they had taken the red from her cheeks and lips, and they were gray also.', '她的眼睛不再闪亮，变得灰蒙蒙的；她的脸颊和嘴唇也没有了红色，也变成了灰色。'),
    (1, 3, 15, 'She was thin and gaunt, and never smiled now.', '她又瘦又憔悴，现在从不笑了。'),
    (1, 3, 16, 'When Dorothy, who was an orphan, first came to her, Aunt Em had been so startled by the child’s laughter that she would scream and press her hand upon her heart whenever Dorothy’s merry voice reached her ears; and she still looked at the little girl with wonder that she could find anything to laugh at.', '当多萝西（她是一个孤儿）刚来到她身边时，艾姆婶婶听到孩子笑声时吓了一跳，每次多萝西开心笑出声，她都会尖叫，捂住自己的心口。她还是会好奇地看着这个小女孩，想不通她有什么好笑的。'),
    (1, 4, 17, 'Uncle Henry never laughed.', '亨利叔叔从不笑。'),
    (1, 4, 18, 'He worked hard from morning till night and did not know what joy was.', '他从早到晚努力干活，不知道什么叫快乐。'),
    (1, 4, 19, 'He was gray also, from his long beard to his rough boots, and he looked stern and solemn, and rarely spoke.', '他也是灰色的，从长长的胡子到粗糙的靴子。他看起来很严肃，不苟言笑，也很少说话。'),
    (1, 5, 20, 'It was Toto that made Dorothy laugh, and saved her from growing as gray as her other surroundings.', '是托托让多萝西开心地笑了，也让她没有变得像周围环境一样灰暗。'),
    (1, 5, 21, 'Toto was not gray; he was a little black dog, with long silky hair and small black eyes that twinkled merrily on either side of his funny, wee nose.', '托托不是灰色的；它是一只小黑狗，有着长长的丝滑毛发，还有两只小小的黑眼睛，在它滑稽的小鼻子的两边，闪着开心的光。'),
    (1, 5, 22, 'Toto played all day long, and Dorothy played with him, and loved him dearly.', '托托整天都在玩耍，多萝西和它一起玩，而且非常爱它。'),
    (1, 6, 23, 'Today, however, they were not playing.', '但是今天，他们没有玩耍。'),
    (1, 6, 24, 'Uncle Henry sat upon the doorstep and looked anxiously at the sky, which was even grayer than usual.', '亨利叔叔坐在门槛上，焦急地看着天空，天空比平时更灰暗了。'),
    (1, 6, 25, 'Dorothy stood in the door with Toto in her arms, and looked at the sky too.', '多萝西抱着托托站在门口，也看着天空。'),
    (1, 6, 26, 'Aunt Em was washing the dishes.', '艾姆婶婶正在洗碗。'),
    (1, 7, 27, 'From the far north they heard a low wail of the wind, and Uncle Henry and Dorothy could see where the long grass bowed in waves before the coming storm.', '他们从很远的北方听到风呜咽的声音，亨利叔叔和多萝西能看到长长的草被风吹得像波浪一样弯下腰，暴风雨要来了。'),
    (1, 7, 28, 'There now came a sharp whistling in the air from the south, and as they turned their eyes that way they saw ripples in the grass coming from that direction also.', '现在，南方传来一阵尖锐的呼啸声，他们朝那个方向看去，看到草地上也出现了波浪，从那边涌过来。'),
    (1, 8, 29, 'Suddenly Uncle Henry stood up.', '突然，亨利叔叔站了起来。'),
    (1, 9, 30, '“There’s a cyclone coming, Em,” he called to his wife.', '“龙卷风要来了，艾姆！”他对妻子喊道。'),
    (1, 9, 31, '“I’ll go look after the stock.”', '“我去看看牲口。”'),
    (1, 9, 32, 'Then he ran toward the sheds where the cows and horses were kept.', '然后他跑向牛棚，那里养着奶牛和马。'),
    (1, 10, 33, 'Aunt Em dropped her work and came to the door.', '艾姆婶婶放下手里的活儿，走到门口。'),
    (1, 10, 34, 'One glance told her of the danger close at hand.', '她看了一眼，就知道危险就在眼前。'),
    (1, 11, 35, '“Quick, Dorothy!” she screamed. “Run for the cellar!”', '“快，多萝西！”她大叫。“快跑去地窖！”'),
    (1, 12, 36, 'Toto jumped out of Dorothy’s arms and hid under the bed, and the girl started to get him.', '托托从多萝西的怀里跳出来，躲到床底下，小女孩便去抓它。'),
    (1, 12, 37, 'Aunt Em, badly frightened, threw open the trap door in the floor and climbed down the ladder into the small, dark hole.', '艾姆婶婶吓坏了，她打开地板上的活板门，顺着梯子爬进那个又小又黑的洞里。'),
    (1, 12, 38, 'Dorothy caught Toto at last and started to follow her aunt.', '多萝西终于抓住了托托，然后跟着婶婶走。'),
    (1, 12, 39, 'When she was halfway across the room there came a great shriek from the wind, and the house shook so hard that she lost her footing and sat down suddenly upon the floor.', '当她走到房间一半的时候，风发出了一声巨大的尖叫，房子摇晃得太厉害，她站不稳，一下子就坐在了地上。'),
    (1, 13, 40, 'Then a strange thing happened.', '接着，一件奇怪的事情发生了。'),
    (1, 14, 41, 'The house whirled around two or three times and rose slowly through the air.', '房子转了两三圈，然后慢慢地升到空中。'),
    (1, 14, 42, 'Dorothy felt as if she were going up in a balloon.', '多萝西感觉自己好像坐着气球飞起来了。'),
    (1, 15, 43, 'The north and south winds met where the house stood, and made it the exact center of the cyclone.', '北风和南风在房子所在的地方相遇，让房子正好在龙卷风的中心。'),
    (1, 15, 44, 'In the middle of a cyclone the air is generally still, but the great pressure of the wind on every side of the house raised it up higher and higher, until it was at the very top of the cyclone; and there it remained and was carried miles and miles away as easily as you could carry a feather.', '龙卷风的中心通常是平静的，但风从四面八方给房子巨大的压力，把房子抬得越来越高，直到它到了龙卷风的最顶端；房子就留在那里，被带走了很远很远，就像你拿起一片羽毛一样轻松。'),
    (1, 16, 45, 'It was very dark, and the wind howled horribly around her, but Dorothy found she was riding quite easily.', '外面很黑，风在她身边可怕地呼啸着，但多萝西发现自己坐得很稳。'),
    (1, 16, 46, 'After the first few whirls around, and one other time when the house tipped badly, she felt as if she were being rocked gently, like a baby in a cradle.', '房子最开始转了几圈，后来有一次还剧烈倾斜了一下，但过了这些之后，她感觉自己被轻轻地摇晃着，就像摇篮里的宝宝一样。'),
    (1, 17, 47, 'Toto did not like it.', '托托不喜欢这样。'),
    (1, 17, 48, 'He ran about the room, now here, now there, barking loudly; but Dorothy sat quite still on the floor and waited to see what would happen.', '他在房间里跑来跑去，一会儿跑这儿，一会儿跑那儿，大声地叫着；但多萝西安静地坐在地板上，等着看会发生什么。'),
    (1, 18, 49, 'Once Toto got too near the open trap door, and fell in; and at first the little girl thought she had lost him.', '有一次，托托离打开的活板门太近，掉了进去；小女孩一开始以为把它弄丢了。'),
    (1, 18, 50, 'But soon she saw one of his ears sticking up through the hole, for the strong pressure of the air was keeping him up so that he could not fall.', '但很快她就看到他的一只耳朵从洞里伸出来，因为空气强大的压力托住了他，所以他没有掉下去。'),
    (1, 18, 51, 'She crept to the hole, caught Toto by the ear, and dragged him into the room again, afterward closing the trap door so that no more accidents could happen.', '她悄悄走到洞口，抓住托托的耳朵，把他拖回房间，然后关上活板门，这样就不会再发生意外了。'),
    (1, 19, 52, 'Hour after hour passed away, and slowly Dorothy got over her fright; but she felt quite lonely, and the wind shrieked so loudly all about her that she nearly became deaf.', '一个小时又一个小时过去了，多萝西慢慢地不再那么害怕了；但她感觉很孤单，风在她身边大声呼啸，她差点被震聋了。'),
    (1, 19, 53, 'At first she had wondered if she would be dashed to pieces when the house fell again; but as the hours passed and nothing terrible happened, she stopped worrying and resolved to wait calmly and see what the future would bring.', '一开始她担心房子再掉下去的时候，自己会不会摔得粉碎；但随着时间过去，什么可怕的事情都没发生，她就不再担心了，决定平静地等待，看看未来会怎样。'),
    (1, 19, 54, 'At last she crawled over the swaying floor to her bed, and lay down upon it; and Toto followed and lay down beside her.', '最后她爬过摇晃的地板到她的床上，躺了上去；托托也跟着过来，躺在她身边。'),
    (1, 20, 55, 'In spite of the swaying of the house and the wailing of the wind, Dorothy soon closed her eyes and fell fast asleep.', '尽管房子还在摇晃，风还在呼啸，多萝西很快就闭上眼睛，睡着了。'),
    (2, 21, 56, 'She was awakened by a shock, so sudden and severe that if Dorothy had not been lying on the soft bed she might have been hurt.', '她被一阵冲击惊醒了，那冲击又突然又猛烈，如果多萝西没有躺在柔软的床上，她可能就受伤了。'),
    (2, 21, 57, 'As it was, the jar made her catch her breath and wonder what had happened; and Toto put his cold little nose into her face and whined dismally.', '尽管如此，这一震还是让她倒吸一口气，想知道发生了什么；托托把冰冷的小鼻子伸到她脸上，可怜地呜咽着。'),
    (2, 21, 58, 'Dorothy sat up and noticed that the house was not moving; nor was it dark, for the bright sunshine came in at the window, flooding the little room.', '多萝西坐起来，发现房子不动了；也不再黑暗了，因为明亮的阳光从窗户照进来，洒满了整个小房间。'),
    (2, 21, 59, 'She sprang from her bed and with Toto at her heels ran and opened the door.', '她从床上跳起来，托托跟在她身后，她跑过去打开了门。'),
    (2, 22, 60, 'The little girl gave a cry of amazement and looked about her, her eyes growing bigger and bigger at the wonderful sights she saw.', '小女孩惊奇地叫了一声，环顾四周，她看到的奇妙景象让她眼睛越睁越大。'),
    (2, 23, 61, 'The cyclone had set the house down very gently—for a cyclone—in the midst of a country of marvelous beauty.', '龙卷风把房子轻轻地放了下来，在一个很美的地方。'),
    (2, 23, 62, 'There were lovely patches of greensward all about, with stately trees bearing rich and luscious fruits.', '周围有绿绿的草地，还有高大的树，上面结满了好吃的水果。'),
    (2, 23, 63, 'Banks of gorgeous flowers were on every hand, and birds with rare and brilliant plumage sang and fluttered in the trees and bushes.', '四处都是漂亮的花，还有穿着漂亮羽毛的鸟儿在树丛里唱歌、飞舞。'),
    (2, 23, 64, 'A little way off was a small brook, rushing and sparkling along between green banks, and murmuring in a voice very grateful to a little girl who had lived so long on the dry, gray prairies.', '不远处有条小溪，水哗啦啦地流着，在绿色的岸边闪闪发光。对于一个一直住在干旱草原上的小女孩来说，这声音听起来很舒服。'),
    (2, 24, 65, 'While she stood looking eagerly at the strange and beautiful sights, she noticed coming toward her a group of the queerest people she had ever seen.', '她好奇地看着这些又奇怪又美丽的地方时，看到一群她从没见过的人朝她走来。'),
    (2, 24, 66, 'They were not as big as the grown folk she had always been used to; but neither were they very small.', '他们不像她平时见的大人那么高，但也不是很矮。'),
    (2, 24, 67, 'In fact, they seemed about as tall as Dorothy, who was a well-grown child for her age, although they were, so far as looks go, many years older.', '他们看起来跟多萝西差不多高，多萝西在同龄孩子里算长得挺好的。不过，他们看起来比多萝西大很多岁。'),
    (2, 25, 68, 'Three were men and one a woman, and all were oddly dressed.', '他们有三男一女，穿的衣服都很特别。'),
    (2, 25, 69, 'They wore round hats that rose to a small point a foot above their heads, with little bells around the brims that tinkled sweetly as they moved.', '他们戴着圆帽子，帽子顶上尖尖的，比头高一尺。帽子边上还有小铃铛，他们一动就发出好听的叮当声。'),
    (2, 25, 70, 'The hats of the men were blue; the little woman’s hat was white, and she wore a white gown that hung in pleats from her shoulders.', '男士们的帽子是蓝色的；小妇人的帽子是白色的，她穿着一件白色的连衣裙，从肩膀垂下来有许多褶子。'),
    (2, 25, 71, 'Over it were sprinkled little stars that glistened in the sun like diamonds.', '连衣裙上洒满了小星星，在阳光下像钻石一样闪闪发光。'),
    (2, 25, 72, 'The men were dressed in blue, of the same shade as their hats, and wore well-polished boots with a deep roll of blue at the tops.', '男士们穿着蓝色的衣服，和帽子是同样的颜色，还穿着擦得亮亮的靴子，靴子顶部有一圈深蓝色。'),
    (2, 25, 73, 'The men, Dorothy thought, were about as old as Uncle Henry, for two of them had beards.', '多萝西觉得，男士们看起来跟亨利叔叔差不多大，因为他们中有两个人留着胡子。'),
    (2, 25, 74, 'But the little woman was doubtless much older.', '但那个小妇人肯定大多了。'),
    (2, 25, 75, 'Her face was covered with wrinkles, her hair was nearly white, and she walked rather stiffly.', '她的脸上都是皱纹，头发几乎全白了，走路也有些僵硬。'),
    (2, 26, 76, 'When these people drew near the house where Dorothy was standing in the doorway, they paused and whispered among themselves, as if afraid to come farther.', '当这些人走到多萝西站在门口的房子附近时，他们停了下来，互相小声说话，好像不敢再往前走了。'),
    (2, 26, 77, 'But the little old woman walked up to Dorothy, made a low bow and said, in a sweet voice:', '但那个小老妇人走到多萝西面前，深深地鞠了一躬，然后用甜甜的声音说：'),
    (2, 27, 78, '“You are welcome, most noble Sorceress, to the land of the Munchkins.', '“最尊贵的魔法师，欢迎你来到芒奇金人的土地。”'),
    (2, 27, 79, 'We are so grateful to you for having killed the Wicked Witch of the East, and for setting our people free from bondage.”', '“我们非常感谢你杀了那个东方坏女巫，把我们的人民从苦难中解救出来。”'),
    (2, 28, 80, 'Dorothy listened to this speech with wonder.', '多萝西听着这些话，感到很惊讶。'),
    (2, 28, 81, 'What could the little woman possibly mean by calling her a sorceress, and saying she had killed the Wicked Witch of the East?', '这个小妇人叫她魔法师，还说她杀了那个东方坏女巫，到底是什么意思呢？'),
    (2, 28, 82, 'Dorothy was an innocent, harmless little girl, who had been carried by a cyclone many miles from home; and she had never killed anything in all her life.', '多萝西只是一个天真无害的小女孩，她被龙卷风从家里卷到了很远的地方。她这辈子从来没杀过任何东西。'),
    (2, 29, 83, 'But the little woman evidently expected her to answer; so Dorothy said, with hesitation, “You are very kind, but there must be some mistake.', '但那个小妇人显然在等她回答，所以多萝西有些迟疑地说：“你人很好，但这一定弄错了。'),
    (2, 29, 84, 'I have not killed anything.”', '我没有杀过任何东西。”'),
    (2, 30, 85, '“Your house did, anyway,” replied the little old woman, with a laugh, “and that is the same thing.', '“反正你的房子做到了！”小老妇人笑着回答，“那是一样的。”'),
    (2, 30, 86, 'See!” she continued, pointing to the corner of the house. “There are her two feet, still sticking out from under a block of wood.”', '“看！”她接着说，指着房子的角落，“她的两只脚还在那块木头下面露出来呢。”'),
    (2, 31, 87, 'Dorothy looked, and gave a little cry of fright.', '多萝西看了一眼，吓得小声叫了起来。'),
    (2, 31, 88, 'There, indeed, just under the corner of the great beam the house rested on, two feet were sticking out, shod in silver shoes with pointed toes.', '果然，就在房子下面那根大梁的角落里，有两只脚伸了出来，脚上穿着银色的尖头鞋。'),
    (2, 32, 89, '“Oh, dear!', '“哎呀！'),
    (2, 32, 90, 'Oh, dear!” cried Dorothy, clasping her hands together in dismay.', '哎呀！”多萝西沮丧地把手合在一起，叫道。'),
    (2, 32, 91, '“The house must have fallen on her.', '“房子一定砸到她了。'),
    (2, 32, 92, 'Whatever shall we do?”', '我们该怎么办呀？”'),
    (2, 33, 93, '“There is nothing to be done,” said the little woman calmly.', '“没办法了，”小个子女人平静地说。'),
    (2, 34, 94, '“But who was she?” asked Dorothy.', '“可是她是谁呀？”多萝西问。'),
    (2, 35, 95, '“She was the Wicked Witch of the East, as I said,” answered the little woman.', '“她就是东方坏女巫，我刚才说了，”小个子女人回答。'),
    (2, 35, 96, '“She has held all the Munchkins in bondage for many years, making them slave for her night and day.', '“她把所有的芒奇金人都抓起来好多年了，让他们白天晚上都给她干活。'),
    (2, 35, 97, 'Now they are all set free, and are grateful to you for the favor.”', '现在他们都自由了，很感谢你帮的忙。”'),
    (2, 36, 98, '“Who are the Munchkins?” inquired Dorothy.', '“芒奇金人是谁呀？”多萝西问。'),
    (2, 37, 99, '“They are the people who live in this land of the East where the Wicked Witch ruled.”', '“他们是住在东方的人，坏女巫以前管着这里。”'),
    (2, 38, 100, '“Are you a Munchkin?” asked Dorothy.', '“你是个芒奇金人吗？”多萝西问。'),
    (2, 39, 101, '“No, but I am their friend, although I live in the land of the North.', '“不是，我是他们的朋友，虽然我住在北方。'),
    (2, 39, 102, 'When they saw the Witch of the East was dead the Munchkins sent a swift messenger to me, and I came at once.', '他们看到东方女巫死了，芒奇金人就马上派人告诉我，我一下子就来了。'),
    (2, 39, 103, 'I am the Witch of the North.”', '我就是北方好女巫。”'),
    (2, 40, 104, '“Oh, gracious!” cried Dorothy. “Are you a real witch?”', '“哦，天哪！”多萝西喊道，“你真的是女巫吗？”'),
    (2, 41, 105, '“Yes, indeed,” answered the little woman.', '“是的，”小个子女人回答。'),
    (2, 41, 106, '“But I am a good witch, and the people love me.', '“不过我是个好女巫，大家都很喜欢我。'),
    (2, 41, 107, 'I am not as powerful as the Wicked Witch was who ruled here, or I should have set the people free myself.”', '我没有以前管这里的坏女巫那么厉害，不然我早就自己把大家放出来了。”'),
    (2, 42, 108, '“But I thought all witches were wicked,” said the girl, who was half frightened at facing a real witch.', '“可是我以为所有女巫都是坏的呢，”小女孩说，她看到真的女巫，有点害怕。'),
    (2, 43, 109, '“Oh, no, that is a great mistake.', '“哦，不，你错了。'),
    (2, 43, 110, 'There were only four witches in all the Land of Oz, and two of them, those who live in the North and the South, are good witches.', '整个奥兹国只有四个女巫，其中两个是好女巫，她们住在北方和南方。'),
    (2, 43, 111, 'I know this is true, for I am one of them myself, and cannot be mistaken.', '我知道这是真的，因为我就是其中一个，我不会弄错的。'),
    (2, 43, 112, 'Those who dwelt in the East and the West were, indeed, wicked witches; but now that you have killed one of them, there is but one Wicked Witch in all the Land of Oz—the one who lives in the West.”', '住在东方和西方的女巫确实是坏女巫；不过你已经杀了一个，整个奥兹国就只剩下一个坏女巫了——就是住在西方的那一个。”'),
    (2, 44, 113, '“But,” said Dorothy, after a moment’s thought, “Aunt Em has told me that the witches were all dead—years and years ago.”', '“可是，”多萝西想了想说，“艾姆婶婶告诉我，女巫们早就死了——很久很久以前就死了。”'),
    (2, 45, 114, '“Who is Aunt Em?” inquired the little old woman.', '“艾姆婶婶是谁呀？”小老太太问。'),
    (2, 46, 115, '“She is my aunt who lives in Kansas, where I came from.”', '“她是我婶婶，住在堪萨斯，我就是从那里来的。”'),
    (2, 47, 116, 'The Witch of the North seemed to think for a time, with her head bowed and her eyes upon the ground.', '北方好女巫低着头，眼睛看着地上，好像在想了一会儿。'),
    (2, 47, 117, 'Then she looked up and said, “I do not know where Kansas is, for I have never heard that country mentioned before.', '然后她抬起头说，“我不知道堪萨斯在哪里，因为我从来没听过这个地方。'),
    (2, 47, 118, 'But tell me, is it a civilized country?”', '不过告诉我，那是个文明的地方吗？”'),
    (2, 48, 119, '“Oh, yes,” replied Dorothy.', '“哦，是的，”多萝西回答。'),
    (2, 49, 120, '“Then that accounts for it.', '“那就对了。'),
    (2, 49, 121, 'In the civilized countries I believe there are no witches left, nor wizards, nor sorceresses, nor magicians.', '我觉得在那些很棒的国家，已经没有女巫、男巫和魔法师了。'),
    (2, 49, 122, 'But, you see, the Land of Oz has never been civilized, for we are cut off from all the rest of the world.', '可是，你看，这个奥兹国从来都不文明，因为我们跟外面的世界都分开了。'),
    (2, 49, 123, 'Therefore we still have witches and wizards amongst us.”', '所以我们这里还有女巫和男巫。”'),
    (2, 50, 124, '“Who are the wizards?” asked Dorothy.', '“谁是男巫啊？”多萝西问。'),
    (2, 51, 125, '“Oz himself is the Great Wizard,” answered the Witch, sinking her voice to a whisper.', '“奥兹大王自己就是最厉害的男巫，”女巫悄悄地说。'),
    (2, 51, 126, '“He is more powerful than all the rest of us together.', '“他比我们所有人都厉害得多。'),
    (2, 51, 127, 'He lives in the City of Emeralds.”', '他住在翡翠城里。”'),
    (2, 52, 128, 'Dorothy was going to ask another question, but just then the Munchkins, who had been standing silently by, gave a loud shout and pointed to the corner of the house where the Wicked Witch had been lying.', '多萝西刚想再问，可这时，一直没说话的芒奇金人突然大叫一声，指着屋角，那里就是坏女巫躺着的地方。'),
    (2, 53, 129, '“What is it?” asked the little old woman, and looked, and began to laugh.', '“怎么啦？”小老太太问，她看了一眼，就哈哈笑起来。'),
    (2, 53, 130, 'The feet of the dead Witch had disappeared entirely, and nothing was left but the silver shoes.', '死去的女巫的脚完全不见了，只剩下那双闪闪的银鞋子。'),
    (2, 54, 131, '“She was so old,” explained the Witch of the North, “that she dried up quickly in the sun.', '“她太老啦，”北方好女巫说，“在太阳下一晒，就很快变干了。'),
    (2, 54, 132, 'That is the end of her.', '她就这样不见了。'),
    (2, 54, 133, 'But the silver shoes are yours, and you shall have them to wear.”', '但这双银鞋是你的，你可以穿上它。”'),
    (2, 54, 134, 'She reached down and picked up the shoes, and after shaking the dust out of them handed them to Dorothy.', '她弯腰捡起鞋子，抖掉上面的灰尘，递给多萝西。'),
    (2, 55, 135, '“The Witch of the East was proud of those silver shoes,” said one of the Munchkins, “and there is some charm connected with them; but what it is we never knew.”', '“东方女巫很喜欢那双银鞋子，”一个芒奇金人说，“它们好像有魔法，可是我们从来都不知道那是什么魔法。”'),
    (2, 56, 136, 'Dorothy carried the shoes into the house and placed them on the table.', '多萝西把鞋子拿进屋里，放在桌子上。'),
    (2, 56, 137, 'Then she came out again to the Munchkins and said:', '然后她又出来对芒奇金人说：'),
    (2, 57, 138, '“I am anxious to get back to my aunt and uncle, for I am sure they will worry about me.', '“我好想快点回到我的叔叔和婶婶身边，他们肯定很担心我。'),
    (2, 57, 139, 'Can you help me find my way?”', '你们能帮我找到回家的路吗？”'),
    (2, 58, 140, 'The Munchkins and the Witch first looked at one another, and then at Dorothy, and then shook their heads.', '芒奇金人和女巫先是互相看，又看看多萝西，最后都摇了摇头。'),
    (2, 59, 141, '“At the East, not far from here,” said one, “there is a great desert, and none could live to cross it.”', '“在东方，离这里不远的地方，”一个人说，“有一片大沙漠，没有人能活着走过去。”'),
    (2, 60, 142, '“It is the same at the South,” said another, “for I have been there and seen it.', '“南方也是这样，”另一个人说，“因为我去过那里，亲眼看到了。'),
    (2, 60, 143, 'The South is the country of the Quadlings.”', '南方是奎德林人的国家。”'),
    (2, 61, 144, '“I am told,” said the third man, “that it is the same at the West.', '“我听说，”第三个人说，“西方也是这样。'),
    (2, 61, 145, 'And that country, where the Winkies live, is ruled by the Wicked Witch of the West, who would make you her slave if you passed her way.”', '那个国家，是温基人住的地方，由西方坏女巫来管，如果你从那里经过，她会让你变成她的仆人。”'),
    (2, 62, 146, '“The North is my home,” said the old lady, “and at its edge is the same great desert that surrounds this Land of Oz.', '“北方是我的家，”老太太说，“北方边上也是一片大沙漠，它把这个奥兹国团团围住。'),
    (2, 62, 147, 'I’m afraid, my dear, you will have to live with us.”', '亲爱的，看来你得跟我们一起住啦。”'),
    (2, 63, 148, 'Dorothy began to sob at this, for she felt lonely among all these strange people.', '多萝西听了这话，就哭了起来，因为在这些陌生人中间，她感到孤零零的。'),
    (2, 63, 149, 'Her tears seemed to grieve the kind-hearted Munchkins, for they immediately took out their handkerchiefs and began to weep also.', '她的眼泪好像让善良的芒奇金人也很难过，他们赶紧拿出自己的手帕，也跟着哭起来。'),
    (2, 63, 150, 'As for the little old woman, she took off her cap and balanced the point on the end of her nose, while she counted “One, two, three” in a solemn voice.', '那个小老太太呢，她摘下帽子，把帽尖稳稳地放在鼻尖上，然后用很认真的声音数着“一、二、三”。'),
    (2, 63, 151, 'At once the cap changed to a slate, on which was written in big, white chalk marks:', '帽子立刻变成一块石板，上面写着大大的白粉笔字：'),
    (2, 64, 152, '“LET DOROTHY GO TO THE CITY OF EMERALDS”', '“让多萝西去翡翠城”'),
    (2, 65, 153, 'The little old woman took the slate from her nose, and having read the words on it, asked, “Is your name Dorothy, my dear?”', '小老太太从鼻子上拿下石板，读了上面的字，问：“亲爱的，你叫多萝西吗？”'),
    (2, 66, 154, '“Yes,” answered the child, looking up and drying her tears.', '“是的。”孩子抬起头，擦干眼泪回答。'),
    (2, 67, 155, '“Then you must go to the City of Emeralds.', '“那你一定要去翡翠城。'),
    (2, 67, 156, 'Perhaps Oz will help you.”', '也许奥兹大王会帮你。”'),
    (2, 68, 157, '“Where is this city?” asked Dorothy.', '“这个城市在哪里？”多萝西问。'),
    (2, 69, 158, '“It is exactly in the center of the country, and is ruled by Oz, the Great Wizard I told you of.”', '“它就在国家的正中间，由我跟你说过的大魔法师奥兹大王统治。”'),
    (2, 70, 159, '“Is he a good man?” inquired the girl anxiously.', '“他是个好人吗？”女孩有点担心地问。'),
    (2, 71, 160, '“He is a good Wizard.', '“他是个好魔法师。'),
    (2, 71, 161, 'Whether he is a man or not I cannot tell, for I have never seen him.”', '他是不是人，我可不知道，因为我从没见过他。”'),
    (2, 72, 162, '“How can I get there?” asked Dorothy.', '“我怎么才能去那里呢？”多萝西问。'),
    (2, 73, 163, '“You must walk.', '“你必须走路去。'),
    (2, 73, 164, 'It is a long journey, through a country that is sometimes pleasant and sometimes dark and terrible.', '那是一段很长的路，要经过有时很美、有时又很黑很可怕的地方。'),
    (2, 73, 165, 'However, I will use all the magic arts I know of to keep you from harm.”', '不过，我会用我所有的魔法，让你不受伤害。”'),
    (2, 74, 166, '“Won’t you go with me?” pleaded the girl, who had begun to look upon the little old woman as her only friend.', '“你不能和我一起去吗？”女孩恳求道，她已经把小老太太当成自己唯一的朋友了。'),
    (2, 75, 167, '“No, I cannot do that,” she replied, “but I will give you my kiss, and no one will dare injure a person who has been kissed by the Witch of the North.”', '“不行，我不能那样做，”她回答，“但我会给你一个我的吻，被北方好女巫亲过的人，没人敢伤害她。”'),
    (2, 76, 168, 'She came close to Dorothy and kissed her gently on the forehead.', '她走近多萝西，轻轻地亲了亲她的额头。'),
    (2, 76, 169, 'Where her lips touched the girl they left a round, shining mark, as Dorothy found out soon after.', '她的嘴唇碰到女孩的地方，留下了一个圆圆的闪亮印记，多萝西很快就发现了。'),
    (2, 77, 170, '“The road to the City of Emeralds is paved with yellow brick,” said the Witch, “so you cannot miss it.', '“去翡翠城的路是用黄砖铺成的，”女巫说，“所以你不会迷路。'),
    (2, 77, 171, 'When you get to Oz do not be afraid of him, but tell your story and ask him to help you.', '等你到了奥兹大王那里，不要害怕他，要告诉他你的故事，请他帮助你。'),
    (2, 77, 172, 'Good-bye, my dear.”', '再见，亲爱的。”'),
    (2, 78, 173, 'The three Munchkins bowed low to her and wished her a pleasant journey, after which they walked away through the trees.', '三个芒奇金人向她深深地鞠了一躬，祝她旅途愉快，然后穿过树林走开了。'),
    (2, 78, 174, 'The Witch gave Dorothy a friendly little nod, whirled around on her left heel three times, and straightway disappeared, much to the surprise of little Toto, who barked after her loudly enough when she had gone, because he had been afraid even to growl while she stood by.', '女巫朝多萝西友善地点了点头，然后左脚跟转了三圈，立刻就消失了，这让小托托很惊讶，她在女巫走后大声地叫了起来，因为女巫在旁边的时候，它连哼一声都不敢。'),
    (2, 79, 175, 'But Dorothy, knowing her to be a witch, had expected her to disappear in just that way, and was not surprised in the least.', '但是多萝西知道她是个女巫，所以她早就料到女巫会那样消失，一点也不惊讶。'),
    (3, 80, 176, 'When Dorothy was left alone she began to feel hungry.', '多萝西一个人待着的时候，她开始感到饿了。'),
    (3, 80, 177, 'So she went to the cupboard and cut herself some bread, which she spread with butter.', '于是她走到碗柜前，切了些面包，又涂上黄油。'),
    (3, 80, 178, 'She gave some to Toto, and taking a pail from the shelf she carried it down to the little brook and filled it with clear, sparkling water.', '她分了些给托托，然后从架子上拿了一个水桶，提到小溪边，装满了清澈闪亮的水。'),
    (3, 80, 179, 'Toto ran over to the trees and began to bark at the birds sitting there.', '托托跑到树林那边，开始对着停在那里的鸟儿叫。'),
    (3, 80, 180, 'Dorothy went to get him, and saw such delicious fruit hanging from the branches that she gathered some of it, finding it just what she wanted to help out her breakfast.', '多萝西去叫它回来，看到了树枝上挂着好多好吃的水果，于是她摘了一些，发现这正是她早餐想吃的。'),
    (3, 81, 181, 'Then she went back to the house, and having helped herself and Toto to a good drink of the cool, clear water, she set about making ready for the journey to the City of Emeralds.', '她回到屋里，给自己和托托倒了一大杯清凉的水。喝完水，她就开始准备去翡翠城了。'),
    (3, 82, 182, 'Dorothy had only one other dress, but that happened to be clean and was hanging on a peg beside her bed.', '多萝西只有一条裙子，不过它很干净，正挂在床边的钩子上。'),
    (3, 82, 183, 'It was gingham, with checks of white and blue; and although the blue was somewhat faded with many washings, it was still a pretty frock.', '这条裙子是方格布做的，有白色和蓝色格子。虽然蓝色洗得有点旧了，但它还是很好看。'),
    (3, 82, 184, 'The girl washed herself carefully, dressed herself in the clean gingham, and tied her pink sunbonnet on her head.', '女孩仔细洗了洗，穿上干净的方格裙，再戴上她的粉色遮阳帽。'),
    (3, 82, 185, 'She took a little basket and filled it with bread from the cupboard, laying a white cloth over the top.', '她拿了一个小篮子，从柜子里拿出面包放进去，然后盖上一块白布。'),
    (3, 82, 186, 'Then she looked down at her feet and noticed how old and worn her shoes were.', '她低头看了看自己的脚，发现鞋子又旧又破了。'),
    (3, 83, 187, '“They surely will never do for a long journey, Toto,” she said.', '“这些鞋子肯定不能穿去长途旅行，托托，”她说道。'),
    (3, 83, 188, 'And Toto looked up into her face with his little black eyes and wagged his tail to show he knew what she meant.', '托托用它的小黑眼睛看着她，摇了摇尾巴，表示它懂她的意思。'),
    (3, 84, 189, 'At that moment Dorothy saw lying on the table the silver shoes that had belonged to the Witch of the East.', '这时，多萝西看到桌上放着一双银鞋，那是东方女巫的。'),
    (3, 85, 190, '“I wonder if they will fit me,” she said to Toto.', '“不知道它们合不合我的脚？”她对托托说。'),
    (3, 85, 191, '“They would be just the thing to take a long walk in, for they could not wear out.”', '“穿着它们走远路最好不过了，因为它们不会穿坏。”'),
    (3, 86, 192, 'She took off her old leather shoes and tried on the silver ones, which fitted her as well as if they had been made for her.', '她脱掉旧皮鞋，穿上银鞋。银鞋穿在她脚上，就像是专门为她做的一样合脚。'),
    (3, 87, 193, 'Finally she picked up her basket.', '最后，她拿起她的篮子。'),
    (3, 88, 194, '“Come along, Toto,” she said.', '“来吧，托托，”她说道。'),
    (3, 88, 195, '“We will go to the Emerald City and ask the Great Oz how to get back to Kansas again.”', '“我们去翡翠城，问问伟大的奥兹大王怎么才能回到堪萨斯。”'),
    (3, 89, 196, 'She closed the door, locked it, and put the key carefully in the pocket of her dress.', '她关上门，锁好，然后小心地把钥匙放进裙子的口袋里。'),
    (3, 89, 197, 'And so, with Toto trotting along soberly behind her, she started on her journey.', '于是，托托在她身后稳稳地小跑着，她开始了旅程。'),
    (3, 90, 198, 'There were several roads nearby, but it did not take her long to find the one paved with yellow bricks.', '附近有几条路，但她很快就找到了那条用黄砖铺成的路。'),
    (3, 90, 199, 'Within a short time she was walking briskly toward the Emerald City, her silver shoes tinkling merrily on the hard, yellow road-bed.', '没过多久，她就轻快地走向翡翠城，她的银鞋在坚硬的黄砖路上发出清脆的响声。'),
    (3, 90, 200, 'The sun shone bright and the birds sang sweetly, and Dorothy did not feel nearly so bad as you might think a little girl would who had been suddenly whisked away from her own country and set down in the midst of a strange land.', '阳光明媚，小鸟唱着甜美的歌。多萝西并没有你想象的那么难过，虽然她突然被带离自己的家乡，来到了一个陌生的地方。'),
    (3, 91, 201, 'She was surprised, as she walked along, to see how pretty the country was about her.', '她边走边看，惊讶地发现周围的景色真漂亮。'),
    (3, 91, 202, 'There were neat fences at the sides of the road, painted a dainty blue color, and beyond them were fields of grain and vegetables in abundance.', '路边有整齐的蓝色小栅栏，栅栏后面是满满的庄稼和蔬菜地。'),
    (3, 91, 203, 'Evidently the Munchkins were good farmers and able to raise large crops.', '看来芒奇金人都是好农民，能种出很多庄稼。'),
    (3, 91, 204, 'Once in a while she would pass a house, and the people came out to look at her and bow low as she went by; for everyone knew she had been the means of destroying the Wicked Witch and setting them free from bondage.', '她偶尔会经过一栋房子，人们会出来看她，在她经过时深深鞠躬；因为每个人都知道，她帮他们打败了坏女巫，让他们摆脱了束缚。'),
    (3, 91, 205, 'The houses of the Munchkins were odd-looking dwellings, for each was round, with a big dome for a roof.', '芒奇金人的房子很奇怪，每栋都是圆圆的，屋顶像个大圆顶。'),
    (3, 91, 206, 'All were painted blue, for in this country of the East blue was the favorite color.', '所有的房子都涂成了蓝色，因为在这个东方国家，蓝色是大家最喜欢的颜色。'),
    (3, 92, 207, 'Toward evening, when Dorothy was tired with her long walk and began to wonder where she should pass the night, she came to a house rather larger than the rest.', '傍晚时分，多萝西走了很久，有点累了，她开始想今晚在哪里过夜。这时，她走到一栋比其他房子大一些的屋子前。'),
    (3, 92, 208, 'On the green lawn before it many men and women were dancing.', '屋前的绿色草坪上，许多男人和女人正在跳舞。'),
    (3, 92, 209, 'Five little fiddlers played as loudly as possible, and the people were laughing and singing, while a big table near by was loaded with delicious fruits and nuts, pies and cakes, and many other good things to eat.', '五个小提琴手拉着琴，声音很大。人们又笑又唱，旁边的大桌子上摆满了好吃的水果、坚果、馅饼、蛋糕和许多其他美味。'),
    (3, 93, 210, 'The people greeted Dorothy kindly, and invited her to supper and to pass the night with them; for this was the home of one of the richest Munchkins in the land, and his friends were gathered with him to celebrate their freedom from the bondage of the Wicked Witch.', '人们亲切地问候多萝西，请她一起吃晚饭，并在他们家过夜。因为这是这片土地上最富有的芒奇金人的家，他的朋友们都聚在这里，庆祝他们摆脱了坏女巫的束缚。'),
    (3, 94, 211, 'Dorothy ate a hearty supper and was waited upon by the rich Munchkin himself, whose name was Boq.', '多萝西 吃了一顿好吃的晚饭，很有钱的 芒奇金人 博克亲自来招待她。'),
    (3, 94, 212, 'Then she sat upon a settee and watched the people dance.', '然后她坐在一张沙发上，看大家跳舞。'),
    (3, 95, 213, 'When Boq saw her silver shoes he said, “You must be a great sorceress.”', '博克看到她的银鞋子，就说：“你一定是个很厉害的女巫师！”'),
    (3, 96, 214, '“Why?” asked the girl.', '女孩问：“为什么呢？”'),
    (3, 97, 215, '“Because you wear silver shoes and have killed the Wicked Witch.', '“因为你穿着银色的鞋子，还把 坏女巫 杀死了。'),
    (3, 97, 216, 'Besides, you have white in your frock, and only witches and sorceresses wear white.”', '而且，你的裙子上有白色，只有女巫和女巫师才穿白色。”'),
    (3, 98, 217, '“My dress is blue and white checked,” said Dorothy, smoothing out the wrinkles in it.', '多萝西 抚平裙子上的褶子说：“我的裙子是蓝色和白色格子的。”'),
    (3, 99, 218, '“It is kind of you to wear that,” said Boq.', '博克说：“你穿这件衣服真好。”'),
    (3, 99, 219, '“Blue is the color of the Munchkins, and white is the witch color.', '“蓝色是 芒奇金人 的颜色，白色是女巫的颜色。'),
    (3, 99, 220, 'So we know you are a friendly witch.”', '所以我们知道你是个友善的女巫。”'),
    (3, 100, 221, 'Dorothy did not know what to say to this, for all the people seemed to think her a witch, and she knew very well she was only an ordinary little girl who had come by the chance of a cyclone into a strange land.', '多萝西 不知道该说什么，因为所有人都觉得她是个女巫。她明明知道自己只是个普通小女孩，只是因为一阵龙卷风才来到了这个陌生的地方。'),
    (3, 101, 222, 'When she had tired watching the dancing, Boq led her into the house, where he gave her a room with a pretty bed in it.', '她看跳舞看累了，博克就带她进了屋子，给了她一间有漂亮床的房间。'),
    (3, 101, 223, 'The sheets were made of blue cloth, and Dorothy slept soundly in them till morning, with Toto curled up on the blue rug beside her.', '床单是蓝色的布做的，多萝西 在上面睡得很香，一直到早上。托托 卷缩在她身边的蓝色地毯上。'),
    (3, 102, 224, 'She ate a hearty breakfast, and watched a wee Munchkin baby, who played with Toto and pulled his tail and crowed and laughed in a way that greatly amused Dorothy.', '她吃了一顿丰盛的早餐，看着一个小小 芒奇金人 婴儿玩 托托，拉它的尾巴，咯咯地笑，这让 多萝西 觉得很有趣。'),
    (3, 102, 225, 'Toto was a fine curiosity to all the people, for they had never seen a dog before.', '托托 让所有人都很好奇，因为他们以前从没见过小狗。'),
    (3, 103, 226, '“How far is it to the Emerald City?” the girl asked.', '女孩问：“到 翡翠城 还有多远？”'),
    (3, 104, 227, '“I do not know,” answered Boq gravely, “for I have never been there.', '博克认真地回答：“我不知道，因为我从来没去过那里。'),
    (3, 104, 228, 'It is better for people to keep away from Oz, unless they have business with him.', '最好大家离 奥兹大王 远一点，除非有事情找他。'),
    (3, 104, 229, 'But it is a long way to the Emerald City, and it will take you many days.', '但是到 翡翠城 的路很远，你要走很多天。'),
    (3, 104, 230, 'The country here is rich and pleasant, but you must pass through rough and dangerous places before you reach the end of your journey.”', '这里很漂亮，东西也多，但是你必须经过一些又难走又危险的地方，才能到达旅程的终点。”'),
    (3, 105, 231, 'This worried Dorothy a little, but she knew that only the Great Oz could help her get to Kansas again, so she bravely resolved not to turn back.', '多萝西 有点担心，但她知道只有大 奥兹大王 才能帮她回到 堪萨斯，所以她勇敢地决定不回头。'),
    (3, 106, 232, 'She bade her friends good-bye, and again started along the road of yellow brick.', '她跟朋友们说了再见，又沿着黄砖路出发了。'),
    (3, 106, 233, 'When she had gone several miles she thought she would stop to rest, and so climbed to the top of the fence beside the road and sat down.', '她走了好几英里后，想停下来休息一下，就爬到路边的篱笆顶上坐了下来。'),
    (3, 106, 234, 'There was a great cornfield beyond the fence, and not far away she saw a Scarecrow, placed high on a pole to keep the birds from the ripe corn.', '篱笆后面有一大片玉米地，不远处她看到一个 稻草人，高高地立在杆子上，用来吓跑吃玉米的鸟。'),
    (3, 107, 235, 'Dorothy leaned her chin upon her hand and gazed thoughtfully at the Scarecrow.', '多萝西 用手托着下巴，认真地看着 稻草人。'),
    (3, 107, 236, 'Its head was a small sack stuffed with straw, with eyes, nose, and mouth painted on it to represent a face.', '它的头是一个塞满稻草的小袋子，上面画着眼睛、鼻子和嘴巴，像一张脸。'),
    (3, 107, 237, 'An old, pointed blue hat, that had belonged to some Munchkin, was perched on his head, and the rest of the figure was a blue suit of clothes, worn and faded, which had also been stuffed with straw.', '它的头上戴着一顶旧旧的蓝色尖帽子，这帽子以前是某个 芒奇金人 的。它的身体是一套蓝色衣服，又旧又褪色，里面也塞满了稻草。'),
    (3, 107, 238, 'On the feet were some old boots with blue tops, such as every man wore in this country, and the figure was raised above the stalks of corn by means of the pole stuck up its back.', '它的脚上穿着旧靴子，上面是蓝色的，就像这个国家所有男人穿的那样。它的背上插着一根杆子，让它高高地立在玉米秆上面。'),
    (3, 108, 239, 'While Dorothy was looking earnestly into the queer, painted face of the Scarecrow, she was surprised to see one of the eyes slowly wink at her.', '多萝西 正在仔细地看着 稻草人 那张奇怪的、画出来的脸，突然惊讶地看到其中一只眼睛慢慢地冲她眨了一下。'),
    (3, 108, 240, 'She thought she must have been mistaken at first, for none of the scarecrows in Kansas ever wink; but presently the figure nodded its head to her in a friendly way.', '她一开始以为自己看错了，因为 堪萨斯 里的稻草人从来不会眨眼。但很快，那个稻草人友好地向她点了点头。'),
    (3, 108, 241, 'Then she climbed down from the fence and walked up to it, while Toto ran around the pole and barked.', '她从篱笆上爬下来，走到那儿。托托呢，它围着杆子跑来跑去，叫个不停。'),
    (3, 109, 242, '“Good day,” said the Scarecrow, in a rather husky voice.', '“你好啊！”稻草人声音有点粗粗地说。'),
    (3, 110, 243, '“Did you speak?” asked the girl, in wonder.', '“你、你会说话？”小女孩好奇地问。'),
    (3, 111, 244, '“Certainly,” answered the Scarecrow.', '“当然啦！”稻草人回答说。'),
    (3, 111, 245, '“How do you do?”', '“你好吗？”'),
    (3, 112, 246, '“I’m pretty well, thank you,” replied Dorothy politely.', '“我挺好的，谢谢你。”多萝西很有礼貌地回答。'),
    (3, 112, 247, '“How do you do?”', '“你好吗？”'),
    (3, 113, 248, '“I’m not feeling well,” said the Scarecrow, with a smile, “for it is very tedious being perched up here night and day to scare away crows.”', '“我不太好。”稻草人笑着说，“每天晚上白天都站在这儿，赶乌鸦，太无聊啦。”'),
    (3, 114, 249, '“Can’t you get down?” asked Dorothy.', '“你不能下来吗？”多萝西问。'),
    (3, 115, 250, '“No, for this pole is stuck up my back.', '“不行啊，这根杆子插在我背上呢。'),
    (3, 115, 251, 'If you will please take away the pole I shall be greatly obliged to you.”', '如果你能把杆子拿开，我会非常感谢你的。”'),
    (3, 116, 252, 'Dorothy reached up both arms and lifted the figure off the pole, for, being stuffed with straw, it was quite light.', '多萝西伸出两只胳膊，把那个东西从杆子上拿了下来。因为它里面都是稻草，所以很轻。'),
    (3, 117, 253, '“Thank you very much,” said the Scarecrow, when he had been set down on the ground.', '“太谢谢你啦！”当稻草人被放到地上时，它说。'),
    (3, 117, 254, '“I feel like a new man.”', '“我感觉自己像个新的人！”'),
    (3, 118, 255, 'Dorothy was puzzled at this, for it sounded queer to hear a stuffed man speak, and to see him bow and walk along beside her.', '多萝西觉得很奇怪，因为一个用稻草做的假人说话，还会鞠躬，然后跟她一起走路，听起来真是不可思议。'),
    (3, 119, 256, '“Who are you?” asked the Scarecrow when he had stretched himself and yawned. “And where are you going?”', '“你是谁呀？”稻草人伸了个懒腰，打了个哈欠，然后问，“你要去哪儿啊？”'),
    (3, 120, 257, '“My name is Dorothy,” said the girl, “and I am going to the Emerald City, to ask the Great Oz to send me back to Kansas.”', '“我叫多萝西。”小女孩说，“我要去翡翠城，请伟大的奥兹大王把我送回堪萨斯去。”'),
    (3, 121, 258, '“Where is the Emerald City?” he inquired. “And who is Oz?”', '“翡翠城在哪里？”它问，“奥兹大王又是谁呀？”'),
    (3, 122, 259, '“Why, don’t you know?” she returned, in surprise.', '“咦，你不知道吗？”她很惊讶地问。'),
    (3, 123, 260, '“No, indeed.', '“不，真的不知道。'),
    (3, 123, 261, 'I don’t know anything.', '我什么都不知道。'),
    (3, 123, 262, 'You see, I am stuffed, so I have no brains at all,” he answered sadly.', '你看，我里面都是稻草，所以根本没有脑子。”它伤心地回答。'),
    (3, 124, 263, '“Oh,” said Dorothy, “I’m awfully sorry for you.”', '“哦，”多萝西说，“我真替你难过。”'),
    (3, 125, 264, '“Do you think,” he asked, “if I go to the Emerald City with you, that Oz would give me some brains?”', '“你觉得，”它问，“如果我跟你一起去翡翠城，奥兹大王会给我一些脑子吗？”'),
    (3, 126, 265, '“I cannot tell,” she returned, “but you may come with me, if you like.', '“我不能确定。”她回答，“但是如果你想，你可以跟我一起来。'),
    (3, 126, 266, 'If Oz will not give you any brains you will be no worse off than you are now.”', '如果奥兹大王不给你脑子，你也不会比现在更糟糕。”'),
    (3, 127, 267, '“That is true,” said the Scarecrow.', '“那倒是真的。”稻草人说。'),
    (3, 127, 268, '“You see,” he continued confidentially, “I don’t mind my legs and arms and body being stuffed, because I cannot get hurt.', '“你看啊，”它悄悄地接着说，“我腿啊、胳膊啊、身体啊，里面都是稻草，我一点都不介意，因为我不会受伤。'),
    (3, 127, 269, 'If anyone treads on my toes or sticks a pin into me, it doesn’t matter, for I can’t feel it.', '要是谁踩到我的脚趾头，或者用针扎我，都没关系，因为我感觉不到疼。'),
    (3, 127, 270, 'But I do not want people to call me a fool, and if my head stays stuffed with straw instead of with brains, as yours is, how am I ever to know anything?”', '可是我不想让别人叫我笨蛋，如果我的脑袋一直只有稻草，没有像你一样的脑子，那我怎么能知道很多事情呢？”'),
    (3, 128, 271, '“I understand how you feel,” said the little girl, who was truly sorry for him.', '“我懂你的感受，”小女孩说，她真的很替他难过。'),
    (3, 128, 272, '“If you will come with me I’ll ask Oz to do all he can for you.”', '“如果你跟我来，我就会请奥兹大王尽力帮你。”'),
    (3, 129, 273, '“Thank you,” he answered gratefully.', '“谢谢你，”他开心地回答说。'),
    (3, 130, 274, 'They walked back to the road.', '他们走回了路上。'),
    (3, 130, 275, 'Dorothy helped him over the fence, and they started along the path of yellow brick for the Emerald City.', '多萝西扶他过了篱笆，他们沿着黄砖路，往翡翠城的方向走去。'),
    (3, 131, 276, 'Toto did not like this addition to the party at first.', '一开始，托托不喜欢这个新加入的伙伴。'),
    (3, 131, 277, 'He smelled around the stuffed man as if he suspected there might be a nest of rats in the straw, and he often growled in an unfriendly way at the Scarecrow.', '它闻了闻那个填充人，好像觉得稻草里有老鼠。它还常常不高兴地对稻草人低吼。'),
    (3, 132, 278, '“Don’t mind Toto,” said Dorothy to her new friend.', '“别理托托，”多萝西对她的新朋友说。'),
    (3, 132, 279, '“He never bites.”', '“他从来不咬人。”'),
    (3, 133, 280, '“Oh, I’m not afraid,” replied the Scarecrow.', '“哦，我不怕，”稻草人回答说。'),
    (3, 133, 281, '“He can’t hurt the straw.', '“他伤不了稻草的。'),
    (3, 133, 282, 'Do let me carry that basket for you.', '让我帮你提那个篮子吧。'),
    (3, 133, 283, 'I shall not mind it, for I can’t get tired.', '我不会觉得累，因为我不会累的。'),
    (3, 133, 284, 'I’ll tell you a secret,” he continued, as he walked along.', '我告诉你一个秘密，”他边走边说。'),
    (3, 133, 285, '“There is only one thing in the world I am afraid of.”', '“世界上我只怕一样东西。”'),
    (3, 134, 286, '“What is that?” asked Dorothy; “the Munchkin farmer who made you?”', '“那是什么？”多萝西问，“是做你的那个芒奇金人农夫吗？”'),
    (3, 135, 287, '“No,” answered the Scarecrow; “it’s a lighted match.”', '“不是，”稻草人回答说，“是一根点燃的火柴。”'),
    (4, 136, 288, 'After a few hours the road began to be rough, and the walking grew so difficult that the Scarecrow often stumbled over the yellow bricks, which were here very uneven.', '几个小时后，路变得不平了。走路很难，稻草人老是被绊倒，因为这里的黄砖很不平。'),
    (4, 136, 289, 'Sometimes, indeed, they were broken or missing altogether, leaving holes that Toto jumped across and Dorothy walked around.', '有时，黄砖甚至碎了或者完全不见了，留下了坑洞，托托跳了过去，多萝西绕了过去。'),
    (4, 136, 290, 'As for the Scarecrow, having no brains, he walked straight ahead, and so stepped into the holes and fell at full length on the hard bricks.', '至于那个稻草人，他没有脑子，只顾往前走，所以就踩进了坑里，重重地摔在硬砖上。'),
    (4, 136, 291, 'It never hurt him, however, and Dorothy would pick him up and set him upon his feet again, while he joined her in laughing merrily at his own mishap.', '他从来不会受伤。多萝西会扶他起来站好，他也会跟多萝西一起，开心地笑自己摔倒了。'),
    (4, 137, 292, 'The farms were not nearly so well cared for here as they were farther back.', '这里的农场没有后面那些地方照看得那么好。'),
    (4, 137, 293, 'There were fewer houses and fewer fruit trees, and the farther they went the more dismal and lonesome the country became.', '房子和果树都变少了，他们走得越远，乡村就变得越荒凉和寂寞。'),
    (4, 138, 294, 'At noon they sat down by the roadside, near a little brook, and Dorothy opened her basket and got out some bread.', '中午时分，他们在一个小溪边，坐在路边。多萝西打开篮子，拿出了一些面包。'),
    (4, 138, 295, 'She offered a piece to the Scarecrow, but he refused.', '她递了一块给那个稻草人，但他不要。'),
    (4, 139, 296, '“I am never hungry,” he said, “and it is a lucky thing I am not, for my mouth is only painted, and if I should cut a hole in it so I could eat, the straw I am stuffed with would come out, and that would spoil the shape of my head.”', '“我从来不饿，”他说，“我不饿真好，因为我的嘴巴只是画上去的。如果我剪个洞吃东西，里面的稻草就会掉出来，那样我的头就会变形了。”'),
    (4, 140, 297, 'Dorothy saw at once that this was true, so she only nodded and went on eating her bread.', '多萝西一下子就明白他说的是真的，所以她只是点点头，继续吃她的面包。'),
    (4, 141, 298, '“Tell me something about yourself and the country you came from,” said the Scarecrow, when she had finished her dinner.', '她吃完饭后，那个稻草人说：“跟我说说你自己，还有你来的那个地方吧。”'),
    (4, 141, 299, 'So she told him all about Kansas, and how gray everything was there, and how the cyclone had carried her to this queer Land of Oz.', '于是她告诉他关于堪萨斯的一切，那里的一切都是灰蒙蒙的，还有龙卷风怎么把她带到了这个奇怪的奥兹国。'),
    (4, 142, 300, 'The Scarecrow listened carefully, and said, “I cannot understand why you should wish to leave this beautiful country and go back to the dry, gray place you call Kansas.”', '那个稻草人认真地听着，然后说：“我不明白你为什么要离开这个美丽的地方，回到你说的那个又干又灰的堪萨斯去。”'),
    (4, 143, 301, '“That is because you have no brains” answered the girl.', '“那是因为你没有脑子呀！”小女孩回答说。'),
    (4, 143, 302, '“No matter how dreary and gray our homes are, we people of flesh and blood would rather live there than in any other country, be it ever so beautiful.', '“不管我们的家多么灰暗、多么无趣，我们这些有血有肉的人，宁愿住在家里，也不愿去其他再美的地方。'),
    (4, 143, 303, 'There is no place like home.”', '没有比家更好的地方了。”'),
    (4, 144, 304, 'The Scarecrow sighed.', '那个稻草人叹了口气。'),
    (4, 145, 305, '“Of course I cannot understand it,” he said.', '“我当然不明白，”他说。'),
    (4, 145, 306, '“If your heads were stuffed with straw, like mine, you would probably all live in the beautiful places, and then Kansas would have no people at all.', '“如果你们的脑袋里也像我一样塞满了稻草，你们可能都会住在那些美丽的地方，那样的话，堪萨斯就一个人都没有了。'),
    (4, 145, 307, 'It is fortunate for Kansas that you have brains.”', '堪萨斯很幸运你们有脑子。”'),
    (4, 146, 308, '“Won’t you tell me a story, while we are resting?” asked the child.', '“我们休息的时候，你给我讲个故事好不好？”孩子问道。'),
    (4, 147, 309, 'The Scarecrow looked at her reproachfully, and answered:', '那个稻草人责备地看了她一眼，然后回答说：'),
    (4, 148, 310, '“My life has been so short that I really know nothing whatever.', '“我的生命太短了，什么都不知道。'),
    (4, 148, 311, 'I was only made day before yesterday.', '我前天才被做出来。'),
    (4, 148, 312, 'What happened in the world before that time is all unknown to me.', '在这之前世界上发生了什么，我一点也不知道。'),
    (4, 148, 313, 'Luckily, when the farmer made my head, one of the first things he did was to paint my ears, so that I heard what was going on.', '幸好，农民叔叔做我脑袋的时候，最先做的一件事就是给我画耳朵，所以我听到了发生的一切。'),
    (4, 148, 314, 'There was another Munchkin with him, and the first thing I heard was the farmer saying, ‘How do you like those ears?’', '当时还有一个芒奇金人在他身边，我听到的第一句话就是农民叔叔问：‘你觉得这耳朵怎么样？’'),
    (4, 149, 315, '“‘They aren’t straight,’” answered the other.', '“‘它们不直呀，’”另一个回答说。'),
    (4, 150, 316, '“‘Never mind,’” said the farmer.', '“‘没关系，’”农民叔叔说。'),
    (4, 150, 317, '“‘They are ears just the same,’” which was true enough.', '“‘它们一样是耳朵，’”这话倒也挺对。'),
    (4, 151, 318, '“‘Now I’ll make the eyes,’” said the farmer.', '“‘现在我来做眼睛，’”农民叔叔说。'),
    (4, 151, 319, 'So he painted my right eye, and as soon as it was finished I found myself looking at him and at everything around me with a great deal of curiosity, for this was my first glimpse of the world.', '于是他画了我的右眼，眼睛一画好，我就好奇地看着他和周围的一切，因为这是我第一次看到这个世界。'),
    (4, 152, 320, '“‘That’s a rather pretty eye,’” remarked the Munchkin who was watching the farmer.', '“‘这眼睛挺好看的，’”那个看着农民叔叔的芒奇金人说。'),
    (4, 152, 321, '“‘Blue paint is just the color for eyes.’', '“‘蓝色颜料最适合做眼睛了。’'),
    (4, 153, 322, '“‘I think I’ll make the other a little bigger,’” said the farmer.', '“‘我想把另一只眼睛画大一点，’”农民叔叔说。'),
    (4, 153, 323, 'And when the second eye was done I could see much better than before.', '第二只眼睛画好后，我看得比以前清楚多了。'),
    (4, 153, 324, 'Then he made my nose and my mouth.', '然后他做了我的鼻子和嘴巴。'),
    (4, 153, 325, 'But I did not speak, because at that time I didn’t know what a mouth was for.', '但我没说话，因为那时候我不知道嘴巴是用来干什么的。'),
    (4, 153, 326, 'I had the fun of watching them make my body and my arms and legs; and when they fastened on my head, at last, I felt very proud, for I thought I was just as good a man as anyone.', '我看着他们做我的身体、胳膊和腿，觉得很有趣；最后他们把我的头安上去的时候，我非常骄傲，因为我觉得我跟其他人一样棒。'),
    (4, 154, 327, '“‘This fellow will scare the crows fast enough,’ said the farmer.', '“‘这家伙能很快把乌鸦吓跑，’”农民叔叔说。'),
    (4, 154, 328, '‘He looks just like a man.’', '‘他看起来真像个人。’'),
    (4, 155, 329, '“‘Why, he is a man,’ said the other, and I quite agreed with him.', '“‘哎呀，他就是一个人呀！’”另一个人说，我非常同意他的话。'),
    (4, 155, 330, 'The farmer carried me under his arm to the cornfield, and set me up on a tall stick, where you found me.', '农民叔叔把我夹在胳膊下面，带到玉米地里，把我立在一根高高的杆子上，你就是在那里找到我的。'),
    (4, 155, 331, 'He and his friend soon after walked away and left me alone.', '他和他的朋友很快就走了，把我一个人留在那儿。'),
    (4, 156, 332, '“I did not like to be deserted this way.', '“我不喜欢这样被丢下。'),
    (4, 156, 333, 'So I tried to walk after them.', '所以我试着去追他们。'),
    (4, 156, 334, 'But my feet would not touch the ground, and I was forced to stay on that pole.', '但是我的脚碰不到地，我只好待在那根杆子上。'),
    (4, 156, 335, 'It was a lonely life to lead, for I had nothing to think of, having been made such a little while before.', '我过得很孤单，因为我刚做好没多久，什么都不知道。'),
    (4, 156, 336, 'Many crows and other birds flew into the cornfield, but as soon as they saw me they flew away again, thinking I was a Munchkin; and this pleased me and made me feel that I was quite an important person.', '好多乌鸦和其他鸟飞到玉米地里，可是一看到我，它们就又飞走了，以为我是一个芒奇金人；这让我很高兴，觉得自己是个很重要的人。'),
    (4, 156, 337, 'By and by an old crow flew near me, and after looking at me carefully he perched upon my shoulder and said:', '过了一会儿，一只老乌鸦飞到我身边，仔细看了看我，然后落在我的肩膀上说：'),
    (4, 157, 338, '“‘I wonder if that farmer thought to fool me in this clumsy manner.', '“‘我猜那个农夫是不是想用这种笨方法骗我。'),
    (4, 157, 339, 'Any crow of sense could see that you are only stuffed with straw.’', '任何一只聪明的乌鸦都能看出来，你只是个草人罢了。’'),
    (4, 157, 340, 'Then he hopped down at my feet and ate all the corn he wanted.', '然后他跳到我脚边，想吃多少玉米就吃多少。'),
    (4, 157, 341, 'The other birds, seeing he was not harmed by me, came to eat the corn too, so in a short time there was a great flock of them about me.', '别的鸟看到他没有被我伤害，也过来吃玉米了，没一会儿，我身边就围着一大群鸟。'),
    (4, 158, 342, '“I felt sad at this, for it showed I was not such a good Scarecrow after all; but the old crow comforted me, saying, ‘If you only had brains in your head you would be as good a man as any of them, and a better man than some of them.', '我为此感到难过，因为这说明我根本不是一个好稻草人；但是那只老乌鸦安慰我说，‘如果你脑袋里有脑子，你就会和他们任何人一样棒，甚至比他们中的一些人还要棒。'),
    (4, 158, 343, 'Brains are the only things worth having in this world, no matter whether one is a crow or a man.’', '在这个世界上，脑子是唯一值得拥有的东西，不管你是一只乌鸦还是一个人。’'),
    (4, 159, 344, '“After the crows had gone I thought this over, and decided I would try hard to get some brains.', '乌鸦们走了以后，我把这件事想了又想，决定要努力去得到一些脑子。'),
    (4, 159, 345, 'By good luck you came along and pulled me off the stake, and from what you say I am sure the Great Oz will give me brains as soon as we get to the Emerald City.”', '很幸运你来了，把我从木桩上拉了下来，听你说的，我相信等我们到了翡翠城，伟大的奥兹大王就会给我脑子。”'),
    (4, 160, 346, '“I hope so,” said Dorothy earnestly, “since you seem anxious to have them.”', '“我希望是这样。”多萝西认真地说，“因为你看起来很想得到它们。”'),
    (4, 161, 347, '“Oh, yes; I am anxious,” returned the Scarecrow.', '“哦，是的！我特别想。”稻草人回答说。'),
    (4, 161, 348, '“It is such an uncomfortable feeling to know one is a fool.”', '“知道自己是个傻瓜，这种感觉太难受了。”'),
    (4, 162, 349, '“Well,” said the girl, “let us go.”', '“好吧，”小女孩说，“我们走吧。”'),
    (4, 162, 350, 'And she handed the basket to the Scarecrow.', '她把篮子递给了稻草人。'),
    (4, 163, 351, 'There were no fences at all by the roadside now, and the land was rough and untilled.', '现在路边已经完全没有栅栏了，土地也很荒凉，没有人耕种。'),
    (4, 163, 352, 'Toward evening they came to a great forest, where the trees grew so big and close together that their branches met over the road of yellow brick.', '傍晚时分，他们来到了一片大森林，那里的树又高又密，树枝都碰到了一起，盖住了黄砖路。'),
    (4, 163, 353, 'It was almost dark under the trees, for the branches shut out the daylight; but the travelers did not stop, and went on into the forest.', '树底下几乎是黑的，因为树枝挡住了阳光；但是旅行者们没有停下，继续往前走进了森林。'),
    (4, 164, 354, '“If this road goes in, it must come out,” said the Scarecrow, “and as the Emerald City is at the other end of the road, we must go wherever it leads us.”', '“如果这条路能进去，那它就一定能出去，”稻草人说，“而且翡翠城就在路的另一头，所以我们必须顺着这条路走下去。”'),
    (4, 165, 355, '“Anyone would know that,” said Dorothy.', '“谁都知道这个。”多萝西说。'),
    (4, 166, 356, '“Certainly; that is why I know it,” returned the Scarecrow.', '“当然了；所以我才知道啊。”稻草人回答说。'),
    (4, 166, 357, '“If it required brains to figure it out, I never should have said it.”', '“要是想明白这个需要脑子，那我肯定就说不出来了。”'),
    (4, 167, 358, 'After an hour or so the light faded away, and they found themselves stumbling along in the darkness.', '过了一个小时左右，光线就消失了，他们只好在黑暗中摸索着往前走。'),
    (4, 167, 359, 'Dorothy could not see at all, but Toto could, for some dogs see very well in the dark; and the Scarecrow declared he could see as well as by day.', '多萝西什么也看不见，但是托托能看见，因为有些狗狗在黑暗中看得很清楚；而稻草人也说他白天晚上都看得见。'),
    (4, 167, 360, 'So she took hold of his arm and managed to get along fairly well.', '于是她抓住了他的胳膊，勉强还能走得挺好。'),
    (4, 168, 361, '“If you see any house, or any place where we can pass the night,” she said, “you must tell me; for it is very uncomfortable walking in the dark.”', '她说：“如果你看到房子，或者可以睡觉的地方，你要告诉我；因为天黑了走路很不舒服。”'),
    (4, 169, 362, 'Soon after the Scarecrow stopped.', '没过多久，稻草人停了下来。'),
    (4, 170, 363, '“I see a little cottage at the right of us,” he said, “built of logs and branches.', '他说：“我看到右边有个小房子，是用木头和树枝搭的。'),
    (4, 170, 364, 'Shall we go there?”', '我们去那里好不好？”'),
    (4, 171, 365, '“Yes, indeed,” answered the child.', '孩子回答说：“好啊，当然好啦！”'),
    (4, 171, 366, '“I am all tired out.”', '“我太累了。”'),
    (4, 172, 367, 'So the Scarecrow led her through the trees until they reached the cottage, and Dorothy entered and found a bed of dried leaves in one corner.', '于是，稻草人带着她穿过树林，直到他们走到那个小房子。多萝西走了进去，在一个角落里找到了一张用干树叶铺的床。'),
    (4, 172, 368, 'She lay down at once, and with Toto beside her soon fell into a sound sleep.', '她马上躺了下来，托托在她身边，她很快就睡着了。'),
    (4, 172, 369, 'The Scarecrow, who was never tired, stood up in another corner and waited patiently until morning came.', '稻草人从来不觉得累，它站在另一个角落里，一直耐心地等着，直到天亮。'),
    (5, 173, 370, 'When Dorothy awoke the sun was shining through the trees and Toto had long been out chasing birds around him and squirrels.', '多萝西醒来的时候，太阳光透过树林照了进来，托托早就出去追小鸟和松鼠了。'),
    (5, 173, 371, 'She sat up and looked around her.', '她坐了起来，看看周围。'),
    (5, 173, 372, 'There was the Scarecrow, still standing patiently in his corner, waiting for her.', '稻草人还在那里，仍然耐心又安静地站在角落里等着她。'),
    (5, 174, 373, '“We must go and search for water,” she said to him.', '她对他说：“我们得去找水。”'),
    (5, 175, 374, '“Why do you want water?” he asked.', '他问：“你为什么要水呀？”'),
    (5, 176, 375, '“To wash my face clean after the dust of the road, and to drink, so the dry bread will not stick in my throat.”', '“为了洗掉脸上的灰尘，让脸变干净。还要喝水，这样干面包就不会卡在我的喉咙里了。”'),
    (5, 177, 376, '“It must be inconvenient to be made of flesh,” said the Scarecrow thoughtfully, “for you must sleep, and eat and drink.', '稻草人想了想说：“用肉做的身体真不方便啊，因为你得睡觉，还得吃东西喝水。'),
    (5, 177, 377, 'However, you have brains, and it is worth a lot of bother to be able to think properly.”', '不过，你有脑袋，能好好思考，就算麻烦一点也值得。”'),
    (5, 178, 378, 'They left the cottage and walked through the trees until they found a little spring of clear water, where Dorothy drank and bathed and ate her breakfast.', '他们离开了小房子，穿过树林，走到找到一个清澈的小泉水的地方，多萝西在那里喝水、洗澡，还吃了早饭。'),
    (5, 178, 379, 'She saw there was not much bread left in the basket, and the girl was thankful the Scarecrow did not have to eat anything, for there was scarcely enough for herself and Toto for the day.', '她看到篮子里剩下的面包不多了，女孩很庆幸稻草人不用吃东西，因为面包就只够她自己和托托吃一天的了。'),
    (5, 179, 380, 'When she had finished her meal, and was about to go back to the road of yellow brick, she was startled to hear a deep groan near by.', '她吃完饭后，正要走回那条黄砖路，突然听到旁边传来一声很响的呻吟声，吓了一跳。'),
    (5, 180, 381, '“What was that?” she asked timidly.', '她小声地问：“那是什么声音？”'),
    (5, 181, 382, '“I cannot imagine,” replied the Scarecrow; “but we can go and see.”', '稻草人回答说：“我不知道，但是我们可以去看看。”'),
    (5, 182, 383, 'Just then another groan reached their ears, and the sound seemed to come from behind them.', '就在这时，又一声呻吟传到他们耳朵里，声音好像是从他们后面传来的。'),
    (5, 182, 384, 'They turned and walked through the forest a few steps, when Dorothy discovered something shining in a ray of sunshine that fell between the trees.', '他们转过身，在森林里走了几步，突然多萝西发现有一道阳光透过树林照下来，那里有什么东西亮亮的。'),
    (5, 182, 385, 'She ran to the place and then stopped short, with a little cry of surprise.', '她跑到那个地方，然后突然停住了，惊讶地叫了一声。'),
    (5, 183, 386, 'One of the big trees had been partly chopped through, and standing beside it, with an uplifted axe in his hands, was a man made entirely of tin.', '有一棵大树被砍了一半，旁边站着一个人，手里拿着一把举起来的斧头，那个人完全是用铁皮做的。'),
    (5, 183, 387, 'His head and arms and legs were jointed upon his body, but he stood perfectly motionless, as if he could not stir at all.', '他的头、胳膊和腿都连接在身体上，但是他一动不动，好像完全不能动一样。'),
    (5, 184, 388, 'Dorothy looked at him in amazement, and so did the Scarecrow, while Toto barked sharply and made a snap at the tin legs, which hurt his teeth.', '多萝西很惊讶地看着他，稻草人也一样。托托大声叫了几下，还去咬铁皮腿，结果把它的牙都弄疼了。'),
    (5, 185, 389, '“Did you groan?” asked Dorothy.', '多萝西问：“是你发出呻吟声的吗？”'),
    (5, 186, 390, '“Yes,” answered the tin man, “I did.', '“是的，”铁皮人回答说，“是我。”'),
    (5, 186, 391, 'I’ve been groaning for more than a year, and no one has ever heard me before or come to help me.”', '我已经哼哼一年多了，以前从来没人听到我，也没人来帮我。'),
    (5, 187, 392, '“What can I do for you?” she inquired softly, for she was moved by the sad voice in which the man spoke.', '“我能为你做些什么呢？”她轻轻地问，因为那个男人的声音听起来太伤心了，她很心疼。'),
    (5, 188, 393, '“Get an oil-can and oil my joints,” he answered.', '“拿个油壶，给我的关节上点油。”他回答。'),
    (5, 188, 394, '“They are rusted so badly that I cannot move them at all; if I am well oiled I shall soon be all right again.', '“它们生锈得太厉害了，我一点也动不了。如果能好好上油，我很快就会好起来的。'),
    (5, 188, 395, 'You will find an oil-can on a shelf in my cottage.”', '你会在我的小房子里，一个架子上找到油壶的。”'),
    (5, 189, 396, 'Dorothy at once ran back to the cottage and found the oil-can, and then she returned and asked anxiously, “Where are your joints?”', '多萝西立刻跑回小房子，找到了油壶。然后她回来，焦急地问：“你的关节在哪里呀？”'),
    (5, 190, 397, '“Oil my neck, first,” replied the Tin Woodman.', '“先给我的脖子上油。”铁皮人回答说。'),
    (5, 190, 398, 'So she oiled it, and as it was quite badly rusted the Scarecrow took hold of the tin head and moved it gently from side to side until it worked freely, and then the man could turn it himself.', '于是她给它上了油。因为生锈得很厉害，稻草人抓住那个铁头，轻轻地左右动了动，直到它能自由活动了，那个人就能自己转动了。'),
    (5, 191, 399, '“Now oil the joints in my arms,” he said.', '“现在，给我的胳膊关节上油。”他说。'),
    (5, 191, 400, 'And Dorothy oiled them and the Scarecrow bent them carefully until they were quite free from rust and as good as new.', '多萝西给它们上了油，稻草人小心地弯动它们，直到它们完全没有锈了，和新的一样好。'),
    (5, 192, 401, 'The Tin Woodman gave a sigh of satisfaction and lowered his axe, which he leaned against the tree.', '铁皮人满意地叹了口气，放下了斧头，把它靠在树上。'),
    (5, 193, 402, '“This is a great comfort,” he said.', '“这真舒服啊！”他说。'),
    (5, 193, 403, '“I have been holding that axe in the air ever since I rusted, and I’m glad to be able to put it down at last.', '“自从我生锈以后，就一直把斧头举在空中。现在终于能放下了，我真高兴。'),
    (5, 193, 404, 'Now, if you will oil the joints of my legs, I shall be all right once more.”', '现在，如果你能给我的腿关节上油，我就又会好起来了。”'),
    (5, 194, 405, 'So they oiled his legs until he could move them freely; and he thanked them again and again for his release, for he seemed a very polite creature, and very grateful.', '于是他们给他的腿上了油，直到他可以自由地动了。他一遍又一遍地感谢他们，因为他看起来非常有礼貌，也很感激。'),
    (5, 195, 406, '“I might have stood there always if you had not come along,” he said; “so you have certainly saved my life.', '“如果你们没有来，我可能就一直站在那里了。”他说，“所以你们真是救了我的命啊！'),
    (5, 195, 407, 'How did you happen to be here?”', '你们怎么会在这里呢？”'),
    (5, 196, 408, '“We are on our way to the Emerald City to see the Great Oz,” she answered, “and we stopped at your cottage to pass the night.”', '“我们正在去 翡翠城 的路上，想去见伟大的 奥兹大王。”她回答说，“我们停在你的小房子里过夜。”'),
    (5, 197, 409, '“Why do you wish to see Oz?” he asked.', '“你们为什么想见 奥兹大王 呢？”他问。'),
    (5, 198, 410, '“I want him to send me back to Kansas, and the Scarecrow wants him to put a few brains into his head,” she replied.', '“我想让他送我回 堪萨斯，而 稻草人 想让他给自己一些脑子。”她回答说。'),
    (5, 199, 411, 'The Tin Woodman appeared to think deeply for a moment.', '铁皮人好像认真地想了一会儿。'),
    (5, 199, 412, 'Then he said:', '然后他说：'),
    (5, 200, 413, '“Do you suppose Oz could give me a heart?”', '“你们觉得 奥兹大王 能给我一颗心吗？”'),
    (5, 201, 414, '“Why, I guess so,” Dorothy answered.', '“嗯，我想可以吧。”多萝西回答说。'),
    (5, 201, 415, '“It would be as easy as to give the Scarecrow brains.”', '“这和给 稻草人 脑子一样容易。”'),
    (5, 202, 416, '“True,” the Tin Woodman returned.', '“确实是这样！”铁皮人说。'),
    (5, 202, 417, '“So, if you will allow me to join your party, I will also go to the Emerald City and ask Oz to help me.”', '“那么，如果你们愿意让我加入，我也想和你们一起去 翡翠城，请 奥兹大王 帮我。”'),
    (5, 203, 418, '“Come along,” said the Scarecrow heartily, and Dorothy added that she would be pleased to have his company.', '“一起来吧！”稻草人高兴地说，多萝西也补充说，她很高兴有他作伴。'),
    (5, 203, 419, 'So the Tin Woodman shouldered his axe and they all passed through the forest until they came to the road that was paved with yellow brick.', '于是铁皮人扛起他的斧头，他们都穿过森林，直到来到那条铺着黄色砖块的路上。'),
    (5, 204, 420, 'The Tin Woodman had asked Dorothy to put the oil-can in her basket.', '铁皮人已经请多萝西把油壶放进她的篮子里了。'),
    (5, 204, 421, '“For,” he said, “if I should get caught in the rain, and rust again, I would need the oil-can badly.”', '他说：“要是淋了雨，我又生锈了，就特别需要油壶。”'),
    (5, 205, 422, 'It was a bit of good luck to have their new comrade join the party, for soon after they had begun their journey again they came to a place where the trees and branches grew so thick over the road that the travelers could not pass.', '有新朋友加入真幸运，因为他们没走多久，就到了一个地方。那里的树木枝叶很密，把路都遮住了，大家过不去。'),
    (5, 205, 423, 'But the Tin Woodman set to work with his axe and chopped so well that soon he cleared a passage for the entire party.', '但是铁皮人拿起斧子，使劲砍起来，很快就为大家开出一条路。'),
    (5, 206, 424, 'Dorothy was thinking so earnestly as they walked along that she did not notice when the Scarecrow stumbled into a hole and rolled over to the side of the road.', '多萝西走路时想得太认真了，没看到稻草人不小心掉进洞里，滚到路边。'),
    (5, 206, 425, 'Indeed he was obliged to call to her to help him up again.', '他只好叫她来帮忙，把他扶起来。'),
    (5, 207, 426, '“Why didn’t you walk around the hole?” asked the Tin Woodman.', '“你为什么不绕开那个洞走呢？”铁皮人问。'),
    (5, 208, 427, '“I don’t know enough,” replied the Scarecrow cheerfully.', '“我懂得不够多，”稻草人开心地说。'),
    (5, 208, 428, '“My head is stuffed with straw, you know, and that is why I am going to Oz to ask him for some brains.”', '“我的脑袋里都是稻草，你知道的。所以我才要去奥兹大王那里，请他给我一些脑子。”'),
    (5, 209, 429, '“Oh, I see,” said the Tin Woodman.', '“哦，我懂了，”铁皮人说。'),
    (5, 209, 430, '“But, after all, brains are not the best things in the world.”', '“但是，脑子也不是世界上最好的东西。”'),
    (5, 210, 431, '“Have you any?” inquired the Scarecrow.', '“你有脑子吗？”稻草人问。'),
    (5, 211, 432, '“No, my head is quite empty,” answered the Woodman.', '“没有，我的脑袋是空的，”铁皮人回答说。'),
    (5, 211, 433, '“But once I had brains, and a heart also; so, having tried them both, I should much rather have a heart.”', '“但我以前有脑子，也有心。我都试过了，我更想要一颗心。”'),
    (5, 212, 434, '“And why is that?” asked the Scarecrow.', '“为什么呢？”稻草人问。'),
    (5, 213, 435, '“I will tell you my story, and then you will know.”', '“我告诉你我的故事，你就知道了。”'),
    (5, 214, 436, 'So, while they were walking through the forest, the Tin Woodman told the following story:', '于是，他们走过森林的时候，铁皮人讲了下面的故事：'),
    (5, 215, 437, '“I was born the son of a woodman who chopped down trees in the forest and sold the wood for a living.', '“我是一个砍树人的儿子，爸爸在森林里砍树，卖木头赚钱养家。'),
    (5, 215, 438, 'When I grew up, I too became a wood-chopper, and after my father died I took care of my old mother as long as she lived.', '我长大后，也成了砍树人。爸爸去世后，我一直照顾妈妈，直到她去世。'),
    (5, 215, 439, 'Then I made up my mind that instead of living alone I would marry, so that I might not become lonely.', '后来我想，我不能一个人生活，要结婚，这样才不会孤单。'),
    (5, 216, 440, '“There was one of the Munchkin girls who was so beautiful that I soon grew to love her with all my heart.', '“在芒奇金人的女孩中，有一个长得特别美，我很快就爱上了她。'),
    (5, 216, 441, 'She, on her part, promised to marry me as soon as I could earn enough money to build a better house for her; so I set to work harder than ever.', '她答应我，只要我赚够钱给她盖一栋好房子，就嫁给我。所以我比以前更努力地工作。'),
    (5, 216, 442, 'But the girl lived with an old woman who did not want her to marry anyone, for she was so lazy she wished the girl to remain with her and do the cooking and the housework.', '但是那个女孩跟一个老太太住在一起，老太太很懒，不想让她嫁人。她希望女孩一直留在身边，做饭和做家务。'),
    (5, 216, 443, 'So the old woman went to the Wicked Witch of the East, and promised her two sheep and a cow if she would prevent the marriage.', '于是老太太找到东方坏女巫，说只要她能阻止这门婚事，就给她两只羊和一头牛。'),
    (5, 216, 444, 'Thereupon the Wicked Witch enchanted my axe, and when I was chopping away at my best one day, for I was anxious to get the new house and my wife as soon as possible, the axe slipped all at once and cut off my left leg.', '于是坏女巫给我的斧子施了魔法。有一天我使劲砍树，因为我急着想快点盖好新房，娶到妻子。结果斧子突然滑了一下，把我的左腿砍掉了。'),
    (5, 217, 445, '“This at first seemed a great misfortune, for I knew a one-legged man could not do very well as a wood-chopper.', '“这刚开始看来是个大麻烦，因为我知道独腿的人当砍树工，肯定做不好。'),
    (5, 217, 446, 'So I went to a tinsmith and had him make me a new leg out of tin.', '于是我去找一个打铁的，让他给我做了一条锡腿。'),
    (5, 217, 447, 'The leg worked very well, once I was used to it.', '我习惯了以后，这条腿用起来很好。'),
    (5, 217, 448, 'But my action angered the Wicked Witch of the East, for she had promised the old woman I should not marry the pretty Munchkin girl.', '但是我的做法惹恼了东方坏女巫，因为她答应过老太太，不让我娶那个美丽的芒奇金人女孩。'),
    (5, 217, 449, 'When I began chopping again, my axe slipped and cut off my right leg.', '我又开始砍树时，斧子滑了一下，把我的右腿也砍掉了。'),
    (5, 217, 450, 'Again I went to the tinsmith, and again he made me a leg out of tin.', '我又去找那个打铁的，他又给我做了一条锡腿。'),
    (5, 217, 451, 'After this the enchanted axe cut off my arms, one after the other; but, nothing daunted, I had them replaced with tin ones.', '后来，那把斧子把我的胳膊一个个砍掉了。但我没害怕，就让铁匠给我安上锡胳膊。'),
    (5, 217, 452, 'The Wicked Witch then made the axe slip and cut off my head, and at first I thought that was the end of me.', '后来，坏女巫 又让斧子滑了一下，把我的头砍掉了。我那时以为自己要完蛋了。'),
    (5, 217, 453, 'But the tinsmith happened to come along, and he made me a new head out of tin.', '但这时铁匠正好来了，他用锡给我做了个新脑袋。'),
    (5, 218, 454, '“I thought I had beaten the Wicked Witch then, and I worked harder than ever; but I little knew how cruel my enemy could be.', '“我那时以为打败了 坏女巫，就更努力地干活了。但我不知道敌人有多坏。'),
    (5, 218, 455, 'She thought of a new way to kill my love for the beautiful Munchkin maiden, and made my axe slip again, so that it cut right through my body, splitting me into two halves.', '她又想了个办法，要让我不再爱美丽的 芒奇金人 姑娘。她又让我的斧子滑了一下，正好把我从中间劈成了两半。'),
    (5, 218, 456, 'Once more the tinsmith came to my help and made me a body of tin, fastening my tin arms and legs and head to it, by means of joints, so that I could move around as well as ever.', '铁匠又来帮我了，他给我做了个锡身体。他把我的锡胳膊、锡腿和锡头都安在上面，用接头连好，这样我又能像以前一样动了。'),
    (5, 218, 457, 'But, alas!', '唉！'),
    (5, 218, 458, 'I had now no heart, so that I lost all my love for the Munchkin girl, and did not care whether I married her or not.', '我现在没了心，所以也不爱 芒奇金人 姑娘了。我也不在乎娶不娶她。'),
    (5, 218, 459, 'I suppose she is still living with the old woman, waiting for me to come after her.', '我想她还在和老太太住，等着我去找她吧。'),
    (5, 219, 460, '“My body shone so brightly in the sun that I felt very proud of it and it did not matter now if my axe slipped, for it could not cut me.', '“我的身体在太阳下亮亮的，我很骄傲。现在斧子滑了也没事，因为它砍不动我了。'),
    (5, 219, 461, 'There was only one danger—that my joints would rust; but I kept an oil-can in my cottage and took care to oil myself whenever I needed it.', '只有一个地方不好——我的关节会生锈。但我屋里有个油壶，我总是小心地给自己上油。'),
    (5, 219, 462, 'However, there came a day when I forgot to do this, and, being caught in a rainstorm, before I thought of the danger my joints had rusted, and I was left to stand in the woods until you came to help me.', '可是有一天，我忘了给自己上油。我被大雨淋湿了，还没想起来，关节就生锈了。我只能一直站在森林里，直到你们来帮我。'),
    (5, 219, 463, 'It was a terrible thing to undergo, but during the year I stood there I had time to think that the greatest loss I had known was the loss of my heart.', '这很难受，但我站在那一年里，有时间想，我失去的最重要的东西是我的心。'),
    (5, 219, 464, 'While I was in love I was the happiest man on earth; but no one can love who has not a heart, and so I am resolved to ask Oz to give me one.', '我恋爱时，是世界上最开心的人。但没有心就不能爱，所以我决定请 奥兹大王 给我一颗心。'),
    (5, 219, 465, 'If he does, I will go back to the Munchkin maiden and marry her.”', '如果他给了，我就会去找 芒奇金人 姑娘，娶她。”'),
    (5, 220, 466, 'Both Dorothy and the Scarecrow had been greatly interested in the story of the Tin Woodman, and now they knew why he was so anxious to get a new heart.', '多萝西 和 稻草人 都很喜欢 铁皮人 的故事，现在他们知道他为什么那么想要一颗新的心了。'),
    (5, 221, 467, '“All the same,” said the Scarecrow, “I shall ask for brains instead of a heart; for a fool would not know what to do with a heart if he had one.”', '“不过呢，” 稻草人 说，“我还是要脑子，不要心。因为傻瓜就算有心，也不知道怎么用。”'),
    (5, 222, 468, '“I shall take the heart,” returned the Tin Woodman; “for brains do not make one happy, and happiness is the best thing in the world.”', '“我还是要心，” 铁皮人 说，“因为有脑子不一定快乐，而快乐是世界上最好的事。”'),
    (5, 223, 469, 'Dorothy did not say anything, for she was puzzled to know which of her two friends was right, and she decided if she could only get back to Kansas and Aunt Em, it did not matter so much whether the Woodman had no brains and the Scarecrow no heart, or each got what he wanted.', '多萝西 没说话，因为她不知道两个朋友谁说得对。她决定，只要能回到 堪萨斯 和 艾姆婶婶 那里，那 铁皮人 没脑子和 稻草人 没心，或者每个人都得到想要的东西，就没那么重要了。'),
    (5, 224, 470, 'What worried her most was that the bread was nearly gone, and another meal for herself and Toto would empty the basket.', '最让她担心的是面包快没了，她和 托托 再吃一顿，篮子就空了。'),
    (5, 224, 471, 'To be sure, neither the Woodman nor the Scarecrow ever ate anything, but she was not made of tin nor straw, and could not live unless she was fed.', '没错，铁皮人 和 稻草人 从来不吃东西，但她不是锡做的也不是稻草做的，她不吃东西就活不了。'),
    (6, 225, 472, 'All this time Dorothy and her companions had been walking through the thick woods.', '这段时间，多萝西 和她的朋友们一直在很密的森林里走。'),
    (6, 225, 473, 'The road was still paved with yellow brick, but these were much covered by dried branches and dead leaves from the trees, and the walking was not at all good.', '路还是黄砖铺的，但被树上的枯树枝和落叶盖住了好多，走起来一点也不好。'),
    (6, 226, 474, 'There were few birds in this part of the forest, for birds love the open country where there is plenty of sunshine.', '这片森林里鸟很少，因为鸟喜欢有很多阳光的空旷地方。'),
    (6, 226, 475, 'But now and then there came a deep growl from some wild animal hidden among the trees.', '但时不时地，树林里会传来一些野兽低沉的叫声。'),
    (6, 226, 476, 'These sounds made the little girl’s heart beat fast, for she did not know what made them; but Toto knew, and he walked close to Dorothy’s side, and did not even bark in return.', '这些声音让小女孩的心跳得很快，因为她不知道是什么声音。但 托托 知道，他紧紧地跟在 多萝西 身边，甚至都没有叫。'),
    (6, 227, 477, '“How long will it be,” the child asked of the Tin Woodman, “before we are out of the forest?”', '“我们要多久才能走出森林呢？”孩子问 铁皮人。'),
    (6, 228, 478, '“I cannot tell,” was the answer, “for I have never been to the Emerald City.', '“我不知道，”他回答，“因为我从来没去过 翡翠城。'),
    (6, 228, 479, 'But my father went there once, when I was a boy, and he said it was a long journey through a dangerous country, although nearer to the city where Oz dwells the country is beautiful.', '但我爸爸在我小的时候去过一次，他说那是一段很远的路，要穿过危险的地方。不过，靠近 奥兹大王 住的那个城市，景色就很美。'),
    (6, 228, 480, 'But I am not afraid so long as I have my oil-can, and nothing can hurt the Scarecrow, while you bear upon your forehead the mark of the Good Witch’s kiss, and that will protect you from harm.”', '但只要我有我的油壶，我就不怕。没有人能伤害 稻草人。你的额头上还有 好女巫 亲吻的印记，那会保护你不受伤。”'),
    (6, 229, 481, '“But Toto!” said the girl anxiously. “What will protect him?”', '“可是 托托！”小女孩着急地说，“什么能保护他呢？”'),
    (6, 230, 482, '“We must protect him ourselves if he is in danger,” replied the Tin Woodman.', '“如果他有危险，我们就要自己保护他，”铁皮人 回答说。'),
    (6, 231, 483, 'Just as he spoke there came from the forest a terrible roar, and the next moment a great Lion bounded into the road.', '他刚说完，森林里就传来一声可怕的吼叫，接着，一只大大的 狮子 跳到了路上。'),
    (6, 231, 484, 'With one blow of his paw he sent the Scarecrow spinning over and over to the edge of the road, and then he struck at the Tin Woodman with his sharp claws.', '他一爪子就把 稻草人 打得滚到了路边，然后用锋利的爪子抓向 铁皮人。'),
    (6, 231, 485, 'But, to the Lion’s surprise, he could make no impression on the tin, although the Woodman fell over in the road and lay still.', '可是，让 狮子 吃惊的是，他抓不动锡皮，尽管 铁皮人 倒在路上一动不动了。'),
    (6, 232, 486, 'Little Toto, now that he had an enemy to face, ran barking toward the Lion, and the great beast had opened his mouth to bite the dog, when Dorothy, fearing Toto would be killed, and heedless of danger, rushed forward and slapped the Lion upon his nose as hard as she could, while she cried out:', '小 托托 现在有敌人要面对了，他叫着跑向 狮子。那只大野兽张开嘴，正要咬狗，这时 多萝西 冲了上去。她怕 托托 会被咬死，也不管危险，使劲拍打 狮子 的鼻子，大声喊道：'),
    (6, 233, 487, '“Don’t you dare to bite Toto!', '“你不许咬 托托！”'),
    (6, 233, 488, 'You ought to be ashamed of yourself, a big beast like you, to bite a poor little dog!”', '“你这么大的野兽，咬一只可怜的小狗，真应该感到羞耻！”'),
    (6, 234, 489, '“I didn’t bite him,” said the Lion, as he rubbed his nose with his paw where Dorothy had hit it.', '“我没咬他，”狮子 说着，用爪子揉了揉 多萝西 打过的地方。'),
    (6, 235, 490, '“No, but you tried to,” she retorted.', '“不，你试着咬了，”她反驳道。'),
    (6, 235, 491, '“You are nothing but a big coward.”', '“你就是个大大的胆小鬼。”'),
    (6, 236, 492, '“I know it,” said the Lion, hanging his head in shame.', '“我知道，”狮子 羞愧地低下了头。'),
    (6, 236, 493, '“I’ve always known it.', '“我一直都知道。”'),
    (6, 236, 494, 'But how can I help it?”', '“可我能怎么办呢？”'),
    (6, 237, 495, '“I don’t know, I’m sure.', '“我不知道，真的。”'),
    (6, 237, 496, 'To think of your striking a stuffed man, like the poor Scarecrow!”', '“你想想，你居然去打一个填充的人，就像可怜的 稻草人！”'),
    (6, 238, 497, '“Is he stuffed?” asked the Lion in surprise, as he watched her pick up the Scarecrow and set him upon his feet, while she patted him into shape again.', '“他是填充的吗？”狮子 惊讶地问，他看着她扶起 稻草人，让他站好，还拍了拍，让他恢复原样。'),
    (6, 239, 498, '“Of course he’s stuffed,” replied Dorothy, who was still angry.', '“他当然是填充的呀，”多萝西 回答说，她还有点生气。'),
    (6, 240, 499, '“That’s why he went over so easily,” remarked the Lion.', '“所以他才那么容易就倒了，”狮子 说。'),
    (6, 240, 500, '“It astonished me to see him whirl around so.', '“看到他那样转来转去，真让我吃惊。”'),
    (6, 240, 501, 'Is the other one stuffed also?”', '“另一个人也是填充的吗？”'),
    (6, 241, 502, '“No,” said Dorothy, “he’s made of tin.”', '“不是，”多萝西 说，“他是锡做的。”'),
    (6, 241, 503, 'And she helped the Woodman up again.', '她又把 铁皮人 扶了起来。'),
    (6, 242, 504, '“That’s why he nearly blunted my claws,” said the Lion.', '“所以他才差点弄钝了我的爪子，”狮子 说。'),
    (6, 242, 505, '“When they scratched against the tin it made a cold shiver run down my back.', '“我的爪子碰到锡皮的时候，我感觉后背一阵发凉。”'),
    (6, 242, 506, 'What is that little animal you are so tender of?”', '“你那么爱护的小动物是什么呀？”'),
    (6, 243, 507, '“He is my dog, Toto,” answered Dorothy.', '“他是我的狗，托托，”多萝西 回答道。'),
    (6, 244, 508, '“Is he made of tin, or stuffed?” asked the Lion.', '“他是锡做的，还是填充的呀？”狮子 问道。'),
    (6, 245, 509, '“Neither.', '“都不是。”'),
    (6, 245, 510, 'He’s a—a—a meat dog,” said the girl.', '“他是一只……一只……一只肉狗，”小女孩说。'),
    (6, 246, 511, '“Oh!', '“哦！'),
    (6, 246, 512, 'He’s a curious animal and seems remarkably small, now that I look at him.', '他是个好奇的小动物，我看着他，觉得他好小好小。'),
    (6, 246, 513, 'No one would think of biting such a little thing, except a coward like me,” continued the Lion sadly.', '没人会想咬这么小的东西，除了我这样的胆小鬼，”狮子伤心地说。'),
    (6, 247, 514, '“What makes you a coward?” asked Dorothy, looking at the great beast in wonder, for he was as big as a small horse.', '“你为什么是个胆小鬼呢？”多萝西好奇地问，看着这只大动物，它像一匹小马那么大。'),
    (6, 248, 515, '“It’s a mystery,” replied the Lion.', '“这是个秘密，”狮子回答。'),
    (6, 248, 516, '“I suppose I was born that way.', '“我想我生来就是这样。”'),
    (6, 248, 517, 'All the other animals in the forest naturally expect me to be brave, for the Lion is everywhere thought to be the King of Beasts.', '森林里所有别的动物都觉得我应该很勇敢，因为大家总觉得狮子是动物之王。'),
    (6, 248, 518, 'I learned that if I roared very loudly every living thing was frightened and got out of my way.', '我发现，只要我大声吼叫，所有的动物都会害怕，然后躲开我。'),
    (6, 248, 519, 'Whenever I’ve met a man I’ve been awfully scared; but I just roared at him, and he has always run away as fast as he could go.', '每次我遇到人，我都特别害怕；但我只是冲他们吼叫，他们就总是跑得飞快。'),
    (6, 248, 520, 'If the elephants and the tigers and the bears had ever tried to fight me, I should have run myself—I’m such a coward; but just as soon as they hear me roar they all try to get away from me, and of course I let them go.”', '如果大象、老虎和熊想和我打架，我肯定会自己先跑掉——我就是个胆小鬼；可是只要它们听到我吼叫，它们就都想跑开，我当然就让它们走了。”'),
    (6, 249, 521, '“But that isn’t right.', '“可是这样不对啊。'),
    (6, 249, 522, 'The King of Beasts shouldn’t be a coward,” said the Scarecrow.', '动物之王不应该是胆小鬼，”稻草人说。'),
    (6, 250, 523, '“I know it,” returned the Lion, wiping a tear from his eye with the tip of his tail.', '“我知道，”狮子回答，用尾巴尖擦了擦眼泪。'),
    (6, 250, 524, '“It is my great sorrow, and makes my life very unhappy.', '“这是我最大的烦恼，让我的生活很不开心。'),
    (6, 250, 525, 'But whenever there is danger, my heart begins to beat fast.”', '可是每当有危险，我的心就跳得好快。”'),
    (6, 251, 526, '“Perhaps you have heart disease,” said the Tin Woodman.', '“也许你得了心脏病，”铁皮人说。'),
    (6, 252, 527, '“It may be,” said the Lion.', '“可能吧，”狮子说。'),
    (6, 253, 528, '“If you have,” continued the Tin Woodman, “you ought to be glad, for it proves you have a heart.', '“如果你有，”铁皮人接着说，“你应该高兴，因为这说明你有心脏啊。'),
    (6, 253, 529, 'For my part, I have no heart; so I cannot have heart disease.”', '我呢，我没有心脏；所以我不会得心脏病。”'),
    (6, 254, 530, '“Perhaps,” said the Lion thoughtfully, “if I had no heart I should not be a coward.”', '“也许，”狮子想了想说，“如果我没有心脏，我就不会是胆小鬼了。”'),
    (6, 255, 531, '“Have you brains?” asked the Scarecrow.', '“你有脑子吗？”稻草人问。'),
    (6, 256, 532, '“I suppose so.', '“我想有吧。'),
    (6, 256, 533, 'I’ve never looked to see,” replied the Lion.', '我从来没看过，”狮子回答。'),
    (6, 257, 534, '“I am going to the Great Oz to ask him to give me some,” remarked the Scarecrow, “for my head is stuffed with straw.”', '“我要去见伟大的奥兹大王，请他给我一些，”稻草人说，“因为我的脑袋里塞满了稻草。”'),
    (6, 258, 535, '“And I am going to ask him to give me a heart,” said the Woodman.', '“我呢，要去请他给我一颗心，”铁皮人说。'),
    (6, 259, 536, '“And I am going to ask him to send Toto and me back to Kansas,” added Dorothy.', '“我呢，要去请他把托托和我送回堪萨斯，”多萝西补充道。'),
    (6, 260, 537, '“Do you think Oz could give me courage?” asked the Cowardly Lion.', '“你觉得奥兹大王能给我勇气吗？”胆小的狮子问。'),
    (6, 261, 538, '“Just as easily as he could give me brains,” said the Scarecrow.', '“就像他能给我脑子一样容易，”稻草人说。'),
    (6, 262, 539, '“Or give me a heart,” said the Tin Woodman.', '“或者给我一颗心，”铁皮人说。'),
    (6, 263, 540, '“Or send me back to Kansas,” said Dorothy.', '“或者把我送回堪萨斯，”多萝西说。'),
    (6, 264, 541, '“Then, if you don’t mind, I’ll go with you,” said the Lion, “for my life is simply unbearable without a bit of courage.”', '“那，如果你不介意，我就和你一起去吧，” 狮子说，“我的生活没有一点勇气，真是太难受了。”'),
    (6, 265, 542, '“You will be very welcome,” answered Dorothy, “for you will help to keep away the other wild beasts.', '“你会很受欢迎的，” 多萝西回答，“因为你会帮我们赶走其他的野兽。'),
    (6, 265, 543, 'It seems to me they must be more cowardly than you are if they allow you to scare them so easily.”', '我觉得呀，如果他们让你这么容易就吓跑了，那他们肯定比你还胆小呢。”'),
    (6, 266, 544, '“They really are,” said the Lion, “but that doesn’t make me any braver, and as long as I know myself to be a coward I shall be unhappy.”', '“他们确实是这样，” 狮子说，“但这并不能让我变得更勇敢。只要觉得自己是个胆小鬼，我就不高兴。”'),
    (6, 267, 545, 'So once more the little company set off upon the journey, the Lion walking with stately strides at Dorothy’s side.', '于是，这小队又一次出发了，狮子迈着大步，走在多萝西旁边。'),
    (6, 267, 546, 'Toto did not approve of this new comrade at first, for he could not forget how nearly he had been crushed between the Lion’s great jaws.', '托托一开始不太喜欢这个新朋友，因为他忘不了自己差点被狮子的大嘴巴夹住。'),
    (6, 267, 547, 'But after a time he became more at ease, and presently Toto and the Cowardly Lion had grown to be good friends.', '但过了一会儿，他放松了许多，很快，托托和胆小的狮子就成了好朋友。'),
    (6, 268, 548, 'During the rest of that day there was no other adventure to mar the peace of their journey.', '那天剩下的时间里，他们的旅程很平静，没有再遇到其他事情。'),
    (6, 268, 549, 'Once, indeed, the Tin Woodman stepped upon a beetle that was crawling along the road, and killed the poor little thing.', '有一次，铁皮人不小心踩到了一只在路上爬的小甲虫，把这个可怜的小东西踩死了。'),
    (6, 268, 550, 'This made the Tin Woodman very unhappy, for he was always careful not to hurt any living creature; and as he walked along he wept several tears of sorrow and regret.', '这让铁皮人很不开心，因为他总是很小心，不伤害任何小动物；他一边走一边流下了伤心的眼泪。'),
    (6, 268, 551, 'These tears ran slowly down his face and over the hinges of his jaw, and there they rusted.', '这些眼泪慢慢地流过他的脸，流到他下巴的关节上，然后，关节就生锈了。'),
    (6, 268, 552, 'When Dorothy presently asked him a question the Tin Woodman could not open his mouth, for his jaws were tightly rusted together.', '多萝西很快问他一个问题时，铁皮人却张不开嘴了，因为他的下巴关节都锈住了。'),
    (6, 268, 553, 'He became greatly frightened at this and made many motions to Dorothy to relieve him, but she could not understand.', '他吓坏了，不停地对多萝西比划，想让她帮他，但多萝西不明白。'),
    (6, 268, 554, 'The Lion was also puzzled to know what was wrong.', '狮子也不知道是怎么回事，感到很困惑。'),
    (6, 268, 555, 'But the Scarecrow seized the oil-can from Dorothy’s basket and oiled the Woodman’s jaws, so that after a few moments he could talk as well as before.', '但稻草人从多萝西的篮子里拿过油壶，给铁皮人的下巴关节上油，过了一会儿，他就能像以前一样说话了。'),
    (6, 269, 556, '“This will serve me a lesson,” said he, “to look where I step.', '“这给我上了一课，” 他说，“走路要看脚下。'),
    (6, 269, 557, 'For if I should kill another bug or beetle I should surely cry again, and crying rusts my jaws so that I cannot speak.”', '因为如果我又踩死别的虫子或甲虫，我肯定还会哭，一哭下巴就会生锈，那样我就说不了话了。”'),
    (6, 270, 558, 'Thereafter he walked very carefully, with his eyes on the road, and when he saw a tiny ant toiling by he would step over it, so as not to harm it.', '从那以后，他走路非常小心，眼睛一直看着路。当他看到一只小蚂蚁在旁边忙碌时，他就会跨过去，不伤害它。'),
    (6, 270, 559, 'The Tin Woodman knew very well he had no heart, and therefore he took great care never to be cruel or unkind to anything.', '铁皮人很清楚自己没有心，所以他非常小心，从不对任何东西坏坏的。'),
    (6, 271, 560, '“You people with hearts,” he said, “have something to guide you, and need never do wrong; but I have no heart, and so I must be very careful.', '“你们这些有心的人啊，” 他说，“有东西指引你们，永远不会做错事；但我没有心，所以我必须非常小心。'),
    (6, 271, 561, 'When Oz gives me a heart of course I needn’t mind so much.”', '等奥兹大王给了我一颗心，我就不用那么小心了。”'),
    (7, 272, 562, 'They were obliged to camp out that night under a large tree in the forest, for there were no houses near.', '那天晚上，他们只能在森林里的一棵大树下露营，因为附近没有房子。'),
    (7, 272, 563, 'The tree made a good, thick covering to protect them from the dew, and the Tin Woodman chopped a great pile of wood with his axe and Dorothy built a splendid fire that warmed her and made her feel less lonely.', '大树提供了厚厚的遮蔽，保护他们不被露水打湿，铁皮人用他的斧头砍了一大堆木头，多萝西生了一个很棒的火堆，火堆让她暖和起来，也让她感觉不那么孤单了。'),
    (7, 272, 564, 'She and Toto ate the last of their bread, and now she did not know what they would do for breakfast.', '她和托托吃完了最后一点面包，现在她不知道他们早上要吃什么了。'),
    (7, 273, 565, '“If you wish,” said the Lion, “I will go into the forest and kill a deer for you.', '“如果你想的话，” 狮子说，“我可以进森林里给你打一只鹿。'),
    (7, 273, 566, 'You can roast it by the fire, since your tastes are so peculiar that you prefer cooked food, and then you will have a very good breakfast.”', '你可以在火边烤着吃，因为你的口味很特别，喜欢吃煮熟的食物，那样你就有很棒的早餐了。”'),
    (7, 274, 567, '“Don’t!', '“别！'),
    (7, 274, 568, 'Please don’t,” begged the Tin Woodman.', '求求你，别那样！” 铁皮人央求道。'),
    (7, 274, 569, '“I should certainly weep if you killed a poor deer, and then my jaws would rust again.”', '“如果你杀了那可怜的鹿，我一定会哭的，然后我的下巴又会生锈了。”'),
    (7, 275, 570, 'But the Lion went away into the forest and found his own supper, and no one ever knew what it was, for he didn’t mention it.', '但是狮子自己进了森林，找到了他的晚饭，没人知道他吃了什么，因为他没说。'),
    (7, 275, 571, 'And the Scarecrow found a tree full of nuts and filled Dorothy’s basket with them, so that she would not be hungry for a long time.', '稻草人 找到一棵长满坚果的树，把坚果装满 多萝西 的篮子，这样她就不会饿肚子很久了。'),
    (7, 275, 572, 'She thought this was very kind and thoughtful of the Scarecrow, but she laughed heartily at the awkward way in which the poor creature picked up the nuts.', '她觉得 稻草人 真是太好心了，但她看到这个小家伙笨手笨脚地捡坚果时，忍不住哈哈大笑起来。'),
    (7, 275, 573, 'His padded hands were so clumsy and the nuts were so small that he dropped almost as many as he put in the basket.', '他的肉乎乎的手太笨拙了，坚果又那么小，他掉到地上的坚果和放进篮子的差不多一样多。'),
    (7, 275, 574, 'But the Scarecrow did not mind how long it took him to fill the basket, for it enabled him to keep away from the fire, as he feared a spark might get into his straw and burn him up.', '但是 稻草人 不在乎要多久才能把篮子装满，因为这样他就可以离火远一点，他怕火星会掉进他的草里把他烧着了。'),
    (7, 275, 575, 'So he kept a good distance away from the flames, and only came near to cover Dorothy with dry leaves when she lay down to sleep.', '所以他离火焰远远的，只有 多萝西 躺下睡觉时，他才走近一点，用干树叶盖住她。'),
    (7, 275, 576, 'These kept her very snug and warm, and she slept soundly until morning.', '这些树叶让她很舒服很暖和，她一直睡到天亮。'),
    (7, 276, 577, 'When it was daylight, the girl bathed her face in a little rippling brook, and soon after they all started toward the Emerald City.', '天亮了，小女孩在小溪里洗了脸，很快，他们就一起朝着 翡翠城 走去。'),
    (7, 277, 578, 'This was to be an eventful day for the travelers.', '对这些旅行者来说，这一天会有很多特别的事发生。'),
    (7, 277, 579, 'They had hardly been walking an hour when they saw before them a great ditch that crossed the road and divided the forest as far as they could see on either side.', '他们刚走了不到一个小时，就看到前面有一条大沟，这条沟穿过马路，把森林分成了两半，一眼望不到头。'),
    (7, 277, 580, 'It was a very wide ditch, and when they crept up to the edge and looked into it they could see it was also very deep, and there were many big, jagged rocks at the bottom.', '这条沟很宽，当他们爬到沟边往下看时，发现它也很深，底部还有很多大块的尖石头。'),
    (7, 277, 581, 'The sides were so steep that none of them could climb down, and for a moment it seemed that their journey must end.', '沟的两边非常陡峭，他们谁也下不去，一时间，他们觉得自己的旅程要到此为止了。'),
    (7, 278, 582, '“What shall we do?” asked Dorothy despairingly.', '“我们该怎么办？” 多萝西 伤心地问。'),
    (7, 279, 583, '“I haven’t the faintest idea,” said the Tin Woodman, and the Lion shook his shaggy mane and looked thoughtful.', '“我一点办法都没有。” 铁皮人 说，狮子 甩了甩他那乱糟糟的鬃毛，看起来在想办法。'),
    (7, 280, 584, 'But the Scarecrow said, “We cannot fly, that is certain.', '但是 稻草人 说：“我们不能飞，这是肯定的。'),
    (7, 280, 585, 'Neither can we climb down into this great ditch.', '我们也不能爬进这条大沟。'),
    (7, 280, 586, 'Therefore, if we cannot jump over it, we must stop where we are.”', '所以，如果我们跳不过去，我们就只能待在这里了。”'),
    (7, 281, 587, '“I think I could jump over it,” said the Cowardly Lion, after measuring the distance carefully in his mind.', '“我想我能跳过去。” 胆小的狮子 说，他在心里仔细地估量了一下距离。'),
    (7, 282, 588, '“Then we are all right,” answered the Scarecrow, “for you can carry us all over on your back, one at a time.”', '“那我们就没事了！” 稻草人 回答，“因为你可以一个一个地把我们都背过去。”'),
    (7, 283, 589, '“Well, I’ll try it,” said the Lion.', '“好吧，我试试看。” 狮子 说。'),
    (7, 283, 590, '“Who will go first?”', '“谁先来？”'),
    (7, 284, 591, '“I will,” declared the Scarecrow, “for, if you found that you could not jump over the gulf, Dorothy would be killed, or the Tin Woodman badly dented on the rocks below.', '“我来！” 稻草人 说，“因为如果你跳不过去，多萝西 可能会死掉，或者 铁皮人 会在下面的石头上摔坏。”'),
    (7, 284, 592, 'But if I am on your back it will not matter so much, for the fall would not hurt me at all.”', '但是如果我在你的背上，就没那么要紧了，因为摔下去一点都不会伤到我。”'),
    (7, 285, 593, '“I am terribly afraid of falling, myself,” said the Cowardly Lion, “but I suppose there is nothing to do but try it.', '“我自己也很怕摔倒。” 胆小的狮子 说，“但我想除了试试看，也没别的办法了。'),
    (7, 285, 594, 'So get on my back and we will make the attempt.”', '所以，到我背上来，我们去试试看。”'),
    (7, 286, 595, 'The Scarecrow sat upon the Lion’s back, and the big beast walked to the edge of the gulf and crouched down.', '稻草人 坐在 狮子 的背上，这只大野兽走到深沟边缘，然后蹲了下来。'),
    (7, 287, 596, '“Why don’t you run and jump?” asked the Scarecrow.', '“你为什么不跑起来跳呢？” 稻草人 问。'),
    (7, 288, 597, '“Because that isn’t the way we Lions do these things,” he replied.', '“因为我们狮子不是那样做的。” 他回答说。'),
    (7, 288, 598, 'Then giving a great spring, he shot through the air and landed safely on the other side.', '然后他猛地一跳，飞过空中，安全地落在了另一边。'),
    (7, 288, 599, 'They were all greatly pleased to see how easily he did it, and after the Scarecrow had got down from his back the Lion sprang across the ditch again.', '看到他跳得这么轻松，大家都很高兴。稻草人 从他背上下来后，狮子 又跳回了沟的这边。'),
    (7, 289, 600, 'Dorothy thought she would go next; so she took Toto in her arms and climbed on the Lion’s back, holding tightly to his mane with one hand.', '多萝西 觉得她该下一个过去了；所以她抱起 托托，爬到 狮子 的背上，一只手紧紧抓住他的鬃毛。'),
    (7, 289, 601, 'The next moment it seemed as if she were flying through the air; and then, before she had time to think about it, she was safe on the other side.', '下一刻，她好像在空中飞。还没来得及想，她就安全地到了对面。'),
    (7, 289, 602, 'The Lion went back a third time and got the Tin Woodman, and then they all sat down for a few moments to give the beast a chance to rest, for his great leaps had made his breath short, and he panted like a big dog that has been running too long.', '狮子又回去了一次，把铁皮人也带来了。然后他们都坐下来休息了一会儿，让那只动物歇歇脚。因为它跳得太猛了，喘不过气，就像跑了很久的大狗一样呼哧呼哧地喘气。'),
    (7, 290, 603, 'They found the forest very thick on this side, and it looked dark and gloomy.', '他们发现这边的森林很密，看起来又黑又暗。'),
    (7, 290, 604, 'After the Lion had rested they started along the road of yellow brick, silently wondering, each in his own mind, if ever they would come to the end of the woods and reach the bright sunshine again.', '狮子休息好了，他们就沿着黄砖路往前走。大家心里都在默默地想，他们什么时候才能走出这片森林，再次看到明亮的阳光呢？'),
    (7, 290, 605, 'To add to their discomfort, they soon heard strange noises in the depths of the forest, and the Lion whispered to them that it was in this part of the country that the Kalidahs lived.', '更让他们不舒服的是，他们很快就听到森林深处传来奇怪的声音。狮子小声告诉他们，卡力达就住在这个地方。'),
    (7, 291, 606, '“What are the Kalidahs?” asked the girl.', '“卡力达是什么呀？”小女孩问。'),
    (7, 292, 607, '“They are monstrous beasts with bodies like bears and heads like tigers,” replied the Lion, “and with claws so long and sharp that they could tear me in two as easily as I could kill Toto.', '“它们是可怕的怪兽，身子像熊，头像老虎，”狮子回答，“它们的爪子又长又尖，能把我撕成两半，就像我能杀死托托一样容易。'),
    (7, 292, 608, 'I’m terribly afraid of the Kalidahs.”', '我特别害怕卡力达。”'),
    (7, 293, 609, '“I’m not surprised that you are,” returned Dorothy.', '“你害怕一点也不奇怪，”多萝西说。'),
    (7, 293, 610, '“They must be dreadful beasts.”', '“它们一定是可怕的怪兽。”'),
    (7, 294, 611, 'The Lion was about to reply when suddenly they came to another gulf across the road.', '狮子正要回答，突然他们又来到了一条横在路上的大沟。'),
    (7, 294, 612, 'But this one was so broad and deep that the Lion knew at once he could not leap across it.', '可这条沟又宽又深，狮子一看就知道自己跳不过去。'),
    (7, 295, 613, 'So they sat down to consider what they should do, and after serious thought the Scarecrow said:', '于是他们坐下来，想想该怎么办。仔细想了想，稻草人说：'),
    (7, 296, 614, '“Here is a great tree, standing close to the ditch.', '“这儿有一棵大树，就长在沟边上。'),
    (7, 296, 615, 'If the Tin Woodman can chop it down, so that it will fall to the other side, we can walk across it easily.”', '如果铁皮人能把它砍倒，让它倒到沟对面去，我们就能轻松地走过去了。”'),
    (7, 297, 616, '“That is a first-rate idea,” said the Lion.', '“这是个好主意！”狮子说。'),
    (7, 297, 617, '“One would almost suspect you had brains in your head, instead of straw.”', '“你脑袋里简直像是长了脑子，而不是稻草！”'),
    (7, 298, 618, 'The Woodman set to work at once, and so sharp was his axe that the tree was soon chopped nearly through.', '铁皮人立刻开始干活。它的斧头很锋利，很快就把树砍得差不多了。'),
    (7, 298, 619, 'Then the Lion put his strong front legs against the tree and pushed with all his might, and slowly the big tree tipped and fell with a crash across the ditch, with its top branches on the other side.', '然后狮子用它强壮的前腿顶住树，使劲一推。大树慢慢地倾斜，轰隆一声倒了下去，横在了沟上，树顶的枝条也到了对面。'),
    (7, 299, 620, 'They had just started to cross this queer bridge when a sharp growl made them all look up, and to their horror they saw running toward them two great beasts with bodies like bears and heads like tigers.', '他们刚开始过这座奇怪的桥，就听到一声尖锐的吼叫，所有人都抬起头。让他们害怕的是，他们看到两只怪兽正朝他们跑来，它们的身体像熊，头像老虎。'),
    (7, 300, 621, '“They are the Kalidahs!” said the Cowardly Lion, beginning to tremble.', '“它们是卡力达！”胆小的狮子说着，身体开始发抖。'),
    (7, 301, 622, '“Quick!” cried the Scarecrow. “Let us cross over.”', '“快！”稻草人大喊，“我们快过去！”'),
    (7, 302, 623, 'So Dorothy went first, holding Toto in her arms, the Tin Woodman followed, and the Scarecrow came next.', '于是多萝西抱着托托先过去了，铁皮人跟着，然后是稻草人。'),
    (7, 302, 624, 'The Lion, although he was certainly afraid, turned to face the Kalidahs, and then he gave so loud and terrible a roar that Dorothy screamed and the Scarecrow fell over backward, while even the fierce beasts stopped short and looked at him in surprise.', '狮子虽然也很害怕，但他还是转过身，面对着卡力达，然后发出了震耳欲聋的可怕吼声。多萝西吓得尖叫起来，稻草人也向后摔倒了。就连那些凶猛的怪兽也停了下来，惊讶地看着他。'),
    (7, 303, 625, 'But, seeing they were bigger than the Lion, and remembering that there were two of them and only one of him, the Kalidahs again rushed forward, and the Lion crossed over the tree and turned to see what they would do next.', '可是，那些怪兽看到它们比狮子还大，又想到它们有两只，而它只有一只，于是卡力达又冲了过来。狮子已经过了树桥，转过身想看看它们接下来会做什么。'),
    (7, 303, 626, 'Without stopping an instant the fierce beasts also began to cross the tree.', '那些凶猛的怪兽一点也没停，也开始过那棵树了。'),
    (7, 303, 627, 'And the Lion said to Dorothy:', '狮子对多萝西说：'),
    (7, 304, 628, '“We are lost, for they will surely tear us to pieces with their sharp claws.', '“我们完蛋了，它们一定会用锋利的爪子把我们撕成碎片的。”'),
    (7, 304, 629, 'But stand close behind me, and I will fight them as long as I am alive.”', '“但是，你站到我后面来，只要我还活着，我就会和它们打！”'),
    (7, 305, 630, '“Wait a minute!” called the Scarecrow.', '“等一下！”稻草人大喊。'),
    (7, 305, 631, 'He had been thinking what was best to be done, and now he asked the Woodman to chop away the end of the tree that rested on their side of the ditch.', '他一直在想办法。他请 铁皮人 砍掉伸到沟里的那段树。'),
    (7, 305, 632, 'The Tin Woodman began to use his axe at once, and, just as the two Kalidahs were nearly across, the tree fell with a crash into the gulf, carrying the ugly, snarling brutes with it, and both were dashed to pieces on the sharp rocks at the bottom.', '铁皮人 立刻拿起斧头砍树。就在两只 卡力达 快要爬过来时，大树“轰”地一声倒进了深渊，把那些又丑又凶的 卡力达 也带了下去。它们撞到下面的尖石头上，摔得粉碎。'),
    (7, 306, 633, '“Well,” said the Cowardly Lion, drawing a long breath of relief, “I see we are going to live a little while longer, and I am glad of it, for it must be a very uncomfortable thing not to be alive.', '“呼，” 胆小的狮子 松了口气说，“看来我们还能多活一会儿。我真高兴，因为死了肯定很难受。”'),
    (7, 306, 634, 'Those creatures frightened me so badly that my heart is beating yet.”', '那些东西把我吓坏了，我的心还在扑通扑通地跳呢。”'),
    (7, 307, 635, '“Ah,” said the Tin Woodman sadly, “I wish I had a heart to beat.”', '“唉，” 铁皮人 伤心地说，“我真希望我有一颗会跳的心。”'),
    (7, 308, 636, 'This adventure made the travelers more anxious than ever to get out of the forest, and they walked so fast that Dorothy became tired, and had to ride on the Lion’s back.', '这次惊险的事让大家更想快点走出森林。他们走得很快，多萝西 都累了，只好骑在 狮子 的背上。'),
    (7, 308, 637, 'To their great joy the trees became thinner the farther they advanced, and in the afternoon they suddenly came upon a broad river, flowing swiftly just before them.', '让他们高兴的是，越往前走，树木越稀疏了。下午，他们突然看到一条宽宽的河，河水在他们面前哗哗地流淌。'),
    (7, 308, 638, 'On the other side of the water they could see the road of yellow brick running through a beautiful country, with green meadows dotted with bright flowers and all the road bordered with trees hanging full of delicious fruits.', '在河的另一边，他们看到了黄砖路。黄砖路穿过一片美丽的土地，那里有绿油油的草地，开满了鲜花，路两边都长满了挂着甜美果子的树。'),
    (7, 308, 639, 'They were greatly pleased to see this delightful country before them.', '看到眼前这片美丽的地方，他们非常开心。'),
    (7, 309, 640, '“How shall we cross the river?” asked Dorothy.', '“我们怎么过河呢？” 多萝西 问道。'),
    (7, 310, 641, '“That is easily done,” replied the Scarecrow.', '“这很容易！” 稻草人 回答。'),
    (7, 310, 642, '“The Tin Woodman must build us a raft, so we can float to the other side.”', '“铁皮人 必须给我们造一个木筏，这样我们就能漂到对面去了。”'),
    (7, 311, 643, 'So the Woodman took his axe and began to chop down small trees to make a raft, and while he was busy at this the Scarecrow found on the riverbank a tree full of fine fruit.', '于是 铁皮人 拿起斧头，开始砍小树来做木筏。就在他忙着的时候，稻草人 在河岸边找到了一棵结满了美味果子的树。'),
    (7, 311, 644, 'This pleased Dorothy, who had eaten nothing but nuts all day, and she made a hearty meal of the ripe fruit.', '多萝西 一整天只吃了坚果，这让她很高兴，她饱饱地吃了一顿成熟的果子。'),
    (7, 312, 645, 'But it takes time to make a raft, even when one is as industrious and untiring as the Tin Woodman, and when night came the work was not done.', '但是，造木筏需要时间，即使像 铁皮人 那样勤劳、不知疲倦的人也一样。晚上到了，木筏还没造好。'),
    (7, 312, 646, 'So they found a cozy place under the trees where they slept well until the morning; and Dorothy dreamed of the Emerald City, and of the good Wizard Oz, who would soon send her back to her own home again.', '于是他们在树下找了个舒服的地方，一直睡到天亮。多萝西 梦到了 翡翠城，还有善良的巫师 奥兹大王，巫师很快就会送她回家。'),
    (8, 313, 647, 'Our little party of travelers awakened the next morning refreshed and full of hope, and Dorothy breakfasted like a princess off peaches and plums from the trees beside the river.', '第二天早上，小小的旅行队伍醒来，精神饱满，充满希望。多萝西 像公主一样，吃了河边树上的桃子和李子当早餐。'),
    (8, 313, 648, 'Behind them was the dark forest they had passed safely through, although they had suffered many discouragements; but before them was a lovely, sunny country that seemed to beckon them on to the Emerald City.', '他们身后是他们安全穿过的黑森林，虽然经历了很多不开心的事情。但眼前却是一片可爱、阳光明媚的土地，仿佛在招手让他们去 翡翠城。'),
    (8, 314, 649, 'To be sure, the broad river now cut them off from this beautiful land.', '当然，这条宽阔的河流把他们和这片美丽的土地隔开了。'),
    (8, 314, 650, 'But the raft was nearly done, and after the Tin Woodman had cut a few more logs and fastened them together with wooden pins, they were ready to start.', '但木筏快要造好了。铁皮人 再砍几根木头，用木钉把它们固定在一起后，他们就可以出发了。'),
    (8, 314, 651, 'Dorothy sat down in the middle of the raft and held Toto in her arms.', '多萝西 坐在木筏中间，抱着 托托。'),
    (8, 314, 652, 'When the Cowardly Lion stepped upon the raft it tipped badly, for he was big and heavy; but the Scarecrow and the Tin Woodman stood upon the other end to steady it, and they had long poles in their hands to push the raft through the water.', '当 胆小的狮子 走上木筏时，木筏晃得很厉害，因为他又大又重。但 稻草人 和 铁皮人 站在另一头来稳住木筏，他们手里拿着长长的杆子，用来在水里推木筏。'),
    (8, 315, 653, 'They got along quite well at first, but when they reached the middle of the river the swift current swept the raft downstream, farther and farther away from the road of yellow brick.', '一开始他们走得很顺利，但当他们到了河中间时，湍急的水流把木筏冲向下游，离黄砖路越来越远了。'),
    (8, 315, 654, 'And the water grew so deep that the long poles would not touch the bottom.', '河水变得很深，长杆子都够不着底了。'),
    (8, 316, 655, '“This is bad,” said the Tin Woodman, “for if we cannot get to the land we shall be carried into the country of the Wicked Witch of the West, and she will enchant us and make us her slaves.”', '“这可糟了，” 铁皮人 说，“要是我们到不了岸边，就会被冲到 西方坏女巫 的国家，她会施魔法把我们变成她的奴隶。”'),
    (8, 317, 656, '“And then I should get no brains,” said the Scarecrow.', '“那我可就得不到脑子了！” 稻草人 说。'),
    (8, 318, 657, '“And I should get no courage,” said the Cowardly Lion.', '“那我可就得不到勇气了！” 胆小的狮子 说。'),
    (8, 319, 658, '“And I should get no heart,” said the Tin Woodman.', '“那我可就得不到心了！” 铁皮人 说。'),
    (8, 320, 659, '“And I should never get back to Kansas,” said Dorothy.', '“那我永远都回不了 堪萨斯 了！” 多萝西 说。'),
    (8, 321, 660, '“We must certainly get to the Emerald City if we can,” the Scarecrow continued, and he pushed so hard on his long pole that it stuck fast in the mud at the bottom of the river.', '“我们一定要想办法到 翡翠城 去，” 稻草人 接着说。他用力地推着长杆子，结果杆子牢牢地卡在了河底的泥巴里。'),
    (8, 321, 661, 'Then, before he could pull it out again—or let go—the raft was swept away, and the poor Scarecrow was left clinging to the pole in the middle of the river.', '他还没来得及把杆子拔出来，木筏就被水冲走了。可怜的 稻草人 只好紧紧抱着杆子，孤零零地留在河中间。'),
    (8, 322, 662, '“Good-bye!” he called after them, and they were very sorry to leave him.', '“再见！”他大声喊着。大家都很舍不得他。'),
    (8, 322, 663, 'Indeed, the Tin Woodman began to cry, but fortunately remembered that he might rust, and so dried his tears on Dorothy’s apron.', '铁皮人 真的开始哭了，但他想起自己可能会生锈，就赶紧用 多萝西 的围裙擦干了眼泪。'),
    (8, 323, 664, 'Of course this was a bad thing for the Scarecrow.', '当然，这对 稻草人 来说是很糟糕的事。'),
    (8, 324, 665, '“I am now worse off than when I first met Dorothy,” he thought.', '“我现在比第一次遇到 多萝西 的时候更糟了。”他想。'),
    (8, 324, 666, '“Then, I was stuck on a pole in a cornfield, where I could make-believe scare the crows, at any rate.', '“那时，我插在玉米地里的杆子上，至少还能假装吓唬乌鸦。'),
    (8, 324, 667, 'But surely there is no use for a Scarecrow stuck on a pole in the middle of a river.', '但一个插在河中央杆子上的 稻草人，肯定没用了。'),
    (8, 324, 668, 'I am afraid I shall never have any brains, after all!”', '我恐怕永远也得不到脑子了！”'),
    (8, 325, 669, 'Down the stream the raft floated, and the poor Scarecrow was left far behind.', '木筏顺着水流漂走了，可怜的 稻草人 被远远地落下了。'),
    (8, 325, 670, 'Then the Lion said:', '这时 狮子 说：'),
    (8, 326, 671, '“Something must be done to save us.', '“我们得想办法救大家。”'),
    (8, 326, 672, 'I think I can swim to the shore and pull the raft after me, if you will only hold fast to the tip of my tail.”', '我想我觉得我能游到岸边，把木筏拉过来，只要你们紧紧抓住我的尾巴尖。”'),
    (8, 327, 673, 'So he sprang into the water, and the Tin Woodman caught fast hold of his tail.', '于是他跳进水里，铁皮人 赶紧抓住了他的尾巴。'),
    (8, 327, 674, 'Then the Lion began to swim with all his might toward the shore.', '接着 狮子 用尽全身力气，向岸边游去。'),
    (8, 327, 675, 'It was hard work, although he was so big; but by and by they were drawn out of the current, and then Dorothy took the Tin Woodman’s long pole and helped push the raft to the land.', '这可真费力啊，虽然他很大。但是很快，他们就被带出了急流。然后 多萝西 拿起 铁皮人 的长杆，帮忙把木筏推到了岸上。'),
    (8, 328, 676, 'They were all tired out when they reached the shore at last and stepped off upon the pretty green grass, and they also knew that the stream had carried them a long way past the road of yellow brick that led to the Emerald City.', '他们终于到了岸边，踩在漂亮的绿草地上，都累坏了。他们也知道，水流把他们带离了通往 翡翠城 的黄色砖路很远了。'),
    (8, 329, 677, '“What shall we do now?” asked the Tin Woodman, as the Lion lay down on the grass to let the sun dry him.', '“我们现在该怎么办呢？” 铁皮人 问。这时 狮子 正躺在草地上晒太阳，想让身体变干。'),
    (8, 330, 678, '“We must get back to the road, in some way,” said Dorothy.', '“我们必须想办法回到路上。” 多萝西 说道。'),
    (8, 331, 679, '“The best plan will be to walk along the riverbank until we come to the road again,” remarked the Lion.', '“最好的办法是沿着河岸走，直到我们回到那条路上。” 狮子 说。'),
    (8, 332, 680, 'So, when they were rested, Dorothy picked up her basket and they started along the grassy bank, to the road from which the river had carried them.', '于是，他们休息好后，多萝西 拿起她的篮子，大家沿着长满草的河岸走，回到河水冲走他们的那条路上。'),
    (8, 332, 681, 'It was a lovely country, with plenty of flowers and fruit trees and sunshine to cheer them, and had they not felt so sorry for the poor Scarecrow, they could have been very happy.', '那是个美丽的地方，有很多鲜花、果树和阳光，让大家很开心。如果不是为可怜的 稻草人 感到难过，他们本来会很开心的。'),
    (8, 333, 682, 'They walked along as fast as they could, Dorothy only stopping once to pick a beautiful flower; and after a time the Tin Woodman cried out: “Look!”', '他们尽可能快地往前走，多萝西 只停下来一次去摘了一朵漂亮的花。过了一会儿，铁皮人 突然喊道：“看！”'),
    (8, 334, 683, 'Then they all looked at the river and saw the Scarecrow perched upon his pole in the middle of the water, looking very lonely and sad.', '于是大家看向河里，看到 稻草人 孤零零地站在水中央的杆子上，看起来很孤独也很伤心。'),
    (8, 335, 684, '“What can we do to save him?” asked Dorothy.', '“我们能做些什么来救他呢？” 多萝西 问。'),
    (8, 336, 685, 'The Lion and the Woodman both shook their heads, for they did not know.', '狮子 和 铁皮人 都摇了摇头，因为他们都不知道。'),
    (8, 336, 686, 'So they sat down upon the bank and gazed wistfully at the Scarecrow until a Stork flew by, who, upon seeing them, stopped to rest at the water’s edge.', '于是他们坐在河岸上，看着 稻草人，心里很着急。直到一只 鹳鸟 飞过，它看到他们后，就停下来在水边休息。'),
    (8, 337, 687, '“Who are you and where are you going?” asked the Stork.', '“你们是谁？要去哪里啊？” 鹳鸟 问。'),
    (8, 338, 688, '“I am Dorothy,” answered the girl, “and these are my friends, the Tin Woodman and the Cowardly Lion; and we are going to the Emerald City.”', '“我是 多萝西，”女孩回答，“这些是我的朋友，铁皮人 和 胆小的狮子。我们要去 翡翠城。”'),
    (8, 339, 689, '“This isn’t the road,” said the Stork, as she twisted her long neck and looked sharply at the queer party.', '“这不是那条路啊。” 鹳鸟 说，它扭着长长的脖子，好奇地看着这群奇怪的朋友们。'),
    (8, 340, 690, '“I know it,” returned Dorothy, “but we have lost the Scarecrow, and are wondering how we shall get him again.”', '“我知道。” 多萝西 回答，“但是我们把 稻草人 弄丢了，不知道怎么把他找回来。”'),
    (8, 341, 691, '“Where is he?” asked the Stork.', '“他在哪儿？” 鹳鸟问。'),
    (8, 342, 692, '“Over there in the river,” answered the little girl.', '“在那边的河里呢，” 小女孩回答。'),
    (8, 343, 693, '“If he wasn’t so big and heavy I would get him for you,” remarked the Stork.', '“要是他没那么大那么重，我就帮你把他拿回来，” 鹳鸟说。'),
    (8, 344, 694, '“He isn’t heavy a bit,” said Dorothy eagerly, “for he is stuffed with straw; and if you will bring him back to us, we shall thank you ever and ever so much.”', '“他一点也不重啊！” 多萝西着急地说，“他肚子里全是稻草！你要是把他带回来，我们会非常非常感谢你的！”'),
    (8, 345, 695, '“Well, I’ll try,” said the Stork, “but if I find he is too heavy to carry I shall have to drop him in the river again.”', '“好吧，我试试看，” 鹳鸟说，“不过要是他太重了，我拿不动，就只能再把他扔回河里啦。”'),
    (8, 346, 696, 'So the big bird flew into the air and over the water till she came to where the Scarecrow was perched upon his pole.', '于是，大鸟飞上天空，飞过水面，一直飞到 稻草人停在他柱子上的地方。'),
    (8, 346, 697, 'Then the Stork with her great claws grabbed the Scarecrow by the arm and carried him up into the air and back to the bank, where Dorothy and the Lion and the Tin Woodman and Toto were sitting.', '接着，鹳鸟用她的大爪子抓住了 稻草人的胳膊，把他带到空中，又带回河岸边，多萝西、狮子、铁皮人和 托托都在那儿坐着呢。'),
    (8, 347, 698, 'When the Scarecrow found himself among his friends again, he was so happy that he hugged them all, even the Lion and Toto; and as they walked along he sang “Tol-de-ri-de-oh!” at every step, he felt so gay.', '当 稻草人又回到了朋友们身边，他可高兴啦！他抱了抱所有人，连 狮子和 托托也抱了。他们边走边唱着“Tol-de-ri-de-oh!”，每走一步都唱，他真是太开心了。'),
    (8, 348, 699, '“I was afraid I should have to stay in the river forever,” he said, “but the kind Stork saved me, and if I ever get any brains I shall find the Stork again and do her some kindness in return.”', '“我刚才还以为我得永远待在河里了呢，”他说，“但是好心的 鹳鸟救了我。如果我以后变聪明了，我一定会再找到 鹳鸟，好好报答她！”'),
    (8, 349, 700, '“That’s all right,” said the Stork, who was flying along beside them.', '“没关系啦，” 鹳鸟在他们旁边飞着说。'),
    (8, 349, 701, '“I always like to help anyone in trouble.', '“我总是喜欢帮助遇到麻烦的人。”'),
    (8, 349, 702, 'But I must go now, for my babies are waiting in the nest for me.', '“不过我得走了，我的宝宝们还在窝里等我呢。”'),
    (8, 349, 703, 'I hope you will find the Emerald City and that Oz will help you.”', '“我希望你能找到 翡翠城，也希望 奥兹大王会帮助你。”'),
    (8, 350, 704, '“Thank you,” replied Dorothy, and then the kind Stork flew into the air and was soon out of sight.', '“谢谢你！” 多萝西回答。接着，好心的 鹳鸟飞上了天，很快就不见了。'),
    (8, 351, 705, 'They walked along listening to the singing of the brightly colored birds and looking at the lovely flowers which now became so thick that the ground was carpeted with them.', '他们继续往前走，听着五颜六色的鸟儿唱歌，看着漂亮的花朵。花儿越来越多，把地面都铺满了，像地毯一样。'),
    (8, 351, 706, 'There were big yellow and white and blue and purple blossoms, besides great clusters of scarlet poppies, which were so brilliant in color they almost dazzled Dorothy’s eyes.', '那里有大朵的黄色、白色、蓝色和紫色花朵，还有一大丛一大丛火红色的罂粟花。这些花儿颜色鲜艳极了，都快把 多萝西的眼睛闪花了。'),
    (8, 352, 707, '“Aren’t they beautiful?” the girl asked, as she breathed in the spicy scent of the bright flowers.', '“它们是不是很美呀？”女孩闻着鲜花的香味问道。'),
    (8, 353, 708, '“I suppose so,” answered the Scarecrow.', '“我想是吧，” 稻草人回答。'),
    (8, 353, 709, '“When I have brains, I shall probably like them better.”', '“等我有了大脑，我可能就会更喜欢它们了。”'),
    (8, 354, 710, '“If I only had a heart, I should love them,” added the Tin Woodman.', '“要是我有一颗心，我就会爱上它们了，” 铁皮人补充道。'),
    (8, 355, 711, '“I always did like flowers,” said the Lion.', '“我一直都喜欢花，” 狮子说。'),
    (8, 355, 712, '“They seem so helpless and frail.', '“它们看起来好柔弱，需要人保护。”'),
    (8, 355, 713, 'But there are none in the forest so bright as these.”', '“不过森林里没有这么鲜艳的花。”'),
    (8, 356, 714, 'They now came upon more and more of the big scarlet poppies, and fewer and fewer of the other flowers; and soon they found themselves in the midst of a great meadow of poppies.', '他们现在看到了越来越多的火红色大罂粟花，其他的花却越来越少了。很快，他们就来到了一大片罂粟花海里。'),
    (8, 356, 715, 'Now it is well known that when there are many of these flowers together their odor is so powerful that anyone who breathes it falls asleep, and if the sleeper is not carried away from the scent of the flowers, he sleeps on and on forever.', '大家都知道，如果这些花开得很多，它们的气味就会很浓，闻到的人都会睡着。要是睡着的人没有被带离花丛，他就会一直睡下去，永远醒不过来。'),
    (8, 356, 716, 'But Dorothy did not know this, nor could she get away from the bright red flowers that were everywhere about; so presently her eyes grew heavy and she felt she must sit down to rest and to sleep.', '但是 多萝西不知道这件事，她也无法离开那些到处都是的鲜红花朵。于是，她的眼睛越来越重，觉得她必须坐下来休息睡觉了。'),
    (8, 357, 717, 'But the Tin Woodman would not let her do this.', '但是 铁皮人不让她这么做。'),
    (8, 358, 718, '“We must hurry and get back to the road of yellow brick before dark,” he said; and the Scarecrow agreed with him.', '“我们得赶紧在天黑前回到黄砖路上去！”他说。稻草人也同意了他的话。'),
    (8, 358, 719, 'So they kept walking until Dorothy could stand no longer.', '于是他们继续走，直到 多萝西再也站不住了。'),
    (8, 358, 720, 'Her eyes closed in spite of herself and she forgot where she was and fell among the poppies, fast asleep.', '她不由自主地闭上了眼睛，忘了自己在哪里，倒在了罂粟花丛中，睡着了。'),
    (8, 359, 721, '“What shall we do?” asked the Tin Woodman.', '“我们该怎么办？” 铁皮人问。'),
    (8, 360, 722, '“If we leave her here she will die,” said the Lion.', '“如果我们把她留在这儿，她会死的。” 狮子说。'),
    (8, 360, 723, '“The smell of the flowers is killing us all.', '“这些花的味道快把我们都熏倒了。'),
    (8, 360, 724, 'I myself can scarcely keep my eyes open, and the dog is asleep already.”', '我自己都睁不开眼睛了，小狗也睡着了。”'),
    (8, 361, 725, 'It was true; Toto had fallen down beside his little mistress.', '真的，托托已经倒在他小主人身边了。'),
    (8, 361, 726, 'But the Scarecrow and the Tin Woodman, not being made of flesh, were not troubled by the scent of the flowers.', '但稻草人和铁皮人不是肉做的，所以不怕花香。'),
    (8, 362, 727, '“Run fast,” said the Scarecrow to the Lion, “and get out of this deadly flower bed as soon as you can.', '“快跑，” 稻草人对狮子说，“尽快离开这个危险的花丛。'),
    (8, 362, 728, 'We will bring the little girl with us, but if you should fall asleep you are too big to be carried.”', '我们会带小女孩走，但如果你睡着了，你太大了，我们可抬不动你。”'),
    (8, 363, 729, 'So the Lion aroused himself and bounded forward as fast as he could go.', '于是狮子振作起来，尽力往前跑。'),
    (8, 363, 730, 'In a moment he was out of sight.', '一会儿工夫，他就看不见了。'),
    (8, 364, 731, '“Let us make a chair with our hands and carry her,” said the Scarecrow.', '“我们用手做个椅子抬她吧，” 稻草人说。'),
    (8, 364, 732, 'So they picked up Toto and put the dog in Dorothy’s lap, and then they made a chair with their hands for the seat and their arms for the arms and carried the sleeping girl between them through the flowers.', '于是他们抱起托托，把小狗放在多萝西的腿上。然后他们用手当椅子面，用胳膊当扶手，抬着睡着的小女孩穿过花丛。'),
    (8, 365, 733, 'On and on they walked, and it seemed that the great carpet of deadly flowers that surrounded them would never end.', '他们一直走啊走，周围那一大片危险的花海似乎永远走不完。'),
    (8, 365, 734, 'They followed the bend of the river, and at last came upon their friend the Lion, lying fast asleep among the poppies.', '他们沿着河湾走，终于看到了他们的朋友狮子，他正躺在罂粟花里睡得很熟。'),
    (8, 365, 735, 'The flowers had been too strong for the huge beast and he had given up at last, and fallen only a short distance from the end of the poppy bed, where the sweet grass spread in beautiful green fields before them.', '花的力量对这只大野兽来说太强大了，他终于放弃了。他倒下的地方离罂粟花丛的尽头不远，那里有美丽的绿色草地，长着甜甜的青草。'),
    (8, 366, 736, '“We can do nothing for him,” said the Tin Woodman, sadly; “for he is much too heavy to lift.', '“我们帮不了他，” 铁皮人伤心地说，“他太重了，我们抬不动。'),
    (8, 366, 737, 'We must leave him here to sleep on forever, and perhaps he will dream that he has found courage at last.”', '我们只能让他永远睡在这里了，也许他会梦到自己终于变得勇敢了。”'),
    (8, 367, 738, '“I’m sorry,” said the Scarecrow.', '“我很抱歉，” 稻草人说。'),
    (8, 367, 739, '“The Lion was a very good comrade for one so cowardly.', '“狮子虽然有点胆小，但他是个很好的伙伴。'),
    (8, 367, 740, 'But let us go on.”', '可是，我们得继续走了。”'),
    (8, 368, 741, 'They carried the sleeping girl to a pretty spot beside the river, far enough from the poppy field to prevent her breathing any more of the poison of the flowers, and here they laid her gently on the soft grass and waited for the fresh breeze to waken her.', '他们把睡着的小女孩抬到河边一个漂亮的地方，那里离罂粟花田很远，小女孩就不会再吸到花的毒气了。他们轻轻地把她放在柔软的草地上，等着清新的风把她唤醒。'),
    (9, 369, 742, '“We cannot be far from the road of yellow brick, now,” remarked the Scarecrow, as he stood beside the girl, “for we have come nearly as far as the river carried us away.”', '“我们现在离黄砖路应该不远了，” 稻草人站在女孩旁边说，“因为我们已经走了差不多河水把我们冲走那么远了。”'),
    (9, 370, 743, 'The Tin Woodman was about to reply when he heard a low growl, and turning his head (which worked beautifully on hinges) he saw a strange beast come bounding over the grass toward them.', '铁皮人正要回答，突然听到一声低沉的吼叫。他转过头（他的头在铰链上转得很漂亮），看到一只奇怪的野兽从草地上向他们跑来。'),
    (9, 370, 744, 'It was, indeed, a great yellow Wildcat, and the Woodman thought it must be chasing something, for its ears were lying close to its head and its mouth was wide open, showing two rows of ugly teeth, while its red eyes glowed like balls of fire.', '这确实是一只大大的黄色野猫，铁皮人觉得它一定在追什么东西，因为它的耳朵紧贴着头，嘴巴张得大大的，露出两排可怕的牙齿，红色的眼睛像火球一样发光。'),
    (9, 370, 745, 'As it came nearer the Tin Woodman saw that running before the beast was a little gray field mouse, and although he had no heart he knew it was wrong for the Wildcat to try to kill such a pretty, harmless creature.', '离得近了，铁皮人看到跑在野兽前面的是一只灰色小田鼠。虽然他没有心脏，但他知道野猫去杀这么可爱、没害处的小动物是不对的。'),
    (9, 371, 746, 'So the Woodman raised his axe, and as the Wildcat ran by he gave it a quick blow that cut the beast’s head clean off from its body, and it rolled over at his feet in two pieces.', '于是铁皮人举起斧头，当野猫跑过时，他快速一击，把野兽的头从身体上砍了下来，野猫分成两半，滚到他脚下。'),
    (9, 372, 747, 'The field mouse, now that it was freed from its enemy, stopped short; and coming slowly up to the Woodman it said, in a squeaky little voice:', '小田鼠从敌人那里逃脱了，它立刻停了下来。它慢慢走到铁皮人身边，用吱吱的小声音说：'),
    (9, 373, 748, '“Oh, thank you!', '“哦，谢谢你！'),
    (9, 373, 749, 'Thank you ever so much for saving my life.”', '太感谢你救了我的命了！”'),
    (9, 374, 750, '“Don’t speak of it, I beg of you,” replied the Woodman.', '“别客气，小事一桩。” 铁皮人回答。'),
    (9, 374, 751, '“I have no heart, you know, so I am careful to help all those who may need a friend, even if it happens to be only a mouse.”', '“我没有心，所以我会很小心地帮助那些需要朋友的人，就算它只是一只小老鼠。”'),
    (9, 375, 752, '“Only a mouse!” cried the little animal, indignantly. “Why, I am a Queen—the Queen of all the Field Mice!”', '“只是一只老鼠！”小动物生气地喊道，“我可是一位女王——所有田鼠的女王！”'),
    (9, 376, 753, '“Oh, indeed,” said the Woodman, making a bow.', '“哦，真的吗？”铁皮人说着，鞠了一躬。'),
    (9, 377, 754, '“Therefore you have done a great deed, as well as a brave one, in saving my life,” added the Queen.', '“所以，你救了我的命，做了一件很棒也很勇敢的事，”女王补充道。'),
    (9, 378, 755, 'At that moment several mice were seen running up as fast as their little legs could carry them, and when they saw their Queen they exclaimed:', '就在这时，几只老鼠跑了过来，跑得飞快。当它们看到自己的女王时，大声喊道：'),
    (9, 379, 756, '“Oh, your Majesty, we thought you would be killed!', '“哦，陛下，我们以为您会被杀死呢！'),
    (9, 379, 757, 'How did you manage to escape the great Wildcat?”', '您是怎么从那只大野猫手里逃出来的呀？”'),
    (9, 379, 758, 'They all bowed so low to the little Queen that they almost stood upon their heads.', '它们都向小女王深深地鞠躬，几乎都要倒立了。'),
    (9, 380, 759, '“This funny tin man,” she answered, “killed the Wildcat and saved my life.', '“这个有趣的铁皮人，”她回答，“杀了那只野猫，救了我的命。'),
    (9, 380, 760, 'So hereafter you must all serve him, and obey his slightest wish.”', '所以从今以后，你们都得为他服务，听他所有的话。”'),
    (9, 381, 761, '“We will!” cried all the mice, in a shrill chorus.', '“我们会的！”所有老鼠尖声合唱道。'),
    (9, 381, 762, 'And then they scampered in all directions, for Toto had awakened from his sleep, and seeing all these mice around him he gave one bark of delight and jumped right into the middle of the group.', '然后它们四处跑开，因为托托醒了。他看到身边有这么多老鼠，就高兴地叫了一声，跳进了老鼠群里。'),
    (9, 381, 763, 'Toto had always loved to chase mice when he lived in Kansas, and he saw no harm in it.', '托托在堪萨斯生活的时候，就一直喜欢追老鼠，他觉得这没什么不对。'),
    (9, 382, 764, 'But the Tin Woodman caught the dog in his arms and held him tight, while he called to the mice, “Come back!', '但是铁皮人把狗抱在怀里，紧紧地抱着，同时他对老鼠们喊道：“回来！'),
    (9, 382, 765, 'Come back!', '回来！'),
    (9, 382, 766, 'Toto shall not hurt you.”', '托托不会伤害你们的。”'),
    (9, 383, 767, 'At this the Queen of the Mice stuck her head out from underneath a clump of grass and asked, in a timid voice, “Are you sure he will not bite us?”', '这时，老鼠女王从一丛草下面探出头来，怯生生地问：“你确定他不会咬我们吗？”'),
    (9, 384, 768, '“I will not let him,” said the Woodman; “so do not be afraid.”', '“我不会让他咬的，”铁皮人说，“所以别害怕。”'),
    (9, 385, 769, 'One by one the mice came creeping back, and Toto did not bark again, although he tried to get out of the Woodman’s arms, and would have bitten him had he not known very well he was made of tin.', '老鼠们一只接一只地爬了回来。托托没有再叫，虽然他努力想从铁皮人的怀里挣脱出去，如果他不知道铁皮人是铁皮做的，他肯定会咬他一口。'),
    (9, 385, 770, 'Finally one of the biggest mice spoke.', '最后，其中一只最大的老鼠开口了。'),
    (9, 386, 771, '“Is there anything we can do,” it asked, “to repay you for saving the life of our Queen?”', '它问：“我们能做些什么，来报答您救了我们女王的命呢？”'),
    (9, 387, 772, '“Nothing that I know of,” answered the Woodman; but the Scarecrow, who had been trying to think, but could not because his head was stuffed with straw, said, quickly, “Oh, yes; you can save our friend, the Cowardly Lion, who is asleep in the poppy bed.”', '“据我所知，没有什么。”铁皮人回答道。但是稻草人，他一直在努力思考，却想不出来，因为他的脑袋里塞满了稻草，他很快地说：“哦，有了！你们可以救我们的朋友胆小的狮子，他睡在罂粟花丛里呢。”'),
    (9, 388, 773, '“A Lion!” cried the little Queen. “Why, he would eat us all up.”', '“一只狮子！”小女王叫道，“他会把我们都吃掉的。”'),
    (9, 389, 774, '“Oh, no,” declared the Scarecrow; “this Lion is a coward.”', '“哦，不，”稻草人说，“这只狮子是个胆小鬼。”'),
    (9, 390, 775, '“Really?” asked the Mouse.', '“真的吗？”老鼠问道。'),
    (9, 391, 776, '“He says so himself,” answered the Scarecrow, “and he would never hurt anyone who is our friend.', '“他自己就是这么说的，”稻草人回答，“他绝不会伤害我们的朋友。'),
    (9, 391, 777, 'If you will help us to save him I promise that he shall treat you all with kindness.”', '如果你帮我们救他，我保证他会对你们很好的。”'),
    (9, 392, 778, '“Very well,” said the Queen, “we trust you.', '“好吧，”女王说，“我们相信你。'),
    (9, 392, 779, 'But what shall we do?”', '但是我们该怎么做呢？”'),
    (9, 393, 780, '“Are there many of these mice which call you Queen and are willing to obey you?”', '“有没有很多老鼠都叫你女王，并且愿意听你的话？”'),
    (9, 394, 781, '“Oh, yes; there are thousands,” she replied.', '“哦，是的，有好多好多只呢！”她回答说。'),
    (9, 395, 782, '“Then send for them all to come here as soon as possible, and let each one bring a long piece of string.”', '“那就请它们都快点来这里吧，每只都要带一根长长的绳子哦。”'),
    (9, 396, 783, 'The Queen turned to the mice that attended her and told them to go at once and get all her people.', '女王转头对身边的老鼠说，让它们赶紧去把所有老鼠都叫来。'),
    (9, 396, 784, 'As soon as they heard her orders they ran away in every direction as fast as possible.', '它们一听到女王的命令，就飞快地朝各个方向跑开了。'),
    (9, 397, 785, '“Now,” said the Scarecrow to the Tin Woodman, “you must go to those trees by the riverside and make a truck that will carry the Lion.”', '“现在，”稻草人对铁皮人说，“你得去河边的那些树那儿，做一个能运走狮子的小推车。”'),
    (9, 398, 786, 'So the Woodman went at once to the trees and began to work; and he soon made a truck out of the limbs of trees, from which he chopped away all the leaves and branches.', '于是，铁皮人立刻跑到树林里开始干活了。他很快就用树枝做了一辆小推车，把上面的叶子和分叉都砍掉了。'),
    (9, 398, 787, 'He fastened it together with wooden pegs and made the four wheels out of short pieces of a big tree trunk.', '他用木钉把它们固定在一起，又用一截大树干做了四个轮子。'),
    (9, 398, 788, 'So fast and so well did he work that by the time the mice began to arrive the truck was all ready for them.', '他做得又快又好，等老鼠们开始来的时候，小推车就已经完全准备好了。'),
    (9, 399, 789, 'They came from all directions, and there were thousands of them: big mice and little mice and middle-sized mice; and each one brought a piece of string in his mouth.', '它们从四面八方赶来，有好多好多只：大老鼠、小老鼠和中等大小的老鼠。每只嘴里都叼着一根绳子。'),
    (9, 399, 790, 'It was about this time that Dorothy woke from her long sleep and opened her eyes.', '就在这个时候，多萝西从睡梦中醒了过来，睁开了眼睛。'),
    (9, 399, 791, 'She was greatly astonished to find herself lying upon the grass, with thousands of mice standing around and looking at her timidly.', '她很吃惊地发现自己躺在草地上，周围站着好多好多只老鼠，它们都怯怯地看着她。'),
    (9, 399, 792, 'But the Scarecrow told her about everything, and turning to the dignified little Mouse, he said:', '但是稻草人把所有的事情都告诉了她。然后，他转向那只很有礼貌的小老鼠，说：'),
    (9, 400, 793, '“Permit me to introduce to you her Majesty, the Queen.”', '“请允许我为您介绍，这位就是女王陛下。”'),
    (9, 401, 794, 'Dorothy nodded gravely and the Queen made a curtsy, after which she became quite friendly with the little girl.', '多萝西郑重地点了点头，女王也行了个屈膝礼。之后，她就和这个小女孩变得很友好了。'),
    (9, 402, 795, 'The Scarecrow and the Woodman now began to fasten the mice to the truck, using the strings they had brought.', '稻草人和铁皮人开始把老鼠绑到小推车上，用的就是老鼠们带来的绳子。'),
    (9, 402, 796, 'One end of a string was tied around the neck of each mouse and the other end to the truck.', '绳子的一头系在每只老鼠的脖子上，另一头系在小推车上。'),
    (9, 402, 797, 'Of course the truck was a thousand times bigger than any of the mice who were to draw it; but when all the mice had been harnessed, they were able to pull it quite easily.', '当然，小推车比那些要拉它的老鼠大了一千倍！但是当所有老鼠都系好以后，它们就能很轻松地拉动小推车了。'),
    (9, 402, 798, 'Even the Scarecrow and the Tin Woodman could sit on it, and were drawn swiftly by their queer little horses to the place where the Lion lay asleep.', '连稻草人和铁皮人都能坐在上面，被它们那些特别的小马车夫飞快地拉到了狮子睡觉的地方。'),
    (9, 403, 799, 'After a great deal of hard work, for the Lion was heavy, they managed to get him up on the truck.', '费了好大的劲儿，因为狮子很重，他们终于把他弄到了小推车上。'),
    (9, 403, 800, 'Then the Queen hurriedly gave her people the order to start, for she feared if the mice stayed among the poppies too long they also would fall asleep.', '然后女王赶紧命令她的人们出发，因为她担心老鼠们在罂粟花里待太久，也会睡着。'),
    (9, 404, 801, 'At first the little creatures, many though they were, could hardly stir the heavily loaded truck; but the Woodman and the Scarecrow both pushed from behind, and they got along better.', '一开始，这些小家伙们，虽然有很多只，却很难拉动这辆很重的小推车。但是铁皮人和稻草人都在后面推，他们就走得更好了。'),
    (9, 404, 802, 'Soon they rolled the Lion out of the poppy bed to the green fields, where he could breathe the sweet, fresh air again, instead of the poisonous scent of the flowers.', '很快，他们就把狮子从罂粟花丛里推出了，到了绿色的草地上。在那里，他又能呼吸到甜甜的新鲜空气了，而不是那些花有毒的味道。'),
    (9, 405, 803, 'Dorothy came to meet them and thanked the little mice warmly for saving her companion from death.', '多萝西来迎接他们，并热烈地感谢小老鼠们救了她的伙伴，让他免于死亡。'),
    (9, 405, 804, 'She had grown so fond of the big Lion she was glad he had been rescued.', '她已经非常喜欢这个大大的狮子了，所以很高兴他被救了出来。'),
    (9, 406, 805, 'Then the mice were unharnessed from the truck and scampered away through the grass to their homes.', '然后，老鼠们从小推车上解开，一溜烟地穿过草地跑回了家。'),
    (9, 406, 806, 'The Queen of the Mice was the last to leave.', '老鼠女王是最后一个走的。'),
    (9, 407, 807, '“If ever you need us again,” she said, “come out into the field and call, and we shall hear you and come to your assistance.', '“如果你们以后还需要我们，”她说，“就到田野里来叫我们，我们会听到的，然后来帮你们的忙。'),
    (9, 407, 808, 'Good-bye!”', '再见！”'),
    (9, 408, 809, '“Good-bye!” they all answered, and away the Queen ran, while Dorothy held Toto tightly lest he should run after her and frighten her.', '“再见！”他们都回答道。女王跑走了，而多萝西紧紧地拉着托托，生怕他追上去吓到女王。'),
    (9, 409, 810, 'After this they sat down beside the Lion until he should awaken; and the Scarecrow brought Dorothy some fruit from a tree near by, which she ate for her dinner.', '这之后，他们就坐在狮子的旁边，等着他醒过来。稻草人从附近的树上给多萝西摘了一些水果，多萝西就把它当晚餐吃了。'),
    (10, 410, 811, 'It was some time before the Cowardly Lion awakened, for he had lain among the poppies a long while, breathing in their deadly fragrance; but when he did open his eyes and roll off the truck he was very glad to find himself still alive.', '胆小的狮子睡了一会儿才醒来。他躺在罂粟花里很久，吸了它们危险的香味。当他睁开眼睛，从车上滚下来时，他很高兴自己还活着。'),
    (10, 411, 812, '“I ran as fast as I could,” he said, sitting down and yawning, “but the flowers were too strong for me.', '他坐下来打着哈欠说：“我跑得很快，但这些花太厉害了。”'),
    (10, 411, 813, 'How did you get me out?”', '你们怎么把我弄出来的？”'),
    (10, 412, 814, 'Then they told him of the field mice, and how they had generously saved him from death; and the Cowardly Lion laughed, and said:', '接着，他们告诉他田鼠们的事，说田鼠们是怎样好心地救了他。胆小的狮子笑了，说：'),
    (10, 413, 815, '“I have always thought myself very big and terrible; yet such little things as flowers came near to killing me, and such small animals as mice have saved my life.', '“我一直觉得自己又高又壮，很厉害。可是，像花这样小的东西差点要了我的命，而像老鼠这样小的动物却救了我的命。”'),
    (10, 413, 816, 'How strange it all is!', '这多奇怪啊！'),
    (10, 413, 817, 'But, comrades, what shall we do now?”', '“但是，伙伴们，我们现在该怎么办？”'),
    (10, 414, 818, '“We must journey on until we find the road of yellow brick again,” said Dorothy, “and then we can keep on to the Emerald City.”', '“我们必须一直往前走，直到再次找到黄砖路，”多萝西说，“然后我们就能去到翡翠城了。”'),
    (10, 415, 819, 'So, the Lion being fully refreshed, and feeling quite himself again, they all started upon the journey, greatly enjoying the walk through the soft, fresh grass; and it was not long before they reached the road of yellow brick and turned again toward the Emerald City where the Great Oz dwelt.', '于是，狮子精神完全恢复了，感觉又像以前一样了。他们都开始旅行，很喜欢走在柔软新鲜的草地上。没多久，他们就走到了黄砖路，再次走向伟大的奥兹大王住的翡翠城。'),
    (10, 416, 820, 'The road was smooth and well paved, now, and the country about was beautiful, so that the travelers rejoiced in leaving the forest far behind, and with it the many dangers they had met in its gloomy shades.', '现在路面又平又好走，周围的景色也很美。旅行者们很高兴把森林远远地抛在身后，也把他们在黑暗森林里遇到的许多危险抛开了。'),
    (10, 416, 821, 'Once more they could see fences built beside the road; but these were painted green, and when they came to a small house, in which a farmer evidently lived, that also was painted green.', '他们再次看到路边有篱笆了，这些篱笆都被漆成了绿色。当他们走到一间小房子前，里面好像住着一个农夫，那房子也被漆成了绿色。'),
    (10, 416, 822, 'They passed by several of these houses during the afternoon, and sometimes people came to the doors and looked at them as if they would like to ask questions; but no one came near them nor spoke to them because of the great Lion, of which they were very much afraid.', '整个下午，他们经过了好几间这样的房子。有时有人走到门口，看着他们，好像想问问题。但没人走近他们，也没人跟他们说话，因为他们很害怕那个大大的狮子。'),
    (10, 416, 823, 'The people were all dressed in clothing of a lovely emerald-green color and wore peaked hats like those of the Munchkins.', '那些人都穿着漂亮的翠绿色衣服，戴着像芒奇金人一样的尖帽子。'),
    (10, 417, 824, '“This must be the Land of Oz,” said Dorothy, “and we are surely getting near the Emerald City.”', '“这一定是奥兹国，”多萝西说，“我们肯定快要到翡翠城了。”'),
    (10, 418, 825, '“Yes,” answered the Scarecrow.', '“是的，”稻草人回答。'),
    (10, 418, 826, '“Everything is green here, while in the country of the Munchkins blue was the favorite color.', '“这里的一切都是绿色的，而在芒奇金人的国度里，蓝色才是大家最喜欢的颜色。”'),
    (10, 418, 827, 'But the people do not seem to be as friendly as the Munchkins, and I’m afraid we shall be unable to find a place to pass the night.”', '“但这里的人们好像不像芒奇金人那么友好，我怕我们找不到过夜的地方。”'),
    (10, 419, 828, '“I should like something to eat besides fruit,” said the girl, “and I’m sure Toto is nearly starved.', '女孩说：“我除了水果，还想吃点别的。我肯定托托也快饿坏了。”'),
    (10, 419, 829, 'Let us stop at the next house and talk to the people.”', '“我们去下一家停下来，跟他们说说话吧。”'),
    (10, 420, 830, 'So, when they came to a good-sized farmhouse, Dorothy walked boldly up to the door and knocked.', '于是，当他们走到一间挺大的农家房子前，多萝西大胆地走到门口敲了敲门。'),
    (10, 421, 831, 'A woman opened it just far enough to look out, and said, “What do you want, child, and why is that great Lion with you?”', '一个女人把门开了一点点，探出头来，说：“孩子，你们想干什么？那个大大的狮子为什么跟着你们？”'),
    (10, 422, 832, '“We wish to pass the night with you, if you will allow us,” answered Dorothy; “and the Lion is my friend and comrade, and would not hurt you for the world.”', '“如果我们能和你们一起过夜，我们会很高兴的，”多萝西回答，“狮子是我的朋友和伙伴，他绝对不会伤害你。”'),
    (10, 423, 833, '“Is he tame?” asked the woman, opening the door a little wider.', '“他很温顺吗？”女人把门又开大了一点，问道。'),
    (10, 424, 834, '“Oh, yes,” said the girl, “and he is a great coward, too.', '“哦，是的，”女孩说，“他还是个大大的胆小鬼呢。”'),
    (10, 424, 835, 'He will be more afraid of you than you are of him.”', '他会比你更害怕你。”'),
    (10, 425, 836, '“Well,” said the woman, after thinking it over and taking another peep at the Lion, “if that is the case you may come in, and I will give you some supper and a place to sleep.”', '“好吧，”女人想了想，又偷偷看了看狮子，说，“如果真是这样，你们可以进来，我会给你们一些晚饭和睡觉的地方。”'),
    (10, 426, 837, 'So they all entered the house, where there were, besides the woman, two children and a man.', '于是他们都进了屋子。屋子里除了那个女人，还有两个孩子和一个男人。'),
    (10, 426, 838, 'The man had hurt his leg, and was lying on the couch in a corner.', '那个男人腿受伤了，正躺在角落的沙发上。'),
    (10, 426, 839, 'They seemed greatly surprised to see so strange a company, and while the woman was busy laying the table the man asked:', '他们看到这么一群陌生人，显得非常惊讶。女人忙着摆桌子的时候，男人问道：'),
    (10, 427, 840, '“Where are you all going?”', '“你们要去哪里？”'),
    (10, 428, 841, '“To the Emerald City,” said Dorothy, “to see the Great Oz.”', '“去 翡翠城，” 多萝西 说，“去见伟大的 奥兹大王。”'),
    (10, 429, 842, '“Oh, indeed!” exclaimed the man. “Are you sure that Oz will see you?”', '“哦，真的吗！” 那人惊呼道。“你确定 奥兹大王 会见你吗？”'),
    (10, 430, 843, '“Why not?” she replied.', '“为什么不呢？” 她回答。'),
    (10, 431, 844, '“Why, it is said that he never lets anyone come into his presence.', '“哎呀，大家都说他从不见任何人。'),
    (10, 431, 845, 'I have been to the Emerald City many times, and it is a beautiful and wonderful place; but I have never been permitted to see the Great Oz, nor do I know of any living person who has seen him.”', '我去了 翡翠城 好多次，那地方又美又好玩；可是我从来没能见到伟大的 奥兹大王，我也不知道有谁见过他。”'),
    (10, 432, 846, '“Does he never go out?” asked the Scarecrow.', '“他从不出去吗？” 稻草人 问道。'),
    (10, 433, 847, '“Never.', '“从不。'),
    (10, 433, 848, 'He sits day after day in the great Throne Room of his Palace, and even those who wait upon him do not see him face to face.”', '他日复一日地坐在他宫殿的大宝座厅里，就连服侍他的人也见不到他的真面目。”'),
    (10, 434, 849, '“What is he like?” asked the girl.', '“他长什么样呀？” 女孩问。'),
    (10, 435, 850, '“That is hard to tell,” said the man thoughtfully.', '“这可不好说，” 那人想了想说。'),
    (10, 435, 851, '“You see, Oz is a Great Wizard, and can take on any form he wishes.', '“你看，奥兹大王 是个大魔法师，他想变成什么样都行。'),
    (10, 435, 852, 'So that some say he looks like a bird; and some say he looks like an elephant; and some say he looks like a cat.', '所以有人说他像小鸟；有人说他像大象；还有人说他像小猫。'),
    (10, 435, 853, 'To others he appears as a beautiful fairy, or a brownie, or in any other form that pleases him.', '对另一些人来说，他会变成漂亮的仙女，或者小矮人，或者任何他喜欢的样子。'),
    (10, 435, 854, 'But who the real Oz is, when he is in his own form, no living person can tell.”', '可是真正的 奥兹大王，他自己本来的样子是什么，没人能说出来。”'),
    (10, 436, 855, '“That is very strange,” said Dorothy, “but we must try, in some way, to see him, or we shall have made our journey for nothing.”', '“这真奇怪，”多萝西 说，“但我们一定要想办法见到他，不然我们这次旅行就白费了。”'),
    (10, 437, 856, '“Why do you wish to see the terrible Oz?” asked the man.', '“你们为什么要见可怕的 奥兹大王 呢？” 那人问。'),
    (10, 438, 857, '“I want him to give me some brains,” said the Scarecrow eagerly.', '“我想要他给我一些脑子，” 稻草人 急切地说。'),
    (10, 439, 858, '“Oh, Oz could do that easily enough,” declared the man.', '“哦，奥兹大王 很容易就能做到，” 那人说。'),
    (10, 439, 859, '“He has more brains than he needs.”', '“他有好多用不完的脑子呢。”'),
    (10, 440, 860, '“And I want him to give me a heart,” said the Tin Woodman.', '“我想要他给我一颗心，” 铁皮人 说。'),
    (10, 441, 861, '“That will not trouble him,” continued the man, “for Oz has a large collection of hearts, of all sizes and shapes.”', '“那不会麻烦他，” 那人接着说，“因为 奥兹大王 有一大堆心，各种大小形状的都有。”'),
    (10, 442, 862, '“And I want him to give me courage,” said the Cowardly Lion.', '“我想要他给我勇气，” 胆小的狮子 说。'),
    (10, 443, 863, '“Oz keeps a great pot of courage in his Throne Room,” said the man, “which he has covered with a golden plate, to keep it from running over.', '“奥兹大王 在他的宝座厅里放着一大罐勇气，” 那人说，“他用一个金盘子盖着，防止它溢出来。'),
    (10, 443, 864, 'He will be glad to give you some.”', '他会很乐意给你一些的。”'),
    (10, 444, 865, '“And I want him to send me back to Kansas,” said Dorothy.', '“我想要他把我送回 堪萨斯，” 多萝西 说。'),
    (10, 445, 866, '“Where is Kansas?” asked the man, with surprise.', '“堪萨斯 在哪里？” 那人惊讶地问。'),
    (10, 446, 867, '“I don’t know,” replied Dorothy sorrowfully, “but it is my home, and I’m sure it’s somewhere.”', '“我不知道，” 多萝西 伤心地回答，“但那是我家，我相信它一定在某个地方。”'),
    (10, 447, 868, '“Very likely.', '“很可能吧。'),
    (10, 447, 869, 'Well, Oz can do anything; so I suppose he will find Kansas for you.', '嗯，奥兹大王 什么都能做到；所以我猜他会帮你找到 堪萨斯 的。'),
    (10, 447, 870, 'But first you must get to see him, and that will be a hard task; for the Great Wizard does not like to see anyone, and he usually has his own way.', '但首先你得去见到他，那可不容易；因为这位大魔法师不喜欢见任何人，而且他总是随心所欲。'),
    (10, 447, 871, 'But what do YOU want?” he continued, speaking to Toto.', '“那你想要什么呢？”他接着问托托。'),
    (10, 447, 872, 'Toto only wagged his tail; for, strange to say, he could not speak.', '托托只是摇了摇尾巴，说来也奇怪，他不会说话。'),
    (10, 448, 873, 'The woman now called to them that supper was ready, so they gathered around the table and Dorothy ate some delicious porridge and a dish of scrambled eggs and a plate of nice white bread, and enjoyed her meal.', '女人叫他们去吃晚饭，说晚饭做好了。他们围坐在桌子旁，多萝西吃了美味的粥、一盘炒鸡蛋和一片白面包，吃得很开心。'),
    (10, 448, 874, 'The Lion ate some of the porridge, but did not care for it, saying it was made from oats and oats were food for horses, not for lions.', '狮子吃了点粥，但不喜欢，他说这是燕麦做的，燕麦是给马吃的，不是给狮子吃的。'),
    (10, 448, 875, 'The Scarecrow and the Tin Woodman ate nothing at all.', '稻草人和铁皮人什么都没吃。'),
    (10, 448, 876, 'Toto ate a little of everything, and was glad to get a good supper again.', '托托每样都吃了一点，很高兴又能吃到好吃的晚饭了。'),
    (10, 449, 877, 'The woman now gave Dorothy a bed to sleep in, and Toto lay down beside her, while the Lion guarded the door of her room so she might not be disturbed.', '女人给多萝西一张床睡觉，托托睡在她旁边，狮子守在她的房门口，这样她就不会被打扰了。'),
    (10, 449, 878, 'The Scarecrow and the Tin Woodman stood up in a corner and kept quiet all night, although of course they could not sleep.', '稻草人和铁皮人站在一个角落里，整晚都安安静静的，虽然他们当然睡不着。'),
    (10, 450, 879, 'The next morning, as soon as the sun was up, they started on their way, and soon saw a beautiful green glow in the sky just before them.', '第二天早上，太阳一出来，他们就上路了。很快，他们就看到前面天空有一道美丽的绿光。'),
    (10, 451, 880, '“That must be the Emerald City,” said Dorothy.', '“那一定是翡翠城。”多萝西说。'),
    (10, 452, 881, 'As they walked on, the green glow became brighter and brighter, and it seemed that at last they were nearing the end of their travels.', '他们继续往前走，绿光变得越来越亮，好像他们终于快走到旅行的终点了。'),
    (10, 452, 882, 'Yet it was afternoon before they came to the great wall that surrounded the City.', '不过，直到下午，他们才走到包围着这座城市的大墙。'),
    (10, 452, 883, 'It was high and thick and of a bright green color.', '这墙又高又厚，是亮绿色的。'),
    (10, 453, 884, 'In front of them, and at the end of the road of yellow brick, was a big gate, all studded with emeralds that glittered so in the sun that even the painted eyes of the Scarecrow were dazzled by their brilliancy.', '在他们前面，也是黄砖路的尽头，有一扇大门，门上镶满了绿宝石，这些绿宝石在阳光下闪闪发光，甚至连稻草人画出来的眼睛都被闪得睁不开。'),
    (10, 454, 885, 'There was a bell beside the gate, and Dorothy pushed the button and heard a silvery tinkle sound within.', '门旁边有一个铃铛，多萝西按了按钮，听到里面传来银铃般清脆的声音。'),
    (10, 454, 886, 'Then the big gate swung slowly open, and they all passed through and found themselves in a high arched room, the walls of which glistened with countless emeralds.', '然后，大门慢慢地打开了，他们都走了进去，发现自己在一个高高的拱形房间里，房间的墙壁上闪耀着无数的绿宝石。'),
    (10, 455, 887, 'Before them stood a little man about the same size as the Munchkins.', '他们面前站着一个小个子男人，和芒奇金人差不多高。'),
    (10, 455, 888, 'He was clothed all in green, from his head to his feet, and even his skin was of a greenish tint.', '他从头到脚都穿着绿色的衣服，甚至他的皮肤都带点绿色。'),
    (10, 455, 889, 'At his side was a large green box.', '他旁边有一个大大的绿色盒子。'),
    (10, 456, 890, 'When he saw Dorothy and her companions the man asked, “What do you wish in the Emerald City?”', '当他看到多萝西和她的伙伴们时，那个男人问：“你们想在翡翠城做什么？”'),
    (10, 457, 891, '“We came here to see the Great Oz,” said Dorothy.', '“我们来这里是想见伟大的奥兹大王。”多萝西说。'),
    (10, 458, 892, 'The man was so surprised at this answer that he sat down to think it over.', '那个男人对这个回答感到很惊讶，他坐下来想了想。'),
    (10, 459, 893, '“It has been many years since anyone asked me to see Oz,” he said, shaking his head in perplexity.', '“很多年了，没有人要求见奥兹大王了。”他困惑地摇了摇头说。'),
    (10, 459, 894, '“He is powerful and terrible, and if you come on an idle or foolish errand to bother the wise reflections of the Great Wizard, he might be angry and destroy you all in an instant.”', '“他很强大，也很可怕。如果你们是无聊或者傻傻地来打扰伟大的巫师思考，他可能会生气，一瞬间把你们都消灭掉。”'),
    (10, 460, 895, '“But it is not a foolish errand, nor an idle one,” replied the Scarecrow; “it is important.', '“这不是傻傻地来，也不是无聊地来。”稻草人回答说，“这件事很重要。'),
    (10, 460, 896, 'And we have been told that Oz is a good Wizard.”', '而且我们听说奥兹大王是一位好巫师。”'),
    (10, 461, 897, '“So he is,” said the green man, “and he rules the Emerald City wisely and well.', '“是的，他就是。”绿人说，“他管理翡翠城很聪明，也很好。”'),
    (10, 461, 898, 'But to those who are not honest, or who approach him from curiosity, he is most terrible, and few have ever dared ask to see his face.', '“但对于不诚实的人，或者只是好奇来找他的人，他就非常可怕，很少有人敢要求见他的真面目。”'),
    (10, 461, 899, 'I am the Guardian of the Gates, and since you demand to see the Great Oz I must take you to his Palace.', '“我是城门守卫，既然你们坚持要见伟大的奥兹大王，我就必须带你们去他的宫殿。'),
    (10, 461, 900, 'But first you must put on the spectacles.”', '但首先你们必须戴上眼镜。”'),
    (10, 462, 901, '“Why?” asked Dorothy.', '“为什么？” 多萝西 问道。'),
    (10, 463, 902, '“Because if you did not wear spectacles the brightness and glory of the Emerald City would blind you.', '“因为如果你不戴眼镜，翡翠城 的光芒会把你的眼睛闪瞎的。'),
    (10, 463, 903, 'Even those who live in the City must wear spectacles night and day.', '即使住在城里的人，也得日日夜夜戴着眼镜。'),
    (10, 463, 904, 'They are all locked on, for Oz so ordered it when the City was first built, and I have the only key that will unlock them.”', '这些眼镜都被锁住了，因为 奥兹大王 在建城时就是这么吩咐的，而我呢，有唯一能打开它们的钥匙。”'),
    (10, 464, 905, 'He opened the big box, and Dorothy saw that it was filled with spectacles of every size and shape.', '他打开大盒子，多萝西 看到里面装满了各种大小和形状的眼镜。'),
    (10, 464, 906, 'All of them had green glasses in them.', '所有的眼镜片都是绿色的。'),
    (10, 464, 907, 'The Guardian of the Gates found a pair that would just fit Dorothy and put them over her eyes.', '城门守卫 找到一副刚好适合 多萝西 的眼镜，给她戴上。'),
    (10, 464, 908, 'There were two golden bands fastened to them that passed around the back of her head, where they were locked together by a little key that was at the end of a chain the Guardian of the Gates wore around his neck.', '眼镜上固定着两条金色的带子，绕过她的后脑勺，被一把小钥匙锁住了。这把小钥匙就系在 城门守卫 脖子上的一条链子上。'),
    (10, 464, 909, 'When they were on, Dorothy could not take them off had she wished, but of course she did not wish to be blinded by the glare of the Emerald City, so she said nothing.', '戴上后，多萝西 想摘也摘不下来了。不过她当然不想被 翡翠城 的光芒闪瞎，所以她什么也没说。'),
    (10, 465, 910, 'Then the green man fitted spectacles for the Scarecrow and the Tin Woodman and the Lion, and even on little Toto; and all were locked fast with the key.', '接着，那个绿衣服的人又给 稻草人、铁皮人、狮子 戴上了眼镜，甚至给小小的 托托 也戴上了；所有的眼镜都用钥匙牢牢地锁住了。'),
    (10, 466, 911, 'Then the Guardian of the Gates put on his own glasses and told them he was ready to show them to the Palace.', '接着，城门守卫 戴上自己的眼镜，告诉他们，他已经准备好带他们去皇宫了。'),
    (10, 466, 912, 'Taking a big golden key from a peg on the wall, he opened another gate, and they all followed him through the portal into the streets of the Emerald City.', '他从墙上的一个挂钩上取下一把大金钥匙，打开了另一扇门。他们都跟着他穿过大门，走进了 翡翠城 的街道。'),
    (11, 467, 913, 'Even with eyes protected by the green spectacles, Dorothy and her friends were at first dazzled by the brilliancy of the wonderful City.', '即使眼睛有绿色眼镜的保护，多萝西 和她的朋友们最初还是被这座神奇城市的明亮光芒晃得睁不开眼。'),
    (11, 467, 914, 'The streets were lined with beautiful houses all built of green marble and studded everywhere with sparkling emeralds.', '街道两旁都是漂亮的房子，它们全是用绿色大理石建成的，上面还镶满了闪闪发光的绿宝石。'),
    (11, 467, 915, 'They walked over a pavement of the same green marble, and where the blocks were joined together were rows of emeralds, set closely, and glittering in the brightness of the sun.', '他们走在同样是绿色大理石铺成的路上，大理石块连接的地方，都密密地镶着一排排的绿宝石，在阳光下闪闪发光。'),
    (11, 467, 916, 'The window panes were of green glass; even the sky above the City had a green tint, and the rays of the sun were green.', '窗户的玻璃是绿色的；就连城市上方的天空也带着一点绿色，太阳的光线也是绿色的。'),
    (11, 468, 917, 'There were many people—men, women, and children—walking about, and these were all dressed in green clothes and had greenish skins.', '街上有很多人在走动——有男人、女人和小孩——他们都穿着绿色的衣服，皮肤也带着一点绿色。'),
    (11, 468, 918, 'They looked at Dorothy and her strangely assorted company with wondering eyes, and the children all ran away and hid behind their mothers when they saw the Lion; but no one spoke to them.', '他们好奇地看着 多萝西 和她那群奇奇怪怪的同伴。当孩子们看到 狮子 时，都跑开躲到妈妈身后了；但没有人跟他们说话。'),
    (11, 468, 919, 'Many shops stood in the street, and Dorothy saw that everything in them was green.', '街上有很多商店，多萝西 看到店里所有的东西都是绿色的。'),
    (11, 468, 920, 'Green candy and green pop-corn were offered for sale, as well as green shoes, green hats, and green clothes of all sorts.', '有绿色的糖果、绿色的爆米花在卖，还有绿色的鞋子、绿色的帽子和各种各样的绿色衣服。'),
    (11, 468, 921, 'At one place a man was selling green lemonade, and when the children bought it Dorothy could see that they paid for it with green pennies.', '有个地方，一个人在卖绿色的柠檬水，当孩子们买的时候，多萝西 看到他们用绿色的硬币付钱。'),
    (11, 469, 922, 'There seemed to be no horses nor animals of any kind; the men carried things around in little green carts, which they pushed before them.', '好像没有马，也没有任何动物；男人们把东西放在绿色的小推车里，在前面推着走。'),
    (11, 469, 923, 'Everyone seemed happy and contented and prosperous.', '每个人看起来都高高兴兴、很满足、生活得很好。'),
    (11, 470, 924, 'The Guardian of the Gates led them through the streets until they came to a big building, exactly in the middle of the City, which was the Palace of Oz, the Great Wizard.', '城门守卫 带着他们穿过街道，直到来到城市正中央的一座大建筑，那就是大巫师 奥兹大王 的宫殿。'),
    (11, 470, 925, 'There was a soldier before the door, dressed in a green uniform and wearing a long green beard.', '门前站着一个士兵，穿着绿色的制服，留着长长的绿色胡子。'),
    (11, 471, 926, '“Here are strangers,” said the Guardian of the Gates to him, “and they demand to see the Great Oz.”', '“这里有陌生人，”城门守卫 对他说，“他们想见大巫师 奥兹大王。”'),
    (11, 472, 927, '“Step inside,” answered the soldier, “and I will carry your message to him.”', '“请进，”士兵回答，“我会把你们的话告诉他的。”'),
    (11, 473, 928, 'So they passed through the Palace Gates and were led into a big room with a green carpet and lovely green furniture set with emeralds.', '于是他们穿过宫殿大门，被带进一个大房间，里面铺着绿色的地毯，摆着漂亮的绿色家具，上面还镶嵌着绿宝石。'),
    (11, 473, 929, 'The soldier made them all wipe their feet upon a green mat before entering this room, and when they were seated he said politely:', '士兵让他们在进这个房间前，都把脚在绿色的垫子上擦干净。等他们坐下后，他礼貌地说：'),
    (11, 474, 930, '“Please make yourselves comfortable while I go to the door of the Throne Room and tell Oz you are here.”', '“请大家舒服地坐着，我这就去宝座厅门口，告诉 奥兹大王 你们来了。”'),
    (11, 475, 931, 'They had to wait a long time before the soldier returned.', '他们等了好久，士兵才回来。'),
    (11, 475, 932, 'When, at last, he came back, Dorothy asked:', '士兵终于回来了，多萝西问：'),
    (11, 476, 933, '“Have you seen Oz?”', '“你见到奥兹大王了吗？”'),
    (11, 477, 934, '“Oh, no,” returned the soldier; “I have never seen him.', '“哦，没有，”士兵说，“我从来没见过他。”'),
    (11, 477, 935, 'But I spoke to him as he sat behind his screen and gave him your message.', '不过我跟他说了话，他当时坐在屏风后面。我还把你的话告诉了他。'),
    (11, 477, 936, 'He said he will grant you an audience, if you so desire; but each one of you must enter his presence alone, and he will admit but one each day.', '他说如果你想见他，他会让你进去。不过你们每个人都得单独进去，而且他一天只让一个人进去。'),
    (11, 477, 937, 'Therefore, as you must remain in the Palace for several days, I will have you shown to rooms where you may rest in comfort after your journey.”', '所以，你们得在宫殿里住几天。我会让人带你们去房间，这样你们就能好好休息了，因为你们赶了很远的路。”'),
    (11, 478, 938, '“Thank you,” replied the girl; “that is very kind of Oz.”', '“谢谢你，”女孩说，“奥兹大王人真好。”'),
    (11, 479, 939, 'The soldier now blew upon a green whistle, and at once a young girl, dressed in a pretty green silk gown, entered the room.', '士兵吹了一声绿色的哨子，一个穿着漂亮绿丝绸裙子的女孩马上走进了房间。'),
    (11, 479, 940, 'She had lovely green hair and green eyes, and she bowed low before Dorothy as she said, “Follow me and I will show you your room.”', '她有着绿色的头发和绿色的眼睛。她向多萝西鞠了一躬，说：“跟我来，我带你去你的房间。”'),
    (11, 480, 941, 'So Dorothy said good-bye to all her friends except Toto, and taking the dog in her arms followed the green girl through seven passages and up three flights of stairs until they came to a room at the front of the Palace.', '于是，多萝西跟所有朋友说了再见，只留下托托。她抱着小狗，跟着绿衣女孩穿过七条走廊，又走了三段楼梯，终于来到了宫殿前面的一间房间。'),
    (11, 480, 942, 'It was the sweetest little room in the world, with a soft comfortable bed that had sheets of green silk and a green velvet counterpane.', '这是世界上最可爱的小房间了！床又软又舒服，铺着绿色的丝绸床单和绿色的天鹅绒被子。'),
    (11, 480, 943, 'There was a tiny fountain in the middle of the room, that shot a spray of green perfume into the air, to fall back into a beautifully carved green marble basin.', '房间中间有一个小喷泉，喷出绿色的香水雾气。这些雾气又落回到一个雕刻得很漂亮的绿色大理石盆子里。'),
    (11, 480, 944, 'Beautiful green flowers stood in the windows, and there was a shelf with a row of little green books.', '窗户上放着美丽的绿色鲜花，书架上还摆着一排排绿色的小书。'),
    (11, 480, 945, 'When Dorothy had time to open these books she found them full of queer green pictures that made her laugh, they were so funny.', '多萝西有空打开这些书的时候，发现里面都是奇怪的绿色图画，逗得她哈哈大笑，太好玩了。'),
    (11, 481, 946, 'In a wardrobe were many green dresses, made of silk and satin and velvet; and all of them fitted Dorothy exactly.', '衣柜里有很多绿色的裙子，是用丝绸、缎子和天鹅绒做的。每件都特别合多萝西的身。'),
    (11, 482, 947, '“Make yourself perfectly at home,” said the green girl, “and if you wish for anything ring the bell.', '“你就当这里是自己家一样，”绿衣女孩说，“想要什么就按铃。”'),
    (11, 482, 948, 'Oz will send for you tomorrow morning.”', '奥兹大王明天早上会派人来叫你。”'),
    (11, 483, 949, 'She left Dorothy alone and went back to the others.', '她把多萝西一个人留在房间里，然后回去找其他人了。'),
    (11, 483, 950, 'These she also led to rooms, and each one of them found himself lodged in a very pleasant part of the Palace.', '她也把这些人带到了房间，他们每个人都发现自己住在了宫殿里一个很舒服的地方。'),
    (11, 483, 951, 'Of course this politeness was wasted on the Scarecrow; for when he found himself alone in his room he stood stupidly in one spot, just within the doorway, to wait till morning.', '当然，这份好心对稻草人来说一点用都没有。因为他发现自己一个人在房间里时，就傻傻地站在门口，一直等到天亮。'),
    (11, 483, 952, 'It would not rest him to lie down, and he could not close his eyes; so he remained all night staring at a little spider which was weaving its web in a corner of the room, just as if it were not one of the most wonderful rooms in the world.', '躺下对他来说没用，他也闭不上眼睛。所以他整晚都盯着一只小蜘蛛，这只小蜘蛛正在房间角落里织网。他好像根本不知道这是世界上最棒的房间之一。'),
    (11, 483, 953, 'The Tin Woodman lay down on his bed from force of habit, for he remembered when he was made of flesh; but not being able to sleep, he passed the night moving his joints up and down to make sure they kept in good working order.', '铁皮人习惯性地躺在床上，因为他记得自己以前是肉做的。但他睡不着，只好整晚不停地动来动去，检查自己的关节有没有坏掉。'),
    (11, 483, 954, 'The Lion would have preferred a bed of dried leaves in the forest, and did not like being shut up in a room; but he had too much sense to let this worry him, so he sprang upon the bed and rolled himself up like a cat and purred himself asleep in a minute.', '狮子更喜欢森林里用干树叶做的床，不喜欢被关在房间里。但他很聪明，没让自己烦恼。所以他跳到床上，像猫一样卷成一团，很快就舒服地睡着了。'),
    (11, 484, 955, 'The next morning, after breakfast, the green maiden came to fetch Dorothy, and she dressed her in one of the prettiest gowns, made of green brocaded satin.', '第二天早上，吃过早饭后，绿衣女孩来接多萝西。她给多萝西穿上了一件最漂亮的绿色丝绸裙子。'),
    (11, 484, 956, 'Dorothy put on a green silk apron and tied a green ribbon around Toto’s neck, and they started for the Throne Room of the Great Oz.', '多萝西穿上了一件绿色丝绸围裙，给托托的脖子上系了一条绿色丝带。然后他们一起去大奥兹大王的宝座室了。'),
    (11, 485, 957, 'First they came to a great hall in which were many ladies and gentlemen of the court, all dressed in rich costumes.', '首先，他们来到了一个大厅。里面有很多穿着漂亮衣服的贵族。'),
    (11, 485, 958, 'These people had nothing to do but talk to each other, but they always came to wait outside the Throne Room every morning, although they were never permitted to see Oz.', '这些人除了聊天没什么事可做，但他们每天早上都会来宝座室外面等着，虽然他们从来都不能见到奥兹大王。'),
    (11, 485, 959, 'As Dorothy entered they looked at her curiously, and one of them whispered:', '多萝西进去的时候，他们都好奇地看着她，其中一个人小声说：'),
    (11, 486, 960, '“Are you really going to look upon the face of Oz the Terrible?”', '“你真的要去见可怕的奥兹大王吗？”'),
    (11, 487, 961, '“Of course,” answered the girl, “if he will see me.”', '“当然啦，”女孩说，“如果他肯见我。”'),
    (11, 488, 962, '“Oh, he will see you,” said the soldier who had taken her message to the Wizard, “although he does not like to have people ask to see him.', '“哦，他会见你的！”那个替她给魔法师传话的士兵说，“虽然他不喜欢别人求他见面。'),
    (11, 488, 963, 'Indeed, at first he was angry and said I should send you back where you came from.', '真的，一开始他还很生气，说要把你送回老家去。'),
    (11, 488, 964, 'Then he asked me what you looked like, and when I mentioned your silver shoes he was very much interested.', '后来他问你长什么样，当我提到你的银鞋时，他可感兴趣啦。'),
    (11, 488, 965, 'At last I told him about the mark upon your forehead, and he decided he would admit you to his presence.”', '最后，我又告诉他你额头上的印记，他才决定让你去见他。”'),
    (11, 489, 966, 'Just then a bell rang, and the green girl said to Dorothy, “That is the signal.', '就在这时，铃声响了，绿衣女孩对多萝西说：“这是信号。'),
    (11, 489, 967, 'You must go into the Throne Room alone.”', '你必须一个人走进宝座大厅。”'),
    (11, 490, 968, 'She opened a little door and Dorothy walked boldly through and found herself in a wonderful place.', '她打开一扇小门，多萝西勇敢地走了进去，发现自己在一个很棒的地方。'),
    (11, 490, 969, 'It was a big, round room with a high arched roof, and the walls and ceiling and floor were covered with large emeralds set closely together.', '这是一个又大又圆的房间，屋顶很高很高。墙上、天花板上和地板上，都紧紧地镶满了大大的祖母绿宝石。'),
    (11, 490, 970, 'In the center of the roof was a great light, as bright as the sun, which made the emeralds sparkle in a wonderful manner.', '屋顶中间有一盏很亮的灯，亮得像太阳一样，把那些祖母绿宝石照得闪闪发光，真漂亮。'),
    (11, 491, 971, 'But what interested Dorothy most was the big throne of green marble that stood in the middle of the room.', '不过，最让多萝西感兴趣的，是房间中央那把绿色的、大理石做的大宝座。'),
    (11, 491, 972, 'It was shaped like a chair and sparkled with gems, as did everything else.', '它长得像一把椅子，上面镶满了闪闪发光的宝石，其他东西也是这样。'),
    (11, 491, 973, 'In the center of the chair was an enormous Head, without a body to support it or any arms or legs whatever.', '椅子中间有一个巨大的头，没有身子，也没有胳膊和腿。'),
    (11, 491, 974, 'There was no hair upon this head, but it had eyes and a nose and mouth, and was much bigger than the head of the biggest giant.', '这个头没有头发，可它有眼睛、鼻子和嘴巴，比最大的巨人的头还要大好多好多。'),
    (11, 492, 975, 'As Dorothy gazed upon this in wonder and fear, the eyes turned slowly and looked at her sharply and steadily.', '多萝西又好奇又害怕地看着这个大头，它的眼睛慢慢转动，又尖锐又一直盯着她看。'),
    (11, 492, 976, 'Then the mouth moved, and Dorothy heard a voice say:', '然后，嘴巴动了，多萝西听到一个声音说：'),
    (11, 493, 977, '“I am Oz, the Great and Terrible.', '“我是奥兹大王，伟大又可怕的。'),
    (11, 493, 978, 'Who are you, and why do you seek me?”', '你是谁呀？为什么要来找我呀？”'),
    (11, 494, 979, 'It was not such an awful voice as she had expected to come from the big Head; so she took courage and answered:', '这声音没有她想象中从大头里发出的那么可怕；于是她鼓起勇气回答说：'),
    (11, 495, 980, '“I am Dorothy, the Small and Meek.', '“我是多萝西，又小又乖的。'),
    (11, 495, 981, 'I have come to you for help.”', '我是来请你帮忙的。”'),
    (11, 496, 982, 'The eyes looked at her thoughtfully for a full minute.', '眼睛想了想，看了她整整一分钟。'),
    (11, 496, 983, 'Then said the voice:', '然后，那个声音说：'),
    (11, 497, 984, '“Where did you get the silver shoes?”', '“你的银鞋是从哪里来的呀？”'),
    (11, 498, 985, '“I got them from the Wicked Witch of the East, when my house fell on her and killed her,” she replied.', '“我是从东方坏女巫那里得到的，我的房子掉下来，砸死了她。”她回答说。'),
    (11, 499, 986, '“Where did you get the mark upon your forehead?” continued the voice.', '“你额头上的印记是怎么来的呀？”那个声音接着问。'),
    (11, 500, 987, '“That is where the Good Witch of the North kissed me when she bade me good-bye and sent me to you,” said the girl.', '“那是北方好女巫亲我的时候，跟我说再见，然后送我来找你的。”女孩说。'),
    (11, 501, 988, 'Again the eyes looked at her sharply, and they saw she was telling the truth.', '眼睛又尖锐地看了看她，发现她说的是真话。'),
    (11, 501, 989, 'Then Oz asked, “What do you wish me to do?”', '然后，奥兹大王问：“你希望我为你做什么呢？”'),
    (11, 502, 990, '“Send me back to Kansas, where my Aunt Em and Uncle Henry are,” she answered earnestly.', '“送我回堪萨斯去吧，我的艾姆婶婶和亨利叔叔都在那里呢。”她很认真地回答说。'),
    (11, 502, 991, '“I don’t like your country, although it is so beautiful.', '“我不喜欢你的国家，虽然它很漂亮。'),
    (11, 502, 992, 'And I am sure Aunt Em will be dreadfully worried over my being away so long.”', '我肯定 艾姆婶婶 会很担心我离开这么久。”'),
    (11, 503, 993, 'The eyes winked three times, and then they turned up to the ceiling and down to the floor and rolled around so queerly that they seemed to see every part of the room.', '那双眼睛眨了三下，然后往天花板上看，又往地板上看，还古怪地转来转去，好像看到了房间的每个角落。'),
    (11, 503, 994, 'And at last they looked at Dorothy again.', '最后，它们又看向了 多萝西。'),
    (11, 504, 995, '“Why should I do this for you?” asked Oz.', '“我为什么要帮你做这个呢？” 奥兹大王 问。'),
    (11, 505, 996, '“Because you are strong and I am weak; because you are a Great Wizard and I am only a little girl.”', '“因为你很强壮，我很弱小；因为你是个大巫师，我只是个小女孩。”'),
    (11, 506, 997, '“But you were strong enough to kill the Wicked Witch of the East,” said Oz.', '“可是，你已经很厉害了，能杀死 东方坏女巫，” 奥兹大王 说。'),
    (11, 507, 998, '“That just happened,” returned Dorothy simply; “I could not help it.”', '“那只是碰巧发生的，” 多萝西 简单地说，“我控制不了。”'),
    (11, 508, 999, '“Well,” said the Head, “I will give you my answer.', '“好吧，”那个头说，“我会给你我的答案。'),
    (11, 508, 1000, 'You have no right to expect me to send you back to Kansas unless you do something for me in return.', '你不应该指望我送你回 堪萨斯，除非你也能为我做点什么。'),
    (11, 508, 1001, 'In this country everyone must pay for everything he gets.', '在这个国家，每个人得到东西都要付出代价。'),
    (11, 508, 1002, 'If you wish me to use my magic power to send you home again you must do something for me first.', '如果你想我用魔法送你回家，你必须先为我做件事。'),
    (11, 508, 1003, 'Help me and I will help you.”', '你帮我，我帮你。”'),
    (11, 509, 1004, '“What must I do?” asked the girl.', '“我必须做什么呢？”小女孩问。'),
    (11, 510, 1005, '“Kill the Wicked Witch of the West,” answered Oz.', '“杀死 西方坏女巫，” 奥兹大王 回答。'),
    (11, 511, 1006, '“But I cannot!” exclaimed Dorothy, greatly surprised.', '“可是我做不到啊！” 多萝西 非常吃惊地叫道。'),
    (11, 512, 1007, '“You killed the Witch of the East and you wear the silver shoes, which bear a powerful charm.', '“你杀死了东方的女巫，还穿着那双带有强大魔力的银鞋。'),
    (11, 512, 1008, 'There is now but one Wicked Witch left in all this land, and when you can tell me she is dead I will send you back to Kansas—but not before.”', '现在这个地方只剩下了一个 坏女巫，等你告诉我她死了，我就会送你回 堪萨斯——但不是现在。”'),
    (11, 513, 1009, 'The little girl began to weep, she was so much disappointed; and the eyes winked again and looked upon her anxiously, as if the Great Oz felt that she could help him if she would.', '小女孩开始哭了，她太失望了；那双眼睛又眨了眨，焦急地看着她，好像伟大的 奥兹大王 觉得她要是愿意就可以帮到他。'),
    (11, 514, 1010, '“I never killed anything, willingly,” she sobbed.', '“我从来没有故意杀死过任何东西，”她抽泣着说。'),
    (11, 514, 1011, '“Even if I wanted to, how could I kill the Wicked Witch?', '“就算我想做，我怎么能杀死 坏女巫 呢？'),
    (11, 514, 1012, 'If you, who are Great and Terrible, cannot kill her yourself, how do you expect me to do it?”', '连您这样又伟大又可怕的都杀不死她，您怎么能指望我去做呢？”'),
    (11, 515, 1013, '“I do not know,” said the Head; “but that is my answer, and until the Wicked Witch dies you will not see your uncle and aunt again.', '“我不知道，”那个头说，“但这就是我的答案，在 坏女巫 死之前，你不会再见到你的叔叔和婶婶了。'),
    (11, 515, 1014, 'Remember that the Witch is Wicked—tremendously Wicked—and ought to be killed.', '记住，这个女巫是邪恶的——非常邪恶——应该被杀死。'),
    (11, 515, 1015, 'Now go, and do not ask to see me again until you have done your task.”', '现在走吧，在你完成任务之前，不要再要求见我。”'),
    (11, 516, 1016, 'Sorrowfully Dorothy left the Throne Room and went back where the Lion and the Scarecrow and the Tin Woodman were waiting to hear what Oz had said to her.', '多萝西 伤心地离开了王座大厅，回到 狮子、稻草人 和 铁皮人 正在等她，想听听 奥兹大王 对她说了什么的地方。'),
    (11, 516, 1017, '“There is no hope for me,” she said sadly, “for Oz will not send me home until I have killed the Wicked Witch of the West; and that I can never do.”', '“我没有希望了，”她伤心地说，“因为 奥兹大王 不会送我回家，除非我杀死了 西方坏女巫；而那是我永远也做不到的。”'),
    (11, 517, 1018, 'Her friends were sorry, but could do nothing to help her; so Dorothy went to her own room and lay down on the bed and cried herself to sleep.', '她的朋友们都很难过，但帮不了她什么；于是 多萝西 回到自己的房间，躺在床上，哭着睡着了。'),
    (11, 518, 1019, 'The next morning the soldier with the green whiskers came to the Scarecrow and said:', '第二天早上，那个留着绿色胡子的士兵来到 稻草人 面前，说：'),
    (11, 519, 1020, '“Come with me, for Oz has sent for you.”', '“跟我来，因为 奥兹大王 找你。”'),
    (11, 520, 1021, 'So the Scarecrow followed him and was admitted into the great Throne Room, where he saw, sitting in the emerald throne, a most lovely Lady.', '于是，稻草人跟着他，进了一个大大的王座厅。他看到一位很漂亮的女士，正坐在绿色的宝座上。'),
    (11, 520, 1022, 'She was dressed in green silk gauze and wore upon her flowing green locks a crown of jewels.', '她穿着绿色的丝绸裙子，头上戴着一个亮晶晶的宝石皇冠。'),
    (11, 520, 1023, 'Growing from her shoulders were wings, gorgeous in color and so light that they fluttered if the slightest breath of air reached them.', '她的肩膀上长着一对翅膀，颜色特别好看，轻得连一点点风都能让它们扇动起来。'),
    (11, 521, 1024, 'When the Scarecrow had bowed, as prettily as his straw stuffing would let him, before this beautiful creature, she looked upon him sweetly, and said:', '稻草人努力地向这位美丽的女士鞠了个躬（他身体里都是稻草，鞠躬可不容易）。女士甜甜地看着他，说：'),
    (11, 522, 1025, '“I am Oz, the Great and Terrible.', '“我是奥兹大王，又厉害又吓人。”'),
    (11, 522, 1026, 'Who are you, and why do you seek me?”', '“你是谁呀？为什么来找我呢？”'),
    (11, 523, 1027, 'Now the Scarecrow, who had expected to see the great Head Dorothy had told him of, was much astonished; but he answered her bravely.', '稻草人原本以为会看到多萝西说过的大脑袋，结果很吃惊。但他还是勇敢地回答了。'),
    (11, 524, 1028, '“I am only a Scarecrow, stuffed with straw.', '“我只是一个身体里装满稻草的稻草人。”'),
    (11, 524, 1029, 'Therefore I have no brains, and I come to you praying that you will put brains in my head instead of straw, so that I may become as much a man as any other in your dominions.”', '“所以我没有脑子。我来求您，请您把脑子放进我的头里，不要再装稻草了。这样我就可以像您王国里的其他人一样，变成一个真正的人了。”'),
    (11, 525, 1030, '“Why should I do this for you?” asked the Lady.', '“我为什么要帮你做这个呢？”女士问。'),
    (11, 526, 1031, '“Because you are wise and powerful, and no one else can help me,” answered the Scarecrow.', '“因为您又聪明又厉害，别人都帮不了我。”稻草人回答。'),
    (11, 527, 1032, '“I never grant favors without some return,” said Oz; “but this much I will promise.', '“我从来不白白帮人忙。”奥兹大王说，“但是我可以答应你一件事。”'),
    (11, 527, 1033, 'If you will kill for me the Wicked Witch of the West, I will bestow upon you a great many brains, and such good brains that you will be the wisest man in all the Land of Oz.”', '“如果你帮我杀死西方坏女巫，我就会给你很多很多脑子，而且是很棒的脑子！你会成为整个奥兹国里最聪明的人。”'),
    (11, 528, 1034, '“I thought you asked Dorothy to kill the Witch,” said the Scarecrow, in surprise.', '“我以为您让多萝西去杀女巫呢。”稻草人很惊讶地说。'),
    (11, 529, 1035, '“So I did.', '“是的，我确实是这么说的。”'),
    (11, 529, 1036, 'I don’t care who kills her.', '“我才不在乎是谁杀了她呢。”'),
    (11, 529, 1037, 'But until she is dead I will not grant your wish.', '“但如果她没死，我就不会帮你实现愿望。”'),
    (11, 529, 1038, 'Now go, and do not seek me again until you have earned the brains you so greatly desire.”', '“现在走吧，等你得到了你特别想要的脑子以后，再来找我。”'),
    (11, 530, 1039, 'The Scarecrow went sorrowfully back to his friends and told them what Oz had said; and Dorothy was surprised to find that the Great Wizard was not a Head, as she had seen him, but a lovely Lady.', '稻草人伤心地回到朋友身边，告诉他们奥兹大王说了什么。多萝西很惊讶地发现，原来那个伟大的魔法师不是她以前见过的大脑袋，而是一位漂亮的女士。'),
    (11, 531, 1040, '“All the same,” said the Scarecrow, “she needs a heart as much as the Tin Woodman.”', '“不过呀，”稻草人说，“她和铁皮人一样，也需要一颗心。”'),
    (11, 532, 1041, 'On the next morning the soldier with the green whiskers came to the Tin Woodman and said:', '第二天早上，那个长着绿色胡子的士兵来到铁皮人面前，对他说：'),
    (11, 533, 1042, '“Oz has sent for you.', '“奥兹大王让你过去。”'),
    (11, 533, 1043, 'Follow me.”', '“跟着我来。”'),
    (11, 534, 1044, 'So the Tin Woodman followed him and came to the great Throne Room.', '于是，铁皮人跟着他，来到了大大的王座厅。'),
    (11, 534, 1045, 'He did not know whether he would find Oz a lovely Lady or a Head, but he hoped it would be the lovely Lady.', '他不知道这次看到奥兹大王会是漂亮的女士还是大脑袋，但他希望是那位漂亮的女士。'),
    (11, 534, 1046, '“For,” he said to himself, “if it is the head, I am sure I shall not be given a heart, since a head has no heart of its own and therefore cannot feel for me.', '“因为呀，”他心里想，“如果是那个大脑袋，我肯定得不到一颗心。大脑袋自己没有心，所以也不会明白我的感受。”'),
    (11, 534, 1047, 'But if it is the lovely Lady I shall beg hard for a heart, for all ladies are themselves said to be kindly hearted.”', '“但如果是那位漂亮的女士，我就会拼命求她给我一颗心。因为大家都说，女士们的心都很善良。”'),
    (11, 535, 1048, 'But when the Woodman entered the great Throne Room he saw neither the Head nor the Lady, for Oz had taken the shape of a most terrible Beast.', '但当铁皮人走进大大的王座厅时，他没有看到大脑袋，也没有看到那位女士。因为奥兹大王变成了一只特别可怕的野兽。'),
    (11, 535, 1049, 'It was nearly as big as an elephant, and the green throne seemed hardly strong enough to hold its weight.', '它差不多和大象一样大，那个绿色的宝座好像都快承受不住它的重量了。'),
    (11, 535, 1050, 'The Beast had a head like that of a rhinoceros, only there were five eyes in its face.', '这只野兽的头长得像犀牛，不过它的脸上长了五只眼睛。'),
    (11, 535, 1051, 'There were five long arms growing out of its body, and it also had five long, slim legs.', '它身上长着五条长长的胳膊，还有五条又长又细的腿。'),
    (11, 535, 1052, 'Thick, woolly hair covered every part of it, and a more dreadful-looking monster could not be imagined.', '它全身都盖着厚厚的羊毛状的毛，真是想不到还有比它更可怕的怪兽了。'),
    (11, 535, 1053, 'It was fortunate the Tin Woodman had no heart at that moment, for it would have beat loud and fast from terror.', '幸好那个时候，铁皮人没有心脏，不然它会因为害怕而心跳得又响又快。'),
    (11, 535, 1054, 'But being only tin, the Woodman was not at all afraid, although he was much disappointed.', '但因为铁皮人只是个铁皮人，所以一点也不害怕，虽然它很失望。'),
    (11, 536, 1055, '“I am Oz, the Great and Terrible,” spoke the Beast, in a voice that was one great roar.', '“我是奥兹大王，那个又伟大又可怕的，”野兽吼着说，声音像一声巨吼。'),
    (11, 536, 1056, '“Who are you, and why do you seek me?”', '“你是谁？为什么要找我？”'),
    (11, 537, 1057, '“I am a Woodman, and made of tin.', '“我是一个铁皮人，是用铁皮做的。”'),
    (11, 537, 1058, 'Therefore I have no heart, and cannot love.', '“所以我没有心，也无法爱人。”'),
    (11, 537, 1059, 'I pray you to give me a heart that I may be as other men are.”', '“我求你给我一颗心，让我能像其他人一样。”'),
    (11, 538, 1060, '“Why should I do this?” demanded the Beast.', '“我为什么要这么做？”野兽问道。'),
    (11, 539, 1061, '“Because I ask it, and you alone can grant my request,” answered the Woodman.', '“因为我请求你，而且只有你才能帮我这个忙，”铁皮人回答。'),
    (11, 540, 1062, 'Oz gave a low growl at this, but said, gruffly: “If you indeed desire a heart, you must earn it.”', '听到这话，奥兹大王低吼了一声，然后粗声说：“如果你真的想要一颗心，你就必须去争取。”'),
    (11, 541, 1063, '“How?” asked the Woodman.', '“怎么争取？”铁皮人问。'),
    (11, 542, 1064, '“Help Dorothy to kill the Wicked Witch of the West,” replied the Beast.', '“帮多萝西杀死西方坏女巫，”野兽回答。'),
    (11, 542, 1065, '“When the Witch is dead, come to me, and I will then give you the biggest and kindest and most loving heart in all the Land of Oz.”', '“当女巫死了，你再来找我，我就会给你整个奥兹国里最大、最善良、最有爱心的心。”'),
    (11, 543, 1066, 'So the Tin Woodman was forced to return sorrowfully to his friends and tell them of the terrible Beast he had seen.', '于是，铁皮人只好伤心地回到朋友们身边，告诉他们它看到的那个可怕的野兽。'),
    (11, 543, 1067, 'They all wondered greatly at the many forms the Great Wizard could take upon himself, and the Lion said:', '他们都很好奇，大魔法师能变成这么多样子，狮子说：'),
    (11, 544, 1068, '“If he is a Beast when I go to see him, I shall roar my loudest, and so frighten him that he will grant all I ask.', '“如果我去见他时，他是一只野兽，我就大声吼叫，吓得他答应我所有的要求。”'),
    (11, 544, 1069, 'And if he is the lovely Lady, I shall pretend to spring upon her, and so compel her to do my bidding.', '“如果他是一个可爱的女士，我就假装扑向她，逼她听我的话。”'),
    (11, 544, 1070, 'And if he is the great Head, he will be at my mercy; for I will roll this head all about the room until he promises to give us what we desire.', '“如果他是一个巨大的头，那他就会任我摆布；我会把这个头在房间里滚来滚去，直到他答应给我们想要的东西。”'),
    (11, 544, 1071, 'So be of good cheer, my friends, for all will yet be well.”', '“所以，我的朋友们，开心点吧，一切都会好起来的。”'),
    (11, 545, 1072, 'The next morning the soldier with the green whiskers led the Lion to the great Throne Room and bade him enter the presence of Oz.', '第二天早上，那个留着绿色胡子的士兵带着狮子来到巨大的宝座室，让它进去见奥兹大王。'),
    (11, 546, 1073, 'The Lion at once passed through the door, and glancing around saw, to his surprise, that before the throne was a Ball of Fire, so fierce and glowing he could scarcely bear to gaze upon it.', '狮子立刻穿过门，环顾四周，惊讶地看到宝座前有一个火球，又凶又亮，它几乎不敢直视。'),
    (11, 546, 1074, 'His first thought was that Oz had by accident caught on fire and was burning up; but when he tried to go nearer, the heat was so intense that it singed his whiskers, and he crept back tremblingly to a spot nearer the door.', '它第一个念头是奥兹大王不小心着火了，正在燃烧；但当它试图走近时，热量太大了，把它的胡须都烧焦了，它颤抖着爬回离门更近的地方。'),
    (11, 547, 1075, 'Then a low, quiet voice came from the Ball of Fire, and these were the words it spoke:', '接着，一个低沉、安静的声音从火球中传来，它说的话是：'),
    (11, 548, 1076, '“I am Oz, the Great and Terrible.', '“我是奥兹大王，那个又伟大又可怕的。”'),
    (11, 548, 1077, 'Who are you, and why do you seek me?”', '“你是谁？为什么要找我？”'),
    (11, 549, 1078, 'And the Lion answered, “I am a Cowardly Lion, afraid of everything.', '狮子回答说：“我是一个胆小的狮子，什么都怕。”'),
    (11, 549, 1079, 'I came to you to beg that you give me courage, so that in reality I may become the King of Beasts, as men call me.”', '“我来求你给我勇气，这样我才能真正成为人们口中的万兽之王。”'),
    (11, 550, 1080, '“Why should I give you courage?” demanded Oz.', '“我为什么要给你勇气？”奥兹大王问道。'),
    (11, 551, 1081, '“Because of all Wizards you are the greatest, and alone have power to grant my request,” answered the Lion.', '“因为在所有巫师里，您最厉害，只有您能帮我实现愿望，”狮子回答说。'),
    (11, 552, 1082, 'The Ball of Fire burned fiercely for a time, and the voice said, “Bring me proof that the Wicked Witch is dead, and that moment I will give you courage.', '火球猛烈地烧了一会儿，那个声音说：“如果你能证明坏女巫已经死了，我立刻就给你勇气。'),
    (11, 552, 1083, 'But as long as the Witch lives, you must remain a coward.”', '“但是只要巫婆还活着，你就只能是个胆小鬼。”'),
    (11, 553, 1084, 'The Lion was angry at this speech, but could say nothing in reply, and while he stood silently gazing at the Ball of Fire it became so furiously hot that he turned tail and rushed from the room.', '狮子听了这番话很生气，却说不出话来反驳。他静静地看着火球，火球变得太热了，他只好转身冲出了房间。'),
    (11, 553, 1085, 'He was glad to find his friends waiting for him, and told them of his terrible interview with the Wizard.', '他很高兴看到朋友们在等他，然后把和巫师糟糕的谈话告诉了他们。'),
    (11, 554, 1086, '“What shall we do now?” asked Dorothy sadly.', '“我们现在该怎么办呢？”多萝西伤心地问。'),
    (11, 555, 1087, '“There is only one thing we can do,” returned the Lion, “and that is to go to the land of the Winkies, seek out the Wicked Witch, and destroy her.”', '“我们只有一件事可以做，”狮子回答说，“那就是去温基人的土地，找到坏女巫，然后消灭她。”'),
    (11, 556, 1088, '“But suppose we cannot?” said the girl.', '“但如果我们做不到呢？”女孩说。'),
    (11, 557, 1089, '“Then I shall never have courage,” declared the Lion.', '“那我就永远没有勇气了，”狮子说。'),
    (11, 558, 1090, '“And I shall never have brains,” added the Scarecrow.', '“那我就永远没有脑子了，”稻草人补充说。'),
    (11, 559, 1091, '“And I shall never have a heart,” spoke the Tin Woodman.', '“那我就永远没有心了，”铁皮人说。'),
    (11, 560, 1092, '“And I shall never see Aunt Em and Uncle Henry,” said Dorothy, beginning to cry.', '“那我就永远见不到艾姆婶婶和亨利叔叔了，”多萝西说着，开始哭了。'),
    (11, 561, 1093, '“Be careful!” cried the green girl. “The tears will fall on your green silk gown and spot it.”', '“小心！”那个绿衣女孩喊道，“眼泪会滴到你的绿丝裙上，弄脏它的。”'),
    (11, 562, 1094, 'So Dorothy dried her eyes and said, “I suppose we must try it; but I am sure I do not want to kill anybody, even to see Aunt Em again.”', '于是多萝西擦干了眼睛说：“我想我们必须试试；但我真的不想杀任何人，哪怕是为了再见到艾姆婶婶。”'),
    (11, 563, 1095, '“I will go with you; but I’m too much of a coward to kill the Witch,” said the Lion.', '“我跟你们一起去；但我太胆小了，不敢杀巫婆，”狮子说。'),
    (11, 564, 1096, '“I will go too,” declared the Scarecrow; “but I shall not be of much help to you, I am such a fool.”', '“我也去，”稻草人说；“但我帮不了你们太多忙，我太笨了。”'),
    (11, 565, 1097, '“I haven’t the heart to harm even a Witch,” remarked the Tin Woodman; “but if you go I certainly shall go with you.”', '“我可没有心去伤害哪怕一个巫婆，”铁皮人说；“但如果你们去，我一定会跟着你们。”'),
    (11, 566, 1098, 'Therefore it was decided to start upon their journey the next morning, and the Woodman sharpened his axe on a green grindstone and had all his joints properly oiled.', '于是大家决定第二天早上就开始旅程，铁皮人在一个绿色的磨刀石上磨了他的斧头，还把他的关节都好好地上了油。'),
    (11, 566, 1099, 'The Scarecrow stuffed himself with fresh straw and Dorothy put new paint on his eyes that he might see better.', '稻草人给自己塞满了新鲜的稻草，多萝西在他的眼睛上涂了新颜料，这样他就能看得更清楚了。'),
    (11, 566, 1100, 'The green girl, who was very kind to them, filled Dorothy’s basket with good things to eat, and fastened a little bell around Toto’s neck with a green ribbon.', '那个对他们很好的绿衣女孩，给多萝西的篮子里装满了好吃的东西，还用一条绿色的丝带在托托的脖子上系了一个小铃铛。'),
    (11, 567, 1101, 'They went to bed quite early and slept soundly until daylight, when they were awakened by the crowing of a green cock that lived in the back yard of the Palace, and the cackling of a hen that had laid a green egg.', '他们很早就睡了，一直睡得很香，直到天亮。天亮时，他们被住在宫殿后院的一只绿色公鸡的叫声，和一只下了绿色蛋的母鸡的咯咯声吵醒了。'),
    (12, 568, 1102, 'The soldier with the green whiskers led them through the streets of the Emerald City until they reached the room where the Guardian of the Gates lived.', '那个绿胡子士兵带着他们穿过翡翠城的街道，直到他们到达了城门守卫住的房间。'),
    (12, 568, 1103, 'This officer unlocked their spectacles to put them back in his great box, and then he politely opened the gate for our friends.', '这位官员解开了他们的眼镜，把它们放回他的大盒子里，然后他礼貌地为我们的朋友们打开了大门。'),
    (12, 569, 1104, '“Which road leads to the Wicked Witch of the West?” asked Dorothy.', '“哪条路通向西方坏女巫？”多萝西问。'),
    (12, 570, 1105, '“There is no road,” answered the Guardian of the Gates.', '“没有路，”城门守卫回答说。'),
    (12, 570, 1106, '“No one ever wishes to go that way.”', '“从来没有人想走那条路。”'),
    (12, 571, 1107, '“How, then, are we to find her?” inquired the girl.', '“那我们怎么才能找到她呢？”女孩问道。'),
    (12, 572, 1108, '“That will be easy,” replied the man, “for when she knows you are in the country of the Winkies she will find you, and make you all her slaves.”', '“那很容易，”那人回答说，“因为当她知道你们在温基人的国家时，她会找到你们，并把你们都变成她的奴隶。”'),
    (12, 573, 1109, '“Perhaps not,” said the Scarecrow, “for we mean to destroy her.”', '“也许不会，”稻草人说，“因为我们打算消灭她。”'),
    (12, 574, 1110, '“Oh, that is different,” said the Guardian of the Gates.', '“哦，那可不一样了，”城门守卫说。'),
    (12, 574, 1111, '“No one has ever destroyed her before, so I naturally thought she would make slaves of you, as she has of the rest.', '“以前没人打败过她，我以为她会把你们变成奴隶，就像对其他人那样。'),
    (12, 574, 1112, 'But take care; for she is wicked and fierce, and may not allow you to destroy her.', '不过你们要小心哦！她很坏很凶，可能不会让你们打败她。'),
    (12, 574, 1113, 'Keep to the West, where the sun sets, and you cannot fail to find her.”', '一直往西边走，就是太阳下山的地方，你们肯定能找到她。”'),
    (12, 575, 1114, 'They thanked him and bade him good-bye, and turned toward the West, walking over fields of soft grass dotted here and there with daisies and buttercups.', '他们谢谢他，跟他说了再见，就往西边走。他们走过软软的草地，草地上开着小雏菊和金凤花。'),
    (12, 575, 1115, 'Dorothy still wore the pretty silk dress she had put on in the palace, but now, to her surprise, she found it was no longer green, but pure white.', '多萝西还穿着在宫殿里的漂亮丝绸裙子，但让她惊讶的是，裙子不再是绿色，而是纯白色了。'),
    (12, 575, 1116, 'The ribbon around Toto’s neck had also lost its green color and was as white as Dorothy’s dress.', '托托脖子上的丝带也变白了，和多萝西的裙子一样白。'),
    (12, 576, 1117, 'The Emerald City was soon left far behind.', '很快，翡翠城就被远远地甩在后面了。'),
    (12, 576, 1118, 'As they advanced the ground became rougher and hillier, for there were no farms nor houses in this country of the West, and the ground was untilled.', '他们往前走，地面变得越来越不平坦，还出现了小山坡。因为西边的这片土地上，没有农场，没有房子，也没有人耕地。'),
    (12, 577, 1119, 'In the afternoon the sun shone hot in their faces, for there were no trees to offer them shade; so that before night Dorothy and Toto and the Lion were tired, and lay down upon the grass and fell asleep, with the Woodman and the Scarecrow keeping watch.', '下午，太阳晒得他们的脸热热的，因为这里没有大树遮荫。所以天黑前，多萝西、托托和狮子都累了，躺在草地上睡着了。铁皮人和稻草人帮他们守夜。'),
    (12, 578, 1120, 'Now the Wicked Witch of the West had but one eye, yet that was as powerful as a telescope, and could see everywhere.', '那个西方坏女巫只有一只眼睛，但这只眼睛像望远镜一样厉害，能看到所有地方。'),
    (12, 578, 1121, 'So, as she sat in the door of her castle, she happened to look around and saw Dorothy lying asleep, with her friends all about her.', '她坐在城堡门口，不经意间往四周一看，就看见睡着的多萝西，她的朋友们都在她身边。'),
    (12, 578, 1122, 'They were a long distance off, but the Wicked Witch was angry to find them in her country; so she blew upon a silver whistle that hung around her neck.', '他们离得很远，但坏女巫发现他们在自己的地盘上，非常生气。于是，她吹响了挂在脖子上的银哨子。'),
    (12, 579, 1123, 'At once there came running to her from all directions a pack of great wolves.', '一下子，一大群大灰狼就从四面八方跑到了她身边。'),
    (12, 579, 1124, 'They had long legs and fierce eyes and sharp teeth.', '它们有长长的腿，凶狠的眼睛，还有尖尖的牙齿。'),
    (12, 580, 1125, '“Go to those people,” said the Witch, “and tear them to pieces.”', '“去把那些人撕成碎片！”女巫说。'),
    (12, 581, 1126, '“Are you not going to make them your slaves?” asked the leader of the wolves.', '“你不是要把他们变成奴隶吗？”狼头领问。'),
    (12, 582, 1127, '“No,” she answered, “one is of tin, and one of straw; one is a girl and another a Lion.', '“不，”她回答，“一个是铁皮，一个是稻草；一个是小女孩，另一个是狮子。'),
    (12, 582, 1128, 'None of them is fit to work, so you may tear them into small pieces.”', '他们没一个能干活的，所以你们可以把他们撕成小碎片。”'),
    (12, 583, 1129, '“Very well,” said the wolf, and he dashed away at full speed, followed by the others.', '“好嘞！”狼说，然后它就飞快地冲了出去，其他狼也跟着它。'),
    (12, 584, 1130, 'It was lucky the Scarecrow and the Woodman were wide awake and heard the wolves coming.', '幸好稻草人和铁皮人都醒着，听到了狼群来了。'),
    (12, 585, 1131, '“This is my fight,” said the Woodman, “so get behind me and I will meet them as they come.”', '“这是我的战斗，”铁皮人说，“你们躲在我后面，我来对付它们。”'),
    (12, 586, 1132, 'He seized his axe, which he had made very sharp, and as the leader of the wolves came on the Tin Woodman swung his arm and chopped the wolf’s head from its body, so that it immediately died.', '他拿起磨得很锋利的斧子。当狼头领冲上来时，铁皮人一挥手，就把狼的头砍了下来，狼立刻就死了。'),
    (12, 586, 1133, 'As soon as he could raise his axe another wolf came up, and he also fell under the sharp edge of the Tin Woodman’s weapon.', '他刚举起斧子，又一只狼冲了上来，也倒在了铁皮人的锋利武器下。'),
    (12, 586, 1134, 'There were forty wolves, and forty times a wolf was killed, so that at last they all lay dead in a heap before the Woodman.', '一共有四十只狼，铁皮人杀了四十只，最后它们都堆在铁皮人面前死掉了。'),
    (12, 587, 1135, 'Then he put down his axe and sat beside the Scarecrow, who said, “It was a good fight, friend.”', '然后他放下斧子，坐在稻草人旁边，稻草人说：“朋友，你打得真棒！”'),
    (12, 588, 1136, 'They waited until Dorothy awoke the next morning.', '他们等到第二天早上多萝西醒来。'),
    (12, 588, 1137, 'The little girl was quite frightened when she saw the great pile of shaggy wolves, but the Tin Woodman told her all.', '小女孩看到一大堆毛茸茸的狼，吓得不轻，但铁皮人把所有事情都告诉了她。'),
    (12, 588, 1138, 'She thanked him for saving them and sat down to breakfast, after which they started again upon their journey.', '她谢谢他救了大家，然后坐下来吃早饭。吃完饭，他们又继续赶路了。'),
    (12, 589, 1139, 'Now this same morning the Wicked Witch came to the door of her castle and looked out with her one eye that could see far off.', '就在这天早上，坏女巫来到城堡门口，用她那只看得可远的眼睛往外看。'),
    (12, 589, 1140, 'She saw all her wolves lying dead, and the strangers still traveling through her country.', '她看到自己的狼都死了，那些陌生人还在她的地盘上走着。'),
    (12, 589, 1141, 'This made her angrier than before, and she blew her silver whistle twice.', '这让她更生气了，她吹了两下银哨子。'),
    (12, 590, 1142, 'Straightway a great flock of wild crows came flying toward her, enough to darken the sky.', '很快，一大群野乌鸦飞来了，它们多得把天空都遮住了。'),
    (12, 591, 1143, 'And the Wicked Witch said to the King Crow, “Fly at once to the strangers; peck out their eyes and tear them to pieces.”', '那个坏女巫对乌鸦王说：“快飞过去，把陌生人的眼睛啄出来，把他们撕碎！”'),
    (12, 592, 1144, 'The wild crows flew in one great flock toward Dorothy and her companions.', '野乌鸦一大群地飞向多萝西和她的朋友们。'),
    (12, 592, 1145, 'When the little girl saw them coming she was afraid.', '小女孩看到乌鸦飞来，有点害怕。'),
    (12, 593, 1146, 'But the Scarecrow said, “This is my battle, so lie down beside me and you will not be harmed.”', '但是稻草人说：“这是我的事情，你们躺在我旁边，就不会受伤。”'),
    (12, 594, 1147, 'So they all lay upon the ground except the Scarecrow, and he stood up and stretched out his arms.', '于是，除了稻草人，大家都躺在地上。他站起来，伸开双臂。'),
    (12, 594, 1148, 'And when the crows saw him they were frightened, as these birds always are by scarecrows, and did not dare to come any nearer.', '乌鸦们看到他，吓了一跳。因为这些鸟总是害怕稻草人，所以不敢再靠近。'),
    (12, 594, 1149, 'But the King Crow said:', '但是乌鸦王说：'),
    (12, 595, 1150, '“It is only a stuffed man.', '“这只是个用稻草做的假人。”'),
    (12, 595, 1151, 'I will peck his eyes out.”', '“我要把他的眼睛啄出来。”'),
    (12, 596, 1152, 'The King Crow flew at the Scarecrow, who caught it by the head and twisted its neck until it died.', '乌鸦王飞向稻草人，稻草人抓住了它的头，把它的脖子扭断，乌鸦就死了。'),
    (12, 596, 1153, 'And then another crow flew at him, and the Scarecrow twisted its neck also.', '然后另一只乌鸦飞过来，稻草人也扭断了它的脖子。'),
    (12, 596, 1154, 'There were forty crows, and forty times the Scarecrow twisted a neck, until at last all were lying dead beside him.', '一共有四十只乌鸦，稻草人扭了四十次脖子，直到所有的乌鸦都死了，躺在他身边。'),
    (12, 596, 1155, 'Then he called to his companions to rise, and again they went upon their journey.', '然后他叫伙伴们起来，他们又继续赶路了。'),
    (12, 597, 1156, 'When the Wicked Witch looked out again and saw all her crows lying in a heap, she got into a terrible rage, and blew three times upon her silver whistle.', '那个坏女巫又往外看，看到她的乌鸦都死成一堆，她气得不得了，吹了三下银哨子。'),
    (12, 598, 1157, 'Forthwith there was heard a great buzzing in the air, and a swarm of black bees came flying toward her.', '很快，空中传来一阵嗡嗡声，一大群黑蜜蜂飞向她。'),
    (12, 599, 1158, '“Go to the strangers and sting them to death!” commanded the Witch, and the bees turned and flew rapidly until they came to where Dorothy and her friends were walking.', '“去把陌生人蜇死！”女巫命令道。蜜蜂们很快飞到多萝西和她朋友们的地方。'),
    (12, 599, 1159, 'But the Woodman had seen them coming, and the Scarecrow had decided what to do.', '但是铁皮人已经看到它们飞来了，稻草人也想好了办法。'),
    (12, 600, 1160, '“Take out my straw and scatter it over the little girl and the dog and the Lion,” he said to the Woodman, “and the bees cannot sting them.”', '他对铁皮人说：“把我身上的稻草拿出来，撒在小女孩、小狗和狮子身上，这样蜜蜂就蜇不到他们了。”'),
    (12, 600, 1161, 'This the Woodman did, and as Dorothy lay close beside the Lion and held Toto in her arms, the straw covered them entirely.', '铁皮人照做了。当多萝西紧紧地躺在狮子旁边，怀里抱着托托时，稻草把他们全都盖住了。'),
    (12, 601, 1162, 'The bees came and found no one but the Woodman to sting, so they flew at him and broke off all their stings against the tin, without hurting the Woodman at all.', '蜜蜂飞来，发现只有铁皮人可以蜇，于是它们都飞向他，把所有的毒刺都刺在铁皮上，一点也没伤到铁皮人。'),
    (12, 601, 1163, 'And as bees cannot live when their stings are broken that was the end of the black bees, and they lay scattered thick about the Woodman, like little heaps of fine coal.', '蜜蜂的毒刺断了就活不了。所以那些黑蜜蜂都死了，它们密密麻麻地散落在铁皮人身边，就像一小堆堆细小的煤炭。'),
    (12, 602, 1164, 'Then Dorothy and the Lion got up, and the girl helped the Tin Woodman put the straw back into the Scarecrow again, until he was as good as ever.', '然后多萝西和狮子站起来，小女孩帮铁皮人把稻草重新放回稻草人里面，他又变得和以前一样好。'),
    (12, 602, 1165, 'So they started upon their journey once more.', '于是他们又出发了。'),
    (12, 603, 1166, 'The Wicked Witch was so angry when she saw her black bees in little heaps like fine coal that she stamped her foot and tore her hair and gnashed her teeth.', '那个坏女巫看到黑蜜蜂死成一小堆堆像细煤炭一样，气得直跺脚，撕扯自己的头发，还咬牙切齿。'),
    (12, 603, 1167, 'And then she called a dozen of her slaves, who were the Winkies, and gave them sharp spears, telling them to go to the strangers and destroy them.', '然后她叫来十几个奴隶，也就是那些温基人，给了他们锋利的矛，让他们去把陌生人消灭掉。'),
    (12, 604, 1168, 'The Winkies were not a brave people, but they had to do as they were told.', '那些温基人不是很勇敢，但他们必须听命令。'),
    (12, 604, 1169, 'So they marched away until they came near to Dorothy.', '于是他们出发了，一直走到快靠近多萝西的地方。'),
    (12, 604, 1170, 'Then the Lion gave a great roar and sprang towards them, and the poor Winkies were so frightened that they ran back as fast as they could.', '然后狮子大吼一声，跳向他们，可怜的温基人吓坏了，撒腿就跑了回去。'),
    (12, 605, 1171, 'When they returned to the castle the Wicked Witch beat them well with a strap, and sent them back to their work, after which she sat down to think what she should do next.', '当他们回到城堡，坏女巫用鞭子好好地教训了他们，然后让他们继续工作。接着，她坐下来想，接下来该怎么做。'),
    (12, 605, 1172, 'She could not understand how all her plans to destroy these strangers had failed; but she was a powerful Witch, as well as a wicked one, and she soon made up her mind how to act.', '她不明白，为什么她想赶走这些陌生人的办法都失败了。不过她是个很厉害、也很坏的女巫，所以她很快就想好了下一步该怎么做。'),
    (12, 606, 1173, 'There was, in her cupboard, a Golden Cap, with a circle of diamonds and rubies running round it.', '在她的柜子里，有一个金冠。它上面有一圈亮晶晶的钻石和红宝石。'),
    (12, 606, 1174, 'This Golden Cap had a charm.', '这个金冠有魔力。'),
    (12, 606, 1175, 'Whoever owned it could call three times upon the Winged Monkeys, who would obey any order they were given.', '谁戴上它，就能叫飞猴三次。飞猴会听从他说的任何命令。'),
    (12, 606, 1176, 'But no person could command these strange creatures more than three times.', '但是，没有人能命令这些奇怪的家伙超过三次。'),
    (12, 606, 1177, 'Twice already the Wicked Witch had used the charm of the Cap.', '坏女巫已经用过帽子上的魔力两次了。'),
    (12, 606, 1178, 'Once was when she had made the Winkies her slaves, and set herself to rule over their country.', '第一次是她把温基人变成了自己的奴隶，还当上了他们的国王。'),
    (12, 606, 1179, 'The Winged Monkeys had helped her do this.', '飞猴帮她做到了这件事。'),
    (12, 606, 1180, 'The second time was when she had fought against the Great Oz himself, and driven him out of the land of the West.', '第二次是她和厉害的奥兹大王打架，把他赶出了西边的土地。'),
    (12, 606, 1181, 'The Winged Monkeys had also helped her in doing this.', '飞猴也帮她做到了这件事。'),
    (12, 606, 1182, 'Only once more could she use this Golden Cap, for which reason she did not like to do so until all her other powers were exhausted.', '她只能再用这个金冠一次了。所以，除非她其他的厉害本领都用完了，她才不想用它。'),
    (12, 606, 1183, 'But now that her fierce wolves and her wild crows and her stinging bees were gone, and her slaves had been scared away by the Cowardly Lion, she saw there was only one way left to destroy Dorothy and her friends.', '可是现在，她的坏狼、野乌鸦和会蜇人的蜜蜂都跑光了。她的奴隶也被胆小的狮子吓走了。她发现，只剩下最后一个办法可以赶走多萝西和她的朋友们了。'),
    (12, 607, 1184, 'So the Wicked Witch took the Golden Cap from her cupboard and placed it upon her head.', '于是，坏女巫从柜子里拿出金冠，戴在自己头上。'),
    (12, 607, 1185, 'Then she stood upon her left foot and said, slowly:', '然后她用左脚站着，慢慢地说：'),
    (12, 608, 1186, '“Ep-pe, pep-pe, kak-ke!”', '“Ep-pe, pep-pe, kak-ke！”'),
    (12, 609, 1187, 'Next she stood upon her right foot and said:', '接着，她用右脚站着，说：'),
    (12, 610, 1188, '“Hil-lo, hol-lo, hel-lo!”', '“Hil-lo, hol-lo, hel-lo！”'),
    (12, 611, 1189, 'After this she stood upon both feet and cried in a loud voice:', '说完，她两只脚都站好了，大声喊道：'),
    (12, 612, 1190, '“Ziz-zy, zuz-zy, zik!”', '“Ziz-zy, zuz-zy, zik！”'),
    (12, 613, 1191, 'Now the charm began to work.', '现在，魔力开始起作用了。'),
    (12, 613, 1192, 'The sky was darkened, and a low rumbling sound was heard in the air.', '天空变黑了，空气中传来一阵低沉的“轰隆隆”的声音。'),
    (12, 613, 1193, 'There was a rushing of many wings, a great chattering and laughing, and the sun came out of the dark sky to show the Wicked Witch surrounded by a crowd of monkeys, each with a pair of immense and powerful wings on his shoulders.', '好多翅膀“呼啦啦”地飞过，还传来一阵阵吱吱喳喳的说话声和笑声。太阳从黑乎乎的天空中露出来，大家看到坏女巫被一群猴子围住了。每只猴子的肩膀上都有一对很大很有力的翅膀。'),
    (12, 614, 1194, 'One, much bigger than the others, seemed to be their leader.', '其中有一只，比别的猴子大好多，它好像是猴子们的头儿。'),
    (12, 614, 1195, 'He flew close to the Witch and said, “You have called us for the third and last time.', '它飞到女巫身边说：“你已经叫我们第三次了，也是最后一次了。'),
    (12, 614, 1196, 'What do you command?”', '你有什么吩咐呢？”'),
    (12, 615, 1197, '“Go to the strangers who are within my land and destroy them all except the Lion,” said the Wicked Witch.', '“去我这里，把那些陌生人都赶走，除了狮子，”坏女巫说。'),
    (12, 615, 1198, '“Bring that beast to me, for I have a mind to harness him like a horse, and make him work.”', '“把那个怪兽带给我，我想把它像马一样套上绳子，让它干活。”'),
    (12, 616, 1199, '“Your commands shall be obeyed,” said the leader.', '“你的命令我们会照做，”猴子头儿说。'),
    (12, 616, 1200, 'Then, with a great deal of chattering and noise, the Winged Monkeys flew away to the place where Dorothy and her friends were walking.', '然后，飞猴吱吱喳喳地叫着，闹哄哄地飞走了，飞到了多萝西和她的朋友们正在走路的地方。'),
    (12, 617, 1201, 'Some of the Monkeys seized the Tin Woodman and carried him through the air until they were over a country thickly covered with sharp rocks.', '一些猴子抓住了 铁皮人，带着他飞到空中，一直飞到一片到处都是尖尖石头的地方。'),
    (12, 617, 1202, 'Here they dropped the poor Woodman, who fell a great distance to the rocks, where he lay so battered and dented that he could neither move nor groan.', '它们把可怜的 铁皮人 从高空扔了下去，他重重地摔在石头上，摔得扁扁的，动也动不了，哼都哼不出声。'),
    (12, 618, 1203, 'Others of the Monkeys caught the Scarecrow, and with their long fingers pulled all of the straw out of his clothes and head.', '另一些猴子抓住了 稻草人，用它们长长的手指把衣服和头里的稻草都拉了出来。'),
    (12, 618, 1204, 'They made his hat and boots and clothes into a small bundle and threw it into the top branches of a tall tree.', '它们把他的帽子、靴子和衣服捆成一小捆，扔到了一棵高高的大树顶上。'),
    (12, 619, 1205, 'The remaining Monkeys threw pieces of stout rope around the Lion and wound many coils about his body and head and legs, until he was unable to bite or scratch or struggle in any way.', '剩下的猴子用粗粗的绳子套住 狮子，把他的身子、头和腿都紧紧地缠起来，让他不能咬，不能抓，也不能挣扎了。'),
    (12, 619, 1206, 'Then they lifted him up and flew away with him to the Witch’s castle, where he was placed in a small yard with a high iron fence around it, so that he could not escape.', '然后它们抬起他，带着他飞到了女巫的城堡，把他关在一个有高高铁栏杆的小院子里，让他逃不掉。'),
    (12, 620, 1207, 'But Dorothy they did not harm at all.', '但是 多萝西 它们一点儿也没伤害。'),
    (12, 620, 1208, 'She stood, with Toto in her arms, watching the sad fate of her comrades and thinking it would soon be her turn.', '她抱着 托托 站在那里，看着她的朋友们遇到麻烦，想着很快就会轮到自己了。'),
    (12, 620, 1209, 'The leader of the Winged Monkeys flew up to her, his long, hairy arms stretched out and his ugly face grinning terribly; but he saw the mark of the Good Witch’s kiss upon her forehead and stopped short, motioning the others not to touch her.', '飞猴 的头儿飞到她身边，他伸出长长的、毛茸茸的胳膊，丑陋的脸上露出可怕的笑容；但他看到了 好女巫 亲吻在她额头上的印记，立刻停了下来，示意别的猴子不要碰她。'),
    (12, 621, 1210, '“We dare not harm this little girl,” he said to them, “for she is protected by the Power of Good, and that is greater than the Power of Evil.', '“我们不敢伤害这个小女孩，”他对它们说，“因为有善良的力量保护她，那比邪恶的力量更强大。'),
    (12, 621, 1211, 'All we can do is to carry her to the castle of the Wicked Witch and leave her there.”', '我们能做的只有把她带到 坏女巫 的城堡，把她留在那里。”'),
    (12, 622, 1212, 'So, carefully and gently, they lifted Dorothy in their arms and carried her swiftly through the air until they came to the castle, where they set her down upon the front doorstep.', '于是，它们小心翼翼地抱起 多萝西，带着她飞快地穿过空中，一直飞到城堡，把她放在大门口的台阶上。'),
    (12, 622, 1213, 'Then the leader said to the Witch:', '然后头儿对女巫说：'),
    (12, 623, 1214, '“We have obeyed you as far as we were able.', '“我们已经尽力听你的话了。'),
    (12, 623, 1215, 'The Tin Woodman and the Scarecrow are destroyed, and the Lion is tied up in your yard.', '铁皮人 和 稻草人 被毁了，狮子 也被绑在你的院子里了。'),
    (12, 623, 1216, 'The little girl we dare not harm, nor the dog she carries in her arms.', '那个小女孩我们不敢伤害，她怀里的狗狗我们也不敢伤害。'),
    (12, 623, 1217, 'Your power over our band is now ended, and you will never see us again.”', '你对我们这群猴子的控制结束了，你再也见不到我们了。”'),
    (12, 624, 1218, 'Then all the Winged Monkeys, with much laughing and chattering and noise, flew into the air and were soon out of sight.', '然后所有的 飞猴 大声笑着、说着、吵着，飞到空中，很快就不见了。'),
    (12, 625, 1219, 'The Wicked Witch was both surprised and worried when she saw the mark on Dorothy’s forehead, for she knew well that neither the Winged Monkeys nor she, herself, dare hurt the girl in any way.', '当 坏女巫 看到 多萝西 额头上的印记时，既惊讶又担心，因为她很清楚，无论是 飞猴 还是她自己，都不敢伤害这个小女孩。'),
    (12, 625, 1220, 'She looked down at Dorothy’s feet, and seeing the Silver Shoes, began to tremble with fear, for she knew what a powerful charm belonged to them.', '她低头看着 多萝西 的脚，看到 银鞋 后，吓得发抖，因为她知道 银鞋 有多么强大的魔法。'),
    (12, 625, 1221, 'At first the Witch was tempted to run away from Dorothy; but she happened to look into the child’s eyes and saw how simple the soul behind them was, and that the little girl did not know of the wonderful power the Silver Shoes gave her.', '女巫一开始差点儿就想从 多萝西 身边跑掉；但她碰巧看到了小女孩的眼睛，发现她的心灵多么纯真，而且小女孩根本不知道 银鞋 给了她多么神奇的力量。'),
    (12, 625, 1222, 'So the Wicked Witch laughed to herself, and thought, “I can still make her my slave, for she does not know how to use her power.”', '于是 坏女巫 偷偷地笑了，心想：“我还是可以把她变成我的仆人，因为她不知道怎么使用她的力量。”'),
    (12, 625, 1223, 'Then she said to Dorothy, harshly and severely:', '然后她凶巴巴地，很严厉地对 多萝西 说：'),
    (12, 626, 1224, '“Come with me; and see that you mind everything I tell you, for if you do not I will make an end of you, as I did of the Tin Woodman and the Scarecrow.”', '“跟我来；记住，要听我的话，如果不听，我就会像对付 铁皮人 和 稻草人 那样，把你消灭掉。”'),
    (12, 627, 1225, 'Dorothy followed her through many of the beautiful rooms in her castle until they came to the kitchen, where the Witch bade her clean the pots and kettles and sweep the floor and keep the fire fed with wood.', '多萝西 跟着她穿过城堡里许多漂亮的房间，一直到了厨房，女巫让她擦锅碗瓢盆，扫地，还要给炉子添柴火。'),
    (12, 628, 1226, 'Dorothy went to work meekly, with her mind made up to work as hard as she could; for she was glad the Wicked Witch had decided not to kill her.', '多萝西 顺从地开始干活，她决定要努力干活；因为她很高兴 坏女巫 决定不杀她。'),
    (12, 629, 1227, 'With Dorothy hard at work, the Witch thought she would go into the courtyard and harness the Cowardly Lion like a horse; it would amuse her, she was sure, to make him draw her chariot whenever she wished to go to drive.', '看到 多萝西 在努力干活，女巫心想她要去院子里，把 胆小的狮子 像马一样套起来；她相信，每次她想出去的时候，就让 胆小的狮子 给她拉马车，这会让她觉得好玩。'),
    (12, 629, 1228, 'But as she opened the gate the Lion gave a loud roar and bounded at her so fiercely that the Witch was afraid, and ran out and shut the gate again.', '但当她打开门的时候，狮子 大吼一声，凶猛地扑向她，女巫吓坏了，跑出去，又把门关上了。'),
    (12, 630, 1229, '“If I cannot harness you,” said the Witch to the Lion, speaking through the bars of the gate, “I can starve you.', '“如果我不能把你套起来，”女巫隔着门上的栏杆对 狮子 说，“我就可以把你饿死。'),
    (12, 630, 1230, 'You shall have nothing to eat until you do as I wish.”', '在你听我的话之前，什么也别想吃。”'),
    (12, 631, 1231, 'So after that she took no food to the imprisoned Lion; but every day she came to the gate at noon and asked, “Are you ready to be harnessed like a horse?”', '从那以后，她就不再给关着的狮子送吃的了；但是每天中午，她都会来到门口问：“你准备好像马一样被套上绳子了吗？”'),
    (12, 632, 1232, 'And the Lion would answer, “No. If you come in this yard, I will bite you.”', '而狮子会回答说：“不。如果你进这个院子，我就咬你。”'),
    (12, 633, 1233, 'The reason the Lion did not have to do as the Witch wished was that every night, while the woman was asleep, Dorothy carried him food from the cupboard.', '狮子不用按女巫希望的去做，是因为每天晚上，当女巫睡着的时候，多萝西会从柜子里给他拿吃的。'),
    (12, 633, 1234, 'After he had eaten he would lie down on his bed of straw, and Dorothy would lie beside him and put her head on his soft, shaggy mane, while they talked of their troubles and tried to plan some way to escape.', '他吃完后，就会躺在草床上，多萝西会躺在他身边，把头放在他柔软蓬松的鬃毛上，他们一边说着自己的烦恼，一边想办法逃跑。'),
    (12, 633, 1235, 'But they could find no way to get out of the castle, for it was constantly guarded by the yellow Winkies, who were the slaves of the Wicked Witch and too afraid of her not to do as she told them.', '但是他们找不到办法逃出城堡，因为城堡一直被黄色的温基人守着，它们是坏女巫的奴隶，太害怕她了，所以不敢不听她的话。'),
    (12, 634, 1236, 'The girl had to work hard during the day, and often the Witch threatened to beat her with the same old umbrella she always carried in her hand.', '白天，小女孩要努力干活，女巫经常威胁要用她手里那把旧伞打她。'),
    (12, 634, 1237, 'But, in truth, she did not dare to strike Dorothy, because of the mark upon her forehead.', '但是，其实她不敢打多萝西，因为她额头上的印记。'),
    (12, 634, 1238, 'The child did not know this, and was full of fear for herself and Toto.', '小女孩不知道这件事，她很害怕自己和托托。'),
    (12, 634, 1239, 'Once the Witch struck Toto a blow with her umbrella and the brave little dog flew at her and bit her leg in return.', '有一次女巫用伞打了托托一下，勇敢的小狗就扑过去咬了她的腿。'),
    (12, 634, 1240, 'The Witch did not bleed where she was bitten, for she was so wicked that the blood in her had dried up many years before.', '女巫被咬的地方没有流血，因为她太坏了，她身体里的血很多年前就干了。'),
    (12, 635, 1241, 'Dorothy’s life became very sad as she grew to understand that it would be harder than ever to get back to Kansas and Aunt Em again.', '多萝西的生活变得很伤心，因为她渐渐明白，再想回到堪萨斯和艾姆婶婶身边会比以前更难了。'),
    (12, 635, 1242, 'Sometimes she would cry bitterly for hours, with Toto sitting at her feet and looking into her face, whining dismally to show how sorry he was for his little mistress.', '有时候她会伤心地哭好几个小时，托托会坐在她脚边，看着她的脸，悲伤地呜咽着，表示它很心疼小主人。'),
    (12, 635, 1243, 'Toto did not really care whether he was in Kansas or the Land of Oz so long as Dorothy was with him; but he knew the little girl was unhappy, and that made him unhappy too.', '托托其实不在乎自己是在堪萨斯还是在奥兹国，只要多萝西在他身边就好；但是他知道小女孩不开心，这也让他不开心。'),
    (12, 636, 1244, 'Now the Wicked Witch had a great longing to have for her own the Silver Shoes which the girl always wore.', '现在坏女巫非常想要把小女孩一直穿在身上的银鞋占为己有。'),
    (12, 636, 1245, 'Her bees and her crows and her wolves were lying in heaps and drying up, and she had used up all the power of the Golden Cap; but if she could only get hold of the Silver Shoes, they would give her more power than all the other things she had lost.', '她的蜜蜂、乌鸦和狼都堆成一堆，枯萎了，她也用光了金冠所有的魔力；但是如果她能得到银鞋，它们会给她比她失去的所有东西加起来还要多的力量。'),
    (12, 636, 1246, 'She watched Dorothy carefully, to see if she ever took off her shoes, thinking she might steal them.', '她仔细地盯着多萝西，想看看她有没有脱下鞋子，觉得她可以偷走它们。'),
    (12, 636, 1247, 'But the child was so proud of her pretty shoes that she never took them off except at night and when she took her bath.', '但是小女孩很喜欢她的漂亮鞋子，所以除了晚上和洗澡的时候，她从不脱下它们。'),
    (12, 636, 1248, 'The Witch was too much afraid of the dark to dare go in Dorothy’s room at night to take the shoes, and her dread of water was greater than her fear of the dark, so she never came near when Dorothy was bathing.', '女巫太害怕黑暗了，不敢晚上去多萝西的房间拿鞋子，她对水的恐惧比对黑暗的恐惧更大，所以当多萝西洗澡的时候，她从不靠近。'),
    (12, 636, 1249, 'Indeed, the old Witch never touched water, nor ever let water touch her in any way.', '确实，这个老女巫从不碰水，也从不让水碰到她。'),
    (12, 637, 1250, 'But the wicked creature was very cunning, and she finally thought of a trick that would give her what she wanted.', '但是这个坏家伙很狡猾，她终于想到了一个能让她得到想要东西的办法。'),
    (12, 637, 1251, 'She placed a bar of iron in the middle of the kitchen floor, and then by her magic arts made the iron invisible to human eyes.', '她在厨房地板中间放了一根铁棍，然后用魔法让铁棍在人的眼睛里看不见。'),
    (12, 637, 1252, 'So that when Dorothy walked across the floor she stumbled over the bar, not being able to see it, and fell at full length.', '这样当多萝西走过地板时，她会绊倒在铁棍上，因为她看不见它，然后就摔了个大跟头。'),
    (12, 637, 1253, 'She was not much hurt, but in her fall one of the Silver Shoes came off; and before she could reach it, the Witch had snatched it away and put it on her own skinny foot.', '她没有受太大的伤，但是她摔倒的时候，一只银鞋掉了下来；还没等她捡起来，女巫就一把抢走了，穿在了自己瘦瘦的脚上。'),
    (12, 638, 1254, 'The wicked woman was greatly pleased with the success of her trick, for as long as she had one of the shoes she owned half the power of their charm, and Dorothy could not use it against her, even had she known how to do so.', '这个坏女人对自己的计谋成功非常高兴，因为只要她有一只鞋子，她就拥有它们一半的魔力，而且多萝西也无法用它来对抗她，即使她知道怎么做。'),
    (12, 639, 1255, 'The little girl, seeing she had lost one of her pretty shoes, grew angry, and said to the Witch, “Give me back my shoe!”', '小女孩看到自己丢了一只漂亮的鞋子，就生气了，对女巫说：“把我的鞋子还给我！”'),
    (12, 640, 1256, '“I will not,” retorted the Witch, “for it is now my shoe, and not yours.”', '“我才不！”女巫反驳道，“因为这现在是我的鞋子，不是你的。”'),
    (12, 641, 1257, '“You are a wicked creature!” cried Dorothy. “You have no right to take my shoe from me.”', '“你这个坏家伙！”多萝西叫道，“你没权利拿走我的鞋子！”'),
    (12, 642, 1258, '“I shall keep it, just the same,” said the Witch, laughing at her, “and someday I shall get the other one from you, too.”', '“我还是要留着它，”女巫嘲笑着她说道，“总有一天，我还会从你那里拿到另一只的。”'),
    (12, 643, 1259, 'This made Dorothy so very angry that she picked up the bucket of water that stood near and dashed it over the Witch, wetting her from head to foot.', '这让多萝西非常生气，以至于她拿起旁边的一桶水，朝女巫泼过去，把她从头到脚都弄湿了。'),
    (12, 644, 1260, 'Instantly the wicked woman gave a loud cry of fear, and then, as Dorothy looked at her in wonder, the Witch began to shrink and fall away.', '坏女人立刻发出一声害怕的大叫，然后，当多萝西好奇地看着她的时候，女巫开始缩小并消失了。'),
    (12, 645, 1261, '“See what you have done!” she screamed. “In a minute I shall melt away.”', '“看你做了什么！”她大叫。“我很快就要融化了。”'),
    (12, 646, 1262, '“I’m very sorry, indeed,” said Dorothy, who was truly frightened to see the Witch actually melting away like brown sugar before her very eyes.', '“我真的对不起，”多萝西说，她吓坏了，因为女巫真的像糖一样在她眼前融化了。'),
    (12, 647, 1263, '“Didn’t you know water would be the end of me?” asked the Witch, in a wailing, despairing voice.', '“你不知道水会让我消失吗？”女巫哭着、绝望地问。'),
    (12, 648, 1264, '“Of course not,” answered Dorothy.', '“当然不知道啊。”多萝西说。'),
    (12, 648, 1265, '“How should I?”', '“我怎么会知道呢？”'),
    (12, 649, 1266, '“Well, in a few minutes I shall be all melted, and you will have the castle to yourself.', '“好吧，过几分钟我就完全融化了，城堡就是你的啦。'),
    (12, 649, 1267, 'I have been wicked in my day, but I never thought a little girl like you would ever be able to melt me and end my wicked deeds.', '我以前很坏，但我从没想过，像你这样的小女孩能把我融化，让我不能再做坏事了。'),
    (12, 649, 1268, 'Look out—here I go!”', '小心啦——我要消失啦！”'),
    (12, 650, 1269, 'With these words the Witch fell down in a brown, melted, shapeless mass and began to spread over the clean boards of the kitchen floor.', '女巫说完，就变成一滩棕色、融化的东西，铺满了厨房干净的地板。'),
    (12, 650, 1270, 'Seeing that she had really melted away to nothing, Dorothy drew another bucket of water and threw it over the mess.', '看到女巫真的完全融化不见了，多萝西又提了一桶水，泼在那些融化了的东西上。'),
    (12, 650, 1271, 'She then swept it all out the door.', '她把它们全都扫出门外。'),
    (12, 650, 1272, 'After picking out the silver shoe, which was all that was left of the old woman, she cleaned and dried it with a cloth, and put it on her foot again.', '她捡起那只银鞋，那是老巫婆身上唯一剩下的。她用布擦干净，擦干，又穿回了脚上。'),
    (12, 650, 1273, 'Then, being at last free to do as she chose, she ran out to the courtyard to tell the Lion that the Wicked Witch of the West had come to an end, and that they were no longer prisoners in a strange land.', '接着，她终于可以做自己想做的事了。她跑到院子里，告诉狮子，西方坏女巫已经消失了，他们再也不是这陌生地方的囚犯了。'),
    (13, 651, 1274, 'The Cowardly Lion was much pleased to hear that the Wicked Witch had been melted by a bucket of water, and Dorothy at once unlocked the gate of his prison and set him free.', '胆小的狮子听说坏女巫被一桶水融化了，非常开心。多萝西立刻打开了牢房的门，放他出来了。'),
    (13, 651, 1275, 'They went in together to the castle, where Dorothy’s first act was to call all the Winkies together and tell them that they were no longer slaves.', '他们一起走进城堡。多萝西做的第一件事，就是把所有温基人叫到一起，告诉他们，他们再也不是奴隶了。'),
    (13, 652, 1276, 'There was great rejoicing among the yellow Winkies, for they had been made to work hard during many years for the Wicked Witch, who had always treated them with great cruelty.', '黄色的温基人们都非常高兴，因为他们被坏女巫逼着辛苦工作了很多年。坏女巫总是对他们很坏。'),
    (13, 652, 1277, 'They kept this day as a holiday, then and ever after, and spent the time in feasting and dancing.', '从那天起，他们就把这一天当作节日，一直庆祝下去，唱歌跳舞，开心地吃喝玩乐。'),
    (13, 653, 1278, '“If our friends, the Scarecrow and the Tin Woodman, were only with us,” said the Lion, “I should be quite happy.”', '“如果我们的朋友，稻草人和铁皮人也能跟我们在一起，”狮子说，“我就会很开心了。”'),
    (13, 654, 1279, '“Don’t you suppose we could rescue them?” asked the girl anxiously.', '“我们不能去救他们吗？”女孩着急地问。'),
    (13, 655, 1280, '“We can try,” answered the Lion.', '“我们可以试试看。”狮子回答。'),
    (13, 656, 1281, 'So they called the yellow Winkies and asked them if they would help to rescue their friends, and the Winkies said that they would be delighted to do all in their power for Dorothy, who had set them free from bondage.', '于是他们叫来黄色的温基人，问他们愿不愿意帮忙救朋友。温基人说，他们很乐意为多萝西做任何事，因为多萝西把他们从苦日子里救了出来。'),
    (13, 656, 1282, 'So she chose a number of the Winkies who looked as if they knew the most, and they all started away.', '于是她选了一些看起来最聪明的温基人，他们就出发了。'),
    (13, 656, 1283, 'They traveled that day and part of the next until they came to the rocky plain where the Tin Woodman lay, all battered and bent.', '他们那天走了很久，第二天也走了一段路，终于来到了那片都是石头的平原。铁皮人就躺在那里，破破烂烂的，都弯了。'),
    (13, 656, 1284, 'His axe was near him, but the blade was rusted and the handle broken off short.', '他的斧头就在旁边，可是斧刃生锈了，斧柄也断成了两截。'),
    (13, 657, 1285, 'The Winkies lifted him tenderly in their arms, and carried him back to the Yellow Castle again, Dorothy shedding a few tears by the way at the sad plight of her old friend, and the Lion looking sober and sorry.', '温基人们轻轻地把他抱起来，又把他带回了黄色的城堡。一路上，多萝西看到老朋友这么可怜，流了几滴眼泪。狮子看着也很严肃，很难过。'),
    (13, 657, 1286, 'When they reached the castle Dorothy said to the Winkies:', '他们到了城堡后，多萝西对温基人说：'),
    (13, 658, 1287, '“Are any of your people tinsmiths?”', '“你们中间有人会修理锡器吗？”'),
    (13, 659, 1288, '“Oh, yes.', '“哦，有啊。'),
    (13, 659, 1289, 'Some of us are very good tinsmiths,” they told her.', '我们中间有些人很会修锡器呢！”他们告诉她。'),
    (13, 660, 1290, '“Then bring them to me,” she said.', '“那就把他们带来给我吧。”她说。'),
    (13, 660, 1291, 'And when the tinsmiths came, bringing with them all their tools in baskets, she inquired, “Can you straighten out those dents in the Tin Woodman, and bend him back into shape again, and solder him together where he is broken?”', '铁匠们提着工具筐来了。她问：“你们能把铁皮人身上的坑弄平，让他变回原来的样子，再把断掉的地方焊起来吗？”'),
    (13, 661, 1292, 'The tinsmiths looked the Woodman over carefully and then answered that they thought they could mend him so he would be as good as ever.', '铁匠们仔细看了看铁皮人，然后说他们能把他修好，让他和以前一样。'),
    (13, 661, 1293, 'So they set to work in one of the big yellow rooms of the castle and worked for three days and four nights, hammering and twisting and bending and soldering and polishing and pounding at the legs and body and head of the Tin Woodman, until at last he was straightened out into his old form, and his joints worked as well as ever.', '于是他们在城堡里一间大大的黄房间里干活，忙了三天四夜。他们又是敲又是打，又是焊又是磨，在铁皮人的腿、身体和头上忙活，直到他变回了原来的样子，关节也和以前一样灵活了。'),
    (13, 661, 1294, 'To be sure, there were several patches on him, but the tinsmiths did a good job, and as the Woodman was not a vain man he did not mind the patches at all.', '当然，他身上多了几块补丁，但铁匠们手艺很好。而且铁皮人一点也不臭美，所以他一点也不介意这些补丁。'),
    (13, 662, 1295, 'When, at last, he walked into Dorothy’s room and thanked her for rescuing him, he was so pleased that he wept tears of joy, and Dorothy had to wipe every tear carefully from his face with her apron, so his joints would not be rusted.', '他终于走进多萝西的房间，感谢她救了他。他高兴得流下了眼泪，多萝西赶紧用围裙擦掉他脸上的每一滴泪水，免得他的关节生锈。'),
    (13, 662, 1296, 'At the same time her own tears fell thick and fast at the joy of meeting her old friend again, and these tears did not need to be wiped away.', '同时，她也因为又见到老朋友而高兴得哗哗地流下了眼泪，这些眼泪倒不用擦掉。'),
    (13, 662, 1297, 'As for the Lion, he wiped his eyes so often with the tip of his tail that it became quite wet, and he was obliged to go out into the courtyard and hold it in the sun till it dried.', '而狮子呢，他用尾巴尖擦眼睛擦得太频繁了，结果尾巴尖都湿透了。他只好跑到院子里，把尾巴放在太阳下晒干。'),
    (13, 663, 1298, '“If we only had the Scarecrow with us again,” said the Tin Woodman, when Dorothy had finished telling him everything that had happened, “I should be quite happy.”', '多萝西讲完所有事情后，铁皮人说：“要是稻草人也能跟我们在一起就好了，那我就会非常开心了。”'),
    (13, 664, 1299, '“We must try to find him,” said the girl.', '“我们得把他找回来，”女孩说。'),
    (13, 665, 1300, 'So she called the Winkies to help her, and they walked all that day and part of the next until they came to the tall tree in the branches of which the Winged Monkeys had tossed the Scarecrow’s clothes.', '于是她叫上温基人帮忙，他们走了一天一夜，直到来到那棵大树前。飞猴曾把稻草人的衣服扔在那棵树上。'),
    (13, 666, 1301, 'It was a very tall tree, and the trunk was so smooth that no one could climb it; but the Woodman said at once, “I’ll chop it down, and then we can get the Scarecrow’s clothes.”', '那是一棵很高很高的树，树干太光滑了，没有人能爬上去。但铁皮人马上说：“我把它砍倒，这样我们就能拿到稻草人的衣服了。”'),
    (13, 667, 1302, 'Now while the tinsmiths had been at work mending the Woodman himself, another of the Winkies, who was a goldsmith, had made an axe-handle of solid gold and fitted it to the Woodman’s axe, instead of the old broken handle.', '就在铁匠们修理铁皮人的时候，另一个温基人（他是个金匠）用纯金给铁皮人做了一个新斧柄，替换掉了旧的坏掉的斧柄。'),
    (13, 667, 1303, 'Others polished the blade until all the rust was removed and it glistened like burnished silver.', '还有的人把斧刃磨得亮亮的，直到一点锈都没有了，闪着银色的光。'),
    (13, 668, 1304, 'As soon as he had spoken, the Tin Woodman began to chop, and in a short time the tree fell over with a crash, whereupon the Scarecrow’s clothes fell out of the branches and rolled off on the ground.', '他刚说完，铁皮人就开始砍树了。没多久，大树就轰隆一声倒了下来，稻草人的衣服也从树枝上掉了下来，滚到地上。'),
    (13, 669, 1305, 'Dorothy picked them up and had the Winkies carry them back to the castle, where they were stuffed with nice, clean straw; and behold! here was the Scarecrow, as good as ever, thanking them over and over again for saving him.', '多萝西把衣服捡起来，让温基人背回城堡。在那里，人们把衣服里塞满了干净的稻草。瞧！稻草人又变回了原来的样子，不停地感谢他们救了他。'),
    (13, 670, 1306, 'Now that they were reunited, Dorothy and her friends spent a few happy days at the Yellow Castle, where they found everything they needed to make them comfortable.', '大家又聚到一起了，多萝西和她的朋友们在黄城堡里度过了几天开心的日子。在那里，他们想要什么就有什么，过得很舒服。'),
    (13, 671, 1307, 'But one day the girl thought of Aunt Em, and said, “We must go back to Oz, and claim his promise.”', '但有一天，女孩想起了艾姆婶婶，说：“我们得回到奥兹大王那里，让他兑现承诺了。”'),
    (13, 672, 1308, '“Yes,” said the Woodman, “at last I shall get my heart.”', '“是的，”铁皮人说，“我终于能拿到我的心了。”'),
    (13, 673, 1309, '“And I shall get my brains,” added the Scarecrow joyfully.', '“我也会拿到我的大脑了！”稻草人高兴地补充道。'),
    (13, 674, 1310, '“And I shall get my courage,” said the Lion thoughtfully.', '“我也会拿到我的勇气了。”狮子认真地说。'),
    (13, 675, 1311, '“And I shall get back to Kansas,” cried Dorothy, clapping her hands.', '“我也可以回到堪萨斯那里了！”多萝西拍着手叫道。'),
    (13, 675, 1312, '“Oh, let us start for the Emerald City tomorrow!”', '“啊，我们明天就去翡翠城吧！”'),
    (13, 676, 1313, 'This they decided to do.', '他们决定就这样做。'),
    (13, 676, 1314, 'The next day they called the Winkies together and bade them good-bye.', '第二天，他们把温基人叫到一起，跟他们告别。'),
    (13, 676, 1315, 'The Winkies were sorry to have them go, and they had grown so fond of the Tin Woodman that they begged him to stay and rule over them and the Yellow Land of the West.', '温基人舍不得他们走，他们太喜欢铁皮人了，求他留下，管理他们和黄色的西方土地。'),
    (13, 676, 1316, 'Finding they were determined to go, the Winkies gave Toto and the Lion each a golden collar; and to Dorothy they presented a beautiful bracelet studded with diamonds; and to the Scarecrow they gave a gold-headed walking stick, to keep him from stumbling; and to the Tin Woodman they offered a silver oil-can, inlaid with gold and set with precious jewels.', '看到他们非走不可，温基人送给托托和狮子每人一个金项圈；送给多萝西一个镶满钻石的手镯；送给稻草人一根金头拐杖，这样他走路就不会摔倒了；送给铁皮人一个银油壶，上面镶着金子和漂亮的宝石。'),
    (13, 677, 1317, 'Every one of the travelers made the Winkies a pretty speech in return, and all shook hands with them until their arms ached.', '旅行者们都对温基人说了感谢的话，大家跟他们一一握手，直到胳膊都酸了。'),
    (13, 678, 1318, 'Dorothy went to the Witch’s cupboard to fill her basket with food for the journey, and there she saw the Golden Cap.', '多萝西去女巫的柜子里，给自己的篮子装上路上吃的食物，她在那里看到了金冠。'),
    (13, 678, 1319, 'She tried it on her own head and found that it fitted her exactly.', '她把它戴在自己头上，发现刚刚好。'),
    (13, 678, 1320, 'She did not know anything about the charm of the Golden Cap, but she saw that it was pretty, so she made up her mind to wear it and carry her sunbonnet in the basket.', '她不知道金冠有什么魔力，但她觉得它很漂亮，于是她决定戴上它，把自己的遮阳帽放在篮子里。'),
    (13, 679, 1321, 'Then, being prepared for the journey, they all started for the Emerald City; and the Winkies gave them three cheers and many good wishes to carry with them.', '准备好后，他们就出发去翡翠城了。温基人给他们欢呼，祝他们一路顺风。'),
    (14, 680, 1322, 'You will remember there was no road—not even a pathway—between the castle of the Wicked Witch and the Emerald City.', '你还记得吗？从坏女巫的城堡到翡翠城，根本没有路，连小道都没有。'),
    (14, 680, 1323, 'When the four travelers went in search of the Witch she had seen them coming, and so sent the Winged Monkeys to bring them to her.', '四个旅行者去找巫婆时，巫婆看到了他们。于是她派飞猴把他们带到她那儿。'),
    (14, 680, 1324, 'It was much harder to find their way back through the big fields of buttercups and yellow daisies than it was being carried.', '穿过一大片毛茛花和黄色雏菊地，要自己找路回去，比被带着走难多了。'),
    (14, 680, 1325, 'They knew, of course, they must go straight east, toward the rising sun; and they started off in the right way.', '他们知道，他们必须一直往东走，朝着太阳升起的方向。他们一开始走得很对。'),
    (14, 680, 1326, 'But at noon, when the sun was over their heads, they did not know which was east and which was west, and that was the reason they were lost in the great fields.', '但到了中午，太阳在他们头顶时，他们就分不清哪里是东哪里是西了。所以他们迷失在了大片田地里。'),
    (14, 680, 1327, 'They kept on walking, however, and at night the moon came out and shone brightly.', '不过他们继续往前走。到了晚上，月亮出来了，亮亮地照着。'),
    (14, 680, 1328, 'So they lay down among the sweet smelling yellow flowers and slept soundly until morning—all but the Scarecrow and the Tin Woodman.', '于是他们躺在香香的黄花中间，睡得很香，直到天亮——除了稻草人和铁皮人。'),
    (14, 681, 1329, 'The next morning the sun was behind a cloud, but they started on, as if they were quite sure which way they were going.', '第二天早上，太阳躲在云后面，但他们还是出发了，好像他们很确定要走哪条路一样。'),
    (14, 682, 1330, '“If we walk far enough,” said Dorothy, “I am sure we shall sometime come to some place.”', '多萝西说：“如果我们走得够远，我肯定我们总会走到某个地方的。”'),
    (14, 683, 1331, 'But day by day passed away, and they still saw nothing before them but the scarlet fields.', '但一天天过去了，他们眼前除了那红色的田野，什么也没看到。'),
    (14, 683, 1332, 'The Scarecrow began to grumble a bit.', '稻草人开始有点抱怨了。'),
    (14, 684, 1333, '“We have surely lost our way,” he said, “and unless we find it again in time to reach the Emerald City, I shall never get my brains.”', '他说：“我们肯定迷路了。如果我们不能及时找到路去翡翠城，我就永远得不到我的智慧了。”'),
    (14, 685, 1334, '“Nor I my heart,” declared the Tin Woodman.', '铁皮人说：“我也得不到我的心了。”'),
    (14, 685, 1335, '“It seems to me I can scarcely wait till I get to Oz, and you must admit this is a very long journey.”', '“我觉得我等不及要去奥兹大王了。你们也得承认，这路程太长了。”'),
    (14, 686, 1336, '“You see,” said the Cowardly Lion, with a whimper, “I haven’t the courage to keep tramping forever, without getting anywhere at all.”', '胆小的狮子带着哭腔说：“你看，我可没有勇气一直走下去，什么地方也到不了。”'),
    (14, 687, 1337, 'Then Dorothy lost heart.', '然后多萝西泄气了。'),
    (14, 687, 1338, 'She sat down on the grass and looked at her companions, and they sat down and looked at her, and Toto found that for the first time in his life he was too tired to chase a butterfly that flew past his head.', '她坐在草地上，看着她的同伴们。他们也坐下来看着她。托托发现，他生平第一次累得追不上从头顶飞过的蝴蝶了。'),
    (14, 687, 1339, 'So he put out his tongue and panted and looked at Dorothy as if to ask what they should do next.', '于是他伸出舌头，喘着气，看着多萝西，好像在问他们接下来该怎么办。'),
    (14, 688, 1340, '“Suppose we call the field mice,” she suggested.', '她建议：“不如我们叫田鼠来吧。”'),
    (14, 688, 1341, '“They could probably tell us the way to the Emerald City.”', '“它们也许能告诉我们去翡翠城的路。”'),
    (14, 689, 1342, '“To be sure they could,” cried the Scarecrow.', '稻草人大喊：“它们当然可以！”'),
    (14, 689, 1343, '“Why didn’t we think of that before?”', '“我们怎么早没想到呢？”'),
    (14, 690, 1344, 'Dorothy blew the little whistle she had always carried about her neck since the Queen of the Mice had given it to her.', '多萝西吹响了她一直挂在脖子上的小哨子，那是鼠后送给她的。'),
    (14, 690, 1345, 'In a few minutes they heard the pattering of tiny feet, and many of the small gray mice came running up to her.', '几分钟后，他们听到小脚跑动的声音，许多灰色的小老鼠跑了过来。'),
    (14, 690, 1346, 'Among them was the Queen herself, who asked, in her squeaky little voice:', '鼠后也在其中。她用尖尖的小声音问道：'),
    (14, 691, 1347, '“What can I do for my friends?”', '“我能为我的朋友们做些什么呢？”'),
    (14, 692, 1348, '“We have lost our way,” said Dorothy.', '多萝西说：“我们迷路了。”'),
    (14, 692, 1349, '“Can you tell us where the Emerald City is?”', '“你能告诉我们翡翠城在哪里吗？”'),
    (14, 693, 1350, '“Certainly,” answered the Queen; “but it is a great way off, for you have had it at your backs all this time.”', '鼠后回答：“当然可以。但它很远呢，因为这段时间它一直都在你们身后。”'),
    (14, 693, 1351, 'Then she noticed Dorothy’s Golden Cap, and said, “Why don’t you use the charm of the Cap, and call the Winged Monkeys to you?', '然后她看到 多萝西 的 金冠，说：“你为什么不用帽子的魔力，把 飞猴 叫过来呢？'),
    (14, 693, 1352, 'They will carry you to the City of Oz in less than an hour.”', '他们不到一小时就会把你送到 奥兹国。”'),
    (14, 694, 1353, '“I didn’t know there was a charm,” answered Dorothy, in surprise.', '“我不知道有这种魔力啊，”多萝西 惊讶地回答说。'),
    (14, 694, 1354, '“What is it?”', '“那是什么？”'),
    (14, 695, 1355, '“It is written inside the Golden Cap,” replied the Queen of the Mice.', '“它写在 金冠 里面，”老鼠女王回答说。'),
    (14, 695, 1356, '“But if you are going to call the Winged Monkeys we must run away, for they are full of mischief and think it great fun to plague us.”', '“但是如果你要叫 飞猴 来的话，我们就得跑开，因为它们很淘气，觉得捉弄我们很好玩。”'),
    (14, 696, 1357, '“Won’t they hurt me?” asked the girl anxiously.', '“它们不会伤害我吧？”小女孩担心地问。'),
    (14, 697, 1358, '“Oh, no.', '“哦，不会的。'),
    (14, 697, 1359, 'They must obey the wearer of the Cap.', '它们必须听戴帽子的人的话。'),
    (14, 697, 1360, 'Good-bye!”', '再见！”'),
    (14, 697, 1361, 'And she scampered out of sight, with all the mice hurrying after her.', '她一溜烟跑得不见了，所有的老鼠都跟着她跑开了。'),
    (14, 698, 1362, 'Dorothy looked inside the Golden Cap and saw some words written upon the lining.', '多萝西 看了看 金冠 里面，看到衬里上写着一些字。'),
    (14, 698, 1363, 'These, she thought, must be the charm, so she read the directions carefully and put the Cap upon her head.', '她想，这些一定是魔力，所以她仔细地读了说明，然后把帽子戴在头上。'),
    (14, 699, 1364, '“Ep-pe, pep-pe, kak-ke!” she said, standing on her left foot.', '她单脚站在左脚上，说：“艾普-佩，佩普-佩，卡克-克！”'),
    (14, 700, 1365, '“What did you say?” asked the Scarecrow, who did not know what she was doing.', '“你说了什么？”稻草人 问，它不知道她在做什么。'),
    (14, 701, 1366, '“Hil-lo, hol-lo, hel-lo!”', '“希尔-洛，霍尔-洛，赫尔-洛！”'),
    (14, 701, 1367, 'Dorothy went on, standing this time on her right foot.', '多萝西 继续说，这次她单脚站在右脚上。'),
    (14, 702, 1368, '“Hello!” replied the Tin Woodman calmly.', '“你好！”铁皮人 平静地回答说。'),
    (14, 703, 1369, '“Ziz-zy, zuz-zy, zik!” said Dorothy, who was now standing on both feet.', '多萝西 这次两只脚都站着，说：“兹兹-西，祖祖-西，西克！”'),
    (14, 703, 1370, 'This ended the saying of the charm, and they heard a great chattering and flapping of wings, as the band of Winged Monkeys flew up to them.', '这样魔咒就念完了，他们听到一阵很大的叫声和翅膀拍打声，一群 飞猴 朝他们飞了过来。'),
    (14, 704, 1371, 'The King bowed low before Dorothy, and asked, “What is your command?”', '国王在 多萝西 面前深深地鞠了一躬，问：“有什么吩咐吗？”'),
    (14, 705, 1372, '“We wish to go to the Emerald City,” said the child, “and we have lost our way.”', '“我们想去 翡翠城，”孩子说，“我们迷路了。”'),
    (14, 706, 1373, '“We will carry you,” replied the King, and no sooner had he spoken than two of the Monkeys caught Dorothy in their arms and flew away with her.', '“我们会带你们去的，”国王回答说，他刚说完，两只猴子就抱起 多萝西 飞走了。'),
    (14, 706, 1374, 'Others took the Scarecrow and the Woodman and the Lion, and one little Monkey seized Toto and flew after them, although the dog tried hard to bite him.', '其他的猴子带着 稻草人、铁皮人 和 狮子，一只小猴子抓起 托托 追了上去，尽管狗狗努力想咬它。'),
    (14, 707, 1375, 'The Scarecrow and the Tin Woodman were rather frightened at first, for they remembered how badly the Winged Monkeys had treated them before; but they saw that no harm was intended, so they rode through the air quite cheerfully, and had a fine time looking at the pretty gardens and woods far below them.', '稻草人 和 铁皮人 一开始有点害怕，因为它们记得 飞猴 以前对它们很不好；但它们看到 飞猴 没有恶意，于是它们开心地在空中飞，欣赏着下面美丽的园林和森林。'),
    (14, 708, 1376, 'Dorothy found herself riding easily between two of the biggest Monkeys, one of them the King himself.', '多萝西 发现自己很舒服地坐在两只最大的猴子中间，其中一只就是国王。'),
    (14, 708, 1377, 'They had made a chair of their hands and were careful not to hurt her.', '它们用手搭成了一把椅子，而且很小心，没有弄伤她。'),
    (14, 709, 1378, '“Why do you have to obey the charm of the Golden Cap?” she asked.', '“你们为什么要听 金冠 的魔力呢？”她问。'),
    (14, 710, 1379, '“That is a long story,” answered the King, with a winged laugh; “but as we have a long journey before us, I will pass the time by telling you about it, if you wish.”', '“那是个很长的故事，”国王笑着回答说；“不过我们还有很长的路要走，如果你愿意，我就讲给你听，打发时间。”'),
    (14, 711, 1380, '“I shall be glad to hear it,” she replied.', '“我很乐意听，”她回答。'),
    (14, 712, 1381, '“Once,” began the leader, “we were a free people, living happily in the great forest, flying from tree to tree, eating nuts and fruit, and doing just as we pleased without calling anybody master.', '“很久很久以前，”领头的那只猴子说，“我们是一群自由的猴子，开心地住在森林里。我们在树上飞来飞去，吃坚果和水果，想做什么就做什么，没有主人管我们。'),
    (14, 712, 1382, 'Perhaps some of us were rather too full of mischief at times, flying down to pull the tails of the animals that had no wings, chasing birds, and throwing nuts at the people who walked in the forest.', '有时候，我们很调皮。我们会飞下去，拉那些没有翅膀的小动物的尾巴，追赶小鸟，还会朝在森林里走路的人扔坚果。'),
    (14, 712, 1383, 'But we were careless and happy and full of fun, and enjoyed every minute of the day.', '不过，我们那时无忧无虑，非常开心，每天都玩得很尽兴。'),
    (14, 712, 1384, 'This was many years ago, long before Oz came out of the clouds to rule over this land.', '这是很多年前的事了，比奥兹大王从云朵里出来统治这片土地还要早很多。'),
    (14, 713, 1385, '“There lived here then, away at the North, a beautiful princess, who was also a powerful sorceress.', '“当时，在这片土地的北方，住着一位美丽的公主。她也是一位很厉害的女巫。'),
    (14, 713, 1386, 'All her magic was used to help the people, and she was never known to hurt anyone who was good.', '她的魔法都是用来帮助别人的，她从没伤害过好人。'),
    (14, 713, 1387, 'Her name was Gayelette, and she lived in a handsome palace built from great blocks of ruby.', '她叫盖耶莱特，住在一座漂亮的宫殿里，宫殿是用大块红宝石建成的。'),
    (14, 713, 1388, 'Everyone loved her, but her greatest sorrow was that she could find no one to love in return, since all the men were much too stupid and ugly to mate with one so beautiful and wise.', '大家都喜欢她，但她最伤心的是，找不到一个能真心喜欢她的人。因为所有男人都又笨又丑，配不上她这样又美又聪明的公主。'),
    (14, 713, 1389, 'At last, however, she found a boy who was handsome and manly and wise beyond his years.', '终于，她找到了一个男孩。他又帅气又勇敢，而且比同龄人更聪明。'),
    (14, 713, 1390, 'Gayelette made up her mind that when he grew to be a man she would make him her husband, so she took him to her ruby palace and used all her magic powers to make him as strong and good and lovely as any woman could wish.', '盖耶莱特决定，等他长大成人，就嫁给他。于是，她把他带回自己的红宝石宫殿，用尽所有魔法，让他变得又强壮又善良，还像任何女人希望的那样可爱。'),
    (14, 713, 1391, 'When he grew to manhood, Quelala, as he was called, was said to be the best and wisest man in all the land, while his manly beauty was so great that Gayelette loved him dearly, and hastened to make everything ready for the wedding.', '等他长大成人，人们都说他叫奎拉拉，是这片土地上最好、最聪明的人。他又帅气又英武，盖耶莱特非常爱他，赶紧准备他们的婚礼。'),
    (14, 714, 1392, '“My grandfather was at that time the King of the Winged Monkeys which lived in the forest near Gayelette’s palace, and the old fellow loved a joke better than a good dinner.', '“我的爷爷那时候是飞猴的国王，他们住在盖耶莱特宫殿附近的森林里。我爷爷这老头子啊，就爱开玩笑，比喜欢美食还爱。'),
    (14, 714, 1393, 'One day, just before the wedding, my grandfather was flying out with his band when he saw Quelala walking beside the river.', '有一天，就在婚礼前不久，我爷爷带着他的猴子们飞出去，看到奎拉拉在河边散步。'),
    (14, 714, 1394, 'He was dressed in a rich costume of pink silk and purple velvet, and my grandfather thought he would see what he could do.', '他穿着一套华丽的衣服，是粉色丝绸和紫色天鹅绒做的。我爷爷心想，他要捉弄一下他。'),
    (14, 714, 1395, 'At his word the band flew down and seized Quelala, carried him in their arms until they were over the middle of the river, and then dropped him into the water.', '爷爷一声令下，猴子们就飞下去抓住了奎拉拉，把他抬起来，一直飞到河中央，然后把他扔进了水里。'),
    (14, 715, 1396, '“‘Swim out, my fine fellow,’ cried my grandfather, ‘and see if the water has spotted your clothes.’', '“‘游出来吧，小伙子！’我爷爷大声喊，‘看看水是不是把你的衣服弄脏了。’'),
    (14, 715, 1397, 'Quelala was much too wise not to swim, and he was not in the least spoiled by all his good fortune.', '奎拉拉很聪明，他知道要游泳。他并没有因为好运而变得娇气。'),
    (14, 715, 1398, 'He laughed, when he came to the top of the water, and swam in to shore.', '当他浮出水面时，他笑了，然后游到了岸边。'),
    (14, 715, 1399, 'But when Gayelette came running out to him she found his silks and velvet all ruined by the river.', '可是当盖耶莱特跑出来找他时，发现他的丝绸和天鹅绒衣服都被河水弄坏了。'),
    (14, 716, 1400, '“The princess was angry, and she knew, of course, who did it.', '“公主很生气，她当然知道是谁做的。'),
    (14, 716, 1401, 'She had all the Winged Monkeys brought before her, and she said at first that their wings should be tied and they should be treated as they had treated Quelala, and dropped in the river.', '她把所有的飞猴都叫到她面前，一开始她说要把它们的翅膀绑起来，像它们对待奎拉拉一样，把它们扔进河里。'),
    (14, 716, 1402, 'But my grandfather pleaded hard, for he knew the Monkeys would drown in the river with their wings tied, and Quelala said a kind word for them also; so that Gayelette finally spared them, on condition that the Winged Monkeys should ever after do three times the bidding of the owner of the Golden Cap.', '但是我爷爷努力求情，因为他知道猴子们翅膀被绑住会淹死在河里。奎拉拉也替它们说了好话。所以盖耶莱特最后饶了它们，条件是：从今以后，飞猴要听金冠的主人三次命令。'),
    (14, 716, 1403, 'This Cap had been made for a wedding present to Quelala, and it is said to have cost the princess half her kingdom.', '这顶帽子是给奎拉拉做的结婚礼物，据说公主为了它，花掉了半个国家。'),
    (14, 716, 1404, 'Of course my grandfather and all the other Monkeys at once agreed to the condition, and that is how it happens that we are three times the slaves of the owner of the Golden Cap, whosoever he may be.”', '当然，我爷爷和所有其他猴子立刻同意了这个条件。所以啊，我们成了金冠主人的三次奴隶，不管他是谁。”'),
    (14, 717, 1405, '“And what became of them?” asked Dorothy, who had been greatly interested in the story.', '“后来它们怎么样了？”多萝西问，她听故事听得很有兴趣。'),
    (14, 718, 1406, '“Quelala being the first owner of the Golden Cap,” replied the Monkey, “he was the first to lay his wishes upon us.', '“奎拉拉是金冠的第一个主人，”猴子回答说，“他是第一个命令我们做事的。'),
    (14, 718, 1407, 'As his bride could not bear the sight of us, he called us all to him in the forest after he had married her and ordered us always to keep where she could never again set eyes on a Winged Monkey, which we were glad to do, for we were all afraid of her.', '因为他的新娘受不了看到我们，所以他结婚后把我们都叫到森林里，命令我们永远待在她看不见飞猴的地方。我们也很乐意这样做，因为我们都很怕她。'),
    (14, 719, 1408, '“This was all we ever had to do until the Golden Cap fell into the hands of the Wicked Witch of the West, who made us enslave the Winkies, and afterward drive Oz himself out of the Land of the West.', '“我们一直都只做这些事，直到金冠落到了西方坏女巫手里。他让我们去奴役温基人，后来又把奥兹大王赶出了西方之地。'),
    (14, 719, 1409, 'Now the Golden Cap is yours, and three times you have the right to lay your wishes upon us.”', '现在，这顶金冠是你的了，你有三次权利来命令我们。”'),
    (14, 720, 1410, 'As the Monkey King finished his story Dorothy looked down and saw the green, shining walls of the Emerald City before them.', '猴子王讲完故事，多萝西低头一看，只见翡翠城的绿色发光的墙壁就在他们眼前。'),
    (14, 720, 1411, 'She wondered at the rapid flight of the Monkeys, but was glad the journey was over.', '她看到猴子飞得很快，感到很惊奇，但很高兴旅程结束了。'),
    (14, 720, 1412, 'The strange creatures set the travelers down carefully before the gate of the City, the King bowed low to Dorothy, and then flew swiftly away, followed by all his band.', '这些奇怪的家伙小心地把旅行者们放在城门前，猴王向多萝西深深地鞠了一躬，然后带着所有猴子飞走了。'),
    (14, 721, 1413, '“That was a good ride,” said the little girl.', '“这次飞得真棒！”小女孩说。'),
    (14, 722, 1414, '“Yes, and a quick way out of our troubles,” replied the Lion.', '“是啊，这样我们就能很快摆脱麻烦了！”狮子回答说。'),
    (14, 722, 1415, '“How lucky it was you brought away that wonderful Cap!”', '“你把那顶很棒的帽子带走，真是太幸运了！”'),
    (15, 723, 1416, 'The four travelers walked up to the great gate of Emerald City and rang the bell.', '四个旅行者走到翡翠城的大门前，按响了门铃。'),
    (15, 723, 1417, 'After ringing several times, it was opened by the same Guardian of the Gates they had met before.', '按了几次门铃后，还是以前他们见过的那个城门守卫开了门。'),
    (15, 724, 1418, '“What! are you back again?” he asked, in surprise.', '“什么！你们又回来了？”他很惊讶地问。'),
    (15, 725, 1419, '“Do you not see us?” answered the Scarecrow.', '“你没看见我们吗？”稻草人回答说。'),
    (15, 726, 1420, '“But I thought you had gone to visit the Wicked Witch of the West.”', '“可我以为你们是去拜访西方坏女巫了呢。”'),
    (15, 727, 1421, '“We did visit her,” said the Scarecrow.', '“我们确实去拜访她了，”稻草人说。'),
    (15, 728, 1422, '“And she let you go again?” asked the man, in wonder.', '“她又让你们走了吗？”那人很疑惑地问。'),
    (15, 729, 1423, '“She could not help it, for she is melted,” explained the Scarecrow.', '“她没办法，因为她融化了，”稻草人解释说。'),
    (15, 730, 1424, '“Melted!', '“融化了！'),
    (15, 730, 1425, 'Well, that is good news, indeed,” said the man.', '哦，那真是个好消息！”那人说。'),
    (15, 730, 1426, '“Who melted her?”', '“谁把她融化的？”'),
    (15, 731, 1427, '“It was Dorothy,” said the Lion gravely.', '“是多萝西，”狮子很认真地说。'),
    (15, 732, 1428, '“Good gracious!” exclaimed the man, and he bowed very low indeed before her.', '“天哪！”那人喊道，然后在她面前深深地鞠了一躬。'),
    (15, 733, 1429, 'Then he led them into his little room and locked the spectacles from the great box on all their eyes, just as he had done before.', '然后，他把他们带进自己的小房间，从大盒子里拿出眼镜，给他们每个人戴上，就像以前一样。'),
    (15, 733, 1430, 'Afterward they passed on through the gate into the Emerald City.', '接着，他们穿过大门，走进了翡翠城。'),
    (15, 733, 1431, 'When the people heard from the Guardian of the Gates that Dorothy had melted the Wicked Witch of the West, they all gathered around the travelers and followed them in a great crowd to the Palace of Oz.', '当人们从城门守卫那里听说多萝西融化了西方坏女巫时，他们都围住旅行者，一大群人跟着他们来到了奥兹大王的宫殿。'),
    (15, 734, 1432, 'The soldier with the green whiskers was still on guard before the door, but he let them in at once, and they were again met by the beautiful green girl, who showed each of them to their old rooms at once, so they might rest until the Great Oz was ready to receive them.', '那个留着绿胡子的士兵还在门前站岗，但他立刻让他们进去了。美丽的绿衣女孩又来迎接他们，马上把他们带回了以前的房间，这样他们就可以休息，直到伟大的奥兹大王准备好接见他们。'),
    (15, 735, 1433, 'The soldier had the news carried straight to Oz that Dorothy and the other travelers had come back again, after destroying the Wicked Witch; but Oz made no reply.', '士兵把消息直接带给了奥兹大王，说多萝西和其他旅行者在消灭了坏女巫之后又回来了；但奥兹大王没有回答。'),
    (15, 735, 1434, 'They thought the Great Wizard would send for them at once, but he did not.', '他们以为伟大的巫师会立刻派人请他们，但他没有。'),
    (15, 735, 1435, 'They had no word from him the next day, nor the next, nor the next.', '第二天、第三天、第四天，他们都没有收到他的消息。'),
    (15, 735, 1436, 'The waiting was tiresome and wearing, and at last they grew vexed that Oz should treat them in so poor a fashion, after sending them to undergo hardships and slavery.', '等待让人很疲倦，很烦躁。最后他们很生气，觉得奥兹大王让他们去受苦受难后，竟然这样对待他们。'),
    (15, 735, 1437, 'So the Scarecrow at last asked the green girl to take another message to Oz, saying if he did not let them in to see him at once they would call the Winged Monkeys to help them, and find out whether he kept his promises or not.', '于是，稻草人终于让绿衣女孩再带个口信给奥兹大王，说如果他不马上让他们进去见他，他们就要请飞猴来帮忙，看看他有没有遵守诺言。'),
    (15, 735, 1438, 'When the Wizard was given this message he was so frightened that he sent word for them to come to the Throne Room at four minutes after nine o’clock the next morning.', '巫师听到这个口信后，吓坏了，他让人传话说，让他们第二天早上九点零四分到王座室来。'),
    (15, 735, 1439, 'He had once met the Winged Monkeys in the Land of the West, and he did not wish to meet them again.', '他以前在西方国家见过飞猴，不想再见到他们了。'),
    (15, 736, 1440, 'The four travelers passed a sleepless night, each thinking of the gift Oz had promised to bestow on him.', '四个旅行者度过了一个不眠之夜，每个人都在想着奥兹大王答应要给他们的礼物。'),
    (15, 736, 1441, 'Dorothy fell asleep only once, and then she dreamed she was in Kansas, where Aunt Em was telling her how glad she was to have her little girl at home again.', '多萝西只睡着了一会儿，她就梦到自己去了堪萨斯。在梦里，艾姆婶婶告诉她，小女儿回家她有多开心。'),
    (15, 737, 1442, 'Promptly at nine o’clock the next morning the green-whiskered soldier came to them, and four minutes later they all went into the Throne Room of the Great Oz.', '第二天早上九点，绿胡子士兵准时来了。四分钟后，他们都进了大奥兹大王的王座厅。'),
    (15, 738, 1443, 'Of course each one of them expected to see the Wizard in the shape he had taken before, and all were greatly surprised when they looked about and saw no one at all in the room.', '他们都以为会看到巫师变成以前的样子，结果一看房间里一个人都没有，大家都非常吃惊。'),
    (15, 738, 1444, 'They kept close to the door and closer to one another, for the stillness of the empty room was more dreadful than any of the forms they had seen Oz take.', '他们紧紧靠着门，也紧紧靠着彼此。空房间的安静比他们见过的任何一个奥兹大王的样子都可怕。'),
    (15, 739, 1445, 'Presently they heard a solemn Voice, that seemed to come from somewhere near the top of the great dome, and it said:', '很快，他们听到一个很庄重又很响亮的声音，好像是从大圆顶上面传来的。声音说：'),
    (15, 740, 1446, '“I am Oz, the Great and Terrible.', '“我是奥兹大王，伟大又可怕的巫师。”'),
    (15, 740, 1447, 'Why do you seek me?”', '你们为什么来找我？”'),
    (15, 741, 1448, 'They looked again in every part of the room, and then, seeing no one, Dorothy asked, “Where are you?”', '他们又把房间每个地方都看了看，还是没看到人。然后，多萝西问：“你在哪里呀？”'),
    (15, 742, 1449, '“I am everywhere,” answered the Voice, “but to the eyes of common mortals I am invisible.', '“我无处不在，”声音回答，“但普通人是看不见我的。”'),
    (15, 742, 1450, 'I will now seat myself upon my throne, that you may converse with me.”', '我现在要坐在我的王座上，你们可以和我说话了。”'),
    (15, 742, 1451, 'Indeed, the Voice seemed just then to come straight from the throne itself; so they walked toward it and stood in a row while Dorothy said:', '确实，声音好像是从王座那里直接传来的。于是他们走向王座，排成一排站着。多萝西说：'),
    (15, 743, 1452, '“We have come to claim our promise, O Oz.”', '“我们来要你给我们的承诺，哦，奥兹大王。”'),
    (15, 744, 1453, '“What promise?” asked Oz.', '“什么承诺？”奥兹大王问。'),
    (15, 745, 1454, '“You promised to send me back to Kansas when the Wicked Witch was destroyed,” said the girl.', '“你答应过我，如果坏女巫被消灭了，就把我送回堪萨斯，”小女孩说。'),
    (15, 746, 1455, '“And you promised to give me brains,” said the Scarecrow.', '“你还答应给我智慧的大脑，”稻草人说。'),
    (15, 747, 1456, '“And you promised to give me a heart,” said the Tin Woodman.', '“你还答应给我一颗心，”铁皮人说。'),
    (15, 748, 1457, '“And you promised to give me courage,” said the Cowardly Lion.', '“你还答应给我勇气，”胆小的狮子说。'),
    (15, 749, 1458, '“Is the Wicked Witch really destroyed?” asked the Voice, and Dorothy thought it trembled a little.', '“坏女巫真的被消灭了吗？”声音问道，多萝西觉得声音好像有点颤抖。'),
    (15, 750, 1459, '“Yes,” she answered, “I melted her with a bucket of water.”', '“是的，”她回答，“我用一桶水把她融化了。”'),
    (15, 751, 1460, '“Dear me,” said the Voice, “how sudden!', '“哎呀，”声音说，“这么快就发生了！”'),
    (15, 751, 1461, 'Well, come to me tomorrow, for I must have time to think it over.”', '嗯，你们明天再来找我吧，我需要时间好好想想。”'),
    (15, 752, 1462, '“You’ve had plenty of time already,” said the Tin Woodman angrily.', '“你已经想了很久了！”铁皮人生气地说。'),
    (15, 753, 1463, '“We shan’t wait a day longer,” said the Scarecrow.', '“我们一天都不能再等了！”稻草人说。'),
    (15, 754, 1464, '“You must keep your promises to us!” exclaimed Dorothy.', '“你一定要遵守对我们的承诺！”多萝西大声说。'),
    (15, 755, 1465, 'The Lion thought it might be as well to frighten the Wizard, so he gave a large, loud roar, which was so fierce and dreadful that Toto jumped away from him in alarm and tipped over the screen that stood in a corner.', '狮子觉得也许吓唬一下巫师也不错，于是他大声地吼了一声。吼声又猛烈又可怕，把托托吓了一跳，赶紧跳开，还把墙角的一个屏风碰倒了。'),
    (15, 755, 1466, 'As it fell with a crash they looked that way, and the next moment all of them were filled with wonder.', '屏风轰的一声倒下时，他们都往那边看去。下一刻，大家都非常惊讶。'),
    (15, 755, 1467, 'For they saw, standing in just the spot the screen had hidden, a little old man, with a bald head and a wrinkled face, who seemed to be as much surprised as they were.', '因为他们看到，就在屏风后面，站着一个头发很少、满脸皱纹的小老头。他看起来和他们一样吃惊。'),
    (15, 755, 1468, 'The Tin Woodman, raising his axe, rushed toward the little man and cried out, “Who are you?”', '铁皮人举起斧头，冲向小老头，大声喊道：“你是谁？”'),
    (15, 756, 1469, '“I am Oz, the Great and Terrible,” said the little man, in a trembling voice.', '“我是奥兹大王，伟大又可怕的巫师，”小老头颤抖着声音说。'),
    (15, 756, 1470, '“But don’t strike me—please don’t—and I’ll do anything you want me to.”', '“但别打我——求你了别打我——你要我做什么都行。”'),
    (15, 757, 1471, 'Our friends looked at him in surprise and dismay.', '朋友们很惊讶，也很失望地看着他。'),
    (15, 758, 1472, '“I thought Oz was a great Head,” said Dorothy.', '“我以为 奥兹大王 是个很厉害的大脑袋呢，” 多萝西 说。'),
    (15, 759, 1473, '“And I thought Oz was a lovely Lady,” said the Scarecrow.', '“我以为 奥兹大王 是个漂亮的女士呢，” 稻草人 说。'),
    (15, 760, 1474, '“And I thought Oz was a terrible Beast,” said the Tin Woodman.', '“我以为 奥兹大王 是个可怕的野兽呢，” 铁皮人 说。'),
    (15, 761, 1475, '“And I thought Oz was a Ball of Fire,” exclaimed the Lion.', '“我以为 奥兹大王 是个火球呢！” 狮子 叫道。'),
    (15, 762, 1476, '“No, you are all wrong,” said the little man meekly.', '“不，你们都想错了，”小个子男人轻轻地说。'),
    (15, 762, 1477, '“I have been making believe.”', '“我一直在假装。”'),
    (15, 763, 1478, '“Making believe!” cried Dorothy. “Are you not a Great Wizard?”', '“假装？” 多萝西 喊道。“你不是个很厉害的魔法师吗？”'),
    (15, 764, 1479, '“Hush, my dear,” he said.', '“嘘，亲爱的，”他说。'),
    (15, 764, 1480, '“Don’t speak so loud, or you will be overheard—and I should be ruined.', '“别说那么大声，不然会被别人听到的——我就完蛋了。'),
    (15, 764, 1481, 'I’m supposed to be a Great Wizard.”', '大家都以为我是个很厉害的魔法师呢。”'),
    (15, 765, 1482, '“And aren’t you?” she asked.', '“你不是吗？”她问。'),
    (15, 766, 1483, '“Not a bit of it, my dear; I’m just a common man.”', '“一点也不是，亲爱的；我只是个普通人。”'),
    (15, 767, 1484, '“You’re more than that,” said the Scarecrow, in a grieved tone; “you’re a humbug.”', '“你可不止那样，” 稻草人 伤心地说，“你是个骗子。”'),
    (15, 768, 1485, '“Exactly so!” declared the little man, rubbing his hands together as if it pleased him. “I am a humbug.”', '“没错！”小个子男人说，高兴地搓着手，“我就是个骗子。”'),
    (15, 769, 1486, '“But this is terrible,” said the Tin Woodman.', '“但这太糟糕了！” 铁皮人 说。'),
    (15, 769, 1487, '“How shall I ever get my heart?”', '“那我的心要怎么才能拿到呢？”'),
    (15, 770, 1488, '“Or I my courage?” asked the Lion.', '“那我的勇气呢？” 狮子 问。'),
    (15, 771, 1489, '“Or I my brains?” wailed the Scarecrow, wiping the tears from his eyes with his coat sleeve.', '“那我的脑子呢？” 稻草人 哭着说，用衣袖擦掉眼泪。'),
    (15, 772, 1490, '“My dear friends,” said Oz, “I pray you not to speak of these little things.', '“我亲爱的朋友们，” 奥兹大王 说，“求你们别提这些小事了。'),
    (15, 772, 1491, 'Think of me, and the terrible trouble I’m in at being found out.”', '想想我吧，我被发现了，这麻烦可大了！”'),
    (15, 773, 1492, '“Doesn’t anyone else know you’re a humbug?” asked Dorothy.', '“难道没有别人知道你是个骗子吗？” 多萝西 问。'),
    (15, 774, 1493, '“No one knows it but you four—and myself,” replied Oz.', '“除了你们四个——还有我，没有人知道，” 奥兹大王 回答说。'),
    (15, 774, 1494, '“I have fooled everyone so long that I thought I should never be found out.', '“我骗了大家这么久，以为永远不会被发现呢。'),
    (15, 774, 1495, 'It was a great mistake my ever letting you into the Throne Room.', '让你们进到王座厅里来，真是个大错啊。'),
    (15, 774, 1496, 'Usually I will not see even my subjects, and so they believe I am something terrible.”', '平时我连我的子民都不见，所以他们都觉得我很可怕。”'),
    (15, 775, 1497, '“But, I don’t understand,” said Dorothy, in bewilderment.', '“可是，我不明白，” 多萝西 迷茫地说。'),
    (15, 775, 1498, '“How was it that you appeared to me as a great Head?”', '“你怎么会变成一个大脑袋出现在我面前的呢？”'),
    (15, 776, 1499, '“That was one of my tricks,” answered Oz.', '“那是我变的一个小把戏，” 奥兹大王 回答说。'),
    (15, 776, 1500, '“Step this way, please, and I will tell you all about it.”', '“请往这边走，我会把所有事情都告诉你们。”'),
    (15, 777, 1501, 'He led the way to a small chamber in the rear of the Throne Room, and they all followed him.', '他带大家走到王座厅后面的一个小房间，大家都跟着他进去了。'),
    (15, 777, 1502, 'He pointed to one corner, in which lay the great Head, made out of many thicknesses of paper, and with a carefully painted face.', '他指着一个角落，那里有一个大脑袋。它用很多层纸做的，脸上还画得很漂亮。'),
    (15, 778, 1503, '“This I hung from the ceiling by a wire,” said Oz.', '“我把这个用铁丝挂在天花板上。”奥兹大王说。'),
    (15, 778, 1504, '“I stood behind the screen and pulled a thread, to make the eyes move and the mouth open.”', '“我躲在屏风后面，拉一拉线，就能让眼睛动，嘴巴张开。”'),
    (15, 779, 1505, '“But how about the voice?” she inquired.', '“那声音呢？声音是从哪里来的？”她问。'),
    (15, 780, 1506, '“Oh, I am a ventriloquist,” said the little man.', '“哦，我是一个会腹语的人。”小个子男人说。'),
    (15, 780, 1507, '“I can throw the sound of my voice wherever I wish, so that you thought it was coming out of the Head.', '“我想让声音从哪里出来，它就能从哪里出来。所以你们才以为是从大脑袋里发出来的。”'),
    (15, 780, 1508, 'Here are the other things I used to deceive you.”', '“这些就是我用来骗你们的其他东西。”'),
    (15, 780, 1509, 'He showed the Scarecrow the dress and the mask he had worn when he seemed to be the lovely Lady.', '他给稻草人看了，他扮成漂亮女士时穿的裙子和戴的面具。'),
    (15, 780, 1510, 'And the Tin Woodman saw that his terrible Beast was nothing but a lot of skins, sewn together, with slats to keep their sides out.', '铁皮人发现，他那只可怕的野兽，原来只是一堆皮缝起来的，里面还有木条撑着。'),
    (15, 780, 1511, 'As for the Ball of Fire, the false Wizard had hung that also from the ceiling.', '那个火球呢，假巫师也把它挂在天花板上。'),
    (15, 780, 1512, 'It was really a ball of cotton, but when oil was poured upon it the ball burned fiercely.', '它其实是一个棉花球，只要把油倒在上面，棉花球就会烧得很旺。'),
    (15, 781, 1513, '“Really,” said the Scarecrow, “you ought to be ashamed of yourself for being such a humbug.”', '“真是的，”稻草人说，“你这么骗人，真应该觉得不好意思。”'),
    (15, 782, 1514, '“I am—I certainly am,” answered the little man sorrowfully; “but it was the only thing I could do.', '“是啊——我当然不好意思啦。”小个子男人难过地说，“可我只能那样做。”'),
    (15, 782, 1515, 'Sit down, please, there are plenty of chairs; and I will tell you my story.”', '“请坐下吧，有很多椅子呢。我来给你们讲我的故事。”'),
    (15, 783, 1516, 'So they sat down and listened while he told the following tale.', '于是他们坐下来，听他讲起下面的故事。'),
    (15, 784, 1517, '“I was born in Omaha—”', '“我出生在奥马哈——”'),
    (15, 785, 1518, '“Why, that isn’t very far from Kansas!” cried Dorothy.', '“哎呀，那离堪萨斯不远嘛！”多萝西叫道。'),
    (15, 786, 1519, '“No, but it’s farther from here,” he said, shaking his head at her sadly.', '“不，可是离这里更远。”他难过地对她摇了摇头说。'),
    (15, 786, 1520, '“When I grew up I became a ventriloquist, and at that I was very well trained by a great master.', '“我长大后，成了一个会腹语的人，跟一个很厉害的老师学得可好了。”'),
    (15, 786, 1521, 'I can imitate any kind of a bird or beast.”', '“我能学各种各样的鸟叫和动物叫。”'),
    (15, 786, 1522, 'Here he mewed so like a kitten that Toto pricked up his ears and looked everywhere to see where she was.', '他“喵”了一声，学得太像小猫了，托托赶紧竖起耳朵，到处找小猫在哪儿呢。'),
    (15, 786, 1523, '“After a time,” continued Oz, “I tired of that, and became a balloonist.”', '“过了一段时间，”奥兹大王继续说，“我玩腻了，就去开热气球了。”'),
    (15, 787, 1524, '“What is that?” asked Dorothy.', '“那是什么呀？”多萝西问。'),
    (15, 788, 1525, '“A man who goes up in a balloon on circus day, so as to draw a crowd of people together and get them to pay to see the circus,” he explained.', '“就是马戏团表演那天，坐热气球飞上天的人。他想把大家都吸引过来，让大家买票去看马戏。”他解释说。'),
    (15, 789, 1526, '“Oh,” she said, “I know.”', '“哦，”她说，“我明白了。”'),
    (15, 790, 1527, '“Well, one day I went up in a balloon and the ropes got twisted, so that I couldn’t come down again.', '“嗯，有一天我坐热气球飞上天，绳子缠住了，我就再也下不来了。”'),
    (15, 790, 1528, 'It went way up above the clouds, so far that a current of air struck it and carried it many, many miles away.', '它飞到云层上面很高很高的地方，一阵风吹过来，把它吹到很远很远的地方去了。'),
    (15, 790, 1529, 'For a day and a night I traveled through the air, and on the morning of the second day I awoke and found the balloon floating over a strange and beautiful country.', '我在天上飞了一天一夜，第二天早上醒来时，发现热气球正飘在一个陌生又漂亮的地方上空。'),
    (15, 791, 1530, '“It came down gradually, and I was not hurt a bit.', '“它慢慢地降下来了，我一点儿也没受伤。”'),
    (15, 791, 1531, 'But I found myself in the midst of a strange people, who, seeing me come from the clouds, thought I was a great Wizard.', '但我发现我身边都是奇怪的人，他们看到我从天上下来，就以为我是个厉害的魔法师。'),
    (15, 791, 1532, 'Of course I let them think so, because they were afraid of me, and promised to do anything I wished them to.', '我当然让他们那样想了，因为他们都怕我，还答应我说什么就做什么。'),
    (15, 792, 1533, '“Just to amuse myself, and keep the good people busy, I ordered them to build this City, and my Palace; and they did it all willingly and well.', '“我只是想找点乐子，也想让大家都有事做，就让他们建了这座城市和我的宫殿。他们都非常乐意，也做得很好。'),
    (15, 792, 1534, 'Then I thought, as the country was so green and beautiful, I would call it the Emerald City; and to make the name fit better I put green spectacles on all the people, so that everything they saw was green.”', '然后我想，这个地方这么绿，这么美，我就叫它翡翠城。为了让名字更好听，我给所有人都戴上了绿色的眼镜，这样他们看什么都是绿色的。”'),
    (15, 793, 1535, '“But isn’t everything here green?” asked Dorothy.', '“可是，这里所有东西不都是绿色的吗？”多萝西问。'),
    (15, 794, 1536, '“No more than in any other city,” replied Oz; “but when you wear green spectacles, why of course everything you see looks green to you.', '“不比别的城市更绿。”奥兹大王回答，“不过，当你戴着绿眼镜时，当然看什么都是绿色的啦。'),
    (15, 794, 1537, 'The Emerald City was built a great many years ago, for I was a young man when the balloon brought me here, and I am a very old man now.', '翡翠城是在很多很多年前建的，气球把我带来的时候我还很年轻，现在我已经是个老爷爷了。'),
    (15, 794, 1538, 'But my people have worn green glasses on their eyes so long that most of them think it really is an Emerald City, and it certainly is a beautiful place, abounding in jewels and precious metals, and every good thing that is needed to make one happy.', '但我的人民戴绿眼镜戴了很久，所以大部分人都觉得这里真的是翡翠城。这里确实很美，有好多宝石、值钱的金属，还有好多好东西能让人开心。'),
    (15, 794, 1539, 'I have been good to the people, and they like me; but ever since this Palace was built, I have shut myself up and would not see any of them.', '我对大家很好，他们也喜欢我。但自从这座宫殿建好后，我就把自己关起来，再也不见他们了。'),
    (15, 795, 1540, '“One of my greatest fears was the Witches, for while I had no magical powers at all I soon found out that the Witches were really able to do wonderful things.', '“我最害怕的就是女巫们。虽然我一点魔法都不会，但我很快就发现女巫们真的能做出很厉害的事情。'),
    (15, 795, 1541, 'There were four of them in this country, and they ruled the people who live in the North and South and East and West.', '这个国家有四个女巫，她们管理着住在北方、南方、东方和西方的人。'),
    (15, 795, 1542, 'Fortunately, the Witches of the North and South were good, and I knew they would do me no harm; but the Witches of the East and West were terribly wicked, and had they not thought I was more powerful than they themselves, they would surely have destroyed me.', '幸好，北方和南方的女巫是好人，我知道她们不会伤害我。但东方和西方的女巫非常坏，如果她们没有觉得我比她们更厉害，她们肯定会把我消灭掉。'),
    (15, 795, 1543, 'As it was, I lived in deadly fear of them for many years; so you can imagine how pleased I was when I heard your house had fallen on the Wicked Witch of the East.', '就这样，我好多年都非常害怕她们。所以你可以想象，当我听说你的房子压在东方坏女巫身上时，我有多开心。'),
    (15, 795, 1544, 'When you came to me, I was willing to promise anything if you would only do away with the other Witch; but, now that you have melted her, I am ashamed to say that I cannot keep my promises.”', '你来找我的时候，我愿意答应你任何事，只要你能把另一个女巫除掉。可是，现在你已经把她融化了，我很不好意思地说，我不能遵守我的诺言了。”'),
    (15, 796, 1545, '“I think you are a very bad man,” said Dorothy.', '“我觉得你是个很坏很坏的人。”多萝西说。'),
    (15, 797, 1546, '“Oh, no, my dear; I’m really a very good man, but I’m a very bad Wizard, I must admit.”', '“哦，不，亲爱的；我其实是个很好很好的人，但我真是个很笨的魔法师，我得承认。”'),
    (15, 798, 1547, '“Can’t you give me brains?” asked the Scarecrow.', '“你不能给我一些脑子吗？”稻草人问。'),
    (15, 799, 1548, '“You don’t need them.', '“你不需要那些东西。'),
    (15, 799, 1549, 'You are learning something every day.', '你每天都在学习新东西。'),
    (15, 799, 1550, 'A baby has brains, but it doesn’t know much.', '小宝宝有脑子，但它知道的不多。'),
    (15, 799, 1551, 'Experience is the only thing that brings knowledge, and the longer you are on earth the more experience you are sure to get.”', '经验是唯一能让你学到东西的方法。你在世界上待得越久，就会有越多的经验。”'),
    (15, 800, 1552, '“That may all be true,” said the Scarecrow, “but I shall be very unhappy unless you give me brains.”', '“这些可能都是真的。”稻草人说，“但如果你不给我脑子，我就会很不开心。”'),
    (15, 801, 1553, 'The false Wizard looked at him carefully.', '那个假魔法师仔细地看着他。'),
    (15, 802, 1554, '“Well,” he said with a sigh, “I’m not much of a magician, as I said; but if you will come to me tomorrow morning, I will stuff your head with brains.', '“好吧。”他叹了口气说，“我不是什么厉害的魔法师，就像我说的那样。不过，如果你明天早上来找我，我会把你的脑袋塞满脑子。'),
    (15, 802, 1555, 'I cannot tell you how to use them, however; you must find that out for yourself.”', '不过，我不能告诉你怎么用它们哦！你得自己去想办法。”'),
    (15, 803, 1556, '“Oh, thank you—thank you!” cried the Scarecrow. “I’ll find a way to use them, never fear!”', '“哦，谢谢你——谢谢你！”稻草人大声说，“我一定会找到办法用它们的，别怕！”'),
    (15, 804, 1557, '“But how about my courage?” asked the Lion anxiously.', '“那我的勇气呢？”狮子很着急地问。'),
    (15, 805, 1558, '“You have plenty of courage, I am sure,” answered Oz.', '“你有很多很多勇气，我确定。”奥兹大王回答。'),
    (15, 805, 1559, '“All you need is confidence in yourself.', '你只需要相信你自己就行了。'),
    (15, 805, 1560, 'There is no living thing that is not afraid when it faces danger.', '面对危险的时候，没有哪个小动物或人是不害怕的。'),
    (15, 805, 1561, 'The True courage is in facing danger when you are afraid, and that kind of courage you have in plenty.”', '真正的勇气就是，就算心里害怕，也要去面对危险。你有很多这样的勇气。”'),
    (15, 806, 1562, '“Perhaps I have, but I’m scared just the same,” said the Lion.', '“也许我有，但我还是有点害怕。” 狮子说。'),
    (15, 806, 1563, '“I shall really be very unhappy unless you give me the sort of courage that makes one forget he is afraid.”', '“如果你不给我那种让人忘了害怕的勇气，我真的会很不开心。”'),
    (15, 807, 1564, '“Very well, I will give you that sort of courage tomorrow,” replied Oz.', '“好的，我明天就给你那种勇气。” 奥兹大王回答。'),
    (15, 808, 1565, '“How about my heart?” asked the Tin Woodman.', '“那我的心呢？” 铁皮人问。'),
    (15, 809, 1566, '“Why, as for that,” answered Oz, “I think you are wrong to want a heart.', '“噢，至于心嘛，” 奥兹大王说，“我觉得你想要心是错的。'),
    (15, 809, 1567, 'It makes most people unhappy.', '心会让很多人不开心。'),
    (15, 809, 1568, 'If you only knew it, you are in luck not to have a heart.”', '如果你知道，没有心，你其实是很幸运的。”'),
    (15, 810, 1569, '“That must be a matter of opinion,” said the Tin Woodman.', '“那可能是每个人想法不一样吧。” 铁皮人说。'),
    (15, 810, 1570, '“For my part, I will bear all the unhappiness without a murmur, if you will give me the heart.”', '“我呢，如果你给我一颗心，就算不开心，我也不会抱怨。”'),
    (15, 811, 1571, '“Very well,” answered Oz meekly.', '“好吧。” 奥兹大王乖乖地回答。'),
    (15, 811, 1572, '“Come to me tomorrow and you shall have a heart.', '“你明天来找我，我就会给你一颗心。'),
    (15, 811, 1573, 'I have played Wizard for so many years that I may as well continue the part a little longer.”', '我当巫师这么多年了，再多当一会儿也没关系。”'),
    (15, 812, 1574, '“And now,” said Dorothy, “how am I to get back to Kansas?”', '“那现在呢，” 多萝西说，“我怎么才能回到 堪萨斯呢？”'),
    (15, 813, 1575, '“We shall have to think about that,” replied the little man.', '“我们得好好想想这个。” 小矮人回答。'),
    (15, 813, 1576, '“Give me two or three days to consider the matter and I’ll try to find a way to carry you over the desert.', '“给我两三天时间想想，我会想办法带你们穿过沙漠。'),
    (15, 813, 1577, 'In the meantime you shall all be treated as my guests, and while you live in the Palace my people will wait upon you and obey your slightest wish.', '在这几天里，你们都是我的客人。你们住在宫殿里的时候，我的人会好好照顾你们，听你们的话。'),
    (15, 813, 1578, 'There is only one thing I ask in return for my help—such as it is.', '我帮你们，只求你们做一件事。'),
    (15, 813, 1579, 'You must keep my secret and tell no one I am a humbug.”', '你们一定要帮我保守秘密，不能告诉别人我只是一个骗子。”'),
    (15, 814, 1580, 'They agreed to say nothing of what they had learned, and went back to their rooms in high spirits.', '他们答应不说出自己知道的秘密，然后高高兴兴地回到了自己的房间。'),
    (15, 814, 1581, 'Even Dorothy had hope that “The Great and Terrible Humbug,” as she called him, would find a way to send her back to Kansas, and if he did she was willing to forgive him everything.', '连 多萝西 都相信，那个她叫做“又大又坏的骗子”会想办法送她回 堪萨斯。如果他做到了，她就愿意原谅他做过的一切。'),
    (16, 815, 1582, 'Next morning the Scarecrow said to his friends:', '第二天早上，稻草人 对他的朋友们说：'),
    (16, 816, 1583, '“Congratulate me.', '“恭喜我！'),
    (16, 816, 1584, 'I am going to Oz to get my brains at last.', '我终于要去 奥兹大王 那里拿我的大脑了。'),
    (16, 816, 1585, 'When I return I shall be as other men are.”', '等我回来，我就会和别人一样聪明了。”'),
    (16, 817, 1586, '“I have always liked you as you were,” said Dorothy simply.', '“我一直都喜欢你现在的样子。” 多萝西 简单地说。'),
    (16, 818, 1587, '“It is kind of you to like a Scarecrow,” he replied.', '“你喜欢一个 稻草人，真是太好了。” 他回答。'),
    (16, 818, 1588, '“But surely you will think more of me when you hear the splendid thoughts my new brain is going to turn out.”', '“不过，等你听到我的新大脑想出那些很棒的点子，你一定会更喜欢我的。”'),
    (16, 818, 1589, 'Then he said good-bye to them all in a cheerful voice and went to the Throne Room, where he rapped upon the door.', '然后，他开心地跟大家说再见，去了王座室，敲了敲门。'),
    (16, 819, 1590, '“Come in,” said Oz.', '“进来。” 奥兹大王说。'),
    (16, 820, 1591, 'The Scarecrow went in and found the little man sitting down by the window, engaged in deep thought.', '稻草人进去了，发现小矮人坐在窗边，在想事情呢。'),
    (16, 821, 1592, '“I have come for my brains,” remarked the Scarecrow, a little uneasily.', '“我来取我的脑子。” 稻草人有点不安地说。'),
    (16, 822, 1593, '“Oh, yes; sit down in that chair, please,” replied Oz.', '“哦，好的。请坐到那把椅子上。” 奥兹大王回答说。'),
    (16, 822, 1594, '“You must excuse me for taking your head off, but I shall have to do it in order to put your brains in their proper place.”', '“我得把你的头拿下来，真是不好意思。不过，只有这样，我才能把你的脑子放到对的地方。”'),
    (16, 823, 1595, '“That’s all right,” said the Scarecrow.', '“没关系。” 稻草人说。'),
    (16, 823, 1596, '“You are quite welcome to take my head off, as long as it will be a better one when you put it on again.”', '“你尽管把我的头拿下来吧，只要你再给我装上的时候，我的头能变得更好就行。”'),
    (16, 824, 1597, 'So the Wizard unfastened his head and emptied out the straw.', '于是，魔法师解开了他的头，把里面的稻草都倒了出来。'),
    (16, 824, 1598, 'Then he entered the back room and took up a measure of bran, which he mixed with a great many pins and needles.', '然后他走进后面的房间，拿出一些麸皮，又把好多大头针和缝衣针混了进去。'),
    (16, 824, 1599, 'Having shaken them together thoroughly, he filled the top of the Scarecrow’s head with the mixture and stuffed the rest of the space with straw, to hold it in place.', '他把这些东西好好摇匀，然后把它们放进稻草人的头顶，再用稻草把剩下的地方塞满，让它们固定住。'),
    (16, 825, 1600, 'When he had fastened the Scarecrow’s head on his body again he said to him, “Hereafter you will be a great man, for I have given you a lot of bran-new brains.”', '等他把稻草人的头重新装好，他对稻草人说：“从今以后，你就是个聪明人了，因为我给了你好多全新的脑子！”'),
    (16, 826, 1601, 'The Scarecrow was both pleased and proud at the fulfillment of his greatest wish, and having thanked Oz warmly he went back to his friends.', '稻草人非常开心又骄傲，因为他最大的愿望实现了。他热情地感谢了奥兹大王，然后回到了朋友身边。'),
    (16, 827, 1602, 'Dorothy looked at him curiously.', '多萝西好奇地看着他。'),
    (16, 827, 1603, 'His head was quite bulged out at the top with brains.', '他的头顶鼓了起来，装满了脑子。'),
    (16, 828, 1604, '“How do you feel?” she asked.', '“你感觉怎么样？” 她问。'),
    (16, 829, 1605, '“I feel wise indeed,” he answered earnestly.', '“我真的觉得自己很聪明！” 他认真地回答。'),
    (16, 829, 1606, '“When I get used to my brains I shall know everything.”', '“等我习惯了这些脑子，我就什么都知道了。”'),
    (16, 830, 1607, '“Why are those needles and pins sticking out of your head?” asked the Tin Woodman.', '“为什么那些大头针和缝衣针从你的头里伸出来了？” 铁皮人问。'),
    (16, 831, 1608, '“That is proof that he is sharp,” remarked the Lion.', '“那是证明他很‘尖’呢。” 狮子说。'),
    (16, 832, 1609, '“Well, I must go to Oz and get my heart,” said the Woodman.', '“嗯，我得去找奥兹大王拿我的心了。” 铁皮人说。'),
    (16, 832, 1610, 'So he walked to the Throne Room and knocked at the door.', '于是他走到王座室，敲了敲门。'),
    (16, 833, 1611, '“Come in,” called Oz, and the Woodman entered and said, “I have come for my heart.”', '“请进！” 奥兹大王喊道。铁皮人走了进去，说：“我来取我的心。”'),
    (16, 834, 1612, '“Very well,” answered the little man.', '“好的。” 小矮人回答。'),
    (16, 834, 1613, '“But I shall have to cut a hole in your breast, so I can put your heart in the right place.', '“不过，我得在你的胸口上开个洞，这样才能把你的心放到对的地方。”'),
    (16, 834, 1614, 'I hope it won’t hurt you.”', '“我希望你不会疼。”'),
    (16, 835, 1615, '“Oh, no,” answered the Woodman.', '“哦，不会的。” 铁皮人回答。'),
    (16, 835, 1616, '“I shall not feel it at all.”', '“我一点都不会感觉到疼。”'),
    (16, 836, 1617, 'So Oz brought a pair of tinsmith’s shears and cut a small, square hole in the left side of the Tin Woodman’s breast.', '于是奥兹大王拿来一把剪铁皮的剪刀，在铁皮人胸口的左边剪了一个小小的方洞。'),
    (16, 836, 1618, 'Then, going to a chest of drawers, he took out a pretty heart, made entirely of silk and stuffed with sawdust.', '然后，他走到一个抽屉柜旁边，拿出一个漂亮的心脏，这个心完全是用丝绸做的，里面塞满了木屑。'),
    (16, 837, 1619, '“Isn’t it a beauty?” he asked.', '“它是不是很漂亮？” 他问。'),
    (16, 838, 1620, '“It is, indeed!” replied the Woodman, who was greatly pleased. “But is it a kind heart?”', '“确实很漂亮！” 铁皮人非常高兴地回答。“但是，它是一颗善良的心吗？”'),
    (16, 839, 1621, '“Oh, very!” answered Oz.', '“哦，非常棒！”奥兹大王回答说。'),
    (16, 839, 1622, 'He put the heart in the Woodman’s breast and then replaced the square of tin, soldering it neatly together where it had been cut.', '他把心放进铁皮人的胸膛里，然后把那块锡片放回去，把切开的地方仔细地焊好了。'),
    (16, 840, 1623, '“There,” said he; “now you have a heart that any man might be proud of.', '“好了，”他说，“你现在有一颗人人都会感到骄傲的心了。'),
    (16, 840, 1624, 'I’m sorry I had to put a patch on your breast, but it really couldn’t be helped.”', '对不起，我不得不在你的胸口补一块，但真的没办法。”'),
    (16, 841, 1625, '“Never mind the patch,” exclaimed the happy Woodman.', '“补丁没关系！”快乐的铁皮人大声说。'),
    (16, 841, 1626, '“I am very grateful to you, and shall never forget your kindness.”', '“我非常感谢你，永远不会忘记你的好意。”'),
    (16, 842, 1627, '“Don’t speak of it,” replied Oz.', '“别提了。”奥兹大王回答。'),
    (16, 843, 1628, 'Then the Tin Woodman went back to his friends, who wished him every joy on account of his good fortune.', '然后铁皮人回到朋友们身边，朋友们都为他的好运祝贺他。'),
    (16, 844, 1629, 'The Lion now walked to the Throne Room and knocked at the door.', '狮子现在走到王座室，敲了敲门。'),
    (16, 845, 1630, '“Come in,” said Oz.', '“进来吧。”奥兹大王说。'),
    (16, 846, 1631, '“I have come for my courage,” announced the Lion, entering the room.', '“我来取我的勇气。”狮子走进房间，大声说。'),
    (16, 847, 1632, '“Very well,” answered the little man; “I will get it for you.”', '“好的，”小个子男人回答，“我去帮你拿。”'),
    (16, 848, 1633, 'He went to a cupboard and reaching up to a high shelf took down a square green bottle, the contents of which he poured into a green-gold dish, beautifully carved.', '他走到一个柜子前，伸手从高高的架子上拿下一个绿色的方瓶子，把里面的东西倒进一个雕刻得很漂亮的绿金色盘子里。'),
    (16, 848, 1634, 'Placing this before the Cowardly Lion, who sniffed at it as if he did not like it, the Wizard said:', '他把盘子放在胆小的狮子面前，胆小的狮子闻了闻，好像不喜欢，巫师说：'),
    (16, 849, 1635, '“Drink.”', '“喝吧。”'),
    (16, 850, 1636, '“What is it?” asked the Lion.', '“这是什么？”狮子问。'),
    (16, 851, 1637, '“Well,” answered Oz, “if it were inside of you, it would be courage.', '“嗯，”奥兹大王回答，“如果它在你身体里，那就是勇气。'),
    (16, 851, 1638, 'You know, of course, that courage is always inside one; so that this really cannot be called courage until you have swallowed it.', '你知道，勇气总是在人内心深处的；所以，在你吞下它之前，这还不能叫作勇气。'),
    (16, 851, 1639, 'Therefore I advise you to drink it as soon as possible.”', '所以，我建议你尽快喝掉它。”'),
    (16, 852, 1640, 'The Lion hesitated no longer, but drank till the dish was empty.', '狮子不再犹豫，一直喝到盘子空了。'),
    (16, 853, 1641, '“How do you feel now?” asked Oz.', '“你现在感觉怎么样？”奥兹大王问。'),
    (16, 854, 1642, '“Full of courage,” replied the Lion, who went joyfully back to his friends to tell them of his good fortune.', '“充满了勇气！”狮子回答说，他开心地回到朋友们身边，告诉他们他的好运气。'),
    (16, 855, 1643, 'Oz, left to himself, smiled to think of his success in giving the Scarecrow and the Tin Woodman and the Lion exactly what they thought they wanted.', '奥兹大王独自一人，想着他成功地给了稻草人、铁皮人和狮子他们想要的东西，就笑了。'),
    (16, 855, 1644, '“How can I help being a humbug,” he said, “when all these people make me do things that everybody knows can’t be done?', '“我怎么能不做个骗子呢？”他说，“所有人都让我做那些大家都知道做不到的事情。”'),
    (16, 855, 1645, 'It was easy to make the Scarecrow and the Lion and the Woodman happy, because they imagined I could do anything.', '让稻草人、狮子和铁皮人开心很容易，因为他们都觉得我什么都能做到。'),
    (16, 855, 1646, 'But it will take more than imagination to carry Dorothy back to Kansas, and I’m sure I don’t know how it can be done.”', '但要把多萝西送回堪萨斯那里，光靠想象是不够的，我真不知道该怎么做。”'),
    (17, 856, 1647, 'For three days Dorothy heard nothing from Oz.', '三天里，多萝西没有听到奥兹大王的任何消息。'),
    (17, 856, 1648, 'These were sad days for the little girl, although her friends were all quite happy and contented.', '对小女孩来说，这是伤心的日子，尽管她的朋友们都很开心满足。'),
    (17, 856, 1649, 'The Scarecrow told them there were wonderful thoughts in his head; but he would not say what they were because he knew no one could understand them but himself.', '稻草人告诉他们，他脑子里有很多很棒的想法；但他不说是什么，因为他知道除了自己，没人能懂。'),
    (17, 856, 1650, 'When the Tin Woodman walked about he felt his heart rattling around in his breast; and he told Dorothy he had discovered it to be a kinder and more tender heart than the one he had owned when he was made of flesh.', '当铁皮人走来走去时，他感觉到心在胸膛里叮当作响；他告诉多萝西，他发现这颗心比他由血肉之躯组成时拥有的那颗心更善良、更温柔。'),
    (17, 856, 1651, 'The Lion declared he was afraid of nothing on earth, and would gladly face an army or a dozen of the fierce Kalidahs.', '狮子说他什么都不怕，他很乐意去面对一支军队，或者十几个凶猛的卡力达。'),
    (17, 857, 1652, 'Thus each of the little party was satisfied except Dorothy, who longed more than ever to get back to Kansas.', '大家都挺开心的，除了多萝西，她比以前更想回到堪萨斯。'),
    (17, 858, 1653, 'On the fourth day, to her great joy, Oz sent for her, and when she entered the Throne Room he greeted her pleasantly:', '第四天，让奥兹大王很高兴的是，奥兹大王派人请她过去，她走进王座室时，他开心地跟她打招呼说：'),
    (17, 859, 1654, '“Sit down, my dear; I think I have found the way to get you out of this country.”', '“坐下吧，孩子；我想我找到办法让你离开这里了。”'),
    (17, 860, 1655, '“And back to Kansas?” she asked eagerly.', '“能回到堪萨斯吗？”她急切地问。'),
    (17, 861, 1656, '“Well, I’m not sure about Kansas,” said Oz, “for I haven’t the faintest notion which way it lies.', '“嗯，我不太确定能不能回到堪萨斯，”奥兹大王说，“因为我完全不知道堪萨斯在哪边。'),
    (17, 861, 1657, 'But the first thing to do is to cross the desert, and then it should be easy to find your way home.”', '但我们首先要做的是穿过沙漠，然后你就能很容易地找到回家的路了。”'),
    (17, 862, 1658, '“How can I cross the desert?” she inquired.', '“我怎么才能穿过沙漠呢？”她问。'),
    (17, 863, 1659, '“Well, I’ll tell you what I think,” said the little man.', '“嗯，我来告诉你我的想法，”小个子男人说。'),
    (17, 863, 1660, '“You see, when I came to this country it was in a balloon.', '“你看，我来这里的时候是坐着气球来的。'),
    (17, 863, 1661, 'You also came through the air, being carried by a cyclone.', '你也是从天上来的，是龙卷风把你带过来的。'),
    (17, 863, 1662, 'So I believe the best way to get across the desert will be through the air.', '所以我相信，穿过沙漠最好的办法就是坐着东西飞过去。'),
    (17, 863, 1663, 'Now, it is quite beyond my powers to make a cyclone; but I’ve been thinking the matter over, and I believe I can make a balloon.”', '我可没本事造出龙卷风。但我一直在想这件事，我觉得我能做一个气球。”'),
    (17, 864, 1664, '“How?” asked Dorothy.', '“怎么做呢？”多萝西问。'),
    (17, 865, 1665, '“A balloon,” said Oz, “is made of silk, which is coated with glue to keep the gas in it.', '“气球啊，”奥兹大王说，“是用丝绸做的，丝绸上会涂一层胶水，这样气体就不会跑出来。'),
    (17, 865, 1666, 'I have plenty of silk in the Palace, so it will be no trouble to make the balloon.', '皇宫里有很多丝绸，所以做气球不难。'),
    (17, 865, 1667, 'But in all this country there is no gas to fill the balloon with, to make it float.”', '但在这个国家，没有气体可以用来填充气球，让它飘起来。”'),
    (17, 866, 1668, '“If it won’t float,” remarked Dorothy, “it will be of no use to us.”', '“如果它飘不起来，”多萝西说，“那对我们来说就没用了。”'),
    (17, 867, 1669, '“True,” answered Oz.', '“没错，”奥兹大王回答。'),
    (17, 867, 1670, '“But there is another way to make it float, which is to fill it with hot air.', '“但还有另一种办法让它飘起来，就是往里面灌热空气。'),
    (17, 867, 1671, 'Hot air isn’t as good as gas, for if the air should get cold the balloon would come down in the desert, and we should be lost.”', '热空气不如气体好，因为如果空气变冷了，气球就会掉到沙漠里，我们就会迷路了。”'),
    (17, 868, 1672, '“We!” exclaimed the girl. “Are you going with me?”', '“我们？”女孩惊呼，“你要跟我一起去吗？”'),
    (17, 869, 1673, '“Yes, of course,” replied Oz.', '“是的，当然了，”奥兹大王回答。'),
    (17, 869, 1674, '“I am tired of being such a humbug.', '“我厌倦了当一个骗子。'),
    (17, 869, 1675, 'If I should go out of this Palace my people would soon discover I am not a Wizard, and then they would be vexed with me for having deceived them.', '如果我走出这座皇宫，我的子民很快就会发现我不是巫师，然后他们会因为我骗了他们而生我的气。'),
    (17, 869, 1676, 'So I have to stay shut up in these rooms all day, and it gets tiresome.', '所以我整天都得待在这些房间里，这让我很烦。'),
    (17, 869, 1677, 'I’d much rather go back to Kansas with you and be in a circus again.”', '我更想跟你一起回到堪萨斯，重新回到马戏团表演。”'),
    (17, 870, 1678, '“I shall be glad to have your company,” said Dorothy.', '“我很乐意有你作伴，”多萝西说。'),
    (17, 871, 1679, '“Thank you,” he answered.', '“谢谢你，”他回答。'),
    (17, 871, 1680, '“Now, if you will help me sew the silk together, we will begin to work on our balloon.”', '“现在，如果你能帮我把丝绸缝起来，我们就可以开始做气球了。”'),
    (17, 872, 1681, 'So Dorothy took a needle and thread, and as fast as Oz cut the strips of silk into proper shape the girl sewed them neatly together.', '于是 多萝西 拿起针线。奥兹大王 剪好丝绸条，女孩就把它缝起来。'),
    (17, 872, 1682, 'First there was a strip of light green silk, then a strip of dark green and then a strip of emerald green; for Oz had a fancy to make the balloon in different shades of the color about them.', '先是一条浅绿色的丝绸，接着是深绿色，再是翠绿色。因为 奥兹大王 想把气球做成好多不同深浅的绿色。'),
    (17, 872, 1683, 'It took three days to sew all the strips together, but when it was finished they had a big bag of green silk more than twenty feet long.', '他们花了三天时间，才把所有的丝绸条缝好。做好后，他们就有了一个二十多英尺长的大大的绿色丝绸袋。'),
    (17, 873, 1684, 'Then Oz painted it on the inside with a coat of thin glue, to make it airtight, after which he announced that the balloon was ready.', '接着，奥兹大王 在气球里面涂了一层薄薄的胶水，让它不漏气。然后他说，气球已经准备好了。'),
    (17, 874, 1685, '“But we must have a basket to ride in,” he said.', '他说：“但我们得有个篮子才能坐进去。”'),
    (17, 874, 1686, 'So he sent the soldier with the green whiskers for a big clothes basket, which he fastened with many ropes to the bottom of the balloon.', '于是他派那个留着绿色胡子的士兵去找一个大大的洗衣篮。然后他用好多绳子把篮子牢牢地系在气球底部。'),
    (17, 875, 1687, 'When it was all ready, Oz sent word to his people that he was going to make a visit to a great brother Wizard who lived in the clouds.', '东西都准备好后，奥兹大王 告诉大家，他要去拜访住在云朵里的一位很厉害的巫师哥哥。'),
    (17, 875, 1688, 'The news spread rapidly throughout the city and everyone came to see the wonderful sight.', '这个消息很快传遍了整个城市，大家都跑来看这个奇妙的景象。'),
    (17, 876, 1689, 'Oz ordered the balloon carried out in front of the Palace, and the people gazed upon it with much curiosity.', '奥兹大王 让人把气球抬到皇宫前面，大家好奇地看着它。'),
    (17, 876, 1690, 'The Tin Woodman had chopped a big pile of wood, and now he made a fire of it, and Oz held the bottom of the balloon over the fire so that the hot air that arose from it would be caught in the silken bag.', '铁皮人 已经砍了一大堆木头，现在他把木头点燃，奥兹大王 把气球底部放在火上，热气就跑进了丝绸袋里。'),
    (17, 876, 1691, 'Gradually the balloon swelled out and rose into the air, until finally the basket just touched the ground.', '气球慢慢地鼓起来，升到了空中，最后，篮子刚好碰到地面。'),
    (17, 877, 1692, 'Then Oz got into the basket and said to all the people in a loud voice:', '接着，奥兹大王 坐进篮子里，大声对大家说：'),
    (17, 878, 1693, '“I am now going away to make a visit.', '“我现在要走了，去拜访朋友。'),
    (17, 878, 1694, 'While I am gone the Scarecrow will rule over you.', '我不在的时候，稻草人 会管理你们。”'),
    (17, 878, 1695, 'I command you to obey him as you would me.”', '我命令你们要像听我的话一样，听他的话。”'),
    (17, 879, 1696, 'The balloon was by this time tugging hard at the rope that held it to the ground, for the air within it was hot, and this made it so much lighter in weight than the air without that it pulled hard to rise into the sky.', '这时，气球用力拉着绳子，因为它里面是热空气，比外面轻，很想飞上天。'),
    (17, 880, 1697, '“Come, Dorothy!” cried the Wizard. “Hurry up, or the balloon will fly away.”', '巫师喊道：“快来，多萝西！快点，不然气球要飞走了！”'),
    (17, 881, 1698, '“I can’t find Toto anywhere,” replied Dorothy, who did not wish to leave her little dog behind.', '多萝西 回答说：“我找不到 托托。”她不想把自己的小狗丢下。'),
    (17, 881, 1699, 'Toto had run into the crowd to bark at a kitten, and Dorothy at last found him.', '托托 跑进人群里冲着一只小猫叫，多萝西 终于找到了它。'),
    (17, 881, 1700, 'She picked him up and ran towards the balloon.', '她抱起它，跑向气球。'),
    (17, 882, 1701, 'She was within a few steps of it, and Oz was holding out his hands to help her into the basket, when, crack! went the ropes, and the balloon rose into the air without her.', '她离气球只有几步远了，奥兹大王 伸出手想帮她进篮子。就在这时，绳子“啪”地断了，气球没有她就飞走了。'),
    (17, 883, 1702, '“Come back!” she screamed. “I want to go, too!”', '她大叫：“回来！我也要去！”'),
    (17, 884, 1703, '“I can’t come back, my dear,” called Oz from the basket.', '奥兹大王 从篮子里喊道：“我回不来了，亲爱的。”'),
    (17, 884, 1704, '“Good-bye!”', '“再见！”'),
    (17, 885, 1705, '“Good-bye!” shouted everyone, and all eyes were turned upward to where the Wizard was riding in the basket, rising every moment farther and farther into the sky.', '大家都喊着：“再见！”所有人的眼睛都看着天上。巫师坐在篮子里，每时每刻都飞得更高更远。'),
    (17, 886, 1706, 'And that was the last any of them ever saw of Oz, the Wonderful Wizard, though he may have reached Omaha safely, and be there now, for all we know.', '这是大家最后一次见到奇妙的巫师 奥兹大王 了。没人知道他是不是安全到了奥马哈，现在是不是还在那儿。'),
    (17, 886, 1707, 'But the people remembered him lovingly, and said to one another:', '但大家都很爱他，常常想起他。他们互相说：'),
    (17, 887, 1708, '“Oz was always our friend.', '“奥兹大王 永远是我们的朋友。'),
    (17, 887, 1709, 'When he was here he built for us this beautiful Emerald City, and now he is gone he has left the Wise Scarecrow to rule over us.”', '他在这里时，给我们建了这座漂亮的 翡翠城。现在他走了，留下了聪明的 稻草人 来管理我们。”'),
    (17, 888, 1710, 'Still, for many days they grieved over the loss of the Wonderful Wizard, and would not be comforted.', '可是，好多天里，大家还是很伤心，因为奇妙的巫师不见了。谁也哄不好他们。'),
    (18, 889, 1711, 'Dorothy wept bitterly at the passing of her hope to get home to Kansas again; but when she thought it all over she was glad she had not gone up in a balloon.', '多萝西 很难过，因为她不能回家看 堪萨斯 了。但她想了想，又觉得没坐气球是对的。'),
    (18, 889, 1712, 'And she also felt sorry at losing Oz, and so did her companions.', '她很难过，因为 奥兹大王 不见了。她的朋友们也一样难过。'),
    (18, 890, 1713, 'The Tin Woodman came to her and said:', '铁皮人 走到她身边，对她说：'),
    (18, 891, 1714, '“Truly I should be ungrateful if I failed to mourn for the man who gave me my lovely heart.', '“要是我不为那个给我小心心的人难过，那我可就太不好了。'),
    (18, 891, 1715, 'I should like to cry a little because Oz is gone, if you will kindly wipe away my tears, so that I shall not rust.”', '奥兹大王 走了，我想哭一哭。请你帮我擦掉眼泪，这样我就不会生锈了。”'),
    (18, 892, 1716, '“With pleasure,” she answered, and brought a towel at once.', '“好的！”她说着，马上拿来一条毛巾。'),
    (18, 892, 1717, 'Then the Tin Woodman wept for several minutes, and she watched the tears carefully and wiped them away with the towel.', '然后 铁皮人 哭了很久，她小心地擦掉它的眼泪。'),
    (18, 892, 1718, 'When he had finished, he thanked her kindly and oiled himself thoroughly with his jeweled oil-can, to guard against mishap.', '他哭完后，谢谢她。然后用他的油壶给自己全身都抹了油，这样他就不会出问题了。'),
    (18, 893, 1719, 'The Scarecrow was now the ruler of the Emerald City, and although he was not a Wizard the people were proud of him.', '稻草人 现在是 翡翠城 的首领了。虽然他不是巫师，但大家都为他骄傲。'),
    (18, 893, 1720, '“For,” they said, “there is not another city in all the world that is ruled by a stuffed man.”', '他们说：“因为，全世界没有哪个城市像我们这样，是由一个‘稻草人’来管的。”'),
    (18, 893, 1721, 'And, so far as they knew, they were quite right.', '他们知道的，就是这样。他们说得很对。'),
    (18, 894, 1722, 'The morning after the balloon had gone up with Oz, the four travelers met in the Throne Room and talked matters over.', '气球带着 奥兹大王 飞走后，第二天早上，四个好朋友在王宫里见面，一起商量事情。'),
    (18, 894, 1723, 'The Scarecrow sat in the big throne and the others stood respectfully before him.', '稻草人 坐在大大的王座上，其他人乖乖地站在他面前。'),
    (18, 895, 1724, '“We are not so unlucky,” said the new ruler, “for this Palace and the Emerald City belong to us, and we can do just as we please.', '新首领说：“我们没有那么倒霉。因为这座王宫和 翡翠城 都是我们的了，我们可以想做什么就做什么。'),
    (18, 895, 1725, 'When I remember that a short time ago I was up on a pole in a farmer’s cornfield, and that now I am the ruler of this beautiful City, I am quite satisfied with my lot.”', '我想到不久前，我还在农夫的玉米地里被插在杆子上。现在我是这个漂亮城市的首领了，我对自己现在的生活很满意。”'),
    (18, 896, 1726, '“I also,” said the Tin Woodman, “am well-pleased with my new heart; and, really, that was the only thing I wished in all the world.”', '铁皮人 说：“我也很喜欢我的新心。真的，这是我最想要的东西了。”'),
    (18, 897, 1727, '“For my part, I am content in knowing I am as brave as any beast that ever lived, if not braver,” said the Lion modestly.', '狮子 害羞地说：“我觉得自己很开心，因为我知道我比任何小动物都勇敢，可能还更勇敢！”'),
    (18, 898, 1728, '“If Dorothy would only be contented to live in the Emerald City,” continued the Scarecrow, “we might all be happy together.”', '稻草人 说：“要是 多萝西 愿意住在 翡翠城 里，我们大家就可以一直开开心心地在一起了。”'),
    (18, 899, 1729, '“But I don’t want to live here,” cried Dorothy.', '多萝西 大声说：“我才不想住在这里呢！”'),
    (18, 899, 1730, '“I want to go to Kansas, and live with Aunt Em and Uncle Henry.”', '“我想去 堪萨斯，和 艾姆婶婶、亨利叔叔 住在一起。”'),
    (18, 900, 1731, '“Well, then, what can be done?” inquired the Woodman.', '铁皮人 问：“那我们能做什么呢？”'),
    (18, 901, 1732, 'The Scarecrow decided to think, and he thought so hard that the pins and needles began to stick out of his brains.', '稻草人 决定好好想想。他想得太认真了，脑袋里都快冒出钉子和针了。'),
    (18, 901, 1733, 'Finally he said:', '最后他说：'),
    (18, 902, 1734, '“Why not call the Winged Monkeys, and ask them to carry you over the desert?”', '“为什么不叫 飞猴，让他们把你带过沙漠呢？”'),
    (18, 903, 1735, '“I never thought of that!” said Dorothy joyfully.', '多萝西 开心地说：“我从来没想过这个办法！”'),
    (18, 903, 1736, '“It’s just the thing.', '“就是这样！'),
    (18, 903, 1737, 'I’ll go at once for the Golden Cap.”', '我马上就去叫 金冠。”'),
    (18, 904, 1738, 'When she brought it into the Throne Room she spoke the magic words, and soon the band of Winged Monkeys flew in through the open window and stood beside her.', '她把 飞猴 带到王宫里，念了咒语。很快，一群 飞猴 就从开着的窗户飞了进来，停在她身边。'),
    (18, 905, 1739, '“This is the second time you have called us,” said the Monkey King, bowing before the little girl.', '猴王对小女孩弯腰说：“这是你第二次叫我们了。”'),
    (18, 905, 1740, '“What do you wish?”', '“你想要什么呢？”'),
    (18, 906, 1741, '“I want you to fly with me to Kansas,” said Dorothy.', '“我想让你和我一起飞到堪萨斯去。”多萝西说。'),
    (18, 907, 1742, 'But the Monkey King shook his head.', '但猴王摇了摇头。'),
    (18, 908, 1743, '“That cannot be done,” he said.', '“那可不行。”他说。'),
    (18, 908, 1744, '“We belong to this country alone, and cannot leave it.', '“我们只属于这个国家，不能离开。'),
    (18, 908, 1745, 'There has never been a Winged Monkey in Kansas yet, and I suppose there never will be, for they don’t belong there.', '在堪萨斯从来没有飞猴，我想以后也不会有，因为他们不属于那里。'),
    (18, 908, 1746, 'We shall be glad to serve you in any way in our power, but we cannot cross the desert.', '我们很乐意尽力帮你，但我们不能穿过沙漠。'),
    (18, 908, 1747, 'Good-bye.”', '再见。”'),
    (18, 909, 1748, 'And with another bow, the Monkey King spread his wings and flew away through the window, followed by all his band.', '猴王又鞠了一躬，张开翅膀，带着他的伙伴们飞出了窗外。'),
    (18, 910, 1749, 'Dorothy was ready to cry with disappointment.', '多萝西很失望，都快哭了。'),
    (18, 910, 1750, '“I have wasted the charm of the Golden Cap to no purpose,” she said, “for the Winged Monkeys cannot help me.”', '“我白白浪费了金冠的魔法。”她说，“因为飞猴帮不了我。”'),
    (18, 911, 1751, '“It is certainly too bad!” said the tender-hearted Woodman.', '“这真是太糟糕了！”善良的铁皮人说。'),
    (18, 912, 1752, 'The Scarecrow was thinking again, and his head bulged out so horribly that Dorothy feared it would burst.', '稻草人又开始想办法了，他的头鼓得特别大，多萝西担心它会爆炸。'),
    (18, 913, 1753, '“Let us call in the soldier with the green whiskers,” he said, “and ask his advice.”', '“我们把留着绿胡子的士兵叫进来吧。”他说，“问问他的意见。”'),
    (18, 914, 1754, 'So the soldier was summoned and entered the Throne Room timidly, for while Oz was alive he never was allowed to come farther than the door.', '于是，士兵被叫来了，他小心翼翼地走进王座室，因为在奥兹大王活着的时候，他从来不被允许走到门里面。'),
    (18, 915, 1755, '“This little girl,” said the Scarecrow to the soldier, “wishes to cross the desert.', '“这个小女孩。”稻草人对士兵说，“想穿过沙漠。'),
    (18, 915, 1756, 'How can she do so?”', '她怎么才能过去呢？”'),
    (18, 916, 1757, '“I cannot tell,” answered the soldier, “for nobody has ever crossed the desert, unless it is Oz himself.”', '“我不知道。”士兵回答说，“因为除了奥兹大王自己，从没有人穿过沙漠。”'),
    (18, 917, 1758, '“Is there no one who can help me?” asked Dorothy earnestly.', '“没有人能帮我吗？”多萝西认真地问。'),
    (18, 918, 1759, '“Glinda might,” he suggested.', '“也许格林达可以。”他提议说。'),
    (18, 919, 1760, '“Who is Glinda?” inquired the Scarecrow.', '“格林达是谁？”稻草人问。'),
    (18, 920, 1761, '“The Witch of the South.', '“南方的女巫。'),
    (18, 920, 1762, 'She is the most powerful of all the Witches, and rules over the Quadlings.', '她是所有女巫里最厉害的，统治着奎德林人。'),
    (18, 920, 1763, 'Besides, her castle stands on the edge of the desert, so she may know a way to cross it.”', '而且，她的城堡就在沙漠旁边，所以她也许知道怎么穿过沙漠。”'),
    (18, 921, 1764, '“Glinda is a Good Witch, isn’t she?” asked the child.', '“格林达是个好女巫，对吗？”孩子问。'),
    (18, 922, 1765, '“The Quadlings think she is good,” said the soldier, “and she is kind to everyone.', '“奎德林人觉得她是个好人。”士兵说，“她对每个人都很好。'),
    (18, 922, 1766, 'I have heard that Glinda is a beautiful woman, who knows how to keep young in spite of the many years she has lived.”', '我听说格林达是个漂亮的女人，她活了很多年，却知道怎么让自己一直年轻。”'),
    (18, 923, 1767, '“How can I get to her castle?” asked Dorothy.', '“我怎么才能到她的城堡呢？”多萝西问。'),
    (18, 924, 1768, '“The road is straight to the South,” he answered, “but it is said to be full of dangers to travelers.', '“那条路一直往南走。”他回答说，“但听说那里对走路的人来说很危险。'),
    (18, 924, 1769, 'There are wild beasts in the woods, and a race of queer men who do not like strangers to cross their country.', '森林里有野兽，还有一群奇怪的人，他们不喜欢陌生人穿过他们的地盘。'),
    (18, 924, 1770, 'For this reason none of the Quadlings ever come to the Emerald City.”', '所以，从来没有奎德林人来过翡翠城。”'),
    (18, 925, 1771, 'The soldier then left them and the Scarecrow said:', '士兵离开了他们，然后 稻草人 说：'),
    (18, 926, 1772, '“It seems, in spite of dangers, that the best thing Dorothy can do is to travel to the Land of the South and ask Glinda to help her.', '“看来，虽然有危险，但 多萝西 最好还是去南方之地，请 格林达 帮忙。'),
    (18, 926, 1773, 'For, of course, if Dorothy stays here she will never get back to Kansas.”', '因为呀，如果 多萝西 留在这里，她就永远回不到 堪萨斯 那里了。”'),
    (18, 927, 1774, '“You must have been thinking again,” remarked the Tin Woodman.', '“你一定又在想事情了。” 铁皮人 说。'),
    (18, 928, 1775, '“I have,” said the Scarecrow.', '“是的。” 稻草人 说。'),
    (18, 929, 1776, '“I shall go with Dorothy,” declared the Lion, “for I am tired of your city and long for the woods and the country again.', '“我要和 多萝西 一起去。” 狮子 说，“因为我厌倦了你们的城市，我又想念森林和乡村了。'),
    (18, 929, 1777, 'I am really a wild beast, you know.', '我其实是一只野兽，你知道的。'),
    (18, 929, 1778, 'Besides, Dorothy will need someone to protect her.”', '而且，多萝西 也需要有人保护她。”'),
    (18, 930, 1779, '“That is true,” agreed the Woodman.', '“没错。” 铁皮人 同意。'),
    (18, 930, 1780, '“My axe may be of service to her; so I also will go with her to the Land of the South.”', '“我的斧头也许能帮到她；所以我也要和她一起去南方之地。”'),
    (18, 931, 1781, '“When shall we start?” asked the Scarecrow.', '“我们什么时候出发呢？” 稻草人 问。'),
    (18, 932, 1782, '“Are you going?” they asked, in surprise.', '“你要去吗？” 他们惊讶地问。'),
    (18, 933, 1783, '“Certainly.', '“当然去。'),
    (18, 933, 1784, 'If it wasn’t for Dorothy I should never have had brains.', '要不是 多萝西，我就永远不会有脑子了。'),
    (18, 933, 1785, 'She lifted me from the pole in the cornfield and brought me to the Emerald City.', '她把我从玉米地里的杆子上拿下来，还把我带到了 翡翠城 那里。'),
    (18, 933, 1786, 'So my good luck is all due to her, and I shall never leave her until she starts back to Kansas for good and all.”', '所以我的好运气都是因为她，我永远不会离开她，直到她彻底回到 堪萨斯 那里。”'),
    (18, 934, 1787, '“Thank you,” said Dorothy gratefully.', '“谢谢你。” 多萝西 充满感激地说。'),
    (18, 934, 1788, '“You are all very kind to me.', '“你们都对我很好。'),
    (18, 934, 1789, 'But I should like to start as soon as possible.”', '不过，我希望能尽快出发。”'),
    (18, 935, 1790, '“We shall go tomorrow morning,” returned the Scarecrow.', '“我们明天早上就走。” 稻草人 回答。'),
    (18, 935, 1791, '“So now let us all get ready, for it will be a long journey.”', '“现在大家准备一下吧，这将是一段很长的旅程。”'),
    (19, 936, 1792, 'The next morning Dorothy kissed the pretty green girl good-bye, and they all shook hands with the soldier with the green whiskers, who had walked with them as far as the gate.', '第二天早上，多萝西 亲了亲漂亮的绿衣女孩，和那个留着绿色胡子的士兵一一握手道别。士兵一直送他们到了大门口。'),
    (19, 936, 1793, 'When the Guardian of the Gate saw them again he wondered greatly that they could leave the beautiful City to get into new trouble.', '当 城门守卫 再次见到他们时，他很奇怪他们竟然会离开这座美丽的城市，去惹新的麻烦。'),
    (19, 936, 1794, 'But he at once unlocked their spectacles, which he put back into the green box, and gave them many good wishes to carry with them.', '但他立刻打开了他们的眼镜，放回绿盒子里，并祝愿他们一切顺利。'),
    (19, 937, 1795, '“You are now our ruler,” he said to the Scarecrow; “so you must come back to us as soon as possible.”', '“你现在是我们的统治者了。” 他对 稻草人 说，“所以你必须尽快回来。”'),
    (19, 938, 1796, '“I certainly shall if I am able,” the Scarecrow replied; “but I must help Dorothy to get home, first.”', '“如果我能的话，我当然会回来。” 稻草人 回答，“但首先，我必须帮助 多萝西 回家。”'),
    (19, 939, 1797, 'As Dorothy bade the good-natured Guardian a last farewell she said:', '当 多萝西 和那位好心的守护者最后告别时，她说：'),
    (19, 940, 1798, '“I have been very kindly treated in your lovely City, and everyone has been good to me.', '“在这美丽的城市里，我受到了很好的对待，每个人都对我很好。'),
    (19, 940, 1799, 'I cannot tell you how grateful I am.”', '我无法表达我有多么感激。”'),
    (19, 941, 1800, '“Don’t try, my dear,” he answered.', '“别说了，我的孩子。” 他回答。'),
    (19, 941, 1801, '“We should like to keep you with us, but if it is your wish to return to Kansas, I hope you will find a way.”', '我们想让你跟我们在一起，但如果你想回 堪萨斯，我希望你能找到回去的路。'),
    (19, 941, 1802, 'He then opened the gate of the outer wall, and they walked forth and started upon their journey.', '他打开了外面的大门，他们就走了出去，开始赶路了。'),
    (19, 942, 1803, 'The sun shone brightly as our friends turned their faces toward the Land of the South.', '太阳亮亮地照着，朋友们朝南边的土地走去。'),
    (19, 942, 1804, 'They were all in the best of spirits, and laughed and chatted together.', '他们都非常高兴，又说又笑。'),
    (19, 942, 1805, 'Dorothy was once more filled with the hope of getting home, and the Scarecrow and the Tin Woodman were glad to be of use to her.', '多萝西又有了回家的希望，稻草人和铁皮人也很高兴能帮到她。'),
    (19, 942, 1806, 'As for the Lion, he sniffed the fresh air with delight and whisked his tail from side to side in pure joy at being in the country again, while Toto ran around them and chased the moths and butterflies, barking merrily all the time.', '狮子开心地闻着新鲜空气，高兴地摇着尾巴，因为它又回到了乡下。托托在他们身边跑，追着飞蛾和蝴蝶，一直开心地叫。'),
    (19, 943, 1807, '“City life does not agree with me at all,” remarked the Lion, as they walked along at a brisk pace.', '“城市生活一点都不适合我，”狮子一边快步走着，一边说。'),
    (19, 943, 1808, '“I have lost much flesh since I lived there, and now I am anxious for a chance to show the other beasts how courageous I have grown.”', '“我住在那里瘦了很多，现在我希望能有机会让别的动物看看我有多勇敢。”'),
    (19, 944, 1809, 'They now turned and took a last look at the Emerald City.', '他们转过身，最后看了一眼翡翠城。'),
    (19, 944, 1810, 'All they could see was a mass of towers and steeples behind the green walls, and high up above everything the spires and dome of the Palace of Oz.', '他们看到绿色的城墙后面有很多高塔和尖顶，所有东西上面是奥兹大王宫殿的尖塔和圆顶。'),
    (19, 945, 1811, '“Oz was not such a bad Wizard, after all,” said the Tin Woodman, as he felt his heart rattling around in his breast.', '“奥兹大王其实也不是个坏巫师嘛，”铁皮人摸着自己砰砰跳的心脏说。'),
    (19, 946, 1812, '“He knew how to give me brains, and very good brains, too,” said the Scarecrow.', '“他知道怎么给我智慧，而且是很好的智慧，”稻草人说。'),
    (19, 947, 1813, '“If Oz had taken a dose of the same courage he gave me,” added the Lion, “he would have been a brave man.”', '“要是奥兹大王也吃了点他给我的那种勇气，”狮子补充说，“他也会是个勇敢的人。”'),
    (19, 948, 1814, 'Dorothy said nothing.', '多萝西什么也没说。'),
    (19, 948, 1815, 'Oz had not kept the promise he made her, but he had done his best, so she forgave him.', '奥兹大王没有遵守对她做的承诺，但他已经尽力了，所以她原谅了他。'),
    (19, 948, 1816, 'As he said, he was a good man, even if he was a bad Wizard.', '就像他说的那样，他是个好人，即使他是个坏巫师。'),
    (19, 949, 1817, 'The first day’s journey was through the green fields and bright flowers that stretched about the Emerald City on every side.', '第一天的路程，他们穿过了翡翠城四周绿绿的田野和开满鲜花的草地。'),
    (19, 949, 1818, 'They slept that night on the grass, with nothing but the stars over them; and they rested very well indeed.', '那天晚上他们睡在草地上，头顶上只有星星；他们睡得很好。'),
    (19, 950, 1819, 'In the morning they traveled on until they came to a thick wood.', '早上他们继续赶路，直到来到一片茂密的树林。'),
    (19, 950, 1820, 'There was no way of going around it, for it seemed to extend to the right and left as far as they could see; and, besides, they did not dare change the direction of their journey for fear of getting lost.', '他们没法绕过去，因为树林好像一直向左右延伸，看不到尽头；而且，他们也不敢改变方向，怕迷路。'),
    (19, 950, 1821, 'So they looked for the place where it would be easiest to get into the forest.', '所以他们找了一个最容易走进森林的地方。'),
    (19, 951, 1822, 'The Scarecrow, who was in the lead, finally discovered a big tree with such wide-spreading branches that there was room for the party to pass underneath.', '走在前面的稻草人，终于发现了一棵大树，它的树枝伸得很开，大家可以从下面过去。'),
    (19, 951, 1823, 'So he walked forward to the tree, but just as he came under the first branches they bent down and twined around him, and the next minute he was raised from the ground and flung headlong among his fellow travelers.', '他走过去，刚到第一根树枝下面，树枝就弯下来缠住了他。接着，他被从地上提起来，头朝下地扔到了同伴们中间。'),
    (19, 952, 1824, 'This did not hurt the Scarecrow, but it surprised him, and he looked rather dizzy when Dorothy picked him up.', '这没有伤到稻草人，但让他很吃惊。当多萝西把他捡起来时，他看起来有点头晕。'),
    (19, 953, 1825, '“Here is another space between the trees,” called the Lion.', '“这里树中间还有个空隙！”狮子喊道。'),
    (19, 954, 1826, '“Let me try it first,” said the Scarecrow, “for it doesn’t hurt me to get thrown about.”', '“让我先试试吧，”稻草人说，“因为我被扔来扔去也不会疼。”'),
    (19, 954, 1827, 'He walked up to another tree, as he spoke, but its branches immediately seized him and tossed him back again.', '他一边说，一边走到另一棵树旁，可树枝立刻抓住他，又把他扔了回来。'),
    (19, 955, 1828, '“This is strange,” exclaimed Dorothy.', '“这真奇怪！”多萝西大声说。'),
    (19, 955, 1829, '“What shall we do?”', '“我们该怎么办呢？”'),
    (19, 956, 1830, '“The trees seem to have made up their minds to fight us, and stop our journey,” remarked the Lion.', '“这些树好像决定要和我们打架，不让我们走了，”狮子说。'),
    (19, 957, 1831, '“I believe I will try it myself,” said the Woodman, and shouldering his axe, he marched up to the first tree that had handled the Scarecrow so roughly.', '“我想我自己来试试。” 铁皮人说，他扛起斧头，走到第一棵树前，这棵树刚才对 稻草人 太不客气了。'),
    (19, 957, 1832, 'When a big branch bent down to seize him the Woodman chopped at it so fiercely that he cut it in two.', '当一根大树枝弯下来抓他时，铁皮人使劲一砍，就把树枝砍成了两半。'),
    (19, 957, 1833, 'At once the tree began shaking all its branches as if in pain, and the Tin Woodman passed safely under it.', '树立刻痛苦地摇晃着所有的树枝，铁皮人安全地从树下走过去了。'),
    (19, 958, 1834, '“Come on!” he shouted to the others. “Be quick!”', '“快走！”他大声对其他人喊道，“快点！”'),
    (19, 958, 1835, 'They all ran forward and passed under the tree without injury, except Toto, who was caught by a small branch and shaken until he howled.', '他们都跑过去，安全地从树下过去了，除了 托托。他被一根小树枝缠住，一直摇晃他，直到他大叫起来。'),
    (19, 958, 1836, 'But the Woodman promptly chopped off the branch and set the little dog free.', '但 铁皮人 立刻砍断了树枝，让小狗自由了。'),
    (19, 959, 1837, 'The other trees of the forest did nothing to keep them back, so they made up their minds that only the first row of trees could bend down their branches, and that probably these were the policemen of the forest, and given this wonderful power in order to keep strangers out of it.', '森林里其他的树没有拦住他们。大家就想，可能只有第一排的树才会弯下树枝吧。它们也许是森林里的警察，有了这种厉害的能力，就能不让陌生人进来。'),
    (19, 960, 1838, 'The four travelers walked with ease through the trees until they came to the farther edge of the wood.', '四个旅行者轻松地穿过树林，一直走到森林的另一边。'),
    (19, 960, 1839, 'Then, to their surprise, they found before them a high wall which seemed to be made of white china.', '接着，让他们很惊讶的是，他们面前有一堵高高的墙，看起来像是用白色的瓷做的。'),
    (19, 960, 1840, 'It was smooth, like the surface of a dish, and higher than their heads.', '它很光滑，就像盘子的表面一样，比他们的头还要高。'),
    (19, 961, 1841, '“What shall we do now?” asked Dorothy.', '“我们现在该怎么办呢？” 多萝西问道。'),
    (19, 962, 1842, '“I will make a ladder,” said the Tin Woodman, “for we certainly must climb over the wall.”', '“我来做一个梯子。” 铁皮人说，“我们肯定要爬过这堵墙。”'),
    (20, 963, 1843, 'While the Woodman was making a ladder from wood which he found in the forest Dorothy lay down and slept, for she was tired by the long walk.', '当 铁皮人 用他在森林里找到的木头做梯子时，多萝西 躺下来睡着了，因为走了很长的路，她累了。'),
    (20, 963, 1844, 'The Lion also curled himself up to sleep and Toto lay beside him.', '狮子 也蜷缩起来睡觉，托托 躺在他旁边。'),
    (20, 964, 1845, 'The Scarecrow watched the Woodman while he worked, and said to him:', '稻草人 看着 铁皮人 工作，然后对他说：'),
    (20, 965, 1846, '“I cannot think why this wall is here, nor what it is made of.”', '“我搞不懂这堵墙为什么会在这里，也不知道它是用什么做的。”'),
    (20, 966, 1847, '“Rest your brains and do not worry about the wall,” replied the Woodman.', '“别费脑筋了，也别担心这堵墙。” 铁皮人 回答说。'),
    (20, 966, 1848, '“When we have climbed over it, we shall know what is on the other side.”', '“等我们爬过去，就知道墙后面是什么了。”'),
    (20, 967, 1849, 'After a time the ladder was finished.', '过了一会儿，梯子做好了。'),
    (20, 967, 1850, 'It looked clumsy, but the Tin Woodman was sure it was strong and would answer their purpose.', '它看起来有点笨重，但 铁皮人 确定它很结实，能帮上他们的忙。'),
    (20, 967, 1851, 'The Scarecrow waked Dorothy and the Lion and Toto, and told them that the ladder was ready.', '稻草人 叫醒了 多萝西 和 狮子 和 托托，告诉他们梯子已经准备好了。'),
    (20, 967, 1852, 'The Scarecrow climbed up the ladder first, but he was so awkward that Dorothy had to follow close behind and keep him from falling off.', '稻草人 第一个爬上梯子，但他太笨拙了，所以 多萝西 必须紧跟在他后面，不让他摔下来。'),
    (20, 967, 1853, 'When he got his head over the top of the wall the Scarecrow said, “Oh, my!”', '当他的头探过墙顶时，稻草人 说：“噢，天哪！”'),
    (20, 968, 1854, '“Go on,” exclaimed Dorothy.', '“快点！” 多萝西 大声说。'),
    (20, 969, 1855, 'So the Scarecrow climbed farther up and sat down on the top of the wall, and Dorothy put her head over and cried, “Oh, my!” just as the Scarecrow had done.', '于是 稻草人 又往上爬了一点，坐在了墙顶上，多萝西 也把头探过去，大叫一声：“噢，天哪！” 就像 稻草人 刚才那样。'),
    (20, 970, 1856, 'Then Toto came up, and immediately began to bark, but Dorothy made him be still.', '接着 托托 也爬上来了，立刻就开始叫，但 多萝西 让他安静下来。'),
    (20, 971, 1857, 'The Lion climbed the ladder next, and the Tin Woodman came last; but both of them cried, “Oh, my!” as soon as they looked over the wall.', '接着 狮子 爬上梯子，铁皮人 最后一个上来；可他们俩刚把头探过墙，就都大叫：“噢，天哪！”'),
    (20, 971, 1858, 'When they were all sitting in a row on the top of the wall, they looked down and saw a strange sight.', '当他们都一排排地坐在墙顶上时，他们往下看，看到了一幅奇怪的景象。'),
    (20, 972, 1859, 'Before them was a great stretch of country having a floor as smooth and shining and white as the bottom of a big platter.', '在他们面前是一大片地方，地面又光滑又亮，白得像一个大盘子的底面。'),
    (20, 972, 1860, 'Scattered around were many houses made entirely of china and painted in the brightest colors.', '四周散落着许多房子，它们完全是用瓷做的，漆成了最鲜艳的颜色。'),
    (20, 972, 1861, 'These houses were quite small, the biggest of them reaching only as high as Dorothy’s waist.', '这些房子都很小，最大的也只到多萝西的腰那么高。'),
    (20, 972, 1862, 'There were also pretty little barns, with china fences around them; and many cows and sheep and horses and pigs and chickens, all made of china, were standing about in groups.', '还有很多漂亮的小谷仓，周围有瓷器做的围栏；许多瓷器做的小牛、小羊、小马、小猪和小鸡，都成群地站在那里。'),
    (20, 973, 1863, 'But the strangest of all were the people who lived in this queer country.', '但最奇怪的是，住在这个奇怪国家里的人们。'),
    (20, 973, 1864, 'There were milkmaids and shepherdesses, with brightly colored bodices and golden spots all over their gowns; and princesses with most gorgeous frocks of silver and gold and purple; and shepherds dressed in knee breeches with pink and yellow and blue stripes down them, and golden buckles on their shoes; and princes with jeweled crowns upon their heads, wearing ermine robes and satin doublets; and funny clowns in ruffled gowns, with round red spots upon their cheeks and tall, pointed caps.', '有挤奶的婶婶和放羊的姐姐，她们穿的衣服很亮，裙子上还有金色的点点。有公主，穿着闪闪发光的银色、金色和紫色的裙子。牧羊人穿着有粉色、黄色、蓝色条纹的裤子，鞋子上有金色的扣子。王子头上戴着漂亮的宝石王冠，穿着软软的皮草衣服。还有好玩的小丑，穿着皱巴巴的衣服，脸上画着红点，戴着高高的尖帽子。'),
    (20, 973, 1865, 'And, strangest of all, these people were all made of china, even to their clothes, and were so small that the tallest of them was no higher than Dorothy’s knee.', '而最奇怪的是，这些人全都是瓷器做的，连衣服也是！他们太小了，最高的人也只到多萝西的膝盖。'),
    (20, 974, 1866, 'No one did so much as look at the travelers at first, except one little purple china dog with an extra-large head, which came to the wall and barked at them in a tiny voice, afterwards running away again.', '一开始，没有人理会这些旅行者。只有一只紫色的小瓷狗，它有一个大大的头，走到墙边，冲他们轻轻地叫了几声，然后又跑开了。'),
    (20, 975, 1867, '“How shall we get down?” asked Dorothy.', '“我们怎么下去呢？”多萝西问道。'),
    (20, 976, 1868, 'They found the ladder so heavy they could not pull it up, so the Scarecrow fell off the wall and the others jumped down upon him so that the hard floor would not hurt their feet.', '他们发现梯子太重了，拉不上去。所以稻草人从墙上跳了下来，其他人也跳到他身上，这样硬硬的地板就不会伤到他们的脚了。'),
    (20, 976, 1869, 'Of course they took pains not to light on his head and get the pins in their feet.', '当然，他们很小心，没有跳到他的头上，也没有让钉子扎到脚。'),
    (20, 976, 1870, 'When all were safely down they picked up the Scarecrow, whose body was quite flattened out, and patted his straw into shape again.', '当他们都安全下来后，他们抱起稻草人，他的身体都扁扁的了，然后拍了拍，让他的稻草又变回原来的样子。'),
    (20, 977, 1871, '“We must cross this strange place in order to get to the other side,” said Dorothy, “for it would be unwise for us to go any other way except due South.”', '“我们必须穿过这个奇怪的地方才能到对面，”多萝西说，“因为如果我们不一直往南走，那就不太好。”'),
    (20, 978, 1872, 'They began walking through the country of the china people, and the first thing they came to was a china milkmaid milking a china cow.', '他们开始走过这个瓷器人的国家。他们遇到的第一个景象是一个瓷器挤奶姑娘正在挤一头瓷器奶牛的奶。'),
    (20, 978, 1873, 'As they drew near, the cow suddenly gave a kick and kicked over the stool, the pail, and even the milkmaid herself, and all fell on the china ground with a great clatter.', '当他们走近时，那头奶牛突然踢了一下，踢翻了凳子、桶，甚至连挤奶姑娘也踢倒了！所有东西都“哗啦”一声掉在了瓷器做的地上。'),
    (20, 979, 1874, 'Dorothy was shocked to see that the cow had broken her leg off, and that the pail was lying in several small pieces, while the poor milkmaid had a nick in her left elbow.', '多萝西很惊讶地看到，奶牛的一条腿断了，桶也碎成了好几块。可怜的挤奶姑娘左手肘也裂了一个小口子。'),
    (20, 980, 1875, '“There!” cried the milkmaid angrily.', '“哎呀！”挤奶姑娘生气地叫道。'),
    (20, 980, 1876, '“See what you have done!', '“看看你们做了什么好事！”'),
    (20, 980, 1877, 'My cow has broken her leg, and I must take her to the mender’s shop and have it glued on again.', '我的奶牛腿断了，我得带她去修理店，把腿再粘好。'),
    (20, 980, 1878, 'What do you mean by coming here and frightening my cow?”', '你们来这里吓我的奶牛，是什么意思呀？”'),
    (20, 981, 1879, '“I’m very sorry,” returned Dorothy.', '“对不起，”多萝西回答道。'),
    (20, 981, 1880, '“Please forgive us.”', '“请原谅我们。”'),
    (20, 982, 1881, 'But the pretty milkmaid was much too vexed to make any answer.', '但漂亮的挤奶姑娘太生气了，生气得都没法回答。'),
    (20, 982, 1882, 'She picked up the leg sulkily and led her cow away, the poor animal limping on three legs.', '她不高兴地捡起那条断腿，然后牵着奶牛走了，那可怜的奶牛只能用三条腿走路，一瘸一拐的。'),
    (20, 982, 1883, 'As she left them the milkmaid cast many reproachful glances over her shoulder at the clumsy strangers, holding her nicked elbow close to her side.', '她走的时候，挤奶姑娘回头瞪了好几眼这些笨手笨脚的陌生人，她还紧紧地捂着自己裂口的胳膊肘。'),
    (20, 983, 1884, 'Dorothy was quite grieved at this mishap.', '多萝西看到这场意外，心里很难过。'),
    (20, 984, 1885, '“We must be very careful here,” said the kind-hearted Woodman, “or we may hurt these pretty little people so they will never get over it.”', '“我们在这里可要非常小心啊，”善良的铁皮人说，“不然我们可能会弄伤这些漂亮的小人儿，他们就再也好不了了。”'),
    (20, 985, 1886, 'A little farther on Dorothy met a most beautifully dressed young Princess, who stopped short as she saw the strangers and started to run away.', '再往前走一点，多萝西遇到了一位穿着非常漂亮的年轻公主。公主一看到陌生人就停住了，然后想跑开。'),
    (20, 986, 1887, 'Dorothy wanted to see more of the Princess, so she ran after her.', '多萝西想多看看这位公主，所以她就追了上去。'),
    (20, 986, 1888, 'But the china girl cried out:', '但那个瓷器小女孩大声喊道：'),
    (20, 987, 1889, '“Don’t chase me!', '“别追我！'),
    (20, 987, 1890, 'Don’t chase me!”', '别追我！”'),
    (20, 988, 1891, 'She had such a frightened little voice that Dorothy stopped and said, “Why not?”', '她的声音吓得有些发抖，多萝西停下来问：“为什么不跑呢？”'),
    (20, 989, 1892, '“Because,” answered the Princess, also stopping, a safe distance away, “if I run I may fall down and break myself.”', '“因为呀，”公主也停了下来，站得远远的，说，“如果我跑，可能会摔倒，把自己摔碎的。”'),
    (20, 990, 1893, '“But could you not be mended?” asked the girl.', '“可是，你不能修好吗？”小女孩问。'),
    (20, 991, 1894, '“Oh, yes; but one is never so pretty after being mended, you know,” replied the Princess.', '“噢，可以呀；但修好以后就没那么漂亮了，你知道的。”公主回答。'),
    (20, 992, 1895, '“I suppose not,” said Dorothy.', '“我想也是吧。”多萝西说。'),
    (20, 993, 1896, '“Now there is Mr. Joker, one of our clowns,” continued the china lady, “who is always trying to stand upon his head.', '“看，那位小丑先生，”瓷器女士继续说，“他是我们这里的小丑，老是喜欢倒立。'),
    (20, 993, 1897, 'He has broken himself so often that he is mended in a hundred places, and doesn’t look at all pretty.', '他摔碎过好多次了，修了有一百个地方，一点也不漂亮了。'),
    (20, 993, 1898, 'Here he comes now, so you can see for yourself.”', '他现在过来了，你可以自己看看。”'),
    (20, 994, 1899, 'Indeed, a jolly little clown came walking toward them, and Dorothy could see that in spite of his pretty clothes of red and yellow and green he was completely covered with cracks, running every which way and showing plainly that he had been mended in many places.', '果然，一个开心的小丑向他们走来。多萝西看到，尽管他穿着红黄绿相间的漂亮衣服，但全身都是裂缝，裂缝到处都是，很明显他被修补过很多次。'),
    (20, 995, 1900, 'The Clown put his hands in his pockets, and after puffing out his cheeks and nodding his head at them saucily, he said:', '小丑把手插进口袋里，鼓起脸颊，顽皮地对他们点点头，然后说：'),
    (20, 996, 1901, '“My lady fair, Why do you stare At poor old Mr. Joker?', '“美丽的女士，你为什么盯着可怜的小丑先生看？'),
    (20, 996, 1902, 'You’re quite as stiff And prim as if You’d eaten up a poker!”', '你是不是吃了个火钳，怎么呆呆的，这么严肃！”'),
    (20, 997, 1903, '“Be quiet, sir!” said the Princess. “Can’t you see these are strangers, and should be treated with respect?”', '“安静点，先生！”公主说，“难道你没看到这些是陌生人吗？我们应该尊重他们。”'),
    (20, 998, 1904, '“Well, that’s respect, I expect,” declared the Clown, and immediately stood upon his head.', '“嗯，我想这就是尊重吧，”小丑说，然后立刻倒立了起来。'),
    (20, 999, 1905, '“Don’t mind Mr. Joker,” said the Princess to Dorothy.', '“别理小丑先生。”公主对多萝西说。'),
    (20, 999, 1906, '“He is considerably cracked in his head, and that makes him foolish.”', '“他脑袋里裂缝太多了，所以有点傻。”'),
    (20, 1000, 1907, '“Oh, I don’t mind him a bit,” said Dorothy.', '“噢，我一点也不介意他。”多萝西说。'),
    (20, 1000, 1908, '“But you are so beautiful,” she continued, “that I am sure I could love you dearly.', '“但是你太漂亮了，”她继续说，“我肯定会非常非常喜欢你的。'),
    (20, 1000, 1909, 'Won’t you let me carry you back to Kansas, and stand you on Aunt Em’s mantel?', '你愿不愿意让我把你带回堪萨斯，然后把你放在艾姆婶婶的壁炉架上？'),
    (20, 1000, 1910, 'I could carry you in my basket.”', '我可以用我的篮子把你装走。”'),
    (20, 1001, 1911, '“That would make me very unhappy,” answered the china Princess.', '“那会让我很不开心。”瓷器公主回答。'),
    (20, 1001, 1912, '“You see, here in our country we live contentedly, and can talk and move around as we please.', '“你看，在我们这个国家，我们过得很开心，可以随便说话和走动。'),
    (20, 1001, 1913, 'But whenever any of us are taken away our joints at once stiffen, and we can only stand straight and look pretty.', '但只要我们中的任何一个被带走，我们的关节就会立刻变硬，只能直直地站着，看起来漂亮而已。'),
    (20, 1001, 1914, 'Of course that is all that is expected of us when we are on mantels and cabinets and drawing-room tables, but our lives are much pleasanter here in our own country.”', '当然啦，当我们被放在壁炉架、柜子和客厅桌上时，大家也只希望我们这样。但在这里，我们自己的国家，生活要快乐得多。”'),
    (20, 1002, 1915, '“I would not make you unhappy for all the world!” exclaimed Dorothy. “So I’ll just say good-bye.”', '“我才不愿意让你不开心呢！”多萝西大声说，“那我只好说再见了。”'),
    (20, 1003, 1916, '“Good-bye,” replied the Princess.', '“再见。”公主回答。'),
    (20, 1004, 1917, 'They walked carefully through the china country.', '他们小心翼翼地穿过瓷器国家。'),
    (20, 1004, 1918, 'The little animals and all the people scampered out of their way, fearing the strangers would break them, and after an hour or so the travelers reached the other side of the country and came to another china wall.', '小动物们和所有的人都跑开了，生怕陌生人会把他们弄碎。过了一个多小时，旅行者们到达了这个国家的另一边，看到了一堵新的瓷器墙。'),
    (20, 1005, 1919, 'It was not so high as the first, however, and by standing upon the Lion’s back they all managed to scramble to the top.', '不过，这堵墙没有第一堵那么高。他们站在狮子的背上，都爬到了墙顶。'),
    (20, 1005, 1920, 'Then the Lion gathered his legs under him and jumped on the wall; but just as he jumped, he upset a china church with his tail and smashed it all to pieces.', '然后狮子把腿收起来，跳到墙上；但他刚跳上去，就用尾巴撞倒了一座瓷器教堂，把它全都摔碎了。'),
    (20, 1006, 1921, '“That was too bad,” said Dorothy, “but really I think we were lucky in not doing these little people more harm than breaking a cow’s leg and a church.', '“真不好呀，” 多萝西 说，“不过我们很幸运，没给这些小人儿带来更多麻烦，只弄断了一头牛的腿和一座教堂。”'),
    (20, 1006, 1922, 'They are all so brittle!”', '他们都好脆呀！”'),
    (20, 1007, 1923, '“They are, indeed,” said the Scarecrow, “and I am thankful I am made of straw and cannot be easily damaged.', '“他们确实是，” 稻草人 说，“我很开心我是稻草做的，不容易坏掉。'),
    (20, 1007, 1924, 'There are worse things in the world than being a Scarecrow.”', '世界上还有比当个 稻草人 更糟糕的事呢。”'),
    (21, 1008, 1925, 'After climbing down from the china wall the travelers found themselves in a disagreeable country, full of bogs and marshes and covered with tall, rank grass.', '从瓷墙上爬下来后，他们来到一个不舒服的地方，那里有好多泥沼和湿地，长满了高高的野草。'),
    (21, 1008, 1926, 'It was difficult to walk without falling into muddy holes, for the grass was so thick that it hid them from sight.', '走路很不容易，不小心就会掉进泥坑里，因为草太厚了，把坑都藏起来了。'),
    (21, 1008, 1927, 'However, by carefully picking their way, they got safely along until they reached solid ground.', '不过，他们小心地选路走，终于安全地来到了一块结实的地面。'),
    (21, 1008, 1928, 'But here the country seemed wilder than ever, and after a long and tiresome walk through the underbrush they entered another forest, where the trees were bigger and older than any they had ever seen.', '但这里比以前更荒凉了，走了很久很久，穿过矮树丛，他们又进了一片森林，那里的树比他们见过的所有树都大，都老。'),
    (21, 1009, 1929, '“This forest is perfectly delightful,” declared the Lion, looking around him with joy.', '“这片森林真是太棒了！” 狮子 开心地看着四周说。'),
    (21, 1009, 1930, '“Never have I seen a more beautiful place.”', '“我从没见过这么美的地方。”'),
    (21, 1010, 1931, '“It seems gloomy,” said the Scarecrow.', '“这里看起来有点暗，” 稻草人 说。'),
    (21, 1011, 1932, '“Not a bit of it,” answered the Lion.', '“一点也不啊！” 狮子 回答说。'),
    (21, 1011, 1933, '“I should like to live here all my life.', '“我真想一辈子住在这里呢。'),
    (21, 1011, 1934, 'See how soft the dried leaves are under your feet and how rich and green the moss is that clings to these old trees.', '看，你脚下的干树叶多软啊，这些老树上的苔藓多绿多好看啊。'),
    (21, 1011, 1935, 'Surely no wild beast could wish a pleasanter home.”', '肯定没有野兽会不喜欢这里，不想住在这里吧。”'),
    (21, 1012, 1936, '“Perhaps there are wild beasts in the forest now,” said Dorothy.', '“也许森林里现在有野兽呢，” 多萝西 说。'),
    (21, 1013, 1937, '“I suppose there are,” returned the Lion, “but I do not see any of them about.”', '“我想是有的，” 狮子 回答，“但我没看到它们呀。”'),
    (21, 1014, 1938, 'They walked through the forest until it became too dark to go any farther.', '他们一直走啊走，穿过森林，直到天黑得不能再走了。'),
    (21, 1014, 1939, 'Dorothy and Toto and the Lion lay down to sleep, while the Woodman and the Scarecrow kept watch over them as usual.', '多萝西、托托 和 狮子 躺下睡觉，而 铁皮人 和 稻草人 像以前一样，帮他们看守着。'),
    (21, 1015, 1940, 'When morning came, they started again.', '天亮了，他们又出发了。'),
    (21, 1015, 1941, 'Before they had gone far they heard a low rumble, as of the growling of many wild animals.', '他们没走多远，就听到一阵低沉的轰隆声，好像是好多野兽在吼叫。'),
    (21, 1015, 1942, 'Toto whimpered a little, but none of the others was frightened, and they kept along the well-trodden path until they came to an opening in the wood, in which were gathered hundreds of beasts of every variety.', '托托 小声哼哼了几下，但其他人都没有害怕。他们沿着小路一直走，来到一片空地，那里聚了几百只各种各样的野兽。'),
    (21, 1015, 1943, 'There were tigers and elephants and bears and wolves and foxes and all the others in the natural history, and for a moment Dorothy was afraid.', '那里有老虎、大象、熊、狼、狐狸，还有好多好多动物。那一刻，多萝西 害怕了。'),
    (21, 1015, 1944, 'But the Lion explained that the animals were holding a meeting, and he judged by their snarling and growling that they were in great trouble.', '但 狮子 告诉大家，动物们正在开会。他从它们的吼叫声听出来，它们遇到了大麻烦。'),
    (21, 1016, 1945, 'As he spoke several of the beasts caught sight of him, and at once the great assemblage hushed as if by magic.', '他说话的时候，有几只野兽看到了他，一下子，所有的动物都像变魔术一样，安静下来了。'),
    (21, 1016, 1946, 'The biggest of the tigers came up to the Lion and bowed, saying:', '最大的一只老虎走到 狮子 面前，弯了弯腰，说：'),
    (21, 1017, 1947, '“Welcome, O King of Beasts!', '“欢迎您，动物之王！'),
    (21, 1017, 1948, 'You have come in good time to fight our enemy and bring peace to all the animals of the forest once more.”', '您来得真及时，快来帮我们打败敌人，让森林里的动物们重新过上平静的日子吧。”'),
    (21, 1018, 1949, '“What is your trouble?” asked the Lion quietly.', '“你们有什么麻烦呀？” 狮子 轻轻地问。'),
    (21, 1019, 1950, '“We are all threatened,” answered the tiger, “by a fierce enemy which has lately come into this forest.', '“我们都遇到了危险，”老虎回答，“一个很凶的敌人最近来到了这片森林，威胁着我们所有人。'),
    (21, 1019, 1951, 'It is a most tremendous monster, like a great spider, with a body as big as an elephant and legs as long as a tree trunk.', '它是个巨大的怪物，像个大蜘蛛。它的身体像大象一样大，腿像树干一样长。'),
    (21, 1019, 1952, 'It has eight of these long legs, and as the monster crawls through the forest he seizes an animal with a leg and drags it to his mouth, where he eats it as a spider does a fly.', '它有八条长长的腿。怪物在森林里爬的时候，会用一条腿抓住动物，拖到嘴边，像蜘蛛吃苍蝇一样把它们吃掉。'),
    (21, 1019, 1953, 'Not one of us is safe while this fierce creature is alive, and we had called a meeting to decide how to take care of ourselves when you came among us.”', '只要这个凶猛的怪物还活着，我们谁都不安全。你来的时候，我们正在开会，讨论怎么保护自己呢。”'),
    (21, 1020, 1954, 'The Lion thought for a moment.', '狮子想了想。'),
    (21, 1021, 1955, '“Are there any other lions in this forest?” he asked.', '“这片森林里还有别的狮子吗？”他问。'),
    (21, 1022, 1956, '“No; there were some, but the monster has eaten them all.', '“没有；以前是有些，但都被怪物吃光了。'),
    (21, 1022, 1957, 'And, besides, they were none of them nearly so large and brave as you.”', '而且，它们都没你这么大，也没你这么勇敢。”'),
    (21, 1023, 1958, '“If I put an end to your enemy, will you bow down to me and obey me as King of the Forest?” inquired the Lion.', '“如果我帮你们除掉这个敌人，你们会向我低头，听我的话，把我当成森林之王吗？”狮子问。'),
    (21, 1024, 1959, '“We will do that gladly,” returned the tiger; and all the other beasts roared with a mighty roar: “We will!”', '“我们很乐意这么做！”老虎回答。所有其他动物都大声吼道：“我们愿意！”'),
    (21, 1025, 1960, '“Where is this great spider of yours now?” asked the Lion.', '“你们说的这个大蜘蛛现在在哪里？”狮子问。'),
    (21, 1026, 1961, '“Yonder, among the oak trees,” said the tiger, pointing with his forefoot.', '“就在那边，橡树林里。”老虎用前爪指着说。'),
    (21, 1027, 1962, '“Take good care of these friends of mine,” said the Lion, “and I will go at once to fight the monster.”', '“你们好好照顾我的这些朋友，”狮子说，“我这就去跟怪物打架。”'),
    (21, 1028, 1963, 'He bade his comrades good-bye and marched proudly away to do battle with the enemy.', '他跟伙伴们告别，骄傲地走开了，要去跟敌人打架。'),
    (21, 1029, 1964, 'The great spider was lying asleep when the Lion found him, and it looked so ugly that its foe turned up his nose in disgust.', '狮子找到大蜘蛛的时候，它正在睡觉。大蜘蛛长得太丑了，敌人看了都厌恶地皱起了鼻子。'),
    (21, 1029, 1965, 'Its legs were quite as long as the tiger had said, and its body covered with coarse black hair.', '它的腿真的像老虎说的那样长，身体上长满了粗粗的黑毛。'),
    (21, 1029, 1966, 'It had a great mouth, with a row of sharp teeth a foot long; but its head was joined to the pudgy body by a neck as slender as a wasp’s waist.', '它有个大大的嘴巴，里面有一排一尺长的尖牙。但它的头和胖胖的身体之间，脖子细得像黄蜂的腰。'),
    (21, 1029, 1967, 'This gave the Lion a hint of the best way to attack the creature, and as he knew it was easier to fight it asleep than awake, he gave a great spring and landed directly upon the monster’s back.', '这让狮子知道了攻击它的最好办法。他知道趁它睡觉的时候打更容易，于是猛地一跳，直接跳到怪物的背上。'),
    (21, 1029, 1968, 'Then, with one blow of his heavy paw, all armed with sharp claws, he knocked the spider’s head from its body.', '他用带着锋利指甲的沉重爪子一拍，就把蜘蛛的头从身体上打掉了。'),
    (21, 1029, 1969, 'Jumping down, he watched it until the long legs stopped wiggling, when he knew it was quite dead.', '他跳下来，看着它，直到它的长腿不再动了，这才知道它真的死了。'),
    (21, 1030, 1970, 'The Lion went back to the opening where the beasts of the forest were waiting for him and said proudly:', '狮子回到了空地上，森林里的动物们正在那里等他，他骄傲地说：'),
    (21, 1031, 1971, '“You need fear your enemy no longer.”', '“你们再也不用害怕敌人了。”'),
    (21, 1032, 1972, 'Then the beasts bowed down to the Lion as their King, and he promised to come back and rule over them as soon as Dorothy was safely on her way to Kansas.', '动物们向狮子低头，把他当成了它们的国王。他答应等多萝西安全地去往堪萨斯后，就回来统治它们。'),
    (22, 1033, 1973, 'The four travelers passed through the rest of the forest in safety, and when they came out from its gloom saw before them a steep hill, covered from top to bottom with great pieces of rock.', '四个旅行者安全地走出了森林。当他们走出阴暗的森林时，看到前面有一座陡峭的山，山上从头到脚都是大块大块的石头。'),
    (22, 1034, 1974, '“That will be a hard climb,” said the Scarecrow, “but we must get over the hill, nevertheless.”', '“那会很难爬，”稻草人说，“但我们还是得翻过这座山。”'),
    (22, 1035, 1975, 'So he led the way and the others followed.', '于是他带头，其他人跟着。'),
    (22, 1035, 1976, 'They had nearly reached the first rock when they heard a rough voice cry out, “Keep back!”', '他们快走到第一块大石头那里时，听到一个粗鲁的声音喊道：“别过来！”'),
    (22, 1036, 1977, '“Who are you?” asked the Scarecrow.', '“你们是谁？”稻草人问。'),
    (22, 1037, 1978, 'Then a head showed itself over the rock and the same voice said, “This hill belongs to us, and we don’t allow anyone to cross it.”', '然后，一个脑袋从石头后面露出来，那个声音又说：“这座山是我们的，我们不让任何人过。”'),
    (22, 1038, 1979, '“But we must cross it,” said the Scarecrow.', '“但我们必须过去。”稻草人说。'),
    (22, 1038, 1980, '“We’re going to the country of the Quadlings.”', '“我们要去奎德林人的国家。”'),
    (22, 1039, 1981, '“But you shall not!” replied the voice, and there stepped from behind the rock the strangest man the travelers had ever seen.', '“不行！”那个声音说，一个奇怪的男人从石头后面走了出来，旅行者们从没见过他这么奇怪的人。'),
    (22, 1040, 1982, 'He was quite short and stout and had a big head, which was flat at the top and supported by a thick neck full of wrinkles.', '他很矮很胖，头大大的，头顶平平的，粗粗的脖子上有好多皱纹。'),
    (22, 1040, 1983, 'But he had no arms at all, and, seeing this, the Scarecrow did not fear that so helpless a creature could prevent them from climbing the hill.', '可是他一点胳膊都没有！看到这，稻草人觉得这个没有胳膊的人帮不了什么忙，所以不怕他阻止自己爬山。'),
    (22, 1040, 1984, 'So he said, “I’m sorry not to do as you wish, but we must pass over your hill whether you like it or not,” and he walked boldly forward.', '于是他说：“不好意思，我们不能听你的，不管你喜不喜欢，我们都得过这座山。”他大胆地往前走。'),
    (22, 1041, 1985, 'As quick as lightning the man’s head shot forward and his neck stretched out until the top of the head, where it was flat, struck the Scarecrow in the middle and sent him tumbling, over and over, down the hill.', '像闪电一样快，那个人的头往前一冲，脖子伸得好长，他平平的头顶正好打在稻草人的身上，把稻草人撞得咕噜噜地滚下了山。'),
    (22, 1041, 1986, 'Almost as quickly as it came the head went back to the body, and the man laughed harshly as he said, “It isn’t as easy as you think!”', '他的头几乎一下子就缩了回去，那个人大声地笑着说：“这可不像你想的那么容易！”'),
    (22, 1042, 1987, 'A chorus of boisterous laughter came from the other rocks, and Dorothy saw hundreds of the armless Hammer-Heads upon the hillside, one behind every rock.', '其他石头后面传来了一阵大大的笑声，多萝西看到山坡上好多没有胳膊的锤头人，每块石头后面都藏着一个。'),
    (22, 1043, 1988, 'The Lion became quite angry at the laughter caused by the Scarecrow’s mishap, and giving a loud roar that echoed like thunder, he dashed up the hill.', '狮子看到稻草人摔倒了，大家还在笑，他很生气。他大吼一声，声音像打雷一样响，然后冲上了山。'),
    (22, 1044, 1989, 'Again a head shot swiftly out, and the great Lion went rolling down the hill as if he had been struck by a cannon ball.', '又一个头迅速地冲了出来，大大的狮子像被大炮弹打中一样，咕噜噜地滚下了山。'),
    (22, 1045, 1990, 'Dorothy ran down and helped the Scarecrow to his feet, and the Lion came up to her, feeling rather bruised and sore, and said, “It is useless to fight people with shooting heads; no one can withstand them.”', '多萝西跑下去扶起稻草人，狮子走到她身边，感觉自己又青又痛，说：“和这些会伸头打人的家伙打架没用，谁也打不过他们。”'),
    (22, 1046, 1991, '“What can we do, then?” she asked.', '“那我们该怎么办呢？”她问。'),
    (22, 1047, 1992, '“Call the Winged Monkeys,” suggested the Tin Woodman.', '“叫飞猴来。”铁皮人说。'),
    (22, 1047, 1993, '“You have still the right to command them once more.”', '“你还可以再命令他们一次。”'),
    (22, 1048, 1994, '“Very well,” she answered, and putting on the Golden Cap she uttered the magic words.', '“好的。”她回答，然后戴上金冠，念出了神奇的咒语。'),
    (22, 1048, 1995, 'The Monkeys were as prompt as ever, and in a few moments the entire band stood before her.', '猴子们像以前一样，很快就来了，不一会儿，所有的猴子都站在了她面前。'),
    (22, 1049, 1996, '“What are your commands?” inquired the King of the Monkeys, bowing low.', '“您有什么吩咐？”猴王弯下腰，恭敬地问。'),
    (22, 1050, 1997, '“Carry us over the hill to the country of the Quadlings,” answered the girl.', '“带我们翻过这座山，去奎德林人的国家。”女孩回答说。'),
    (22, 1051, 1998, '“It shall be done,” said the King, and at once the Winged Monkeys caught the four travelers and Toto up in their arms and flew away with them.', '“没问题。”猴王说。飞猴马上就把四个旅行者和托托抱起来，带着他们飞走了。'),
    (22, 1051, 1999, 'As they passed over the hill the Hammer-Heads yelled with vexation, and shot their heads high in the air, but they could not reach the Winged Monkeys, which carried Dorothy and her comrades safely over the hill and set them down in the beautiful country of the Quadlings.', '当他们飞过山的时候，锤头人气得大叫，把头高高地伸向空中，可是他们还是够不着飞猴。飞猴安全地带着多萝西和她的朋友们飞过了山，把他们轻轻地放在了美丽的奎德林人国家。'),
    (22, 1052, 2000, '“This is the last time you can summon us,” said the leader to Dorothy; “so good-bye and good luck to you.”', '“这是你最后一次叫我们了。”领队对多萝西说，“再见啦，祝你好运！”'),
    (22, 1053, 2001, '“Good-bye, and thank you very much,” returned the girl; and the Monkeys rose into the air and were out of sight in a twinkling.', '“再见，非常谢谢你们！”女孩回答。猴子们飞上了天空，一眨眼就不见了。'),
    (22, 1054, 2002, 'The country of the Quadlings seemed rich and happy.', '奎德林人的国家看起来很富有，大家都很开心。'),
    (22, 1054, 2003, 'There was field upon field of ripening grain, with well-paved roads running between, and pretty rippling brooks with strong bridges across them.', '这里有好多成熟的庄稼地，中间是修得很好的路，还有哗哗流淌的小河，上面架着结实的桥。'),
    (22, 1054, 2004, 'The fences and houses and bridges were all painted bright red, just as they had been painted yellow in the country of the Winkies and blue in the country of the Munchkins.', '这里的篱笆、房子和桥，都漆成了鲜红色，就像在温基人的国家是黄色的，在芒奇金人的国家是蓝色的那样。'),
    (22, 1054, 2005, 'The Quadlings themselves, who were short and fat and looked chubby and good-natured, were dressed all in red, which showed bright against the green grass and the yellowing grain.', '奎德林人们自己，又矮又胖，看起来很可爱很和善。他们都穿着红色的衣服，在绿草和金黄的庄稼地里显得特别亮眼。'),
    (22, 1055, 2006, 'The Monkeys had set them down near a farmhouse, and the four travelers walked up to it and knocked at the door.', '猴子们把他们放在一个农舍旁边，四个旅行者走过去敲了敲门。'),
    (22, 1055, 2007, 'It was opened by the farmer’s wife, and when Dorothy asked for something to eat the woman gave them all a good dinner, with three kinds of cake and four kinds of cookies, and a bowl of milk for Toto.', '农夫的妻子开了门，当多萝西问有没有东西吃时，那位婶婶给他们准备了一顿好吃的晚餐，有三种蛋糕和四种饼干，还给了托托一碗牛奶。'),
    (22, 1056, 2008, '“How far is it to the Castle of Glinda?” asked the child.', '“离格林达的城堡还有多远呀？”孩子问。'),
    (22, 1057, 2009, '“It is not a great way,” answered the farmer’s wife.', '“不远了。”农夫的妻子回答。'),
    (22, 1057, 2010, '“Take the road to the South and you will soon reach it.”', '“沿着南边的路走，很快就能到。”'),
    (22, 1058, 2011, 'Thanking the good woman, they started afresh and walked by the fields and across the pretty bridges until they saw before them a very beautiful Castle.', '谢谢好心的婶婶，他们又往前走，路过田地，走过漂亮的小桥，最后看到一座很美的城堡。'),
    (22, 1058, 2012, 'Before the gates were three young girls, dressed in handsome red uniforms trimmed with gold braid; and as Dorothy approached, one of them said to her:', '城堡大门前有三个小姑娘，她们穿着漂亮的红色制服，上面有金色的花边。当多萝西走过来的时候，其中一个对她说：'),
    (22, 1059, 2013, '“Why have you come to the South Country?”', '“你们为什么来南边的国家？”'),
    (22, 1060, 2014, '“To see the Good Witch who rules here,” she answered.', '“来看这里做主的好女巫。” 她回答。'),
    (22, 1060, 2015, '“Will you take me to her?”', '“你能带我去找她吗？”'),
    (22, 1061, 2016, '“Let me have your name, and I will ask Glinda if she will receive you.”', '“告诉我你的名字，我去问问格林达，看她愿不愿意见你们。”'),
    (22, 1061, 2017, 'They told who they were, and the girl soldier went into the Castle.', '他们说了自己是谁，那个小士兵就走进城堡里了。'),
    (22, 1061, 2018, 'After a few moments she came back to say that Dorothy and the others were to be admitted at once.', '没过一会儿她就回来了，说多萝西他们可以马上进去。'),
    (23, 1062, 2019, 'Before they went to see Glinda, however, they were taken to a room of the Castle, where Dorothy washed her face and combed her hair, and the Lion shook the dust out of his mane, and the Scarecrow patted himself into his best shape, and the Woodman polished his tin and oiled his joints.', '不过，在他们去见格林达之前，他们被带到城堡的一个房间。多萝西洗了脸，梳了头发；狮子抖掉它毛上的灰尘；稻草人把自己拍得美美的；铁皮人擦亮了身体，给关节涂了油。'),
    (23, 1063, 2020, 'When they were all quite presentable they followed the soldier girl into a big room where the Witch Glinda sat upon a throne of rubies.', '他们都收拾好后，跟着小士兵来到一个大房间。巫师格林达正坐在一把红宝石做的椅子上。'),
    (23, 1064, 2021, 'She was both beautiful and young to their eyes.', '在他们看来，她又漂亮又年轻。'),
    (23, 1064, 2022, 'Her hair was a rich red in color and fell in flowing ringlets over her shoulders.', '她的头发是很好看的红色，卷卷地披在肩膀上。'),
    (23, 1064, 2023, 'Her dress was pure white but her eyes were blue, and they looked kindly upon the little girl.', '她的裙子是白色的，但眼睛是蓝色的。她很亲切地看着小姑娘。'),
    (23, 1065, 2024, '“What can I do for you, my child?” she asked.', '“孩子，我能帮你什么呢？” 她问。'),
    (23, 1066, 2025, 'Dorothy told the Witch all her story: how the cyclone had brought her to the Land of Oz, how she had found her companions, and of the wonderful adventures they had met with.', '多萝西把她的故事都告诉了巫师：龙卷风怎么把她带到奥兹国，她怎么找到朋友们，还有他们遇到的那些很棒的冒险。'),
    (23, 1067, 2026, '“My greatest wish now,” she added, “is to get back to Kansas, for Aunt Em will surely think something dreadful has happened to me, and that will make her put on mourning; and unless the crops are better this year than they were last, I am sure Uncle Henry cannot afford it.”', '“我现在最想的，”她又说，“就是回到堪萨斯身边。因为艾姆婶婶一定会觉得我出了什么可怕的事，她会很难过的。如果今年收成不比去年好，我想亨利叔叔肯定也没钱。”'),
    (23, 1068, 2027, 'Glinda leaned forward and kissed the sweet, upturned face of the loving little girl.', '格林达弯下腰，亲了亲这个可爱小姑娘甜甜的脸。'),
    (23, 1069, 2028, '“Bless your dear heart,” she said, “I am sure I can tell you of a way to get back to Kansas.”', '“好孩子，”她说，“我肯定能告诉你一个办法，让你回到堪萨斯身边。”'),
    (23, 1069, 2029, 'Then she added, “But, if I do, you must give me the Golden Cap.”', '然后她又说，“但是，如果我帮你，你必须把金冠给我。”'),
    (23, 1070, 2030, '“Willingly!” exclaimed Dorothy; “indeed, it is of no use to me now, and when you have it you can command the Winged Monkeys three times.”', '“没问题！”多萝西大声说，“它现在对我没什么用了。你有了它，就可以让飞猴帮你三次。”'),
    (23, 1071, 2031, '“And I think I shall need their service just those three times,” answered Glinda, smiling.', '“我想我正好需要它们帮我三次。”格林达笑着说。'),
    (23, 1072, 2032, 'Dorothy then gave her the Golden Cap, and the Witch said to the Scarecrow, “What will you do when Dorothy has left us?”', '多萝西把金冠给了她，巫师对稻草人说，“当多萝西离开我们后，你准备做什么？”'),
    (23, 1073, 2033, '“I will return to the Emerald City,” he replied, “for Oz has made me its ruler and the people like me.', '“我要回到翡翠城去，”他回答，“因为奥兹大王让我做了那里的王，人们也都很喜欢我。'),
    (23, 1073, 2034, 'The only thing that worries me is how to cross the hill of the Hammer-Heads.”', '唯一让我担心的是，怎么穿过锤头人的山。”'),
    (23, 1074, 2035, '“By means of the Golden Cap I shall command the Winged Monkeys to carry you to the gates of the Emerald City,” said Glinda, “for it would be a shame to deprive the people of so wonderful a ruler.”', '“我会用金冠让飞猴把你送到翡翠城的城门，”格林达说，“因为让大家失去你这样棒的王，太可惜了。”'),
    (23, 1075, 2036, '“Am I really wonderful?” asked the Scarecrow.', '“我真的那么棒吗？”稻草人问。'),
    (23, 1076, 2037, '“You are unusual,” replied Glinda.', '“你很特别。”格林达说。'),
    (23, 1077, 2038, 'Turning to the Tin Woodman, she asked, “What will become of you when Dorothy leaves this country?”', '她转头对铁皮人说，“当多萝西离开这里的时候，你准备做什么？”'),
    (23, 1078, 2039, 'He leaned on his axe and thought a moment.', '他靠着斧头，想了一会儿。'),
    (23, 1078, 2040, 'Then he said, “The Winkies were very kind to me, and wanted me to rule over them after the Wicked Witch died.', '然后他说，“温基人对我很好，他们希望我在坏女巫去世后，去当他们的王。”'),
    (23, 1078, 2041, 'I am fond of the Winkies, and if I could get back again to the Country of the West, I should like nothing better than to rule over them forever.”', '我喜欢那些温基人。如果我能回到西方国度，我最想做的就是永远统治它们。'),
    (23, 1079, 2042, '“My second command to the Winged Monkeys,” said Glinda “will be that they carry you safely to the land of the Winkies.', '“我对飞猴的第二个命令是，”格林达说，“让它们把你安全地送到温基人的土地。'),
    (23, 1079, 2043, 'Your brain may not be so large to look at as those of the Scarecrow, but you are really brighter than he is—when you are well polished—and I am sure you will rule the Winkies wisely and well.”', '你的脑袋可能没有稻草人的看起来那么大，但你其实比他聪明多了——只要你擦亮一点。我肯定你会好好地、聪明地管理温基人的。”'),
    (23, 1080, 2044, 'Then the Witch looked at the big, shaggy Lion and asked, “When Dorothy has returned to her own home, what will become of you?”', '接着，女巫看着那只又大又毛茸茸的狮子，问道：“等多萝西回了家，你怎么办呢？”'),
    (23, 1081, 2045, '“Over the hill of the Hammer-Heads,” he answered, “lies a grand old forest, and all the beasts that live there have made me their King.', '“翻过锤头人的山，”他回答，“有一片很大的老森林，那里的所有动物都让我做了它们的国王。'),
    (23, 1081, 2046, 'If I could only get back to this forest, I would pass my life very happily there.”', '如果我能回到那片森林，我会在那里过得非常开心。”'),
    (23, 1082, 2047, '“My third command to the Winged Monkeys,” said Glinda, “shall be to carry you to your forest.', '“我对飞猴的第三个命令，”格林达说，“是把你们送到你们的森林里。'),
    (23, 1082, 2048, 'Then, having used up the powers of the Golden Cap, I shall give it to the King of the Monkeys, that he and his band may thereafter be free for evermore.”', '然后，等金冠的力量用完了，我就把它送给猴子国王，这样他和他的猴子们就可以永远自由了。”'),
    (23, 1083, 2049, 'The Scarecrow and the Tin Woodman and the Lion now thanked the Good Witch earnestly for her kindness; and Dorothy exclaimed:', '稻草人、铁皮人和狮子现在真诚地感谢好女巫的好心；多萝西大声说：'),
    (23, 1084, 2050, '“You are certainly as good as you are beautiful!', '“你真是人美心善啊！'),
    (23, 1084, 2051, 'But you have not yet told me how to get back to Kansas.”', '但你还没告诉我怎么回堪萨斯呢。”'),
    (23, 1085, 2052, '“Your Silver Shoes will carry you over the desert,” replied Glinda.', '“你的银鞋会带你穿过沙漠的，”格林达回答。'),
    (23, 1085, 2053, '“If you had known their power you could have gone back to your Aunt Em the very first day you came to this country.”', '“如果你知道它们有多厉害，你第一天来到这里就能回艾姆婶婶了。”'),
    (23, 1086, 2054, '“But then I should not have had my wonderful brains!” cried the Scarecrow. “I might have passed my whole life in the farmer’s cornfield.”', '“但那样我就没有我这聪明的脑袋了！”稻草人大叫道。“我可能会在农民的玉米地里过一辈子。”'),
    (23, 1087, 2055, '“And I should not have had my lovely heart,” said the Tin Woodman.', '“我也就不会有我这颗善良的心了，”铁皮人说。'),
    (23, 1087, 2056, '“I might have stood and rusted in the forest till the end of the world.”', '“我可能就会在森林里站着，一直生锈，直到世界末日。”'),
    (23, 1088, 2057, '“And I should have lived a coward forever,” declared the Lion, “and no beast in all the forest would have had a good word to say to me.”', '“我也会永远是个胆小鬼，”狮子说，“森林里没有一个动物会说我好话。”'),
    (23, 1089, 2058, '“This is all true,” said Dorothy, “and I am glad I was of use to these good friends.', '“这些都是真的，”多萝西说，“我很高兴能帮到这些好朋友。'),
    (23, 1089, 2059, 'But now that each of them has had what he most desired, and each is happy in having a kingdom to rule besides, I think I should like to go back to Kansas.”', '但现在他们都得到了自己最想要的东西，每个人都有自己的王国可以管理，我也想回堪萨斯了。”'),
    (23, 1090, 2060, '“The Silver Shoes,” said the Good Witch, “have wonderful powers.', '“银鞋，”好女巫说，“有神奇的力量。'),
    (23, 1090, 2061, 'And one of the most curious things about them is that they can carry you to any place in the world in three steps, and each step will be made in the wink of an eye.', '它们最特别的一点是，它们可以三步就把你带到世界上的任何地方，每一步都快得像眨眼一样。'),
    (23, 1090, 2062, 'All you have to do is to knock the heels together three times and command the shoes to carry you wherever you wish to go.”', '你只要把鞋跟敲三下，然后命令鞋子带你去你想去的地方就行了。”'),
    (23, 1091, 2063, '“If that is so,” said the child joyfully, “I will ask them to carry me back to Kansas at once.”', '“如果真是这样，”孩子高兴地说，“我这就让它们带我回堪萨斯。”'),
    (23, 1092, 2064, 'She threw her arms around the Lion’s neck and kissed him, patting his big head tenderly.', '她抱住狮子的脖子亲了他一下，温柔地拍了拍他的大脑袋。'),
    (23, 1092, 2065, 'Then she kissed the Tin Woodman, who was weeping in a way most dangerous to his joints.', '然后她亲了亲铁皮人，它正哭得关节都快散架了。'),
    (23, 1092, 2066, 'But she hugged the soft, stuffed body of the Scarecrow in her arms instead of kissing his painted face, and found she was crying herself at this sorrowful parting from her loving comrades.', '但她没有亲稻草人画出来的脸，而是抱住了它软软的身体。她发现自己也哭了，因为要和这些亲爱的朋友们难过地分开了。'),
    (23, 1093, 2067, 'Glinda the Good stepped down from her ruby throne to give the little girl a good-bye kiss, and Dorothy thanked her for all the kindness she had shown to her friends and herself.', '善良的格林达从她的红宝石宝座上走下来，给小女孩一个再见吻，多萝西感谢她对自己和朋友们的所有好意。'),
    (23, 1094, 2068, 'Dorothy now took Toto up solemnly in her arms, and having said one last good-bye she clapped the heels of her shoes together three times, saying:', '多萝西庄重地抱起托托，说了最后一声再见后，她把鞋跟敲了三下，说：'),
    (23, 1095, 2069, '“Take me home to Aunt Em!”', '“带我回艾姆婶婶！”'),
    (23, 1096, 2070, 'Instantly she was whirling through the air, so swiftly that all she could see or feel was the wind whistling past her ears.', '瞬间，她就在空中飞速旋转，快得她只能看到和感觉到风从耳边呼啸而过。'),
    (23, 1097, 2071, 'The Silver Shoes took but three steps, and then she stopped so suddenly that she rolled over upon the grass several times before she knew where she was.', '银鞋只走了三步，就突然停住了。她还在草地上滚了好几圈，才明白自己在哪里。'),
    (23, 1098, 2072, 'At length, however, she sat up and looked about her.', '终于，她坐起来，看了看周围。'),
    (23, 1099, 2073, '“Good gracious!” she cried.', '“哎呀！”她大叫一声。'),
    (23, 1100, 2074, 'For she was sitting on the broad Kansas prairie, and just before her was the new farmhouse Uncle Henry built after the cyclone had carried away the old one.', '因为她正坐在宽阔的堪萨斯大草原上。她面前是一座新农舍亨利叔叔，这是龙卷风把老房子吹走后盖的。'),
    (23, 1100, 2075, 'Uncle Henry was milking the cows in the barnyard, and Toto had jumped out of her arms and was running toward the barn, barking furiously.', '亨利叔叔正在牛圈里挤牛奶。托托从她怀里跳出来，对着牛圈汪汪叫着跑过去。'),
    (23, 1101, 2076, 'Dorothy stood up and found she was in her stocking-feet.', '多萝西站起来，发现自己只穿着袜子。'),
    (23, 1101, 2077, 'For the Silver Shoes had fallen off in her flight through the air, and were lost forever in the desert.', '因为银鞋在空中飞的时候掉了，永远地丢在沙漠里了。'),
    (24, 1102, 2078, 'Aunt Em had just come out of the house to water the cabbages when she looked up and saw Dorothy running toward her.', '艾姆婶婶刚从屋子里出来给白菜浇水。她一抬头，就看见多萝西朝她跑过来。'),
    (24, 1103, 2079, '“My darling child!” she cried, folding the little girl in her arms and covering her face with kisses. “Where in the world did you come from?”', '“我的宝贝！”她大声说，抱住小女孩，亲着她的脸。“你到底是从哪里来的呀？”'),
    (24, 1104, 2080, '“From the Land of Oz,” said Dorothy gravely.', '“从奥兹国来的。”多萝西认真地说。'),
    (24, 1104, 2081, '“And here is Toto, too.', '“还有托托也在这里呢。'),
    (24, 1104, 2082, 'And oh, Aunt Em!', '“哦，艾姆婶婶！'),
    (24, 1104, 2083, 'I’m so glad to be at home again!”', '我又回到家了，真开心！”')
) AS v(chapter_idx, para_idx, seq, text_en, text_cn)
WHERE b.book_key = 'wizard-of-oz';

SELECT 'after' AS phase,
       (SELECT sentence_count FROM public.library_books WHERE book_key = 'wizard-of-oz') AS book_sentence_count,
       (SELECT count(*) FROM public.library_sentences s
          JOIN public.library_books b ON b.id = s.book_id
         WHERE b.book_key = 'wizard-of-oz') AS sentence_rows;

COMMIT;

